INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Ban đầu Ðức Chúa Trời dựng nên trời đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Vả, đất là vô hình và trống không, sự mờ tối ở trên mặt vực; Thần Ðức Chúa Trời vận hành trên mặt nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Ðức Chúa Trời phán rằng: Phải có sự sáng; thì có sự sáng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Ðức Chúa Trời thấy sự sáng là tốt lành, bèn phân sáng ra cùng tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Ðức Chúa Trời đặt tên sự sáng là ngày; sự tối là đêm. Vậy, có buổi chiều và buổi mai; ấy là ngày thứ nhứt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Ðức Chúa Trời lại phán rằng: Phải có một khoảng không ở giữa nước đặng phân rẽ nước cách với nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Ngài làm nên khoảng không, phân rẽ nước ở dưới khoảng không cách với nước ở trên khoảng không; thì có như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Ðức Chúa Trời đặt tên khoảng không là trời. Vậy, có buổi chiều và buổi mai; ấy là ngày thứ nhì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Ðức Chúa Trời lại phán rằng: Những nước ở dưới trời phải tụ lại một nơi, và phải có chỗ khô cạn bày ra; thì có như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Ðức Chúa Trời đặt tên chỗ khô cạn là đất, còn nơi nước tụ lại là biển. Ðức Chúa Trời thấy điều đó là tốt lành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Ðức Chúa Trời lại phán rằng: Ðất phải sanh cây cỏ; cỏ kết hột giống, cây trái kết quả, tùy theo loại mà có hột giống trong mình trên đất; thì có như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Ðất sanh cây cỏ: cỏ kết hột tùy theo loại, cây kết quả có hột trong mình, tùy theo loại. Ðức Chúa Trời thấy điều đó là tốt lành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Vậy, có buổi chiều và buổi mai; ấy là ngày thứ ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Ðức Chúa Trời lại phán rằng: Phải có các vì sáng trong khoảng không trên trời, đặng phân ra ngày với đêm, và dùng làm dấu để định thì tiết, ngày và năm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'lại dùng làm vì sáng trong khoảng không trên trời để soi xuống đất; thì có như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Ðức Chúa Trời làm nên hai vì sáng lớn; vì lớn hơn để cai trị ban ngày, vì nhỏ hơn để cai trị ban đêm; Ngài cũng làm các ngôi sao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Ðức Chúa Trời đặt các vì đó trong khoảng không trên trời, đặng soi sáng đất,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'đặng cai trị ban ngày và ban đêm, đặng phân ra sự sáng với sự tối. Ðức Chúa Trời thấy điều đó là tốt lành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Vậy, có buổi chiều và buổi mai; ấy là ngày thứ tư.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Ðức Chúa Trời lại phán rằng: Nước phải sanh các vật sống cho nhiều, và các loài chim phải bay trên mặt đất trong khoảng không trên trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Ðức Chúa Trời dựng nên các loài cá lớn, các vật sống hay động nhờ nước mà sanh nhiều ra, tùy theo loại, và các loài chim hay bay, tùy theo loại. Ðức Chúa Trời thấy điều đó là tốt lành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Ðức Chúa Trời ban phước cho các loài đó mà phán rằng: Hãy sanh sản, thêm nhiều, làm cho đầy dẫy dưới biển; còn các loài chim hãy sanh sản trên đất cho nhiều.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Vậy, có buổi chiều và buổi mai; ấy là ngày thứ năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Ðức Chúa Trời lại phán rằng: Ðất phải sanh các vật sống tùy theo loại, tức súc vật, côn trùng, và thú rừng, đều tùy theo loại; thì có như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Ðức Chúa Trời làm nên các loài thú rừng tùy theo loại, súc vật tùy theo loại, và các côn trùng trên đất tùy theo loại, Ðức Chúa Trời thấy điều đó là tốt lành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Ðức Chúa Trời phán rằng: Chúng ta hãy làm nên loài người như hình ta và theo tượng ta, đặng quản trị loài cá biển, loài chim trời, loài súc vật, loài côn trùng bò trên mặt đất, và khắp cả đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Ðức Chúa Trời dựng nên loài người như hình Ngài; Ngài dựng nên loài người giống như hình Ðức Chúa Trời; Ngài dựng nên người nam cùng người nữ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Ðức Chúa Trời ban phước cho loài người và phán rằng: Hãy sanh sản, thêm nhiều, làm cho đầy dẫy đất; hãy làm cho đất phục tùng, hãy quản trị loài cá dưới biển, loài chim trên trời cùng các vật sống hành động trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Ðức Chúa Trời lại phán rằng: Nầy, ta sẽ ban cho các ngươi mọi thứ cỏ kết hột mọc khắp mặt đất, và các loài cây sanh quả có hột giống; ấy sẽ là đồ ăn cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Còn các loài thú ngoài đồng, các loài chim trên trời, và các động vật khác trên mặt đất, phàm giống nào có sự sống thì ta ban cho mọi thứ cỏ xanh đặng dùng làm đồ ăn; thì có như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Ðức Chúa Trời thấy các việc Ngài đã làm thật rất tốt lành. Vậy, có buổi chiều và buổi mai; ấy là ngày thứ sáu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Ấy vậy, trời đất và muôn vật đã dựng nên xong rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Ngày thứ bảy, Ðức Chúa Trời làm xong các công việc Ngài đã làm, và ngày thứ bảy, Ngài nghỉ các công việc Ngài đã làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Rồi, Ngài ban phước cho ngày thứ bảy, đặt là ngày thánh; vì trong ngày đó, Ngài nghỉ các công việc đã dựng nên và đã làm xong rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Ấy là gốc tích trời và đất khi đã dựng nên, trong lúc Giê-hô-va Ðức Chúa Trời dựng nên trời và đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Vả, lúc đó, chưa có một cây nhỏ nào mọc ngoài đồng, và cũng chưa có một ngọn cỏ nào mọc ngoài ruộng, vì Giê-hô-va Ðức Chúa Trời chưa có cho mưa xuống trên đất, và cũng chẳng có một người nào cày cấy đất nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Song có hơi nước dưới đất bay lên tưới khắp cùng mặt đất,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Giê-hô-va Ðức Chúa Trời bèn lấy bụi đất nắn nên hình người, hà sanh khí vào lỗ mũi; thì người trở nên một loài sanh linh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Ðoạn, Giê-hô-va Ðức Chúa Trời lập một cảnh vườn tại Ê-đen, ở về hướng Ðông, và đặt người mà Ngài vừa dựng nên ở đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Giê-hô-va Ðức Chúa Trời khiến đất mọc lên các thứ cây đẹp mắt, và trái thì ăn ngon; giữa vườn lại có cây sự sống cùng cây biết điều thiện và điều ác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Một con sông từ Ê-đen chảy ra đặng tưới vườn; rồi từ đó chia ra làm bốn ngả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Tên ngả thứ nhứt là Bi-sôn; ngả đó chảy quanh xứ Ha-vi-la, là nơi có vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Vàng xứ nầy rất cao; đó lại có nhũ hương và bính ngọc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Tên sông thứ nhì là Ghi-hôn, chảy quanh xứ Cu-sơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Tên sông thứ ba là Hi-đê-ke, chảy về phía đông bờ cõi A-si-ri. Còn sông thứ tư là sông Ơ-phơ-rát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Giê-hô-va Ðức Chúa Trời đem người ở vào cảnh vườn Ê-đen để trồng và giữ vườn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Rồi, Giê-hô-va Ðức Chúa Trời phán dạy rằng: Ngươi được tự do ăn hoa quả các thứ cây trong vườn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'nhưng về cây biết điều thiện và điều ác thì chớ hề ăn đến; vì một mai ngươi ăn chắc sẽ chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Giê-hô-va Ðức Chúa Trời phán rằng: Loài người ở một mình thì không tốt; ta sẽ làm nên một kẻ giúp đỡ giống như nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Giê-hô-va Ðức Chúa Trời lấy đất nắn nên các loài thú đồng, các loài chim trời, rồi dẫn đến trước mặt A-đam đặng thử xem người đặt tên chúng nó làm sao, hầu cho tên nào A-đam đặt cho mỗi vật sống, đều thành tên riêng cho nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'A-đam đặt tên các loài súc vật, các loài chim trời cùng các loài thú đồng; nhưng về phần A-đam, thì chẳng tìm được một ai giúp đỡ giống như mình hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Giê-hô-va Ðức Chúa Trời làm cho A-đam ngủ mê, bèn lấy một xương sường, rồi lấp thịt thế vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Giê-hô-va Ðức Chúa Trời dùng xương sường đã lấy nơi A-đam làm nên một người nữ, đưa đến cùng A-đam.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'A-đam nói rằng: Người nầy là xương bởi xương tôi, thịt bởi thịt tôi mà ra. Người nầy sẽ được gọi là người nữ, vì nó do nơi người nam mà có.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Bởi vậy cho nên người nam sẽ lìa cha mẹ mà dính díu cùng vợ mình, và cả hai sẽ trở nên một thịt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Vả, A-đam và vợ, cả hai đều trần truồng, mà chẳng hổ thẹn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Vả, trong các loài thú đồng mà Giê-hô-va Ðức Chúa Trời đã làm nên, có con rắn là giống quỉ quyệt hơn hết. Rắn nói cùng người nữ rằng: Mà chi! Ðức Chúa Trời há có phán dặn các ngươi không được phép ăn trái các cây trong vườn sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Người nữ đáp rằng: Chúng ta được ăn trái các cây trong vườn,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'song về phần trái của cây mọc giữa vườn, Ðức Chúa Trời có phán rằng: Hai ngươi chẳng nên ăn đến và cũng chẳng nên đá-động đến, e khi hai ngươi phải chết chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Rắn bèn nói với người nữ rằng: Hai ngươi chẳng chết đâu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'nhưng Ðức Chúa Trời biết rằng hễ ngày nào hai ngươi ăn trái cây đó, mắt mình mở ra, sẽ như Ðức Chúa Trời, biết điều thiện và điều ác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Người nữ thấy trái của cây đó bộ ăn ngon, lại đẹp mắt và quí vì để mở trí khôn, bèn hái ăn, rồi trao cho chồng đứng gần mình, chồng cũng ăn nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Ðoạn, mắt hai người đều mỡ ra, biết rằng mình lỏa lồ, bèn lấy lá cây vả đóng khố che thân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Lối chiều, nghe tiếng Giê-hô-va Ðức Chúa Trời đi ngang qua vườn, A-đam và vợ ẩn mình giữa bụi cây, để tránh mặt Giê-hô-va Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Giê-hô-va Ðức Chúa Trời kêu A-đam mà phán hỏi rằng: Ngươi ở đâu?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'A-đam thưa rằng: Tôi có nghe tiếng Chúa trong vườn, bèn sợ, bởi vì tôi lỏa lồ, nên đi ẩn mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Ðức Chúa Trời phán hỏi: Ai đã chỉ cho ngươi biết rằng mình lỏa lồ? Ngươi có ăn trái cây ta đã dặn không nên ăn đó chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Thưa rằng: Người nữ mà Chúa đã để gần bên tôi cho tôi trái cây đó và tôi đã ăn rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Giê-hô-va Ðức Chúa Trời phán hỏi người nữ rằng: Người có làm điều chi vậy? Người nữ thưa rằng: Con rắn dỗ dành tôi và tôi đã ăn rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Giê-hô-va Ðức Chúa Trời bèn phán cùng rắn rằng: Vì mầy đã làm điều như vậy, mầy sẽ bị rủa sả trong vòng các loài súc vật, các loài thú đồng, mầy sẽ bò bằng bụng và ăn bụi đất trọn cả đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Ta sẽ làm cho mầy cùng người nữ, dòng dõi mầy cùng dòng dõi người nữ nghịch thù nhau. Người sẽ giày đạp đầu mầy, còn mầy sẽ cắn gót chân người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ngài phán cùng người nữ rằng: Ta sẽ thêm điều cực khổ bội phần trong cơn thai nghén; ngươi sẽ chịu đau đớn mỗi khi sanh con; sự dục vọng ngươi phải xu hướng về chồng, và chồng sẽ cai trị ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Ngài lại phán cùng A-đam rằng: Vì ngươi nghe theo lời vợ mà ăn trái cây ta đã dặn không nên ăn, vậy, đất sẽ bị rủa sả vì ngươi; trọn đời ngươi phải chịu khó nhọc mới có vật đất sanh ra mà ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Ðất sẽ sanh chông gai và cây tật lê, và ngươi sẽ ăn rau của đồng ruộng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'ngươi sẽ làm đổ mồ hôi trán mới có mà ăn, cho đến ngày nào ngươi trở về đất, là nơi mà có ngươi ra; vì ngươi là bụi, ngươi sẽ trở về bụi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'A-đam gọi vợ là Ê-va, vì là mẹ của cả loài người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Giê-hô-va Ðức Chúa Trời lấy da thú kết thành áo dài cho vợ chồng A-đam, và mặc lấy cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Giê-hô-va Ðức Chúa Trời phán rằng: Nầy, về sự phân biệt điều thiện và điều ác, loài người đã thành một bực như chúng ta; vậy bây giờ, ta hãy coi chừng, e loài người giơ tay khiến cũng hái trái cây sự sống mà ăn và được sống đời đời chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Giê-hô-va Ðức Chúa Trời bèn đuổi loài người ra khỏi vườn Ê-đen đặng cày cấy đất, là nơi có người ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Vậy, Ngài đuổi loài người ra khỏi vườn, rồi đặt tại phía đông vườn Ê-đen các thần chê-ru-bin với gươm lưỡi chói lòa, để giữ con đường đi đến cây sự sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'A-đam ăn ở với Ê-va, là vợ mình; người thọ thai sanh Ca-in và nói rằng: Nhờ Ðức Giê-hô-va giúp đỡ, tôi mới sanh được một người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Ê-va lại sanh em Ca-in, là A-bên; A-bên làm nghề chăn chiên, còn Ca-in thì nghề làm ruộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Vả, cách ít lâu, Ca-in dùng thổ sản làm của lễ dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'A-bên cũng dâng chiên đầu lòng trong bầy mình cùng mỡ nó. Ðức Giê-hô-va đoái xem A-bên và nhận lễ vật của người;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'nhưng chẳng đoái đến Ca-in và cũng chẳng nhận lễ vật của người; cho nên Ca-in giận lắm mà gằm nét mặt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Ðức Giê-hô-va phán hỏi Ca-in rằng: Cớ sao ngươi giận, và cớ sao nét mặt ngươi gằm xuống?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Nếu ngươi làm lành, há chẳng ngước mặt lên sao? Còn như chẳng làm lành, thì tội lỗi rình đợi trước cửa, thèm ngươi lắm; nhưng ngươi phải quản trị nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Ca-in thuật lại cùng A-bên là em mình. Vả, khi hai người đương ở ngoài đồng, thì Ca-in xông đến A-bên là em mình, và giết đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Ðức Giê-hô-va hỏi Ca-in rằng: A-bên, em ngươi, ở đâu? Thưa rằng: Tôi không biết; tôi là người giữ em tôi sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Ðức Giê-hô-va hỏi: Ngươi đã làm điều chi vậy? Tiếng của máu em ngươi từ dưới đất kêu thấu đến ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Bây giờ, ngươi sẽ bị đất rủa sả, là đất đã hả miệng chịu hút máu của em ngươi bởi chính tay ngươi làm đổ ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Khi ngươi trồng tỉa, đất chẳng sanh hoa lợi cho ngươi nữa; ngươi sẽ lưu lạc và trốn tránh, trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Ca-in thưa cùng Ðức Giê-hô-va rằng: Sự hình phạt tôi nặng quá mang không nổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Nầy, ngày nay, Chúa đã đuổi tôi ra khỏi đất nầy, tôi sẽ lánh mặt Chúa, sẽ đi lưu lạc trốn tránh trên đất; rồi, xảy có ai gặp tôi, họ sẽ giết đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Ðức Giê-hô-va phán rằng: Bởi cớ ấy, nếu ai giết Ca-in, thì sẽ bị báo thù bảy lần. Ðức Giê-hô-va bèn đánh đấu trên mình Ca-in, hầu cho ai gặp Ca-in thì chẳng giết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Ca-in bèn lui ra khỏi mặt Ðức Giê-hô-va, và ở tại xứ Nốt, về phía đông của Ê-đen.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Ðoạn, Ca-in ăn ở cùng vợ mình, nàng thọ thai và sanh được Hê-nóc; Ca-in xây một cái thành đặt tên là Hê-nóc, tùy theo tên con trai mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Rồi, Hê-nóc sanh Y-rát; Y-rát sanh Nê-hu-đa-ên; Nê-hu-đa-ên sanh Mê-tu-sa-ên; Mê-tu-sa-ên sanh Lê-méc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lê-méc cưới hai vợ; một người tên là A-đa, một người tên là Si-la.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'A-đa sanh Gia-banh; Gia-banh là tổ phụ của các dân ở trại và nuôi bầy súc vật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Em người là Giu-banh, tổ phụ của những kẻ đánh đờn và thổi sáo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Còn Si-la cũng sanh Tu-banh-Ca-in là người rèn đủ thứ khí giới bén bằng đồng và bằng sắt. Em gái của Tu-banh-Ca-in là Na-a-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lê-méc bèn nói với hai vợ mình rằng: Hỡi A-đa và Si-la! hãy nghe tiếng ta; Nầy, vợ Lê-méc hãy lắng tai nghe lời ta: Ừ! Ta đã giết một người, vì làm thương ta, Và một người trẻ, vì đánh sưng bầm ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Nếu Ca-in được bảy lần báo thù, Lê-méc sẽ được bảy mươi bảy lần báo oán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'A-đam còn ăn ở với vợ mình; người sanh được một con trai đặt tên là Sết; vì vợ rằng: Ðức Chúa Trời đã cho tôi một con trai khác thế cho A-bên mà đã bị Ca-in giết rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Sết cũng sanh được một con trai, đặt tên là Ê-nót. Từ đây, người ta bắt đầu cầu khẩn danh Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Ðây là sách chép dòng dõi của A-đam. Ngày mà Ðức Chúa Trời dựng nên loài người, thì người làm nên loài người giống như Ðức Chúa Trời;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Ngài dựng nên người nam cùng người nữ, ban phước cho họ, và trong ngày đã dựng nên, đặt tên là người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Vả, A-đam được một trăm ba mươi tuổi, sanh một con trai giống như hình tượng mình, đặt tên là Sết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Sau khi A-đam sanh Sết rồi, còn sống được tám trăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Vậy, A-đam hưởng thọ được chín trăm ba mươi tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Sết được một trăm năm tuổi, sanh Ê-nót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Sau khi Sết sanh Ê-nót rồi, còn sống được tám trăm bảy năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Vậy, Sết hưởng thọ được chín trăm mười hai tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Ê-nót được chín mươi tuổi, sanh Kê-nan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Sau khi sanh Kê-nan rồi, còn sống được tám trăm mười lăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Vậy, Ê-nót hưởng thọ được chín trăm năm tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kê-nan được bảy mươi tuổi, sanh Ma-ha-la-le.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Sau khi Kê-nan sanh Ma-ha-la-le rồi, còn sống được tám trăm bốn mươi năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Vậy, Kê-nan hưởng thọ được chín trăm mười tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Ma-ha-la-le được sáu mươi lăm tuổi, sanh Giê-rệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Sau khi Ma-ha-la-le sanh Giê-rệt rồi, còn sống được tám trăm ba mươi năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Vậy, Ma-ha-la-le hưởng thọ được tám trăm chín mươi lăm tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Giê-rệt được một trăm sáu mươi hai tuổi, sanh Hê-nóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Sau khi Giê-rệt sanh Hê-nót rồi, còn sống được tám trăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Vậy, Giê-rệt hưởng thọ được chín trăm sáu mươi hai tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Hê-nóc được sáu mươi lăm tuổi, sanh Mê-tu-sê-la.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Sau khi Hê-nóc sanh Mê-tu-sê-la rồi, đồng đi cùng Ðức Chúa Trời trong ba trăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Vậy Hê-nóc hưởng thọ được ban trăm sáu mươi lăm tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Hê-nóc đồng đi cùng Ðức Chúa Trời, rồi mất biệt, bởi vì Ðức Chúa Trời tiếp người đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Mê-tu-sê-la được một trăm tám mươi bảy tuổi, sanh Lê-méc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Sau khi Mê-tu-sê-la sanh Lê-méc rồi, còn sống được bảy trăm tám mươi hai năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Vậy, Mê-tu-sê-la hưởng thọ được chín trăm sáu mươi chín tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lê-méc được một trăm tám mươi hai tuổi, sanh một trai,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Ðặt tên là Nô-ê, mà nói rằng: Ðứa nầy sẽ an ủy lòng ta về công việc và về sự nhọc nhằn mà đất bắt tay ta phải làm, là đất Ðức Giê-hô-va đã rủa sả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Sau khi Lê-méc sanh Nô-ê rồi, còn sống được năm trăm chín mươi lăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Vậy, Lê-méc hưởng thọ được bảy trăm bảy mươi bảy tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Còn Nô-ê, khi đến năm trăm tuổi, sanh Sem Cham và Gia-phết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Vả, khi loài người khởi thêm nhiều trên mặt đất, và khi loài người đã sanh được con gái rồi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'các con trai của Ðức Chúa Trời thấy con gái loài người tốt đẹp, bèn cưới người nào vừa lòng mình mà làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Ðức Giê-hô-va phán rằng: Thần ta sẽ chẳng hằng ở trong loài người luôn; trong điều lầm lạc, loài người chỉ là xác thịt; đời người sẽ là một trăm hai mươi năm mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Ðời đó và đời sau, có người cao lớn trên mặt đất, vì con trai Ðức Chúa Trời ăn ở cùng con gái loài người mà sanh con cái; ấy những người mạnh dạn ngày xưa là tay anh hùng có danh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Ðức Giê-hô-va thấy sự hung ác của loài người trên mặt đất rất nhiều, và các ý tưởng của lòng họ chỉ là xấu luôn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'thì tự trách đã dựng nên loài người trên mặt đất, và buồn rầu trong lòng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Ðức Giê-hô-va phán rằng: Ta sẽ hủy diệt khỏi mặt đất loài người mà ta đã dựng nên, từ loài người cho đến loài súc vật, loài côn trùng, loài chim trời; vì ta tự trách đã dựng nên các loài đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Nhưng Nô-ê được ơn trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Nầy là dòng dõi của Nô-ê. Nô-ê trong đời mình là một người công bình và toàn vẹn, đồng đi cùng Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Nô-ê sanh ba con trai là Sem, Cham và Gia-phết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Thế gian bấy giờ đều bại hoại trước mặt Ðức Chúa Trời và đầy dẫy sự hung ác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Nầy, Ðức Chúa Trời nhìn xem thế gian, thấy điều bại hoại, vì hết thảy xác thịt làm cho đường mình trên đất phải bại hoại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Ðức Chúa Trời bèn phán cùng Nô-ê rằng: Kỳ cuối cùng của mọi xác thịt đã đưa đến trước mặt ta; vì cớ loài người mà đất phải đầy dẫy điều hung hăng; vậy, ta sẽ diệt-trừ họ cùng đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Ngươi hãy đóng một chiếc tàu bằng cây gô-phe, đóng có từng phòng, rồi trét chai bề trong cùng bề ngoài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Vậy, hãy làm theo thế nầy: Bề dài tàu ba trăm thước, bề ngang năm mươi thước, bề cao ba mươi thước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Trên tàu ngươi sẽ làm một cửa sổ, bề cao một thước, và chừa một cửa bên hông; ngươi sẽ làm một từng dưới, một từng giữa và một từng trên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Còn ta đây, ta sẽ dẫn nước lụt khắp trên mặt đất, đặng diệt tuyệt các xác thịt có sanh khí ở dưới trời; hết thảy vật chi ở trên mặt đất đều sẽ chết hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Nhưng ta sẽ lập giao ước cùng ngươi, rồi ngươi và vợ, các con và các dâu của ngươi, đều hãy vào tàu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Về các loài sanh vật, ngươi hãy dẫn xuống tàu mỗi loài một cặp, có đực có cái, có trống có mái, hầu cho ở cùng ngươi đặng giữ tròn sự sống;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'chim tùy theo loại, súc vật tùy theo loại, côn trùng tùy theo loại, mỗi thứ hai con, sẽ đến cùng ngươi, để ngươi giữ tròn sự sống cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Lại, ngươi hãy lấy các thứ đồ ăn đem theo, đặng để dàng làm lương thực cho ngươi và các loài đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Nô-ê làm các điều nầy y như lời Ðức Chúa Trời đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Ðức Giê-hô-va phán cùng Nô-ê rằng: Ngươi và cả nhà ngươi hãy vào tàu, vì về đời nầy ta thấy ngươi là công bình ở trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Trong các loài vật thanh sạch, hãy đem theo mỗi loài bảy cặp, đực và cái; còn loài vật không thanh sạch mỗi loài một cặp, đực và cái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Cũng hãy đem theo những chim trời, mỗi thứ bảy cặp, trống và mái, để giữ giống ở trên khắp mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Vì còn bảy ngày nữa, ta sẽ làm mưa xuống mặt đất, trong bốn mươi ngày và bốn mươi đêm; ta sẽ tuyệt diệt khỏi đất hết các loài của ta đã dựng nên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Ðoạn, Nô-ê làm theo mọi điều Ðức Giê-hô-va đã phán dặn mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Vả, khi lụt xảy ra, và nước tràn trên mặt đất, thì Nô-ê đã được sáu trăm tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Vì cớ nước lụt, nên Nô-ê vào tàu cùng vợ, các con trai và các dâu mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'loài vật thanh sạch và loài vật không thanh sạch, loài chim, loài côn trùng trên mặt đất,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'từng cặp, đực và cái, trống và mái, đều đến cùng Nô-ê mà vào tàu, y như lời Ðức Chúa Trời đã phán dặn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Sau bảy ngày, nước lụt xảy có trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Nhằm năm sáu trăm của đời Nô-ê, tháng hai, ngày mười bảy, chánh ngày đó, các nguồn của vực lớn nổ ra, và các đập trên trời mở xuống;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'mưa sa trên mặt đất trọn bốn mươi ngày và bốn mươi đêm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Lại cũng trong một ngày đó, Nô-ê với vợ, ba con trai: Sem, Cham và Gia-phết, cùng ba dâu mình đồng vào tàu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Họ và các loài, thú rừng tùy theo loại, súc vật tùy theo loại, côn trùng trên mặt đất tùy theo loài, chim tùy theo loại, và hết thảy vật nào có cánh,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'đều từng cặp theo Nô-ê vào tàu; nghĩa là mọi xác thịt nào có sanh khí,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'một đực một cái, một trống một mái, đều đến vào tàu, y như lời Ðức Chúa Trời đã phán dặn; đoạn, Ðức Giê-hô-va đóng cửa tàu lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Nước lụt phủ mặt đất bốn mươi ngày; nước dưng thêm nâng hỏng tàu lên khỏi mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Trên mặt đất nước lớn và dưng thêm nhiều lắm; chiếc tàu nổi trên mặt nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Nước càng dưng lên bội phần trên mặt đất, hết thảy những ngọn núi cao ở dưới trời đều bị ngập.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Nước dưng lên mười lăm thước cao hơn, mấy ngọn núi đều ngập.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Các xác thịt hành động trên mặt đất đều chết ngột, nào chim, nào súc vật, nào thú rừng, nào côn trùng, và mọi người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Các vật có sanh khí trong lỗ mũi, các vật ở trên đất liền đều chết hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Mọi loài ở trên mặt đất đều bị hủy diệt, từ loài người cho đến loài thú, loài côn trùng, cùng loài chim trời, chỉ còn Nô-ê và các loài ở với người trong tàu mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Nước dưng lên trên mặt đất trọn một trăm năm mươi ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Vả, Ðức Chúa Trời nhớ lại Nô-ê cùng các loài thú và súc vật ở trong tàu với người, bèn khiến một trận gió thổi ngang qua trên đất, thì nước dừng lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Các nguồn của vực lớn và các đập trên trời lấp ngăn lại; mưa trên trời không sa xuống nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Nước giựt khỏi mặt đất, lần lần vừa hạ vừa giựt; trong một trăm năm mươi ngày nước mới bớt xuống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Ðến tháng bảy, ngày mười bảy, chiếc tàu tấp trên núi A-ra-rát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Nước cứ lần lần hạ cho đến tháng mười; ngày mồng một tháng đó, mấy đỉnh núi mới lộ ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Ðược bốn mươi ngày, Nô-ê mở cửa sổ mình đã làm trên tàu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'thả một con quạ ra; quạ liệng đi liệng lại cho đến khi nước giựt khô trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Người cũng thả một con bò câu ra, đặng xem thử nước hạ bớt trên mặt đất chưa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Nhưng bò câu chẳng tìm được nơi nào đáp chơn xuống, bèn bay trở về trong tàu cùng người, vì nước còn khắp cả trên mặt đất. Nô-ê giơ tay bắt lấy bò câu, đem vào tàu lại với mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Ðoạn, người đợi bảy ngày nữa, lại thả bò câu ra khỏi tàu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'đến chiều bò câu về cùng người, và nầy, trong mỏ tha một lá Ô-li-ve tươi; Nô-ê hiểu rằng nước đã giảm bớt trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Người đợi bảy ngày nữa, thả bò câu ra; nhưng chuyến nầy bò câu chẳng trở về cùng người nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Nhằm năm sáu trăm một của đời Nô-ê, ngày mồng một, tháng giêng, nước đã giựt bày mặt đất khô; Nô-ê bèn giở mui tàu mà nhìn; nầy, mặt đất đã se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Ðến tháng hai, ngày hai mươi bảy, đất đã khô rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Ðức Chúa Trời bèn phán cùng Nô-ê rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Hãy ra khỏi tàu, ngươi, vợ các con và các dâu ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Hãy thả ra với ngươi mọi vật sống của các xác thịt đã ở cùng ngươi: nào chim, nào thú, nào côn trùng bò trên đất, hầu cho chúng nó sanh sản, và thêm nhiều trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Vậy, Nô-ê cùng vợ người, các con trai và các dâu người ra khỏi tàu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Các thú, rắn, chim cùng mọi vật hành động trên mặt đất tùy theo giống đều ra khỏi tàu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Nô-ê lập một bàn thờ cho Ðức Giê-hô-va. Người bắt các súc vật thanh sạch, các loài chim thanh sạch, bày của lễ thiêu dâng lên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Ðức Giê-hô-va hưởng lấy mùi thơm và nghĩ thầm rằng: Ta chẳng vì loài người mà rủa sả đất nữa, vì tâm tánh loài người vẫn xấu xa từ khi còn tuổi trẻ; ta cũng sẽ chẳng hành các vật sống như ta đã làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Hễ đất còn, thì mùa gieo giống cùng mùa gặt hái, lạnh và nóng, mùa hạ cùng mùa đông, ngày và đêm, chẳng bao giờ tuyệt được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Ðức Chúa Trời ban phước cho Nô-ê cùng các con trai người, mà phán rằng: Hãy sanh sản, thêm nhiều, làm cho đầy dẫy trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Các loài vật ở trên đất, các loài chim trời, và các vật hành động trên đất, cùng các cá biển, đều sẽ kinh khủng ngươi và bị phú vào tay ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Phàm vật chi hành động và có sự sống thì dùng làm đồ ăn cho các ngươi. Ta cho mọi vật đó như ta đã cho thứ cỏ xanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Song các ngươi không nên ăn thịt còn hồn sống, nghĩa là có máu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Quả thật, ta sẽ đòi máu của sự sống ngươi lại, hoặc nơi các loài thú vật, hoặc nơi tay người, hoặc nơi tay của anh em người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Hễ kẻ nào làm đổ máu người, thì sẽ bị người khác làm đổ máu lại; vì Ðức Chúa Trời làm nên người như hình của Ngài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vậy, các ngươi hãy sanh sản, thêm nhiều, và làm cho đầy dẫy trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Ðức Chúa Trời cũng phán cùng Nô-ê và các con trai người rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Còn phần ta đây, ta lập giao ước cùng các ngươi, cùng dòng dõi các ngươi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'và cùng mọi vật sống ở với ngươi, nào loài chim, nào súc vật, nào loài thú ở trên đất, tức là các loài ở trong tàu ra, cho đến các loài vật ở trên đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Vậy, ta lập giao ước cùng các ngươi, và các loài xác thịt chẳng bao giờ lại bị nước lụt hủy diệt, và cũng chẳng có nước lụt để hủy hoại đất nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Ðức Chúa Trời lại phán rằng: Ðây là dấu chỉ về sự giao ước mà ta lập cùng các ngươi, cùng hết thảy vật sống ở với các ngươi, trải qua các đời mãi mãi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Ta đặt mống của ta trên từng mây, dùng làm dấu chỉ sự giao ước của ta với đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Phàm lúc nào ta góp các đám mây trên mặt đất và phàm mống mọc trên từng mây,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'thì ta sẽ nhớ lại sự giao ước của ta đã lập cùng các ngươi, và cùng các loài xác thịt có sự sống, thì nước chẳng bao giờ lại trở nên lụt mà hủy diệt các loài xác thịt nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Vậy, cái mống sẽ ở trên mây, ta nhìn xem nó đặng nhớ lại sự giao ước đời đời của Ðức Chúa Trời cùng các loài xác thịt có sự sống ở trên đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Ðức Chúa Trời lại phán cùng Nô-ê rằng: Ðó là dấu chỉ sự giao ước mà ta đã lập giữa ta và các xác thịt ở trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Các con trai của Nô-ê ở trong tàu ra là Sem, Cham và Gia-phết. Vả, Cham là cha của Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ấy đó, là ba con trai của Nô-ê, và cũng do nơi họ mà có loài người ở khắp trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Vả, Nô-ê khởi cày đất và trồng nho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Người uống rượu say, rồi lõa thể ở giữa trại mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Cham là cha Ca-na-an, thấy sự trần truồng của cha, thì ra ngoài thuật lại cùng hai anh em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Nhưng Sem và Gia-phết đều lấy áo choàng vắt trên vai mình, đi thùi lui đến đắp khuất thân cho cha; và bởi họ xây mặt qua phía khác, nên chẳng thấy sự trần truồng của cha chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Khi Nô-ê tỉnh rượu rồi, hay được điều con thứ hai đã làm cho mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'bèn nói rằng: Ca-na-an đáng rủa sả! Nó sẽ làm mọi cho các tôi tớ của anh em nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Người lại nói rằng: Ðáng ngợi khen Giê-hô-va, là Ðức Chúa Trời của Sem thay; Ca-na-an phải làm tôi cho họ!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Cầu xin Ðức Chúa Trời mở rộng đất cho Gia-phết, cho người ở nơi trại của Sem; còn Ca-na-an phải làm tôi của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Sau khi lụt, Nô-ê còn sống ba trăm năm mươi năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Vậy, Nô-ê hưởng thọ được chín trăm năm mươi tuổi, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Ðây là dòng dõi của Sem, Cham và Gia-phết, ba con trai của Nô-ê; sau khi lụt, họ sanh con cái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Con trai của Gia-phết là Gô-me, Ma-gốc, Ma-đai, Gia-van, Tu-banh, Mê-siếc, và Ti-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Con trai của Gô-me là Ách-kê-na, Ri-phát, và Tô-ga-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Con trai của Gia-van là Ê-li-sa và Ta-rê-si, Kít-sim và Ðô-đa-nim.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Do họ mà có người ta ở tràn ra các cù lao của các dân, tùy theo xứ, tiếng nói, chi phái và dân tộc của họ mà chia ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Con trai của Cham là Cúc, Mích-ra-im, Phút và Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Con trai của Cúc là Sê-ba, Ha-vi-la, Sáp-ta, Ra-ê-ma và Sáp-tê-ca; con trai của Ra-ê-ma là Sê-la và Ðê-đan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Cúc sanh Nim-rốt, ấy là người bắt đầu làm anh hùng trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Người là một tay thợ săn can đảm trước mặt Ðức Giê-hô-va. Bởi cớ đó, có tục ngữ rằng: Hệt như Nim-rốt, một tay thợ săn can đảm trước mặt Ðức Giê-hô-va!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Nước người sơ-lập là Ba-bên, Ê-rết, A-cát và Ca-ne ở tại xứ Si-nê-a.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Từ xứ đó người đến xứ A-si-ri, rồi lập thành Ni-ni-ve, Rê-hô-bô-ti, Ca-lách,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Và thành Rê-sen, là thành rất lớn, ở giữa khoảng thành Ni-ni-ve và Ca-lách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mích-ra-im sanh họ Lu-đim, họ A-na-mim, họ Lê-ha-bim, họ Náp-tu-him,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'họ Bát-ru-sim, họ Cách-lu-him (bởi đó sanh họ Phi-li-tin), và họ Cáp-tô-rim.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Ca-na-an sanh Si-đôn, là con trưởng nam, và Hếch,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'cùng họ Giê-bu-sít, họ A-mô-rít, họ Ghi-rê-ga-sít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'họ Hê-vít, họ A-rê-kít, họ Si-nít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'họ A-va-đít, họ Xê-ma-rít, họ Ha-ma-tít. Kế đó, chi tộc Ca-na-an đi tản lạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Còn địa-phận Ca-na-an, về hướng Ghê-ra, chạy từ Si-đôn tới Ga-xa; về hướng Sô-đôm, Gô-mô-rơ, Át-ma và Sê-bô-im, chạy đến Lê-sa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ðó là con cháu của Cham, tùy theo họ hàng, tiếng nói, xứ và dân tộc của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Sem, tổ phụ của họ Hê-be và anh cả của Gia-phết, cũng có sanh con trai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Con trai của Sem là Ê-lam, A-sự-rơ, A-bác-sát, Lút và A-ram.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Con trai của A-ram là U-xơ, Hu-lơ, Ghê-te và Mách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Còn A-bác-sát sanh Sê-lách; Sê-lách sanh Hê-be,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Hê-be sanh được hai con trai; tên của một người là Bê-léc, vì đất trong đời người đó đã chia ra; trên của người em là Giốc-tan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Giốc-tan sanh A-mô-đát, Sê-lép, Ha-sa-ma-vết và Giê-rách,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Ha-đô-ram, U-xa, Ðiếc-la,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Ô-banh, A-bi-ma-ên, Sê-ba,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ô-phia, Ha-vi-la và Giô-báp. Hết thảy các người đó là con trai của Giốc-tan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Cõi đất của các người đó ở về phía Sê-pha, chạy từ Mê-sa cho đến núi Ðông phương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ðó là con cháu của Sem, tùy theo họ hàng, tiếng nói, xứ và dân tộc của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Ấy là các họ hàng của ba con trai Nô-ê tùy theo đời và dân tộc của họ; lại cũng do nơi họ mà các dân chia ra trên mặt đất sau cơn nước lụt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Vả, cả thiên hạ đều có một giọng nói và một thứ tiếng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Nhưng khi ở Ðông phương dời đi, người ta gặp một đồng bằng trong xứ Si-nê-a, rồi ở tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Người nầy nói với người kia rằng: Hè! chúng ta hãy làm gạch và hầm trong lửa. Lúc đó, gạch thế cho đá, còn chai thế cho hồ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Lại nói rằng: Nào! chúng ta hãy xây một cái thành và dựng lên một cái tháp, chót cao đến tận trời; ta hãy lo làm cho rạng danh, e khi phải tản lạc khắp trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Ðức Giê-hô-va bèn ngự xuống đặng xem cái thành và tháp của con cái loài người xây nên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Ðức Giê-hô-va phán rằng: Nầy, chỉ có một thứ dân, cùng đồng một thứ tiếng; và kia kìa công việc chúng nó đương khởi làm; bây giờ chẳng còn chi ngăn chúng nó làm các điều đã quyết định được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Thôi! chúng ta, hãy xuống, làm lộn xộn tiếng nói của chúng nó, cho họ nghe không được tiếng nói của người nầy với người kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Rồi, từ đó Ðức Giê-hô-va làm cho loài người tản ra khắp trên mặt đất, và họ thôi công việc xây cất thành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Bởi cớ đó đặt tên thành là Ba-bên, vì nơi đó Ðức Giê-hô-va làm lộn xộn tiếng nói của cả thế gian, và từ đây Ngài làm cho loài người tản ra khắp trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Ðây là dòng dõi của Sem: Cách hai năm, sau cơn nước lụt, Sem được một trăm tuổi, sanh A-bác-sát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Sau khi Sem sanh A-bác-sát rồi, còn sống được năm trăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'A-bác-sát được ba mươi lăm tuổi, sanh Sê-lách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Sau khi A-bác-sát sanh Sê-lách rồi, còn sống được bốn trăm ba năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Sê-lách được ba mươi tuổi, sanh Hê-be.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Sau khi Sê-lách sanh Hê-be rồi, còn sống được bốn trăm ba năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Hê-be được ba mươi bốn tuổi, sanh Bê-léc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Sau khi Hê-be sanh Bê-léc rồi, còn sống được bốn trăm ba mươi năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Bê-léc được ba mươi tuổi, sanh Rê-hu');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Sau khi Bê-léc sanh Rê-hu rồi, còn sống được hai trăm chín năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Rê-hu được ba mươi hai tuổi, sanh Sê-rúc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Sau khi Rê-hu sanh Sê-rúc rồi, còn sống được hai trăm bảy năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Sê-rúc được ba mươi tuổi, sanh Na-cô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Sau khi Sê-rúc sanh Na-cô rồi, còn sống được hai trăm năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Na-cô được hai mươi chín tuổi, sanh Tha-rê.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Sau khi Na-cô sanh Tha-rê rồi, còn sống được một trăm mười chín năm, sanh con trai con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Còn Tha-rê được bảy mươi tuổi, sanh Áp-ram, Na-cô và Ha-ran.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Ðây là dòng dõi của Tha-rê: Tha-rê sanh Áp-ram, Na-cô và Ha-ran; Ha-ran sanh Lót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Ha-ran qua đời tại quê hương mình, tức là U-ru, thuộc về xứ Canh-đê, khi cha người là Tha-rê hãy còn sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Áp-ram và Na-cô cưới vợ; vợ Áp-ram tên là Sa-rai, còn vợ Na-cô tên là Minh-ca; Minh-ca và Dích-ca tức là con gái của Ha-ran.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Vả, Sa-rai son sẻ, nên người không có con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Tha-rê dẫn Áp-ram, con trai mình, Lót, con trai Ha-ran, cháu mình, và Sa-rai, vợ Áp-ram, tức dâu mình, đồng ra khỏi U-rơ, thuộc về xứ Canh-đê, đặng qua xứ Ca-na-an. Khi đến Cha-ran thì lập gia cư tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Tha-rê hưởng thọ được hai trăm năm tuổi, rồi qua đời tại Cha-ran.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Vả, Ðức Giê-hô-va có phán cùng Áp-ram rằng: Ngươi hãy ra khỏi quê hương, vòng bà con và nhà cha ngươi, mà đi đến xứ ta sẽ chỉ cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Ta sẽ làm cho ngươi nên một dân lớn; ta sẽ ban phước cho ngươi, cùng làm nổi danh ngươi, và ngươi sẽ thành một nguồn phước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Ta sẽ ban phước cho người nào chúc phước cho ngươi, rủa sả kẻ nào rủa sả ngươi; và các chi tộc nơi thế gian sẽ nhờ ngươi mà được phước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Rồi Áp-ram đi, theo như lời Ðức Giê-hô-va đã phán dạy; Lót đồng đi với người. Khi Áp-ram ra khỏi Cha-ran, tuổi người được bảy mươi lăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Áp-ram dẫn Sa-rai, vợ mình, Lót, cháu mình, cả gia tài đã thâu góp, và các đầy tớ đã được tại Cha-ran, từ đó ra, để đi đến xứ Ca-na-an; rồi, chúng đều đến xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Áp-ram trải qua xứ nầy, đến cây dẻ bộp của Mô-rê, tại Si-chem. Vả, lúc đó, dân Ca-na-an ở tại xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Ðức Giê-hô-va hiện ra cùng Áp-ram mà phán rằng: Ta sẽ ban cho dòng dõi ngươi đất nầy! Rồi tại đó Áp-ram lập một bàn thờ cho Ðức Giê-hô-va, là Ðấng đã hiện đến cùng người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Từ đó, người đi qua núi ở về phía đông Bê-tên, rồi đóng trại; phía tây có Bê-tên, phía đông có A-hi. Ðoạn, người lập tại đó một bàn thờ cho Ðức Giê-hô-va và cầu khẩn danh Ngài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Kế sau, Áp-ram vừa đi vừa đóng trại lần lần đến Nam phương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Bấy giờ, trong xứ bị cơn đói kém; sự đói kém ấy lớn, nên Áp-ram xuống xứ Ê-díp-tô mà kiều ngụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Khi hầu vào đất Ê-díp-tô, Áp-ram bèn nói cùng Sa-rai, vợ mình, rằng: Nầy, ta biết ngươi là một người đờn bà đẹp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Gặp khi nào dân Ê-díp-tô thấy ngươi, họ sẽ nói rằng: Ấy là vợ hắn đó; họ sẽ giết ta, nhưng để cho ngươi sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Ta xin hãy xưng ngươi là em gái ta, hầu cho sẽ vì ngươi mà ta được trọng đãi và giữ toàn mạng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Áp-ram vừa đến xứ Ê-díp-tô, dân Ê-díp-tô nhìn thấy người đờn bà đó đẹp lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Các triều thần của Pha-ra-ôn cùng thấy người và trằm-trồ trước mặt vua; đoạn người đờn bà bị dẫn vào cung Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Vì cớ người, nên Pha-ra-ôn hậu đãi Áp-ram, và Áp-ram được nhiều chiên, bò, lừa đực, lừa cái, lạc đà, tôi trai và tớ gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Song vì Sa-rai, vợ Áp-ram, nên Ðức Giê-hô-va hành phạt Pha-ra-ôn cùng nhà người bị tai họa lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Pha-ra-ôn bèn đòi Áp-ram hỏi rằng: Ngươi đã làm chi cho ta vậy? Sao không tâu với ta rằng là vợ ngươi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Sao đã nói rằng: người đó là em gái tôi? nên nỗi ta đã lấy nàng làm vợ. Bây giờ, vợ ngươi đây; hãy nhận lấy và đi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Ðoạn, Pha-ra-ôn hạ lịnh cho quan quân đưa vợ chồng Áp-ram cùng hết thảy tài vật của người đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Áp-ram ở Ê-díp-tô dẫn vợ cùng các tài vật mình và Lót đồng trở lên Nam phương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Vả, Áp-ram rất giàu có súc vật, vàng và bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'người vừa đi vừa đóng trại, từ Nam phương trở về Bê-tên và A-hi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'là nơi đã lập một bàn thờ lúc trước. Ở đó Áp-ram cầu khẩn danh Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Vả, Lót cùng đi với Áp-ram, cũng có chiên, bò, và trại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Xứ đó không đủ chỗ cho hai người ở chung, vì tài vật rất nhiều cho đến đỗi không ở chung nhau được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Trong khi dân Ca-na-an và dân Phê-rê-sít ở trong xứ, xảy có chuyện tranh giành của bọn chăn chiên Áp-ram cùng bọn chăn chiên Lót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Áp-ram nói cùng Lót rằng: Chúng ta là cốt nhục, xin ngươi cùng ta chẳng nên cãi lẫy nhau và bọn chăn chiên ta cùng bọn chăn chiên ngươi cũng đừng tranh giành nhau nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Toàn xứ há chẳng ở trước mặt ngươi sao? Vậy, hãy lìa khỏi ta; nếu ngươi lấy bên hữu, ta sẽ qua bên tả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Lót bèn ngước mắt lên, thấy khắp cánh đồng bằng bên sông Giô-đanh, là nơi (trước khi Ðức Giê-hô-va chưa phá hủy thành Sô-đôm và Gô-mô-rơ) thảy đều có nước chảy tưới khắp đến Xoa; đồng ó cũng như vườn của Ðức Giê-hô-va và như xứ Ê-díp-tô vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Lót bèn chọn lấy cho mình hết cánh đồng bằng bên sông Giô-đanh và đi qua phía Ðông. Vậy, hai người chia rẽ nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Áp-ram ở trong xứ Ca-na-an, còn Lót ở trong thành của đồng bằng và dời trại mình đến Sô-đôm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Vả, dân Sô-đôm là độc ác và kẻ phạm tội trọng cùng Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Sau khi Lót lìa khỏi Áp-ram rồi, Ðức Giê-hô-va phán cùng Áp-ram rằng: Hãy nhướng mắt lên, nhìn từ chỗ ngươi cho đến phương bắc, phương nam, phương đông và phương tây:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Vì cả xứ nào ngươi thấy, ta sẽ ban cho ngươi và cho dòng dõi ngươi đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Ta sẽ làm cho dòng dõi ngươi như bụi trên đất; thế thì, nếu kẻ nào đếm đặng dòng dõi ngươi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Hãy đứng dậy đi khắp trong xứ, bề dài và bề ngang; vì ta sẽ ban cho ngươi xứ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Ðoạn áp-ram đời trại mình đến ở nơi lùm cây dẻ bộp tại Mam-rê, thuộc về Hếp-rôn, và lập tại đó một bàn thờ cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Trong đời Am-ra-phên, vua Si-nê-a; A-ri-óc, vua Ê-la-sa; Kết-rô-Lao me, vua Ê-lam, và Ti-đanh, vua Gô-im,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'bốn vua hiệp lại tranh chiến cùng Bê-ra, vua Sô-đôm; Bi-rê-sa, vua Gô-mô-rơ; Si-nê-áp, vua Át-ma; Sê-mê-bê, vua Xê-bô-im, và vua Bê-la, tức là Xoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Các vua nầy hiệp lại tại trũng Si-điêm, bây giờ là biển muối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Trong mười hai năm các vua nầy đều là chư-hầu của vua Kết-rô-Lao me; nhưng qua năm thứ mười ba, thì họ dấy loạn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Nhằm năm thứ mười bốn, Kết-rô-Lao-me cùng các vua đồng minh kéo quân đến dẹp dân Rê-pha-im ở đất Ách-tê-rót-Ca-na-im, dân Xu-xin tại đất Ham, dân Ê-mim ở trong đồng bằng Ki-ri-a-ta-im,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'và dân Hô-rít tại núi Sê -i-rơ, cho đến nơi Eân-Ba-ran, ở gần đồng vắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Ðoạn, các vua thâu binh trở về, đến Suối Xử đoán, tức Ca-đe, hãm đánh khắp miền dân A-ma-léc, và dân A-mô-rít ở tại Hát-sát sôn-Tha-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Các vua của Sô-đôm, Gô-mô-rơ, Át-ma, Xê-bô-im và vua Bê-la, tức là Xoa, bèn xuất trận và dàn binh đóng tại trũng Si-điêm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'đặng chống cự cùng Kết-rô-Lao-me, vua Ê-lam; Ti-đanh, vua Gô-im; Am-ra-phên, vua Si-nê-a, và A-ri-óc, vua Ê-la-sa; bốn vị đương địch cùng năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Vả, trong trũng Si-điêm có nhiều hố nhựa chai; vua Sô-đôm và vua Gô-mô-rơ thua chạy, sa xuống hố, còn kẻ nào thoát được chạy trốn trên núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Bên thắng trận bèn cướp lấy hết của cải và lương thực của Sô-đôm và Gô-mô-rơ, rồi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Giặc cũng bắt Lót, là cháu của Áp-ram, ở tại Sô-đôm, và hết thảy gia tài người, rồi đem đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Có một người thoát được chạy đến báo điều đó cùng Áp-ram, là người Hê-bơ-rơ. Áp-ram ở tại lùm cây dẻ bộp của Mam-rê, là người A-mô-rít, anh của Ếch-côn và A-ne; ba người nầy đã có kết-ước cùng Áp-ram.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Khi Áp-ram hay được cháu mình bị quân giặc bắt, bèn chiêu tập ba trăm mười tám gia nhân đã tập luyện, sanh đẻ nơi nhà mình, mà đuổi theo các vua đó đến đất Ðan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Ðoạn Áp-ram chia bọn đầy tớ mình ra, thừa ban đêm xông hãm quân nghịch, đánh đuổi theo đến đất Hô-ba ở về phía tả Ða-mách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Người thâu về đủ hết các tài vật mà quân giặc đã cướp lấy; lại cũng dẫn cháu mình, là Lót cùng gia tài người, đờn bà và dân chúng trở về.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Sau khi Áp-ram đánh bại Kết-rô-Lao-me và các vua đồng minh, thắng trận trở về, thì vua Sô-đôm ra đón rước người tại trũng Sa-ve, tức là trũng Vua.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Mên-chi-xê-đéc, vua Sa-lem, sai đem bánh và rượu ra. Vả, vua nầy là thầy tế lễ của Ðức Chúa Trời Chí cao,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'chúc phước cho Áp-ram và nói rằng: Nguyện Ðức Chúa Trời Chí cao, là Ðấng dựng nên trời và đất, ban phước cho Áp-ram!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Ðáng ngợi khen thay Ðức Chúa Trời Chí cao đã phó kẻ thù nghịch vào tay ngươi! Ðoạn, Áp-ram lấy một phần mười về cả của giặc mà dâng cho vua đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Vua Sô-đôm bèn nói cùng Áp-ram rằng: Hãy giao người cho ta, còn của cải, thì ngươi thâu lấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Áp-ram đáp lại rằng: Tôi giơ tay lên trước mặt Giê-hô-va Ðức Chúa Trời Chí cao, Chúa Tể của trời và đất, mà thề rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Hễ của chi thuộc về vua, dầu đến một sợi chỉ, hay là một sợi dây giày đi nữa, tôi cũng chẳng hề lấy; e vua nói được rằng: Nhờ ta làm cho Áp-ram giàu có,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'chỉ món chi của những người trẻ đã ăn, và phần của các người cùng đi với tôi, là A-ne, Ếch-côn và Mam-rê; về phần họ, họ hãy lấy phần của họ đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Sau các việc đó, trong sự hiện thấy có lời Ðức Giê-hô-va phán cùng Áp-ram rằng: Hỡi Áp-ram! ngươi chớ sợ chi; ta đây là một cái thuẫn đỡ cho ngươi; phần thưởng của ngươi sẽ rất lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Áp-ram thưa rằng: Lạy Chúa Giê-hô-va, Chúa sẽ cho tôi chi? Tôi sẽ chết không con, kẻ nối nghiệp nhà tôi là Ê-li-ê-se, người Ða-mách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Áp-ram lại nói rằng: Nầy, Chúa làm cho tôi tuyệt-tự; một kẻ tôi tớ sanh đẻ tại nhà tôi sẽ làm người kế nghiệp tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Ðức Giê-hô-va bèn phán cùng Áp-ram rằng: Kẻ đó chẳng phải là kẻ kế nghiệp ngươi đâu, nhưng ai ở trong gan ruột ngươi ra, sẽ là người kế nghiệp ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Ðoạn, Ngài dẫn người ra ngoài và phán rằng: Ngươi hãy ngó lên trời, và nếu ngươi đếm được các ngôi sao thì hãy đếm đi. Ngài lại phán rằng: Dòng dõi ngươi cũng sẽ như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Áp-ram tin Ðức Giê-hô-va, thì Ngài kể sự đó là công bình cho người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Ðức Giê-hô-va lại phán cùng Áp-ram rằng: Ta là Ðức Giê-hô-va, Ðấng đã dẫn ngươi ra khỏi U-rơ, thuộc về xứ Canh-đê, để ban cho ngươi xứ nầy làm sản nghiệp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Áp-ram thưa rằng: Lạy Chúa Giê-hô-va, bởi cớ chi tôi biết rằng tôi sẽ được xứ nầy làm sản nghiệp?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Ðức Giê-hô-va đáp rằng: Ngươi hãy bắt đem cho ta một con bò cái ba tuổi, một con dê cái ba tuổi, một con chiên đực ba tuổi, một con cu rừng và một con bò câu con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Áp-ram bắt đủ các loài vật đó, mổ làm hai, để mỗi nửa con mỗi bên đối với nhau, nhưng không mổ các loài chim ra làm hai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Có những chim ăn mồi bay đáp trên mấy con thú chết đó, song Áp-ram đuổi nó đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Vả, khi mặt trời vừa lặn, thì Áp-ram ngủ mê; nầy một cơn kinh hãi, tối tăm nhập vào mình người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Ðức Giê-hô-va phán cùng Áp-ram rằng: Phải biết rằng, dòng dõi ngươi sẽ ngụ trong một xứ chẳng thuộc về chúng nó, làm tôi mọi cho dân xứ đó và bị họ hà hiếp bốn trăm năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Nhưng, ta sẽ đoán phạt dân mà dòng dõi ngươi sẽ làm tôi mọi đó; rồi khi ra khỏi xứ, thì sẽ được của cải rất nhiều.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Còn ngươi sẽ bình yên về nơi tổ phụ, hưởng lộc già sung sướng, rồi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Ðến đời thứ tư, dòng dõi ngươi sẽ trở lại đây, vì tội lỗi của dân A-mô-rít chưa được đầy dẫy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Khi mặt trời đã lặn, thình lình sự tối mịt giáng xuống; kìa có một lò lớn khói lên, và một ngọn lửa lòe ngang qua các xác thịt đã mổ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Ngày đó, Ðức Giê-hô-va lập giao ước cùng Áp-ram, mà phán rằng: Ta cho dòng dõi ngươi xứ nầy, từ sông Ê-díp-tô cho đến sông lớn kia, tức sông Ơ-phơ-rát,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'là xứ của các dân Kê-nít, Kê-nê-sít, Cát-mô-nít');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Hê-tít, Phê-rê-sít, Rê-pha-im,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'A-mô-nít, Ca-na-an, Ghi-ê-ga-sít và Giê-bu-sít.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Vả, Sa-rai, vợ của Áp-ram, vẫn không sanh con; nàng có một con đòi Ê-díp-tô, tên là A-ga.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Sa-rai nói cùng Áp-ram rằng: Nầy, Ðức Giê-hô-va đã làm cho tôi son sẻ, vậy xin ông hãy lại ăn ở cùng con đòi tôi, có lẽ tôi sẽ nhờ nó mà có con chăng. Áp-ram bèn nghe theo lời của Sa-rai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Sau khi Áp-ram đã trú ngụ mười năm tại xứ Ca-na-an, Sa-rai, vợ người, bắt A-ga, là con đòi Ê-díp-tô mình, đưa cho chồng làm hầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Người lại cùng con đòi, thì nàng thọ thai. Khi con đòi thấy mình thọ thai, thì khinh bỉ bà chủ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Sa-rai nói cùng Áp-ram rằng: Ðiều sỉ nhục mà tôi bị đây đổ lại trên ông. Tôi đã phú con đòi tôi vào lòng ông, mà từ khi nó thấy mình thọ thai, thì lại khinh tôi. Cầu Ðức Giê-hô-va xét đoán giữa tôi với ông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Áp-ram đáp cùng Sa-rai rằng: Nầy, con đòi đó ở trong tay ngươi, phân xử thể nào, mặc ý ngươi cho vừa dạ. Ðoạn Sa-rai hành hạ A-ga, thì nàng trốn đi khỏi mặt người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Nhưng thiên sứ của Ðức Giê-hô-va thấy nàng ở trong đồng vắng gần bên suối nước, nơi mé đường đi và Su-rơ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'thì hỏi rằng: Hỡi A-ga, đòi của Sa-rai, ngươi ở đâu đến, và sẽ đi đâu? Nàng thưa rằng: Tôi lánh xa mặt Sa-rai, chủ tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Thiên sứ của Ðức Giê-hô-va dạy nàng rằng: Ngươi hãy trở về chủ ngươi, và chịu lụy dưới tay người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Thiên sứ của Ðức Giê-hô-va lại phán rằng: Ta sẽ thêm dòng dõi ngươi nhiều, đông đảo đến đỗi người ta đếm không đặng nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Lại phán rằng: Nầy, ngươi đương có thai, sẽ sanh một trai, đặt tên là Ích-ma-ên; vì Ðức Giê-hô-va có nghe sự sầu khổ của ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Ðứa trẻ đó sẽ như một con lừa rừng; tay nó sẽ địch cùng mọi người, và tay mọi người sẽ địch lại nó. Nó sẽ ở về phía đông đối mặt cùng hết thảy anh em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Nàng gọi Ðức Giê-hô-va mà đã phán cùng mình, danh là \"Ðức Chúa Trời hay đoái xem,\" vì nàng nói rằng: Chính tại đây, tôi há chẳng có thấy được Ðắng đoái xem tôi sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Bởi cớ ấy, người ta gọi cái giếng nầy ở về giữa khoảng của Ca-đe và Bê-re, là giếng La-chai-Roi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Rồi nàng A-ga sanh được một con trai; Áp-ram đặt tên đứa trai đó là Ích-ma-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Vả lại, khi A-ga sanh Ích-ma-ên cho Áp-ram, thì Áp-ram đã được tám mươi sáu tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Khi Áp-ram được chín mươi chín tuổi, thì Ðức Giê-hô-va hiện đến cùng người và phán rằng: Ta là Ðức Chúa Trời toàn năng; ngươi hãy đi ở trước mặt ta làm một người trọn vẹn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ta sẽ lập giao ước cùng ngươi, làm cho dòng dõi ngươi thêm nhiều quá-bội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Áp-ram bèn sấp mình xuống đất; Ðức Chúa Trời phán cùng người rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Nầy, phần ta đây, ta đã lập giao ước cùng ngươi; vậy ngươi sẽ trở nên tổ phụ của nhiều dân tộc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Thiên hạ chẳng còn gọi ngươi là Áp-ram nữa, nhưng tên ngươi là Áp-ra-ham, vì ta đặt ngươi làm tổ phụ của nhiều dân tộc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Ta sẽ làm cho ngươi sanh sản rất nhiều, làm cho ngươi thành nhiều nước; và các vua sẽ do nơi ngươi mà ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Ta sẽ lập giao ước cùng ngươi, và cùng hậu tự ngươi trải qua các đời; ấy là giao ước đời đời, hầu cho ta làm Ðức Chúa Trời của ngươi và của dòng dõi ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Ta sẽ cho ngươi cùng dòng dõi ngươi xứ mà ngươi đương kiều ngụ, tức toàn xứ Ca-na-an, làm cơ nghiệp đời đời. Vậy, ta sẽ làm Ðức Chúa Trời của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Ðoạn, Ðức Chúa Trời phán cùng Áp-ra-ham rằng: Phần ngươi cùng dòng dõi ngươi, từ đời nọ sang đời kia, sẽ giữ sự giao ước của ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Mỗi người nam trong vòng các ngươi phải chịu phép cắt bì; ấy là giao ước mà các ngươi phải giữ, tức giao ước lập giữa ta và các ngươi, cùng dòng dõi sau ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Các ngươi phải chịu cắt bì; phép đó sẽ là dấu hiệu của sự giao ước giữa ta cùng các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Trải qua các đời, mỗi người nam trong vòng các ngươi, hoặc sanh đẻ tại nhà, hoặc đem tiền ra mua nơi người ngoại bang, chẳng thuộc về dòng giống ngươi, hễ lên được tám ngày rồi, đều phải chịu phép cắt bì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Chớ khá bỏ làm phép cắt bì cho ai sanh tại trong nhà ngươi, hay đem tiền ra mua về; sự giao ước của ta sẽ lập đời đời trong xác thịt của các ngươi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Một người nam nào không chịu phép cắt bì nơi xác thịt mình, sẽ bị truất ra khỏi ngoài dân sự mình; người đó là kẻ bội lời giao ước ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Ðức Chúa Trời phán cùng Áp-ra-ham rằng: còn Sa-rai, vợ ngươi, chớ gọi là Sa-rai nữa; nhưng Sa-ra là tên người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ta sẽ ban phước cho nàng, lại do nơi nàng ta sẽ cho ngươi một con trai, Ta sẽ ban phước cho nàng, nàng sẽ làm mẹ các dân tộc; những vua của các dân tộc sẽ do nơi nàng mà ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Áp-ra-ham bèn sấp mình xuống đất, cười và nói thầm rằng: Hồ dễ người đã trăm tuổi rồi, mà sanh con được chăng? Còn Sa-ra, tuổi đã chín mươi, sẽ sanh sản được sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Áp-ra-ham thưa cùng Ðức Chúa Tr»»i rằng: Chớ chi Ích-ma-ên vẫn được sống trước mặt Ngài!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Ðức Chúa Trời bèn phán rằng: Thật vậy, Sa-ra vợ ngươi, sẽ sanh một con trai, rồi ngươi đặt tên là Y-sác. Ta sẽ lập giao ước cùng nó, để làm giao ước đời đời cho dòng dõi của nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Ta cũng nhậm lời ngươi xin cho Ích-ma-ên. Nầy, ta ban phước cho người, sẽ làm cho người sanh sản và thêm nhiều quá-bội; người sẽ là tổ phụ của mười hai vị công-hầu, và ta làm cho người thành một dân lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Nhưng ta sẽ lập giao ước ta cùng Y-sác, độ khoảng nầy năm tới Sa-ra phải sanh cho ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Khi Ðức Chúa Trời đã phán xong, thì Ngài từ Áp-ra-ham ngự lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Chánh ngày đó, Áp-ra-ham bắt Ích-ma-ên, con trai mình, và hết thảy các người nam trong nhà, hoặc sanh tại đó, hoặc đem tiền ra mua về, mà làm phép cắt bì cho, y như lời Ðức Chúa Trời đã phải dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Vả, khi Áp-ra-ham chịu phép cắt bì, thì đã được chín mươi chín tuổi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'còn Ích-ma-ên, con người, khi chịu phép cắt bì, thì được mười ba tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Cũng trong một ngày đó, Áp-ra-ham và Ích-ma-ên chịu phép cắt bì,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'và mọi người nam trong nhà, hoặc sanh tại đó, hoặc đem tiền ra mua nơi người ngoại bang, đồng chịu phép cắt bì với người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Ðức Giê-hô-va hiện ra cùng Áp-ra-ham nơi lùm cây dẻ bộp của Mam-rê, đương khi ngồi nơi cửa trại lúc trời nắng ban ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Áp-ra-ham nhướng mắt lên, thấy ba người đứng trước mặt. Vừa khi thấy, bèn bắt từ cửa trại chạy đến trước mặt ba người đó, sấp mình xuống đất,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'và thưa rằng: Lạy Chúa, nếu tôi được ơn trước mặt Chúa, xin hãy ghé lại nhà kẻ tôi tớ Chúa, đừng bỏ đi luôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Xin các đấng hãy cho phép người ta lấy chút nước rửa chơn các đấng, và xin hãy nằm nghỉ mát dưới cội cây nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Tôi sẽ đi đem một miếng bánh cho các đấng ăn vững lòng, rồi sẽ dời gót lên đường; vì cớ ấy, nên mới quá bộ lại nhà kẻ tôi tớ các đấng vậy. Các đấng phán rằng: Hãy cứ việc làm như ngươi đã nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Ðoạn, Áp-ra-ham lật đật vào trại đến cùng Sa-ra mà rằng: Hãy mau mau lấy ba đấu bột lọc nhồi đi, rồi làm bánh nhỏ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Áp-ra-ham bèn chạy lại bầy, bắt một con bò con ngon, giao cho đầy tớ mau mau nấu dọn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'rồi lấy mỡ-sữa và sữa cùng con bò con đã nấu xong, dọn ngay trước mặt các đấng; còn người thì đứng hầu trước mặt, dưới cội cây. Vậy các đấng đó bèn ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Các đấng hỏi Áp-ra-ham rằng: Sa-ra, vợ ngươi, ở đâu? Ðáp rằng: Kìa, nàng ở trong trại kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Một đấng nói rằng: Trong độ một năm nữa, ta sẽ trở lại đây với ngươi không sai, và chừng đó, Sa-ra, vợ ngươi, sẽ có một con trai. Sa-ra ở nơi cửa trại sau lưng đấng đó, nghe các lời nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Vả, Áp-ra-ham cùng Sa-ra đã già, tuổi tác đã cao; Sa-ra không còn chi nữa như thế thường người đờn bà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sa-ra cười thầm mà rằng: Già như tôi thế nầy, dễ còn được điều vui đó sao? Còn chúa tôi cũng đã già rồi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Ðức Giê-hô-va phán hỏi Áp-ra-ham rằng: Cớ sao Sa-ra cười như vậy mà rằng: Có quả thật rằng tôi già đến thế nầy lại còn sanh sản chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Há điều chi Ðức Giê-hô-va làm không được chăng? Ðến kỳ đã định, trong một năm nữa, ta sẽ trở lại cùng ngươi, và Sa-ra sẽ có một con trai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Vì Sa-ra sợ, nên chối mà thưa rằng: Tôi có cười đâu! Nhưng Ngài phán rằng: Thật ngươi có cười đó!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Các đấng đều đứng dậy mà đi, ngó về phía, Sô-đôm. Áp-ra-ham cũng theo để tiễn bước các đấng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Ðức Giê-hô-va phán rằng: Lẽ nào ta giấu Áp-ra-ham điều chi ta sẽ làm sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'vì Áp-ra-ham chắc sẽ được trở nên một dân lớn và cường thạnh; các dân tộc trên thế gian đều sẽ nhờ người mà được phước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Ta đã chọn người đặng người khiến dạy các con cùng nội nhà người giữ theo đạo Ðức Giê-hô-va, làm các điều công bình và ngay thẳng; thế thì, Ðức Giê-hô-va sẽ làm cho ứng nghiệm lời Ngài đã hứa cùng Áp-ra-ham.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Ðức Giê-hô-va phán rằng: Tiếng kêu oan về Sô-đôm và Gô-mô-rơ thật là quá, tội lỗi các thành đó thật là trọng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Ta muốn ngự xuống, để xem xét chúng nó ăn ở có thật như tiếng đã kêu thấu đến ta chăng; nếu chẳng thật, thì ta sẽ biết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Vậy, thì đấng bèn từ đó đi qua hướng Sô-đôm; nhưng Áp-ra-ham hãy còn đứng chầu trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Áp-ra-ham lại gần và thưa rằng: Chúa sẽ diệt người công bình luôn với người độc ác sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Ngộ trong thành có năm mươi người công bình, Chúa cũng sẽ diệt họ hết sao? Há chẳng tha thứ cho thành đó vì cớ năm mươi người công bình ở trong sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Không lẽ nào Chúa làm điều như vậy, diệt người công bình luôn với kẻ độc ác; đến đỗi kể người công bình cũng như người độc ác. Không, Chúa chẳng làm điều như vậy bao giờ! Ðấng đoán xét toàn thế gian, há lại không làm sự công bình sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Ðức Giê-hô-va phán rằng: Nếu ta tìm được trong Sô-đôm năm mươi người công bình, vì tình thương bấy nhiêu người đó ta sẽ tha hết cả thành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Áp-ra-ham lại thưa rằng: mặc dầu tôi đây vốn là tro bụi, song tôi cũng dám cả gan thưa lại cùng Chúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Hãy trong năm mươi người công bình rủi thiếu hết năm; vì cớ năm người thiếu Chúa sẽ diệt hết cả thành chăng? Ngài trả lời rằng: Nếu ta tìm được có bốn mươi lăm người, ta chẳng diệt thành đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Áp-ra-ham cứ thưa rằng: Ngộ trong thành chỉ có bốn mươi người công bình, thì sẽ ra sao? Ngài phán rằng: Ta sẽ chẳng diệt đâu, vì tình thương bốn mươi nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Áp-ra-ham cứ tiếp: Tôi xin Chúa đừng giận, thì tôi sẽ thưa: Ngộ trong đó chỉ có ba mươi người, thì sẽ ra sao? Ngài phán: Nếu ta tìm trong đó có ba mươi người, thì ta chẳng diệt đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Áp-ra-ham thưa rằng: Tôi đây cũng cả gan thưa cùng Chúa: Nếu chỉ có hai mươi người, thì lại làm sao? Ngài rằng: Vì tình thương hai mươi người đó, ta sẽ chẳng diệt thành đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Áp-ra-ham lại thưa: Xin Chúa đừng giận, để cho tôi thưa chỉ một lần nầy nữa: Ngộ chỉ có mười người, thì nghĩ làm sao? Ngài phán rằng: Ta cũng sẽ chẳng diệt thành đâu, vì tình thương mười người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Khi Ðức Giê-hô-va phán xong cùng Áp-ra-ham, thì Ngài ngự đi; còn Áp-ra-ham trở về trại mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Lối chiều, hai thiên sứ đến Sô-đôm; lúc đó, Lót đương ngồi tại cửa thành. Khi Lót thấy hai thiên sứ đến, đứng dậy mà đón rước và sấp mình xuống đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Người thưa rằng: Nầy, lạy hai chúa, xin hãy đến ở nhà của kẻ tôi tớ, và hãy nghỉ đêm tại đó. Hai chúa hãy rửa chơn, rồi sáng mai thức dậy lên đường. Hai thiên sứ phán rằng: Không, đêm nầy ta sẽ ở ngoài đường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Nhưng Lót cố mời cho đến đỗi hai thiên sứ phải đi lại vào nhà mình. Người dâng một bữa tiệc, làm bánh không men, và hai thiên sứ bèn dùng tiệc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Hai thiên sứ chưa đi nằm, mà các người nam ở Sô-đôm, từ trẻ đến già, tức cả dân, đều chạy đến bao chung quanh nhà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Bọn đó gọi Lót mà hỏi rằng: Những khác đã vào nhà ngươi buổi chiều tối nay ở đâu? Hãy dẫn họ ra đây, hầu cho chúng ta được biết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lót bèn ra đến cùng dân chúng ở ngoài cửa, rồi đóng cửa lại,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'và nói cùng họ rằng: Nầy, tôi xin anh em đừng làm điều ác đó!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Ðây, tôi sẵn có hai con gái chưa chồng, tôi sẽ đưa chúng nó cho anh em, rồi mặc tình anh em tính làm sao tùy ý; miễn đừng làm cho hại cho hai người kia; vì cớ đó, nên họ đến núp bóng mái nhà tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Bọn dân chúng nói rằng: Ngươi hãy tránh chỗ khác! Lại tiếp rằng: Người nầy đến đây như kẻ kiều ngụ, lại muốn đoán xét nữa sao! Vậy, thôi! chúng ta sẽ đãi ngươi bạc-tệ hơn hai khách kia. Ðoạn, họ lấn ép Lót mạnh quá, và tràn đến đặng phá cửa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Nhưng hai thiên sứ giơ tay ra, đem Lót vào nhà, và đóng cửa lại,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'đoạn, hành phạt bọn dân chúng ở ngoài cửa, từ trẻ đến già, đều quáng lòa mắt, cho đến đỗi tìm cửa mệt mà không được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Hai thiên sứ bèn hỏi Lót rằng: Ngươi còn có ai tại đây nữa chăng? Rể, con trai, con gái và ai trong thành thuộc về ngươi, hãy đem ra khỏi hết đi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Chúng ta sẽ hủy diệt chỗ nầy, vì tiếng kêu oan về dân thành nầy đã thấu lên đến Ðức Giê-hô-va, nên Ngài sai chúng ta xuống mà hủy diệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Lót bèn đi ra và nói cùng rể đã cưới con gái mình rằng: Hãy chổi dậy, đi ra khỏi chốn nầy, vì Ðức Giê-hô-va sẽ hủy diệt thành. Nhưng các chàng rể tưởng người nói chơi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Ðến sáng, hai thiên sứ hối Lót và phán rằng: Hãy thức dậy, dẫn vợ và hai con gái ngươi đương ở đây ra, e khi ngươi cũng chết lây về việc hình phạt của thành nữa chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Nhưng Lót lần lữa; vì cớ Ðức Giê-hô-va thương xót Lót, nên hai thiên sứ nắm lấy tai kéo người, vợ cùng hai con gái người, và dẫn ra khỏi thành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Vả, khi hai thiên sứ dẫn họ ra khỏi rồi, một trong hai vì nói rằng: Hãy chạy trốn cứu lấy mạng, đừng ngó lại sau và cũng đừng dừng bước lại nơi nào ngoài đồng bằng; hãy chạy trốn lên núi, kẻo phải bỏ mình chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lót đáp lại rằng: Lạy Chúa, không được!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Nầy, tôi tớ đã được ơn trước mặt Chúa; Chúa đã tỏ lòng nhơn từ rất lớn cùng tôi mà cứu tròn sự sống tôi. Nhưng tôi chạy trốn lên núi không kịp trước khi tai nạn đến, thì tôi phải chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Kìa, thành kia đã nhỏ, lại cũng gần đặng tôi có thế ẩn mình. Ôi! chớ chi Chúa cho tôi ẩn đó đặng cứu tròn sự sống tôi. Thành nầy há chẳng phải nhỏ sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Thiên sứ phán rằng: Ðây, ta ban ơn nầy cho ngươi nữa, sẽ không hủy diệt thành của ngươi đã nói đó đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Mau mau hãy lại ẩn đó, vì ta không làm chi được khi ngươi chưa vào đến nơi. Bởi cớ ấy, nên người ta gọi tên thành nầy là Xoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Khi mặt trời mọc lên khỏi đất, thì Lót vào đến thành Xoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Ðoạn, Ðức Giê-hô-va giáng mưa diêm sanh và lửa từ nơi Ngài trên trời sa xuống Sô-đôm và Gô-mô-rơ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'hủy diệt hai thành nầy, cả đồng bằng, hết thảy dân sự cùng các cây cỏ ở nơi đất đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Nhưng vợ của Lót quay ngó lại đặng sau mình, nên hóa ra một tượng muối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Áp-ra-ham dậy sớm, đi đến nơi mà người đã đứng chầu Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'ngó về hướng Sô-đôm và Gô-mô-rơ, cùng khắp xứ ở đồng bằng, thì thấy từ dưới đất bay lên một luồng khói, như khói của một lò lửa lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Vả, khi Ðức Chúa Trời hủy diệt các thành nơi đồng bằng, tức là thành Lót ở, thì nhớ đến Áp-ra-ham, cứu Lót ra khỏi chốn phá tan đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lót ở Xoa thì sợ hãi, nên cùng hai con gái mình bỏ đó mà lên núi, ở trong một hang đá kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Cô lớn nói cùng em mình rằng: Cha ta đã già, mà không còn ai trên mặt đất đến sánh duyên cùng ta theo như thế thường thiên hạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Hè! chúng ta hãy phục rượu cho cha, và lại nằm cùng người, để lưu truyền dòng giống cha lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Ðêm đó, hai nàng phục rượu cho cha mình; nàng lớn đến nằm cùng cha; nhưng người chẳng hay lúc nào nàng nằm, lúc nào nàng dậy hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Qua ngày mai, chị nói cùng em rằng: Nầy, đêm hôm qua ta đã nằm cùng cha rồi; hôm nay chúng ta hãy phục rượu cho cha nữa, rồi em hãy lại nằm cùng người, để lưu truyền dòng giống cha lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Ðêm đó, hai nàng lại phục rượu cho cha mình nữa, rồi nàng nhỏ thức dậy lại nằm cùng cha; nhưng người chẳng hay lúc nào nàng nằm, lúc nào nàng dậy hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Vậy, hai con gái của Lót do nơi cha mình mà thọ thai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Nàng lớn sanh được một con trai, đặt tên là Mô-áp; ấy là tổ phụ của dân Mô-áp đến bây giờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Người em cũng sanh đặng một con trai, đặt trên là Bên-Am-mi; ấy là tổ phụ của dân Am-môn đến bây giờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Áp-ra-ham từ đó đi đến miền Nam, kiều ngụ tại Ghê-ra, ở về giữa khoảng Ca-đe và Su-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Áp-ra-ham nói về Sa-ra, vợ mình rằng: Nó là em gái tôi. A-bi-mê-léc, vua Ghê-ra sai người bắt Sa-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Nhưng trong cơn chiêm bao ban đêm, Ðức Chúa Trời hiện đến cùng vua A-bi-mê-léc mà phán rằng: Nầy, ngươi sẽ chết bởi cớ người đờn bà mà ngươi đã bắt đến; vì nàng có chồng rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Vả, vua A-bi-mê-léc chưa đến gần người đó, nên thưa rằng: Lạy Chúa, Chúa há sẽ hủy diệt cả một dân công bình chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Người đó há chẳng nói với tôi rằng: ấy là em gái tôi chăng? và chánh người nữ há chẳng nói rằng: ấy là anh tôi sao? Tôi làm sự nầy bởi lòng ngay thẳng và tay thanh khiết của tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Trong cơn chiêm bao, Ðức Chúa Trời phán nữa rằng: Ta cũng biết ngươi vì lòng ngay thẳng mà làm điều đó; bởi cớ ấy, ta mới ngăn trở ngươi phạm tội cùng ta, và không cho động đến người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Bây giờ, hãy giao đờn bà đó lại cho chồng nó, vì chồng nó là một đấng tiên tri, sẽ cầu nguyện cho ngươi, thì ngươi mới được sống. Còn như không giao lại, thì phải biết rằng ngươi và hết thảy ai thuộc về ngươi quả hẳn sẽ chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Vua A-bi-mê-léc dậy sớm, đòi các tôi tớ mình đến, thuật lại hết mọi lời, thì họ lấy làm kinh ngạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Rồi, A-bi-mê-léc đòi Áp-ra-ham mà nói rằng: Ngươi đã làm gì cho ta vậy? Ta có làm điều chi mất lòng chăng mà ngươi làm cho ta và cả nước phải bị một việc phạm tội lớn dường nầy? Ðối cùng ta, ngươi đã làm những việc không nên làm đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Vua A-bi-mê-léc lại nói cùng Áp-ra-ham rằng: Ngươi có ý gì mà làm như vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Áp-ra-ham đáp: Tôi tự nghĩ rằng: Trong xứ nầy thật không có ai kính sợ Ðức Chúa Trời, thì họ sẽ vì cớ vợ tôi mà giết tôi chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Nhưng nó cũng thật là em gái tôi, em một cha khác mẹ; và tôi cưới nó làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Khi Ðức Chúa Trời làm cho tôi phải lưu lạc xa nhà cha, thì tôi có nói với nàng rằng: Nầy là ơn của ngươi sẽ làm cho ta: Hễ chỗ nào chúng ta sẽ đi đến, hãy nói về ta: Ấy là anh tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Ðoạn, vua A-bi-mê-léc đem chiên và bò, tôi trai cùng tớ gái cho Áp-ra-ham, và trả Sa-ra vợ người lại, mà phán rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Nầy, xứ ta sẵn dành cho ngươi; ngươi thích đâu thì ở đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Rồi vua phán cùng Sa-ra rằng: Ðây, ta ban cho anh ngươi một ngàn miếng bạc; số tiền đó dùng cho ngươi như một bức màn che trước mắt về mọi việc đã xảy ra cùng ngươi; và mọi người đều sẽ cho ngươi là công bình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Áp-ra-ham cầu xin Ðức Chúa Trời, thì Ngài chữa bịnh cho vua A-bi-mê-léc, vợ cùng các con đòi người; vậy, họ đều có con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Vả, lúc trước, vì vụ Sa-ra, vợ Áp-ra-ham, nên Ðức Giê-hô-va làm cho cả nhà A-bi-mê-léc đều son sẻ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Ðức Giê-hô-va đến viếng Sa-ra, theo như lời Ngài đã phán, và làm cho nàng như lời Ngài đã nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sa-ra thọ thai, sanh một con trai cho Áp-ra-ham trong khi tuổi đã già, đúng kỳ Ðức Chúa Trời đã định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Áp-ra-ham đặt tên đứa trai mà Sa-ra đã sanh cho mình là Y-sác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Ðúng tám ngày, Áp-ra-ham làm phép cắt bì cho Y-sác theo như lời Ðức Chúa Trời đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Vả, khi Y-sác ra đời, thì Áp-ra-ham đã được một trăm tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Sa-ra nói rằng: Ðức Chúa Trời làm cho tôi một việc vui cười; hết thảy ai hay được cũng sẽ vui cười về sự của tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Lại nói rằng: Há ai dám nói với Áp-ra-ham rằng Sa-ra sẽ cho con bú ư? vì tôi đã sanh một đứa trai trong lúc người già yếu rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Ðứa trẻ lớn lên, thì thôi bú. Chánh ngày Y-sác thôi bú, Áp-ra-ham bày một tiệc lớn ăn mừng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Sa-ra thấy đứa trai của A-ga, người Ê-díp-tô, đã sanh cho Áp-ra-ham, cười cợt,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'thì người nói với Áp-ra-ham rằng: Hãy đuổi con đòi với con nó đi đi, vì đứa trai của con đòi nầy sẽ chẳng được kế nghiệp cùng con trai tôi là Y-sác đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Lời nầy lấy làm buồn lòng Áp-ra-ham lắm, vì cớ con trai mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Nhưng Ðức Chúa Trời phán cùng Áp-ra-ham rằng: Ngươi chớ buồn bực vì con trai và con đòi ngươi. Sa-ra nói thể nào, hãy nghe theo tiếng người nói; vì do nơi Y-sác sẽ sanh ra dòng dõi lưu danh ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Ta cũng sẽ làm cho đứa trai của con đòi trở nên một dân, vì nó cũng do một nơi ngươi mà ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Áp-ra-ham dậy sớm, lấy bánh và một bầu nước, đưa cho A-ga; để các món đó trên vai nàng, và giao đứa trai cho nàng, rồi đuổi đi. Nàng ra đi, đi dông dài trong đồng vắng Bê -e-Sê-ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Khi nước trong bầu đã hết, nàng để đứa trẻ dưới một cội cây nhỏ kia,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'đi ngồi đối diện cách xa xa dài chừng một khoảng tên bắn; vì nói rằng: Ôi! tôi nỡ nào thấy đứa trẻ phải chết! Nàng ngồi đối diện đó, cất tiếng la khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Ðức Chúa Trời nghe tiếng đứa trẻ khóc, thì thiên sứ của Ðức Chúa Trời từ trên trời kêu nàng A-ga mà phán rằng: Hỡi A-ga! Ngươi có điều gì vậy? Chớ sợ chi, vì Ðức Chúa Trời đã nghe tiếng đứa trẻ ở đâu đó rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Hãy đứng dậy đỡ lấy đứa trẻ và giơ tay nắm nó, vì ta sẽ làm cho nó nên một dân lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Ðoạn, Ðức Chúa Trời mở mắt nàng ra; nàng bèn thấy một cái giếng nước, và đi lại múc đầy bầu cho đứa trẻ uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Ðức Chúa Trời vùa giúp đứa trẻ; nó lớn lên, ở trong đồng vắng, có tài bắn cung.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Nó ở tại trong đồng vắng Pha-ran; mẹ cưới cho nó một người vợ quê ở xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Về thuở đó, vua A-bi-mê-léc và Phi-côn, quan tổng binh mình, nói cùng Áp-ra-ham rằng: Ðức Chúa Trời vùa giúp ngươi trong mọi việc ngươi làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Vậy bây giờ, hãy chỉ danh Ðức Chúa Trời mà thề rằng: Ngươi sẽ chẳng gạt ta, con ta cùng dòng giống ta. Nhưng ngươi sẽ đãi ta và xứ ngươi đương trú ngụ, một lòng tử tế như ta đã đãi ngươi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Áp-ra-ham đáp rằng: Tôi xin thề.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Áp-ra-ham phàn nàn cùng vua A-bi-mê-léc về vụ một giếng kia bị đầy tớ người chiếm đoạt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Vua A-bi-mê-léc bèn nói rằng: Ta chẳng hay ai đã làm nên nông nổi đó; chính ngươi chẳng cho ta hay trước; ngày nay ta mới rõ đây mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Ðoạn, Áp-ra-ham bắt chiên và bò, dâng cho vua A-bi-mê-léc; rồi hai người kết ước cùng nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Áp-ra-ham lựa để riêng ra bảy con chiên tơ trong bầy;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'thì vua A-bi-mê-léc hỏi rằng: Làm chi để bảy con chiên tơ đó riêng ra vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Ðáp rằng: Xin vua hãy nhận lấy bảy con chiên tơ nầy mà chánh tay tôi dâng cho, đặng làm chứng rằng tôi đã đào cái giếng nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Bởi cớ ấy, nên họ đặt tên chỗ nầy là Bê -e-Sê-ba; vì tại đó hai người đều đã thề nguyện cùng nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Vậy, hai người kết ước cùng nhau tại Bê -e-Sê-ba. Ðoạn vua A-bi-mê-léc cùng quan tổng binh Phi-côn đứng dậy, trở về xứ Phi-li-tin.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Áp-ra-ham trồng một cây me tại Bê -e-Sê-ba, và ở đó người cầu khẩn danh Ðức Giê-hô-va, là Ðức Chúa Trời hằng-hữu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Áp-ra-ham trú ngụ lâu ngày tại xứ Phi-li-tin.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Khi mọi việc kia đã xong, thì Ðức Chúa Trời thử Áp-ra-ham; Ngài phán rằng: Hỡi Áp-ra-ham! Người thưa rằng: Có tôi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Ðức Chúa Trời phán rằng: Hãy bắt đứa con một ngươi yêu dấu, là Y-sác, và đi đến xứ Mô-ri-a, nơi đó dâng đứa con làm của lễ thiêu ở trên một hòn núi kia mà ta sẽ chỉ cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Áp-ra-ham dậy sớm, thắng lừa, đem hai đầy tớ và con mình, là Y-sác, cùng đi; người cũng chặt củi để dùng về của lễ thiêu, rồi đi đến nơi mà Ðức Chúa Trời đã truyền dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Qua đến ngày thứ ba, Áp-ra-ham nhướng mắt lên thấy nơi đó ở lối đằng xa,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'thì nói cùng hai kẻ đầy tớ rằng: Hãy ở lại đây với con lừa; ta cùng đứa trẻ sẽ đi đến chốn kia đặng thờ phượng, rồi sẽ trở lại với hai ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Áp-ra-ham lấy củi về của lễ thiêu, chất trên Y-sác, con mình; rồi người cầm lửa và dao trong tay, và cả hai cha con đồng đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Y-sác bèn nói cùng Áp-ra-ham, cha mình rằng: Hỡi Cha! Người đáp: Con ơi! cha đây. Y-sác nói: Củi đây, lửa đây, nhưng chiên con đây có đặng làm của lễ thiêu?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Áp-ra-ham rằng: Con ơi! chính Ðức Chúa Trời sẽ sắm sẵn lấy chiên con đặng dùng làm của lễ thiêu; rồi cả hai cha con cứ đồng đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Họ đến chốn Ðức Chúa Trời đã phán dạy; tại đó, Áp-ra-ham lập bàn thờ, chất củi lên, trói Y-sác con mình lại, để lên đống củi trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Áp-ra-ham bèn giơ tay ra cầm lấy dao đặng giết con mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Thiên sứ của Ðức Giê-hô-va từ trên trời kêu xuống mà rằng: Hỡi Áp-ra-ham, Áp-ra-ham! Người thưa rằng: Có tôi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Thiên sứ phán rằng: Ðừng tra tay vào mình con trẻ và chớ làm chi hại đến nó; vì bây giờ ta biết rằng ngươi thật kính sợ Ðức Chúa Trời, bởi cớ không tiếc với ta con ngươi, tức con một ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Áp-ra-ham nhướng mắt lên, xem thấy sau lưng một con chiên đực, sừng mắc trong bụi cây, bèn bắt con chiên đực đó dâng làm của lễ thiêu thay cho con mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Áp-ra-ham gọi chỗ đó là Giê-hô-va Di-rê. Bởi cớ ấy, ngày nay có tục ngữ rằng: Trên núi của Ðức Giê-hô-va sẽ có sắm sẵn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Thiên sứ của Ðức Giê-hô-va từ trên trời kêu Áp-ra-ham lần thứ nhì mà rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Ðức Giê-hô-va phán rằng: Vì ngươi đã làm điều đó, không tiếc con ngươi, tức con một ngươi, thì ta lấy chánh mình ta mà thề rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'sẽ ban phước cho ngươi, thêm dòng dõi ngươi nhiều như sao trên trời, đông như cát bờ biển, và dòng dõi đó sẽ chiếm được cửa thành quân nghịch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Bởi vì ngươi đã vâng theo lời dặn ta, nên các dân thế gian đều sẽ nhờ dòng dõi ngươi mà được phước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Ðoạn Áp-ra-ham trở về nơi hai người đầy tớ; họ đứng dậy, đồng nhau đi về Bê -e-Sê-ba. Áp-ra-ham cứ ở tại Bê -e-Sê-ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Sau các việc đó, người ta thuật lại với Áp-ra-ham tin nầy rằng: Nầy, nàng Minh-ca cũng sanh con cho em ngươi, là Na-cô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Con trưởng nam là Uùt-xơ, em trai là Bu-xơ, Kê-mu-ên, cha của A-ram;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Kê-sết, Ha-xô, Phin-đát, Díp-láp và Bê-tu-ên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bê-tu-ên là người sanh Rê-be-ca. Minh-ca sanh tám người con trai đó cho Na-cô, em của Áp-ra-ham.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Còn người vợ nhỏ, tên là Rê -u-ma, cũng sanh con, là Tê-la, Ga-ham, Ta-hách và Ma-a-ca.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sa-ra hưởng thọ được một trăm hai mươi bảy tuổi. Ấy là bao nhiêu năm của đời Sa-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Sa-ra qua đời tại Ki-ri-át-a-ra-ba, tức là Hếp-rôn, thuộc về xứ Ca-na-an. Áp-ra-ham đến chịu tang cho Sa-ra và than khóc người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Ðoạn, Áp-ra-ham đứng dậy trước người chết mình và nói cùng dân họ Hếch rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Ta là một khách kiều ngụ trong vòng các ngươi; xin hãy cho một nơi mộ địa trong xứ các ngươi, để chôn người thác của ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Dân họ Hếch đáp rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Lạy Chúa, xin hãy nghe chúng tôi: giữa chúng tôi, chúa tức là một quân trưởng của Ðức Chúa Trời; hãy chôn người chết của chúa nơi mộ địa nào tốt hơn hết của chúng tôi. Trong bọn chúng tôi chẳng có ai tiếc mộ địa mình, đặng chôn người chết của chúa đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Áp-ra-ham bèn đứng dậy, sấp mình xuống trước mặt các dân của xứ, tức dân họ Hếch,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'mà nói rằng: Nếu các ngươi bằng lòng cho chôn người chết ta, thì hãy nghe lời, và cầu xin Ép-rôn, con của Xô-ha giùm ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'đặng người nhượng cho ta hang đá Mặc-bê-la, ở về tận đầu đồng người, để lại cho đúng giá, hầu cho ta được trong vòng các ngươi một nơi mộ địa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Vả, Ép-rôn, người Hê-tít, đương ngồi trong bọn dân họ Hếch, đáp lại cùng Áp-ra-ham trước mặt dân họ Hếch vẫn nghe và trước mặt mọi người đến nơi cửa thành, mà rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Không, thưa chúa, hãy nghe lời tôi: Hiện trước mặt dân tôi, tôi xin dâng cho chúa cánh đồng, và cũng dâng luôn cái hang đá ở trong đó nữa; hãy chôn người chết của chúa đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Áp-ra-ham sấp mình xuống trước mặt dân của xứ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'và nói lại cùng Ép-rôn hiện trước mặt dân của xứ đương nghe, mà rằng: Xin hãy nghe, ta trả giá tiền cái đồng, hãy nhận lấy đi, thì ta mới chôn người chết ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ép-rôn đáp rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Thưa Chúa, hãy nghe lời tôi: một miếng đất giá đáng bốn trăm siếc-lơ bạc, mà tôi cùng chúa, thì có giá chi đâu? Xin hãy chôn người chết của chúa đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Áp-ra-ham nghe theo lời Ép-rôn, trước mặt dân họ Hếch cân bốn trăm siếc-lơ bạc cho người, là bạc thông dụng nơi các tay buôn bán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Vậy, cái đồng của Ép-rôn, tại Mặc-bê-la, nằm ngang Mam-rê, nghĩa là cái đồng ruộng hang đá, các cây cối ở trong và chung quanh theo giới hạn đồng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'đều trước mặt có các dân họ Hếch cùng mọi người đến cửa thành, nhận chắc cho Áp-ra-ham làm sản nghiệp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Sau các việc đó, Áp-ra-ham chôn Sa-ra, vợ mình, trong hang đá của đồng Mặc-bê-la, nằm ngang Nam-rê tại Hếp-rôn, thuộc về xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Ðồng và hang đá đều có các người họ Hếch nhận chắc, để lại cho Áp-ra-ham dùng làm mộ địa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Vả, Áp-ra-ham đã già, tuổi đã cao; trong mọi việc Ðức Giê-hô-va đã ban phước cho người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Áp-ra-ham nói cũng người đầy tớ ở lâu hơn hết trong nhà mình, có quyền quản trị các gia tài, mà rằng: Xin hãy đặt tay lên đùi ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'và ta sẽ biểu ngươi chỉ Ðức Giê-hô-va, là Ðức Chúa Trời của trời và đất, mà thề rằng: ngươi không cưới một cô nào trong bọn con gái của dân Ca-na-an, tức giữa dân ấy ta trú ngụ, làm vợ cho con trai ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Nhưng hãy đi về quê hương ta, trong vòng bà con ta, cưới một người vợ cho Y-sác, con trai ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Người đầy tớ thưa rằng: Có lẽ người con gái không khứng theo tôi về xứ nầy; vậy, có phải tôi dẫn con trai ông đến xứ mà ông đã ra đi khỏi chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Áp-ra-ham nói rằng: Hãy cẩn thận, đừng dẫn con ta về xứ đó!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Giê-hô-va Ðức Chúa Trời trên trời, là Ðấng đã đem ta ra khỏi nhà cha ta và xứ sở ta, có phán và thề rằng: Ta sẽ cho dòng dõi ngươi xứ nầy! Chánh Ngài sẽ sai thiên sứ đi trước ngươi, và nơi đó ngươi hãy cưới một vợ cho con trai ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Nếu người con gái không khứng theo, thì ngươi sẽ khỏi mắc lời của ta biểu ngươi thề; mà dẫu thế nào đi nữa, chớ đem con ta về chốn đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Ðoạn, người đầy tớ để tay lên đùi Áp-ra-ham chủ mình, và thề sẽ làm theo như lời người đã dặn biểu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Ðoạn, người đầy tớ bắt mười con lạc đà trong bầy của chủ mình, đem theo đủ các tài vật của chủ đã giao, rồi đứng dậy đi qua xứ Mê-sô-bô-ta-mi, đến thành của Na-cô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Người cho lạc đà nằm quì gối xuống nghỉ ở ngoài thành, gần bên một giếng kia, vào buổi chiều, đến giờ của những con gái ra đi xách nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Người nói rằng: Hỡi Giê-hô-va, Ðức Chúa Trời của chủ Áp-ra-ham tôi ơi! xin ngày nay cho tôi gặp điều mà tôi tìm kiếm, và hãy làm ơn cho chủ Áp-ra-ham tôi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Nầy, tôi đứng gần bên giếng nầy, các con gái của dân trong thành sẽ ra đi xách nước,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'xin cho người gái trẻ nào mà tôi nói như vầy: \"Xin nàng hãy nghiêng bình, cho tôi uống nhờ hớp nước,\" mà nàng trả lời rằng: \"Hãy uống đi, rồi tôi sẽ cho các lạc đà ngươi uống nữa,\" là chánh người mà Chúa đã định cho Y-sác, kẻ tôi tớ người; và nhờ đó tôi sẽ biết rằng Chúa đã làm ơn cho chủ tôi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Người đầy tớ chưa dứt lời, nầy, nàng Rê-be-ca vác bình trên vai đi ra. Nàng là con gái của Bê-tu-ên, Bê-tu-ên là con trai của Minh-ca, vợ Na-cô, em trai của Áp-ra-ham.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Người gái trẻ đó thật rất đẹp, còn đồng trinh, chưa gả cho ai. Nàng xuống giếng nhận đầy bình nước, rồi trở lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Ðầy tớ bèn chạy lại trước mặt nàng và nói rằng: Xin hãy cho tôi uống một hớp nước trong bình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Nàng đáp rằng: Thưa chúa, hãy uống đi; rồi nàng lật đật đỡ bình xuống tay và cho người uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Khi đỡ cho người uống xong rồi, nàng lại tiếp rằng: Tôi cũng sẽ xách cho mấy con lạc đà chúa uống nữa, chừng nào uống đã thì thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Nàng lật đật đổ nước bình ra máng, chạy xuống giếng xách nước thêm nữa cho hết thảy các con lạc đà uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Còn người ngồi làm thinh mà nhìn nàng, để cho biết Ðức Giê-hô-va làm thành công việc mình đi đây hay chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Khi lạc đà vừa thôi uống, người đầy tớ bèn lấy một khoanh vàng nặng được nửa siếc-lơ và đôi xuyến nặng được mười siếc-lơ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'mà nói rằng: Nàng là con ai? xin nói cho tôi biết. Trong nhà cha nàng có chỗ nào cho tôi ở nghỉ ban đêm chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Nàng đáp rằng: Tôi là con gái của Bê-tu-ên, cháu nội của Minh-ca và Na-cô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Rồi lại nói: Nhà chúng tôi có nhiều rơm và cỏ, và cũng có chỗ để cho ở nghỉ nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Người bèn cúi đầu và sấp mình xuống trước mặt Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'mà nói rằng: Ðáng ngợi khen thay Giê-hô-va, là Ðức Chúa Trời của chủ Áp-ra-ham tôi! Ngài chẳng ngớt thương xót và thành thực đối cùng chủ tôi! Khi đương đi, Ðức Giê-hô-va dẫn dắt tôi đến nhà anh em của chủ tôi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Người gái trẻ đó chạy về, thuật chuyện nầy lại cho nội nhà mẹ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Vả, nàng Rê-be-ca có một anh, tên là La-ban. La-ban chạy đến người đầy tớ đó ở gần bên giếng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Vừa thấy khoanh vàng và đôi xuyến nơi tay em gái mình, và đã nghe chuyện Rê-be-ca thuật lại rằng: Người nầy nói vậy! thì đi đến người, đương đứng gần bên mấy con lạc đà, ở nơi giếng nước,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'mà thưa rằng: Hởi người đã được Ðức Giê-hô-va ban phước! Xin mời vào. Sao đứng ngoài nầy vậy? Tôi đã sửa soạn nhà và dọn-dẹp một nơi cho mấy con lạc đà rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Người đầy tớ bèn vào nhà; La-ban cổi yên cho lạc đà, đem cỏ cùng rơm cho các thú đó; rồi lấy nước đặng rửa chơn cho người đầy tớ và mấy kẻ đi theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Ðoạn, người nhà bày bữa và mời ăn; nhưng người đầy tớ nói: Không, tôi không ăn đâu, nếu chưa nói được những điều tôi cần phải nói. La-ban đáp rằng: Hãy nói đi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Người bèn nói rằng: Tôi là đầy tớ của Áp-ra-ham.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Ðức Giê-hô-va đã ban phước cho chủ tôi bội phần, trở nên thạnh vượng; Ngài cho chủ tôi chiên, bò, bạc, vàng, tôi trai tớ gái, lạc đà và lừa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Vả, Sa-ra, vợ chủ tôi, trở về già, có sanh một con trai cho người; người đã giao gia tài mình lại hết cho con trai đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Chủ tôi lại có bắt tôi thề rằng: Ngươi chớ cưới cho con trai ta một người vợ nào trong bọn con gái của dân Ca-na-an, là xứ ta đương trú ngụ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'nhưng hãy về nhà cha ta, trong vòng bà con ta, mà cưới cho nó một người vợ tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Tôi nói cùng chủ tôi rằng: Có lẽ người con gái không khứng theo tôi về.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Chủ đáp rằng: Ðức Giê-hô-va là Ðấng ta phục sự sẽ sai thiên sứ theo ngươi, làm cho thành công việc ngươi đi; và ngươi sẽ cưới cho con trai ta một người vợ trong vòng bà con ta, tại nhà cha ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Vậy, nếu khi ngươi đi về bà con ta, mà họ không khứng gả cho, thì ngươi sẽ được gỡ lời thề nặng của ngươi đã thề cùng ta đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Ngày nay, khi đi đến giếng kia, tôi có cầu rằng: Lạy Ðức Giê-hô-va, Ðức Chúa Trời của chủ Áp-ra-ham tôi! Xin đoái đến mà giúp công việc của tôi đi đây cho được thành!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Nầy, tôi ngồi gần bên giếng nầy: cầu xin hễ người gái trẻ nào sẽ ra xách nước mà tôi nói cùng nàng rằng: Xin cho tôi uống một hớp nước trong bình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'mà sẽ trả lời rằng: Hãy uống đi, trước tôi sẽ xách cho các lạc đà ngươi uống nữa, xin cho người gái trẻ đó là vợ mà Ðức Giê-hô-va đã định cho con trai của chủ tôi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Chưa dứt lời thầm nguyện, bỗng đâu nàng Rê-be-ca vác bình trên vai đi ra, xuống giếng xách nước. Tôi nói với nàng rằng: Xin cho tôi uống hớp nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Nàng lật đật hạ bình trên vai xuống mà nói rằng: Hãy uống đi, rồi tôi sẽ cho các lạc đà ngươi uống nữa; vậy tôi có uống và nàng cũng có cho các lạc đà uống nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Tôi bèn hỏi nàng rằng: Nàng là con gái ai? Nàng đáp: Tôi là con gái của Bê-tu-ên, cháu nội của Na-cô và Minh-ca. Tôi liền đeo cái khoanh nơi lỗ mũi và đôi xuyến vào tay nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Ðoạn, tôi cúi đầu và sấp mình xuống trước mặt Ðức Giê-hô-va, ngợi khen Giê-hô-va Ðức Chúa Trời của chủ Áp-ra-ham tôi, mà đã dẫn tôi vào đường chánh đáng, để chọn được cho con trai người con gái của em chủ tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Vậy, bây giờ, nếu các ông muốn lấy lòng tử tế và trung tín đối cùng chủ tôi, xin hãy tỏ điều đó cho, dầu không, xin cũng nói cho biết, hầu cho tôi sẽ xây về bên hữu hay là về bên tả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'La-ban và Bê-tu-ên đáp rằng: Ðiều đó do nơi Ðức Giê-hô-va mà ra, chúng tôi đâu nói được cùng ngươi rằng quấy hay rằng phải.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Kìa, Rê-be-ca đương ở trước mặt ngươi, hãy dẫn nó đi, để nó được làm vợ của con trai chủ ngươi, theo như lời Ðức Giê-hô-va phán định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Ðầy tớ của Áp-ra-ham vừa nghe lời hai người nói xong, liền sấp mình xuống đất trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Người lấy đồ trang sức bằng bạc, vàng, và áo xống trao cho Rê-be-ca; rồi cùng lấy các vật quí dâng cho anh và mẹ nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Ðoạn người đầy tớ cùng các người đi theo ngồi ăn uống; rồi ngủ tại đó. Qua ngày sau, khi họ đã thức dậy, người đầy tớ nói rằng: Xin hãy cho tôi trở về chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Nhưng anh và mẹ nàng rằng: Hãy cho người gái trẻ ở lại cùng chúng tôi ít ngày nữa, độ chừng mười bữa, rồi nó sẽ đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Ðầy tớ đáp rằng: Xin chớ cầm tôi trễ lại, vì Ðức Giê-hô-va có làm việc đi đường tôi được thành. Hãy cho tôi đi, trở về nhà chủ tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Họ đáp rằng: Chúng ta hãy gọi người gái trẻ đó và hỏi ý nó ra sao;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'bèn kêu Rê-be-ca và nói rằng: Con muốn đi cùng người nầy chăng? Nàng rằng: Tôi muốn đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Ðoạn, họ cho Rê-be-ca, em gái mình, và người vú của nàng, đi về theo người đầy tớ của Áp-ra-ham và các kẻ đi theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Họ chúc phước cho Rê-be-ca mà rằng: Hỡi em gái chúng ta! Chúc cho em được trở nên mẹ của ức triệu người, và cho dòng dõi em được chiếm lấy cửa thành của quân nghịch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Rê-be-ca và các đòi nàng đứng dậy, lên cỡi lạc đà, đi theo người đầy tớ đó. Vậy, người đầy tớ dẫn Rê-be-ca đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Bấy giờ Y-sác ở tại nam phương từ giếng La-chai-Roi trở về;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'lối chiều, người đi ra ngoài đồng đặng suy ngẫm; nhướng mắt lên, kìa ngó thấy lạc đà đâu đi đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Nàng Rê-be-ca cũng nhướng mắt lên, bèn chợt thấy Y-sác; liền nhảy xuống lạc đà,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'và hỏi đầy tớ rằng: Người ở đằng trước mặt tôi đi lại trong đồng đó là ai: Ðầy tớ thưa rằng: Ấy là chủ tôi đó. Nàng bèn lấy lúp che mặt lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Rồi, đầy tớ thuật cho Y-sác nghe hết các việc mà mình đã làm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Y-sác bèn dẫn Rê-be-ca vào trại của Sa-ra, mẹ mình, cưới làm vợ, và yêu mến nàng. Vậy, Y-sác được giải phiền sau khi mẹ mình qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Áp-ra-ham cưới một người vợ khác, tên là Kê-tu-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Người sanh cho Áp-ra-ham Xim-ram, Giốc-chan, Mê-đan, Ma-đi-an, Dích-bác và Su-ách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Giốc-chan sanh Sê-ba và Ðê-đan; con cháu của Ðê-đan là họ A-chu-rim, họ Lê-tu-chim và họ Lê-um-mim.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Con trai của Ma-đi-an là Ê-pha, Ê-phe, Ha-nóc, A-bi-đa và Eân-đa. Các người trên đây đều là dòng dõi của Kê-tu-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Áp-ra-ham cho Y-sác hết thảy gia tài mình; còn cho các con dòng thứ những tiền của;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'rồi, khi còn sống, người sai họ qua đông phương mà ở, cách xa con dòng chánh, là Y-sác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Áp-ra-ham hưởng thọ được một trăm bảy mươi lăm tuổi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'người tuổi cao tác lớn và đã thỏa về đời mình, tắt hơi, được qui về nơi tổ tông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Hai con trai người, Y-sác và Ích-ma-ên, chôn người trong hang đá Mặc-bê-la tại nơi đồng của Ép-rôn, con trai Sô-ha, người Hê-tít, nằm ngang Mam-rê.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Ấy là cái đồng mà lúc trước Áp-ra-ham mua lại của dân họ Hếch; nơi đó họ chôn Áp-ra-ham cùng Sa-ra, vợ người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Sau khi Áp-ra-ham qua đời, Ðức Giê-hô-va ban phước cho Y-sác con trai người. Y-sác ở gần bên cái giếng La-chai-Roi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Ðây là dòng dõi của Ích-ma-ên, con trai của Áp-ra-ham, do nơi nàng A-ga, người Ê-díp-tô, con đòi của Sa-ra, đã sanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Và đây là trên các con trai của Ích-ma-ên, sắp thứ tự theo ngày ra đời: Con trưởng nam của Ích-ma-ên là Nê-ba-giốt; kế sau Kê-đa, Át-bê-ên, Mi-bô-sam,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Mích-ma, Ðu-ma, Ma-sa,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Ha-đa, Thê-ma, Giê-thu, Na-phích, và Kết-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ðó là các con trai của Ích-ma-ên và tên của họ tùy theo làng và nơi đóng trại mà đặt. Ấy là mười hai vị công hầu trong dân tộc của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ích-ma-ên hưởng thọ được một trăm ba mươi bảy tuổi, rồi tắt hơi mà qua đời, được qui về nơi tổ tông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Dòng dõi người ở trước mặt anh em mình, từ Ha-vi-la cho đến Xu-xơ, đối ngang Ê-díp-tô, chạy qua A-si-ri.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Ðây là dòng dõi của Y-sác, con trai Áp-ra-ham. Áp-ra-ham sanh Y-sác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Vả, khi Y-sác được bốn mươi tuổi, thì cưới Rê-be-ca, con gái của Bê-tu-ên và em gái của La-ban, đều là dân A-ram, ở tại xứ Pha-đan-a-ram.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Y-sác khẩn cầu Ðức Giê-hô-va cho vợ mình, vì nàng son sẻ. Ðức Giê-hô-va cảm động lời khẩn cầu đó, nên cho Rê-be-ca thọ thai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Nhưng vì thai đôi làm cho đụng nhau trong bụng, thì nàng nói rằng: Nếu quả thật vậy, cớ sao đều nầy xảy đến làm chi? Ðoạn nàng đi hỏi Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Ðức Giê-hô-va phán rằng: Hai nước hiện ở trong bụng ngươi, và hai thứ dân sẽ do lòng ngươi mà ra; dân nầy mạnh hơn dân kia, và đứa lớn phải phục đứa nhỏ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Ðến ngày nàng phải sanh nở, nầy hai đứa sanh đôi trong bụng nàng ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Ðứa ra trước đỏ hồng, lông cùng mình như một áo tơi lông; đặt tên là Ê-sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Kế em nó lại ra sau, tay nắm lấy gót Ê-sau; nên đặt tên là Gia-cốp. Khi sanh hai đứa con nầy thì Y-sác đã được sáu mươi tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Khi hai đứa trai nầy lớn lên, thì Ê-sau trở nên một thợ săn giỏi, thường giong ruổi nơi đồng ruộng; còn Gia-cốp là người hiền lành cứ ở lại trại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Y-sác yêu Ê-sau, vì người có tánh ưa ăn thịt rừng; nhưng Rê-be-ca lại yêu Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Một ngày kia, Gia-cốp đương nấu canh, Ê-sau ở ngoài đồng về lấy làm mệt mỏi lắm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'liền nói cùng Gia-cốp rằng: Em hãy cho anh ăn canh gì đỏ đó với, vì anh mệt mỏi lắm. Bởi cớ ấy, người ta gọi Ê-sau là Ê-đôm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Gia-cốp đáp rằng: Nay anh hãy bán quyền trưởng nam cho tôi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ê-sau đáp rằng: Nầy, anh gần thác, quyền trưởng nam để cho anh dùng làm chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Gia-cốp đáp lại rằng: Anh hãy thề trước đi. Người bèn thề; vậy, người bán quyền trưởng nam cho Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Rồi, Gia-cốp cho Ê-sau ăn bánh và canh phạn đậu; ăn uống xong, người bèn đứng dậy đi. Vậy, Ê-sau khinh quyền trưởng nam là thế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Trừ cơn đói kém thứ nhứt trong đời Áp-ra-ham, bấy giờ tại xứ lại có một lần nữa. Y-sác bèn đi đến A-bi-mê-léc, vua Phi-li-tin, tại Ghê-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Ðức Giê-hô-va hiện đến cùng người và phán rằng: Chớ xuống xứ Ê-díp-tô; hãy ở lại xứ mà ta sẽ chỉ cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Hãy ngụ trong xứ nầy, ta sẽ ở cùng ngươi và ban phước cho ngươi; vì ta sẽ cho ngươi cùng dòng dõi ngươi các xứ nầy và ta sẽ làm thành lời ta đã thề cùng Áp-ra-ham, cha ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Ta sẽ thêm dòng dõi ngươi nhiều như sao trên trời, sẽ cho họ các xứ nầy; hết thảy dân thế gian đều sẽ nhờ dòng dõi ngươi mà được phước;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'vì Áp-ra-ham đã vâng lời ta và đã giữ điều ta phán dạy, lịnh, luật và lệ của ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Vậy, Y-sác ở tại Ghê-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Bởi nàng Rê-be-ca sắc-sảo dung nhan, nên khi dân xứ đó hỏi thăm vợ người, thì người đáp rằng: \"Ấy là em gái tôi,\" e khi nói: \"Ấy là vợ tôi,\" thì họ sẽ giết mình chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Vả, người ngụ tại xứ đó cũng đã lâu; một ngày kia A-bi-mê-léc, vua Phi-li-tin, ngó ngang qua cửa sổ, thấy Y-sác đương giỡn chơi cùng Rê-be-ca, vợ người,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'bèn đòi Y-sác mà rằng: Quả thật là vợ ngươi đó; sao có nói: Ấy là em gái tôi? Y-sác đáp rằng: Vì tôi có thầm nói: Chớ khá vì nàng mà tôi phải bỏ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'A-bi-mê-léc hỏi: Ngươi làm chi cho chúng ta vậy? Ngộ có một người dân đến nằm cùng vợ ngươi, ngươi làm cho chúng ta phải phạm tội!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'A-bi-mê-léc bèn truyền lịnh cho cả dân chúng rằng: Kẻ nào động đến người nầy, hay là vợ người nầy, thì sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Y-sác gieo hột giống trong xứ đó; năm ấy gặt được bội trăm phần; vì Ðức Giê-hô-va đã ban phước cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Người nên thạnh vượng, của cải càng ngày càng thêm cho đến đỗi người trở nên rất lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Người có nhiều bầy chiên, bầy bò và tôi tớ rất đông; bởi cớ ấy, dân Phi-li-tin đem lòng ganh ghẻ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Mấy cái giếng lúc trước đầy tớ của Áp-ra-ham, cha người, đã đào, bây giờ đều bị dân Phi-li-tin lấp đất lại hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'A-bi-mê-léc nói cùng Y-sác rằng: Hãy ra khỏi nơi ta, vì ngươi thạnh vượng hơn chúng ta bội phần.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Vậy, Y-sác bỏ chốn nầy đi đến đóng trại tại trũng Ghê-ra và ở đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Y-sác bèn đào lại mấy cái giếng người ta đã đào trong đời Áp-ra-ham, cha mình, mà bị dân Phi-li-tin lấp đất lại khi Áp-ra-ham qua đời, và đặt tên mấy giếng đó như tên của cha mình đã đặt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Các đầy tớ của Y-sác còn đào thêm giếng nơi trũng, gặp được một giếng nước mạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Nhưng bọn chăn chiên Ghê-ra tranh giành cùng bọn chăn chiên của Y-sác, mà rằng: Người đó của chúng ta; nên người đặt tên giếng nầy là Ê-sét. Vì bọn chăn chiên đó có tranh giành cùng mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Kế ấy, các đầy tớ đào một giếng khác, thì bị tranh giành nhau nữa; người đặt tên giếng nầy là Sít-na.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Ðoạn, người bỏ chỗ đó đi đào một giếng khác; về giếng nầy, họ không tranh giành nhau, nên người đặt tên là Rê-hô-bốt, mà rằng: Bây giờ Ðức Giê-hô-va đã để cho chúng ta được rộng rãi, và ta sẽ đặng thịnh vượng trong xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Y-sác ở đó đi, dời lên Bê -e-Sê-ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Ðêm đó Ðức Giê-hô-va hiện đến cùng người và phán rằng: Ta là Ðức Chúa Trời của Áp-ra-ham, cha ngươi; chớ sợ chi, ta ở cùng ngươi, sẽ ban phước cho và thêm dòng dõi ngươi, vì cớ Áp-ra-ham là tôi tớ ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Y-sác lập một bàn thờ, cầu khẩn danh Ðức Giê-hô-va và đóng trại tại đó. Ðoạn, các đầy tớ người đào một cái giếng tại nơi ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Vua A-bi-mê-léc ở Ghê-ra đi đến viếng Y-sác, có A-hu-sát, bạn mình, và Phi-côn, quan tổng binh mình, đi theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Y-sác bèn hỏi rằng: Các người ghét tôi, đã đuổi tôi ra khỏi nơi mình, sao còn đi đến tôi mà chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Chúng đáp rằng: Chúng tôi đã thấy rõ ràng Ðức Giê-hô-va phù hộ người, nên nói với nhau rằng: Phải có một lời thề giữa chúng tôi và người, để chúng ta kết giao ước với người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Hãy thề rằng: Người chẳng bao giờ làm hại chúng tôi, như chúng tôi đã không động đến người, chỉ hậu đãi người và cho đi bình yên. Bây giờ người được Ðức Giê-hô-va ban phước cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Y-sác bày một bữa tiệc, các người đồng ăn uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Qua ngày sau, chúng đậy sớm, lập lời thề với nhau. Rồi, Y-sác đưa các người đó đi về bình yên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Cùng trong ngày đó, các đầy tớ của Y-sác đến đem tin cho người hay về giếng họ đã đào, rằng: Chúng tôi đã thấy có nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Người bèn đặt tên cái giếng đó là Si-ba. Vì cớ đó nên tên thành ấy là Bê -e-Sê-ba cho đến ngày nay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Khi Ê-sau được bốn mươi tuổi, cưới Giu-đít, con gái của Bê -e-ri, người Hê-tít; và Bách-mát, con gái của Ê-lôn, cũng người Hê-tít.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Hai dâu đó là một sự cay đắng lòng cho Y-sác và Rê-be-ca.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Bởi Y-sác đã già, mắt làng chẳng thấy được nữa, bèn gọi Ê-sau, con trưởng nam, mà rằng: Hỡi con! Ê-sau thưa rằng: Có con đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Người bèn nói rằng: Nầy, cha đã già rồi, chẳng biết ngày nào phải chết;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'vậy bây giờ, cha xin con hãy lấy khí giới, ống tên và cung con, ra đồng săn thịt rừng cho cha,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'dọn một món ngon tùy theo cha sở thích; rồi dâng lên cho cha ăn, đặng linh hồn cha chúc phước cho con trước khi chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Vả, đương khi Y-sác nói cùng Ê-sau con trai mình, thì Rê-be-ca có nghe. Ê-sau bèn ra đồng săn thịt rừng đặng đem về cho cha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Rê-be-ca nói cùng Gia-cốp, con trai mình, rằng: Nầy, mẹ có nghe cha nói cùng Ê-sau, anh con, và dặn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Hãy đem thịt rừng về cho cha, dọn một món ngon cha ăn; đặng trước khi qua đời, cha sẽ chúc phước cho con trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Vậy, con ơi! bây giờ, hãy nghe mẹ và làm theo lời mẹ biểu:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Hãy ra ngoài bầy, bắt hai dê con tốt, rồi mẹ sẽ dọn cho cha con một món ngon, tùy theo người sở thích;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'con sẽ đem cho cha ăn, đặng người chúc phước con trước khi qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Gia-cốp thưa lại cùng mẹ rằng: Thưa mẹ, Ê-sau, anh con, có lông, còn con lại không.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Có lẽ cha sẽ rờ mình chăng, coi con như kẻ phỉnh gạt, thì con chắc lấy cho mình sự rủa sả, chớ chẳng phải sự chúc phước đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Mẹ đáp rằng: Con ơi! xin sự rủa sả đó để cho mẹ chịu; hãy cứ nghe lời mẹ, ra bắt hai dê con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Vậy, Gia-cốp đi bắt hai dê con, đem lại cho mẹ, làm món ngon, tùy theo cha sở thích.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Ðoạn Rê-be-ca lấy quần áo tốt nhứt của Ê-sau, con trưởng nam, sẵn để trong nhà, mà mặc vào cho Gia-cốp, con út mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'rồi người lấy da dê con bao hai tay và cổ, vì tay và cổ Gia-cốp không có lông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Rê-be-ca bèn để món ngon và bánh của mình đã dọn vào tay con út mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Gia-cốp bưng đến cha mình và nói rằng: Thưa cha! Y-sác đáp: Có cha đây; con là đứa nào đó?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Gia-cốp thưa: Tôi là Ê-sau, con trưởng nam của cha; con đã làm theo lời cha dặn biểu; xin cha dậy, ngồi ăn lấy thịt săn của con, đặng linh hồn cha sẽ chúc phước cho con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Y-sác hỏi rằng: Sao con đi săn được mau thế? Thưa rằng: Ấy nhờ Giê-hô-va Ðức Chúa Trời của cha xui tôi gặp mau vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Y-sác nói cùng Gia-cốp rằng: Hỡi con! hãy lại gần đặng cha rờ thử xem có phải là Ê-sau, con của cha chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Gia-cốp bèn lại gần Y-sác; người rờ và nói rằng: Tiếng nói thì của Gia-cốp, còn hai tay lại của Ê-sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Người chẳng nhận biết đặng vì hai tay cũng có lông như của anh, là Ê-sau. Vậy Y-sác chúc phước cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Người lại hỏi rằng: Ấy con thật là Ê-sau, con trai ta, phải chăng? Gia-cốp thưa: Phải, con đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Y-sác bèn nói: Hãy dọn cho cha ăn lấy thịt săn của con, đặng linh hồn cha chúc phước cho con. Gia-cốp dọn cho người ăn, cũng có đem rượu cho người uống nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Rồi Y-sác cha người nói rằng: Hỡi con! hãy lại gần và hôn cha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Gia-cốp bèn lại gần và hôn người. Y-sác đánh mùi thơm của áo con, liền chúc phước cho, và nói rằng: Nầy, mùi hương của con ta Khác nào mùi hương của cánh đồng mà Ðức Giê-hô-va đã ban phước cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Cầu xin Ðức Chúa Trời cho con sương móc trên trời xuống, Ðược màu mỡ của đất, và dư dật lúa mì cùng rượu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Muôn dân phải phục con, Các nước phải quì lạy trước mặt con! Hãy được quyền chủ các anh em, Các con trai của mẹ con phải quì lạy trước mặt con! Ai rủa sả con sẽ bị rủa sả lại, Ai cầu phước cho con, sẽ được ban phước lại!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Vừa khi Y-sác chúc phước cho Gia-cốp xuống, và vừa khi Gia-cốp lùi ra khỏi nơi cha mình, thì Ê-sau, anh người, đi săn trở về.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Người cũng dọn một món ngon, dâng lên cho cha và thưa rằng: Xin dậy, ngồi ăn thịt săn của con trai cha, đặng linh hồn cha chúc phước cho con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Y-sác, cha người, hỏi: Con là đứa nào? Thưa rằng: Tôi là Ê-sau, con trưởng nam của cha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Y-sác lấy làm cảm động qua đỗi mà nói rằng: Vậy, còn đứa nào đã săn thịt rừng, và đã dâng lên cho cha đó? Trước khi con về, cha đã ăn hết rồi, và chúc phước cho nó; nó lại sẽ được ban phước vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Vừa nghe dứt lời cha, thì Ê-sau la lên một tiếng rất lớn, và rất thảm thiết mà thưa cùng cha rằng: Cha ơi! xin hãy chúc phước cho con luôn nữa!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Nhưng Y-sác lại đáp: Em con đã dùng mưu kế đến cướp sự chúc phước của con rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Ê-sau liền nói rằng: Có phải vì người ta gọi nó là Gia-cốp mà đó hai lần chiếm lấy vị tôi rồi chăng? Nó đã chiếm quyền trưởng nam tôi, và lại bây giờ còn chiếm sự phước lành của tôi nữa. Tiếp rằng: Cha chẳng có dành sự chúc phước chi cho tôi sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Y-sác đáp rằng: Nầy, cho đã lập nó lên làm chủ con, và đã cho các anh em làm tôi nó; và đã dự bị lúa mì và rượu cho nó. Vậy, cha sẽ làm chi cho con đây?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Ê-sau thưa rằng: Cha ơi! cha chỉ có sự chúc phước đó thôi sao? Hãy chúc phước cho con với, cha! Rồi Ê-sau cất tiếng lên khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Y-sác cha người, đáp rằng: Nầy, nơi con ở sẽ thiếu màu mỡ của đất, Cùng sương-móc trên trời sa xuống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Con sẽ nhờ gươm mới được sống. Và làm tôi tớ cho em con. Song khi con lưu lạc rày đó mai đây, Sẽ bẻ cái ách của em trên cổ con vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Ê-sau trở lòng ghét Gia-cốp vì cớ cha mình chúc phước cho người, bèn nói thầm trong lòng rằng: Ngày tang của cha đã hầu gần; vậy, ta sẽ giết Gia-cốp, em ta, đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Họ đem lời Ê-sau, con lớn, thuật lại cùng Rê-be-ca, thì người sai gọi Gia-cốp, con út mình, mà nói rằng: Nầy, Ê-sau, anh con, toan giết con để báo thù.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Vậy, bây giờ, hỡi con, hãy nghe lời mẹ, đứng dậy, chạy trốn qua nhà La-ban, cậu con, tại Cha-ran,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'và hãy ở cùng người ít lâu, cho đến lúc nào cơn giận của anh con qua hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Khi cơn giận anh con bỏ qua rồi, và nó quên việc con đã gây nên với nó, thì mẹ sẽ biểu con về. Có lẽ đâu mẹ phải chịu mất cả hai đứa trong một ngày ư?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Rê-be-ca nói cùng Y-sác rằng: Tôi đã chán, không muốn sống nữa, vì cớ mấy con gái họ Hếch. Nếu Gia-cốp cưới một trong mấy con gái họ Hếch mà làm vợ, tức một người con gái trong xứ như các dân đó; thôi, tôi còn sống mà chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Y-sác bèn gọi Gia-cốp, chúc phước cho và dặn rằng: Con chớ chọn một người vợ nào hết trong bọn con gái Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Hãy đứng dậy, đi qua xứ Pha-đan-a-ram, tại nhà Bê-tu-ên, ông ngoại con, và cưới ở đó một người vợ trong các con gái của La-ban, là cậu con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Cầu xin Ðức Chúa Trời toàn năng ban phước cho con, làm con sanh sản, thêm nhiều và trở nên một đám dân đông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Cầu xin Ngài ban cho con và dòng dõi con phước lành của Áp-ra-ham, hầu cho xứ con đã kiều ngụ sẽ làm sản nghiệp cho con, tức xứ Ngài đã ban cho Áp-ra-ham!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Rồi Y-sác sai Gia-cốp đi qua xứ Pha-đan-a-ram, đến nhà La-ban, con trai Bê-tu-ên, vốn người A-ram, lại là anh của Rê-bê-ca, mẹ của Gia-cốp và Ê-sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Ê-sau thấy Y-sác đã chúc phước cho Gia-cốp, và sai đi qua xứ Pha-đan-a-ram đặng cưới vợ; và trong lúc đương chúc phước có dặn rằng: Chớ cưới vợ trong bọn con gái Ca-na-an;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'lại đã thấy Gia-cốp vâng lời cha me đi qua xứ Pha-đan-a-ram đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'thì biết rằng bọn con gái Ca-na-an không vừa ý Y-sác, cha mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'nên người bèn đi đến nhà Ích-ma-ên (ngoài hai người vợ đã có rồi) cưới thêm nàng Ma-ba-lát, con gái của Ích-ma-ên, cháu nội của Áp-ra-ham và em của Nê-ba-giốt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Gia-cốp từ Bê -e-Sê-ba đi đến Cha-ran,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'tới một chỗ kia, mặt trời đã khuất, thì qua đêm tại đó. Người lấy một hòn đá làm gối đầu, và nằm ngủ tại đó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'bèn chiêm bao thấy một cái thang bắc từ dưới đất, đầu đến tận trời, các thiên sứ của Ðức Chúa Trời đi lên xuống trên thang đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Nầy, Ðức Giê-hô-va ngự trên đầu thang mà phán rằng: Ta là Ðức Chúa Trời của Áp-ra-ham, tổ phụ ngươi, cùng là Ðức Chúa Trời của Y-sác. Ta sẽ cho ngươi và dòng dõi ngươi đất mà ngươi đương nằm ngủ đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Dòng dõi ngươi sẽ đông như cát bụi trên mặt đất, tràn ra đến đông tây nam bắc, và các chi họ thế gian sẽ nhờ ngươi và dòng dõi ngươi mà được phước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Nầy, ta ở cùng ngươi, ngươi đi đâu, sẽ theo gìn giữ đó, và đem ngươi về xứ nầy; vì ta không bao giờ bỏ ngươi cho đến khi ta làm xong những điều ta đã hứa cùng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Gia-cốp thức giấc, nói rằng: Thật Ðức Giê-hô-va hiện có trong nơi đây mà tôi không biết!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Người bắt sợ và nói rằng: Chốn nầy đáng kinh khủng thay thật là đền Ðức Chúa Trời, thật là cửa của trời!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Người dậy sớm, lấy hòn đá của mình dùng gối đầu, dựng đứng lên làm cây trụ, đổ dầu lên trên chót trụ đó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'rồi đặt tên chốn nầy là Bê-tên; còn nguyên khi trước tên thành là Lu-xơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Gia-cốp bèn khấn vái rằng: Nếu Ðức Chúa Trời ở cùng tôi, gìn giữ tôi trong lúc đi đường, cho bánh ăn, áo mặc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'và nếu tôi trở về bình an đến nhà cha tôi, thì Ðức Giê-hô-va sẽ là Ðức Chúa Trời tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Hòn đá đã dùng làm trụ đây sẽ là đền Ðức Chúa Trời, Và tôi sẽ nộp lại cho Ngài một phần mười mọi của cải mà Ngài sẽ cho tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Ðoạn, Gia-cốp lên đường, đi đến xứ của dân Ðông phương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Người nhìn xem, thấy một cái giếng trong đồng ruộng, gần đó có ba bầy chiên nằm nghỉ, vì nơi nầy là chốn người ta cho các bầy chiên uống nước. Hòn đá đậy trên miệng giếng rất lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Các bầy chiên đều hiệp lại đó, rồi họ lăn hòn đá trên miệng giếng ra, cho các bầy uống nước; đoạn, lăn đá lại chỗ cũ, đậy trên miệng giếng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Gia-cốp hỏi mấy tay chăn chiên rằng: Hỡi các anh! các anh ở đâu đây? Bọn đó đáp rằng: Chúng tôi ở Cha-ran đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Người hỏi: Các anh có biết La-ban, con trai Na-cô, chăng? Ðáp rằng: Chúng tôi biết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Lại hỏi: Người đó được mạnh giỏi chăng? Ðáp rằng: Người vẫn được mạnh giỏi, và nầy, Ra-chên, con gái người, dương đi đến cùng bầy chiên kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Ngươi nói: Nầy, trời hãy còn sớm, chưa phải là giờ nhóm hiệp các súc vật; vậy, các anh hãy cho bầy chiên uống nước, rồi thả đi ăn lại đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Ðáp rằng: Chúng tôi làm như vậy chẳng được; phải đợi các bầy hiệp lại đủ hết rồi, bấy giờ mới lăn hòn đá trên miệng giếng ra, cho bầy uống nước được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Vả, đương lúc người còn nói chuyện cùng bọn đó, thì Ra-chên dắt bầy chiên của cha nàng đến, vi nàng vốn là người chăn chiên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Khi vừa thấy Ra-chên, con gài La-ban, cậu mình, thì người liền lại gần lăn hòn đá ra khỏi miệng giếng, cho bầy chiên của La-ban, cậu mình, uống nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Gia-cốp hôn Ra-chên, cất tiếng lên khóc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'rồi nói cho nàng biết rằng mình là bà con với cha nàng, tức con trai của Rê-bê-ca. Nàng bèn chạy về thuật lại cho cha hay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Vừa khi nghe nói Gia-cốp, con trai của em gái mình, thì La-ban chạy đến trước mặt người, ôm choàng lấy mà hôn, rồi mới vào nhà. Gia-cốp thuật lại cho La-ban nghe các việc đã xảy qua.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'La-ban bèn đáp rằng: Thật vậy, cháu là cốt nhục của cậu; rồi Gia-cốp ở một tháng cùng cậu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Ðoạn, La-ban nói cùng Gia-cốp rằng: vì cớ cháu là bà con của cậu, cháu giúp công không cho cậu thôi sao? Tiền công bao nhiêu hãy nói cho cậu biết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Vả, La-ban có hai con gái, con lớn tên là Lê-a; con nhỏ tên là Ra-chên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Mắt Lê-a yếu, còn Ra-chên hình dung đẹp đẽ, vẻ mặt tốt tươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Gia-cốp yêu Ra-chên nên nói rằng: Vì nàng Ra-chên, con út cậu, tôi sẽ giúp việc trong bảy năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'La-ban trả lời rằng: Thà cậu gả nó cho cháu hơn là gả cho một người khác; hãy ở với cậu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Vậy, Gia-cốp vì Ra-chên, phải giúp việc trong bảy năm: nhưng bởi yêu nàng, nên coi bảy năm bằng chừng đôi ba bữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Kế đó, Gia-cốp nói cùng La-ban rằng: Hạn tôi đã mãn rồi; đâu! xin cậu hãy giao vợ tôi lại đặng tôi đến gần cùng nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'La-ban bèn mời các người trong xóm, bày một bữa tiệc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'đến chiều tối, bắt Lê-a, con gái mình, đưa cho Gia-cốp, rồi chàng đến cùng nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'La-ban lại cắt con đòi Xinh-ba theo hầu Lê-a, con gái mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Sáng bữa sau, mới biết là nàng Lê-a, thì Gia-cốp hỏi La-ban rằng: Cậu đã đãi tôi cách chi vậy? Có phải vì Ra-chên mà tôi mới giúp việc cho nhà cậu chăng? Sao cậu lừa-gạt tôi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'La-ban đáp rằng: Phong tục ở đây chẳng phải được gả em út trước, rồi chị cả sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Hãy ở với đứa nầy trọn một tuần đi, rồi ta sẽ gả luôn đứa kia cho; về đứa kia cháu phải giúp công cho cậu thêm bảy năm nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Gia-cốp theo lời, ở cùng Lê-a trọn một tuần, rồi La-ban gả Ra-chên con gái mình, cho chàng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'và cắt con đòi Bi-la theo hầu Ra-chên con gái mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Gia-cốp đi lại cùng Ra-chên, thương yêu nàng hơn Lê-a. Vậy, người ở giúp việc nhà La-ban thêm bảy năm nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Ðức Giê-hô-va thấy Lê-a bị ghét, bèn cho nàng sanh sản; còn Ra-chên lại son sẻ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lê-a thọ thai, sanh một con trai, đặt tên Ru-bên; vì nói rằng: Ðức Giê-hô-va đã thấy sự cực khổ tôi; bây giờ chồng sẽ yêu mến tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Nàng thọ thai nữa và sanh một con trai, đặt tên Si-mê-ôn; vì nói rằng. Ðức Giê-hô-va có nghe biết tôi bị ghét, nên cho thêm đứa này.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Nàng thọ thai nữa và sanh một con trai; nàng rằng: Lần nầy chồng sẽ dính díu cùng tôi, vì tôi đã sanh cho người ba con trai; bởi cớ đó, đặt tên là Lê-vi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Nàng thọ thai nữa, sanh một con trai, và nói rằng: Lần nầy tôi ngợi khen Ðức Giê-hô-va; vì cớ ấy, đặt tên là Giu-da. Ðoạn, nàng thôi thai nghén.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Ra-chên thấy mình chẳng sanh con cho Gia-cốp, thì đem lòng ghen ghét chị, nói cùng Gia-cốp rằng: Hãy cho tôi có con, bằng không, tôi chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Gia-cốp nổi giận cùng Ra-chên mà rằng: Há ta được thay quyền Ðức Giê-hô-va, mà không cho ngươi sanh sản sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Ra-chên rằng: Nầy con đòi Bi-la của tôi, hãy lại cùng nó, hầu cho nó sanh đẻ thay cho tôi, đặng phần tôi bởi nó cũng có con nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Vậy, Ra-chên đưa Bi-la làm hầu Gia-cốp, và người đi lại cùng nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bi-la thọ thai, sanh một con trai cho Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Ra-chên rằng: Ðức Chúa Trời đã xét tôi công bình, nhậm lời tôi, nên cho tôi một con trai; vì cớ ấy, nàng đặt tên đứa trai đó là Ðan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Bi-la, con đòi của Ra-chên, thọ thai nữa, và sanh một con trai thứ nhì cho Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Ra-chên rằng: Tôi đã hết sức chống cự với chị tôi, và tôi được thắng; vì cớ ấy, nàng đặt tên đứa trai nầy là Nép-ta-li.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Lê-a thấy mình thôi sanh sản, bèn bắt Xinh-ba, con đòi mình, làm hầu cho Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Xinh-ba, con đòi của Lê-a, sanh một con trai cho Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Lê-a rằng: Phước biết dường bao! rồi đặt tên đứa trai đó là Gát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Xinh ba, con đòi của Lê-a, sanh một con trai thứ nhì cho Gia-cốp;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'thì Lê-a rằng: Tôi lấy làm vui mừng dường bao! vì các con gái sẽ xưng ta được phước; nàng bèn đặt tên đứa trai đó là A-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Nhằm mùa gặt lúa mì, Ru-bên đi ra đồng gặp được những trái phong già, đem về dâng cho Lê-a, mẹ mình. Ra-chên bèn nói cùng Lê-a rằng: Xin chị hãy cho tôi những trái phong già của con chị đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Ðáp rằng: Cướp chồng tao há là một việc nhỏ sao, nên mầy còn muốn lấy trái phong già của con trai tao nữa? Ra-chên rằng: Ừ thôi! chồng ta hãy ở cùng chị tối đêm nay, đổi cho trái phong già của con chị đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Ðến chiều, Gia-cốp ở ngoài đồng về, thì Lê-a đến trước mặt người mà nói rằng: Chàng hãy lại cùng tôi, vì tôi đã dùng trái phong già của con tôi chịu thuê được chàng; vậy, đêm đó người lại nằm cùng nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Ðức Chúa Trời nhậm lời Lê-a, nàng thọ thai và sanh cho Gia-cốp một con trai thứ năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Nàng rằng: Ðức Chúa Trời đã đền công tôi, vì cớ tôi đã trao con đòi cho chồng; vậy, nàng đặt tên đứa con trai đó là Y-sa-ca.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lê-a thọ thai nữa, sanh một con trai thứ sáu cho Gia-cốp,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'bèn nói rằng: Ðức Chúa Trời ban cho tôi một vật quí báu; lần nầy chồng sẽ ở cùng tôi, vì đã sanh cho người sáu con trai rồi. Nàng đặt tên đứa con trai nầy là Sa-bu-lôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Kế đó, nàng sanh một con gái, đặt tên là Ði-na.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Ðức Chúa Trời nhớ lại Ra-chên, bèn nhậm lời và cho nàng sanh sản.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Nàng thọ thai, sanh một con trai, mà rằng: Ðức Chúa Trời đã rửa sự xấu hổ cho tôi rồi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'bèn đặt tên đứa trai đó là Giô-sép; lại nói rằng: Cầu xin Ðức Giê-hô-va thêm cho một con trai nữa!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Khi Ra-chên đã sanh Giô-sép thì Gia-cốp thưa cùng La-ban rằng: Xin cậu cho tôi thôi, đặng trở về quê hương tôi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'xin giao vợ và con lại cho tôi, mà tôi đã đặng vì cớ giúp cậu, để tôi đi; bởi cậu cũng biết rằng tôi đã giúp công việc cho cậu thể nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'La-ban đáp rằng: Ước gì cậu được nhờ ơn cháu! Cậu cũng đoán rõ ràng Ðức Giê-hô-va đã vì cháu mà ban phước cho cậu vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Lại nói rằng: Cháu hãy định công giá cháu đi, rồi cậu sẽ trả cho!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Gia-cốp đáp: Cậu biết tôi giúp đỡ cậu thể nào, và về tay tôi bầy súc vật cậu được ra sao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Trước khi tôi đến, súc vật của cậu thật ít, nhưng từ khi tôi đến ở, thì thêm nhiều quá bội. Ðức Giê-hô-va đã ban phước cho cậu từ khi tôi bước chơn vào nhà nầy; bây giờ biết chừng nào tôi sẽ được lo việc nhà tôi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'La-ban rằng: Cậu sẽ cho cháu cái gì bây giờ? Ðáp rằng: Sẽ chẳng cho tôi chi cả. Nếu thuận theo lời nầy, thì tôi sẽ cho ăn và chăn bầy súc vật cậu nữa:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ngày nay tôi sẽ đi kiểm soát các bầy chiên và bầy dê của cậu; trong bầy chiên bầy dê, hễ con nào có rằn, có đốm, cùng chiên sắc đen, thì tôi sẽ để riêng ra; ấy sẽ là phần công giá của tôi đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Một mai cậu đi xem xét công giá tôi, thì lòng ngay thẳng tôi sẽ làm chứng trước mặt cậu. Hễ ở về phần bên tôi, các con dê nào không có rằn và đốm, các chiên con nào không có sắc đen, thì sẽ cho là ăn cắp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'La-ban đáp: Ừ thôi! được như lời cháu nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Chánh ngày đó, La-ban liền để riêng các dê đực có sọc, có đốm, các dê cái đó rằn, có đốm, các vật nào có đém trắng và các chiên con có sắc đen, giao cho mấy con trai mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'rồi để Gia-cốp cùng mình ở cách xa nhau chừng ba ngày đường; Gia-cốp bèn chăn bầy súc vật của La-ban chỉ còn lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Ðoạn, Gia-cốp lấy nhành bạch dương, nhành bồ đào và nhành bá-tiên tươi, lột vỏ để bày lằn da trắng ở trong ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Người để những nhành đã lột vỏ trong máng trước mặt con chiên, là nơi các thú đó đến uống; khi đến uống nước thì con chiên có giao hiệp nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Các con chiên ngó thấy những nhành đó mà giao hiệp nhau thì sanh chiên con có sọc, có rằn và có đốm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Gia-cốp để riêng chiên con ra, rồi để chiên cái trong bầy của La-ban trước mặt các con có sọc và có sắc đen; nhưng bầy mình thì riêng ra, không để gần bầy của La-ban.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Vả, mọi lần các con chiên mạnh mập giao hiệp, thì Gia-cốp để các nhành đó dưới mắt trong máng uống nước, đặng chúng nó đối nhành mà giao hiệp cùng nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Nhưng khi nào con chiên gầy ốm, thì người không để nhành như vậy; thế thì, các chiên con gầy ốm để về phần La-ban, còn chiên con mạnh mập lại về phần Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Vậy, người trở nên rất giàu, có nhiều bầy súc vật, tôi trai, tớ gái, lạc đà và lừa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Gia-cốp được nghe lời các con La-ban nói rằng: Gia-cốp đã lấy hết gia tài cha ta, và vì nhờ của cha ta, nên mới được giàu có dường ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Gia-cốp cũng để ý coi nét mặt cậu, nhận biết rằng người chẳng đối ở với mình như trước nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Ðức Giê-hô-va phán cùng Gia-cốp rằng: Hãy trở về xứ của tổ phụ ngươi, chốn bà con ngươi, ta sẽ phù hộ ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Gia-cốp bèn sai người gọi Ra-chên và Lê-a đến nơi cầm bầy súc vật của mình ngoài đồng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'và nói cùng họ rằng: Ta thấy sắc mặt cha hai ngươi đối cùng ta chẳng còn như trước nữa, nhưng nhờ Ðức Chúa Trời của cha ta phù hộ ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Chánh hai ngươi cũng biết rằng ta đã giúp cha hai ngươi hết sức,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'còn cha hai ngươi lại khinh bạc và mười lần thay đổi công giá ta; nhưng Ðức Chúa Trời không cho phép người làm hại ta chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Khi người dạy rằng: Các con chiên có đốm dùng làm công giá ngươi, quả các con chiên đều sanh con ra có sọc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Thế thì, Ðức Chúa Trời đã bắt súc vật của cha hai ngươi cho ta đó!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Ðương trong lúc chiên giao hiệp nhau, ta nhướng mắt lên, chiêm bao thấy các chiên đực đương giao hiệp cùng chiên cái đều có sọc, có rằn và có đốm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Thiên sứ Ðức Chúa Trời phán cùng ta trong mộng rằng: Hỡi Gia-cốp! Ta bèn thưa: Có tôi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Thiên sứ rằng: Hỡi nhướng mắt lên mà nhìn: hết thảy chiên đực đương giao hiệp cùng chiên cái đều có sọc, có rằn và có đốm; vì ta đã thấy cách La-ban ăn ở cùng ngươi rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ta đây là Ðức Chúa Trời của Bê-tên, tức nơi ngươi đã thoa dầu đầu cây trụ và đã khấn vái ta. Bây giờ, hãy đứng dậy, ra khỏi xứ bầy và trở về xứ của bà con ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Ra-chên và Lê-a đáp cùng người mà rằng: Chúng tôi còn một phần chi hay là cơ nghiệp chi nơi nhà cha chúng tôi chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Vì người đã gả bán chúng tôi và ăn xài hết tiền bạc bán nữa, há người chẳng đãi chúng tôi như người dưng ư?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Các tài vật mà Ðức Chúa Trời đoạt nơi tay cha chúng tôi tức là của chúng tôi và của con cái chúng tôi. Vậy bây giờ, chàng hãy làm theo mọi lời Ðức Chúa Trời đã phải dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Gia-cốp bèn đứng dậy, đỡ vợ và con lên lưng lạc đà,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'dẫn hết thảy súc vật và của cải mình, tức súc vật mình đã gây dựng ở Pha-đan-a-ram, đặng trở về cùng Y-sác, cha mình, ở Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Trong lúc La-ban mắc đi hớt lông chiên người, thì Ra-chên ăn cắp các pho tượng thờ trong nhà của cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Gia-cốp gạt La-ban, vì không nói rằng, mình muốn đi trốn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Vậy, người đứng dậy, đem theo hết thảy tài vật mình, trốn đi ngang qua sông, thẳng tuốt về núi Ga-la-át.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Ðến ngày thứ ba, người ta học lại cùng La-ban rằng Gia-cốp đã trốn đi rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Người bèn đem các anh em mình đuổi theo Gia-cốp trong bảy ngày đường, và theo kịp tại núi Ga-la-át.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Nhưng trong cơn chiêm bao lúc ban đêm, Ðức Chúa Trời đến cùng La-ban, người A-ram, mà phán rằng: Dầu lành dầu dữ, thế nào ngươi khá giữ mình đừng nói chi cùng Gia-cốp hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Vậy, La-ban theo kịp Gia-cốp. Vả, Gia-cốp đương đóng trại trên núi; La-ban và các anh em người cũng đóng trại trên núi Ga-la-át.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'La-ban nói cùng Gia-cốp rằng: Cháu đã làm chi vậy? Cháu đã gạt cậu và dẫn mấy đứa gái cậu như phu tù giặc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Sao trốn nhẹm, gạt và không cho cậu hay trước? Có lẽ cậu đưa đi rất vui vẻ, tiếng hát, tiếng đờn và tiếng trống phụ đưa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Cháu làm cách dại dột vậy, không để cho cậu hôn con trai và con gái cậu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Tay cậu có đủ quyền làm hại cháu; nhưng Ðức Chúa Trời của cha cháu đã mách bảo cùng cậu tối hôm qua rằng: Dầu lành dầu dữ, ngươi khá giữ mình đừng nói chi cùng Gia-cốp hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Bây giờ, vì lòng cháu mong mỏi về nhà cha cháu, nên đã ra đi; nhưng cớ sao cháu lại ăn cắp các pho tượng cậu?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Gia-cốp đáp rằng: Vì cớ tôi e cậu bắt hai người con gái lại chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Nhưng tìm nơi ai được các pho tượng của cậu, thì ai đó sẽ bị chết đi! Tại trước mặt các anh em chúng ta, cậu hãy kiểm soát các món nơi tôi đi, và hãy lấy vật chi thuộc về cậu. Vả, Gia-cốp vốn không hay rằng Ra-chên đã trộm mấy pho tượng đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Vậy, La-ban vào trại Gia-cốp, trại Lê-a, trại hai người đòi, chẳng tìm được chi cả. Ðoạn, ở trại Lê-a bước ra đi vào trại Ra-chên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Vả, Ra-chên có lấy mấy pho tượng đó, giấu dưới bành lạc đà, rồi ngồi lên trên. La-ban soát lục khắp trại chẳng gặp pho tượng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Nàng bèn thưa cùng cha rằng: Vì trong mình con có việc riêng của đờn bà, nên đứng dậy rước chẳng được; xin chúa chớ giận con chi hết. Người kiếm, nhưng chẳng thấy pho tượng đâu hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Gia-cốp bèn nổi giận rầy lộn cùng La-ban, mà rằng: Tôi có án gì, tội gì, mà cậu hằm hằm đuổi theo như vậy!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Cậu đã soát lục các đồ hành lý tôi, có kiếm được món chi thuộc về nhà cậu chăng? Hãy đem món đó ra trước mặt anh em tôi cùng anh em cậu, đặng họ xét đoán đôi ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Kìa, đã hai mươi năm tôi ăn ở nơi nhà cậu, chiên cùng dê cậu nào có sảo thai, và tôi chẳng hề ăn thịt chiên đực của bầy cậu bao giờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'cũng chẳng hề đem về cho cậu một con nào bị xé; bằng có, chính tôi chịu đền đó thôi. Cậu cớ đòi luôn những con bị ăn cắp ban ngày và ăn trộm ban đêm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Ban ngày tôi chịu nắng nồng, ban đêm chịu lạnh lùng, ngủ nào có an giấc được đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Ðó trong hai mươi năm tôi ở tại nhà cậu là thế; trong mười bốn năm giúp việc, để được hai con gái cậu, và sáu năm đặng lãnh lấy bầy súc vật của cậu, mà cậu lại còn thay đổi mười lần công giá tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Nếu Ðức Chúa Trời của cha tôi, Ðức Chúa Trời của Áp-ra-ham, là Ðấng mà Y-sác kính sợ, không phù hộ tôi, chắc bây giờ cậu đuổi tôi ra tay không, Ðức Chúa Trời đã xem thấy nỗi đau-khổ tôi cùng công việc hai tay tôi làm, nên đêm qua Ngài đã xét công bình rồi đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'La-ban đáp cùng Gia-cốp mà rằng: Các đứa gái nầy là con của cậu; các đứa trẻ nầy là trẻ của cậu; các bầy súc vật tức là bầy súc vật của cậu, và các vật chi cháu thấy được tức là của cậu hết; ngày nay cậu sẽ làm chi được cùng các con gái hai là các cháu cậu đó?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Vậy bây giờ, hè! chúng ta kết-ước cùng nhau, để dùng làm chứng cho cậu và cháu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Gia-cốp lấy một hòn đá, dựng đứng lên làm trụ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'và nói cùng các anh em mình rằng: Hãy lượm góp đá lại. Chúng bèn góp đá lại, chất thành một đống, rồi ngồi lên trên ăn bữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'La-ban đặt trên đống đá đó là Y-ê-ga Sa-ha-du-ta; còn Gia-cốp kêu là Ga-lét.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'La-ban nói rằng: Ðống đá nầy ngày nay làm chứng cho cậu và cháu đó. Cho nên chúng gọi là Ga-lét.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Mà cũng gọi là Mích-ba, vì La-ban có nói thêm rằng: Khi chúng ta phân cách nhau, cầu xin Ðức Giê-hô-va coi sóc cậu và cháu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Nếu cháu hành hạ các con gái cậu, nếu cưới vợ khác nữa, thì hãy giữ mình! Chẳng phải người thường soi xét ta đâu, bèn là Ðức Chúa Trời làm chứng cho chúng ta vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'La-ban lại nói cùng Gia-cốp rằng: Nầy đống đá, nầy cây trụ mình cậu đã dựng lên giữa cậu và cháu đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Ðống đá nầy và cây trụ nầy làm chứng rằng cậu chẳng qua khỏi đây, đi đến nơi cháu, và cháu cũng chẳng vượt khỏi đây, đi đến nơi cậu, trong khi có ý muốn làm hại nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Cầu xin Ðức Chúa Trời của Áp-ra-ham, Ðức Chúa Trời của Na-cô, Ðức Chúa Trời của cha các người đó đoán xét cho chúng ta! Gia-cốp chỉ Ðấng của Y-sác, cha mình, kính sợ mà thề.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Ðoạn, người dâng một của lễ tại trên núi, và mời các anh em mình dùng bánh. Vậy, chúng dùng bánh, rồi ở ban đêm trên núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'La-ban dậy sớm, hôn các con trai và các con gái mình, và chúc phước cho, rồi đi trở về nhà mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Gia-cốp cứ đi đường, có thiên sứ Ðức Chúa Trời gặp người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Khi Gia-cốp thấy các vị nầy, nói rằng: Ấy là trại quân của Ðức Chúa Trời! Nên người đặt tên chỗ đó là Ma-ha-na-im.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Gia-cốp sai sứ giả đến trước cùng Ê-sau, anh mình, trong xứ Sê -i-rơ thuộc về địa-phận Ê-đôm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'người bèn dặn rằng: Các ngươi hãy thưa cùng Ê-sau, chúa ta như vầy: Gia-cốp, kẻ tôi tớ chúa, có nói như vầy rằng: Tôi đã ngụ tại nhà La-ban đến ngày nay;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'có bò, lừa, chiên, tôi trai, tớ gái; vậy, xin sai đi nói cho chúa hay trước, hầu cho nhờ được ơn trước mặt chúa tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Các sứ giả trở về nói cùng Gia-cốp rằng: Chúng tôi đã đi đến Ê-sau, anh của chủ; nầy người đương đem bốn trăm người đến để rước chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Gia-cốp rất sợ hãi và sầu não, bèn chia các dân đi theo, cùng các bầy chiên, bò, lạc đà ra làm hai đội, mà rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Nếu Ê-sau đến hãm đánh một trong hai đội, thì đội còn lại sẽ thoát được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Ðoạn, Gia-cốp cầu rằng: Hỡi Ðức Chúa Trời của tổ phụ Áp-ra-ham tôi! Ðức Chúa Trời của cha Y-sác tôi, tức là Ðức Giê-hô-va! Ngài có phán dạy tôi rằng: Hãy trở về xứ ngươi và nơi bà con ngươi, rồi ta sẽ làm ơn cho ngươi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Tôi lấy làm hèn mọn không đáng chịu các ân huệ và các điều thành thực mà Ngài đã làm cho kẻ tôi tớ Ngài; vì lúc trước khi qua sông Giô-đanh chỉ có cây gậy tôi, mà ngày nay tôi lại trở nên hai đội quân nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Vậy, cầu xin Ðức Chúa Trời giải cứu tôi khỏi tay Ê-sau, anh tôi, vì e người đến đánh tôi và đánh luôn mẹ với con nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Vả, Ngài có nói rằng: Quả thật vậy, ta sẽ làm ơn cho ngươi, và làm cho dòng dõi ngươi đông như cát bãi biển, người ta sẽ không biết sao đếm được, vì đông đúc quá.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Người ở ban đêm tại đó, lấy các vật có hiện trong tay để làm một của lễ dâng cho Ê-sau, anh mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'là hai trăm dê cái và hai chục dê đực; hai trăm chiên cái và hai chục chiên đực;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'ba chục lạc đà cái có con đương bú, bốn chục bò cái và mười bò đực; hai chục con lừa cái và mười lừa con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Rồi, giao mỗi bầy riêng ra nơi tay đầy tớ mình và dặn rằng: Các ngươi hãy đi trước ta và dẫn bầy nầy cách một khoảng đến bầy kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Người dặn tên dẫn bầy đi trước hết như vầy: Khi Ê-sau, sanh ta, gặp và hỏi ngươi rằng: Ngươi ở với ai, đi đâu, và bầy súc vật trước mặt ngươi đó thuộc về ai?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'thì hãy thưa rằng: Của Gia-cốp, kẻ tôi tớ chúa; ấy là một lễ gởi dâng cho Ê-sau, chúa tôi; và nầy, chánh mình người đương theo sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Gia-cốp cũng dặn y lời cho tên dẫn bầy thứ nhì, thứ ba và hết thảy người theo coi chừng các bầy, và lại nói: Khi gặp Ê-sau, các ngươi hãy nhớ lời đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'và nói như vầy: Nầy, Gia-cốp, kẻ tôi tớ chúa, đương theo sau chúng tôi. Vì người thầm nghĩ rằng: Mình đem lễ nầy dâng trước cho Ê-sau nguôi giận đã, rồi mình sẽ giáp mặt sau; có lẽ người tiếp rước mình một cách thuận hiệp đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Vậy, lễ nầy đem đi trước, còn người, đêm đó ở lại trại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Ban đêm, người thức dậy, dẫn hai vợ, hai tên đòi và mười một đứa con mình đi qua rạch Gia-bốc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Người đem họ qua rạch, và hết thảy của cải mình qua nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Vả, một mình Gia-cốp ở lại; thì có một người vật lộn với mình được rạng đông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Khi người đó thấy mình không thắng nổi, bèn đánh vào xương hông Gia-cốp; xương hông liền trặt trong khi vật lộn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Người đó bèn nói: Trời đã rạng đông rồi; thôi để cho ta đi; nhưng Gia-cốp đáp rằng: Tôi chẳng cho người đi đâu, nếu người không ban phước cho tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Người đó hỏi: Tên ngươi là chi? Ðáp rằng: Tên tôi là Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Người lại nói: Tên ngươi sẽ chẳng làm Gia-cốp nữa, nhưng tên là Y-sơ-ra-ên, vì ngươi đã có vật lộn cùng Ðức Chúa Trời và người ta; ngươi đều được thắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Gia-cốp hỏi: Xin cho tôi biết tên người. Ðáp rằng: Làm sao ngươi hỏi tên ta? Rồi người nầy ban phước cho Gia-cốp tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Gia-cốp đặt tên chỗ đó là Phê-ni-ên, và nói rằng: Tôi đã thấy Ðức Chúa Trời đối mặt cùng tôi và linh hồn tôi được giải cứu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Khi qua nơi Phi-ni-ên, thấy mặt trời mọc rồi; và người đi giẹo cẳng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Bởi cớ đó, cho đến ngày nay dân Y-sơ-ra-ên chẳng bao giờ ăn gân bắp vế của lối xương hông; vì người đó có đánh vào xương hông Gia-cốp, nơi gân của bắp vế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Gia-cốp nhướng mắt lên và nhìn, kìa, Ê-sau dẫn bốn trăm người đi đến. Người bèn chia các con cho Lê-a, Ra-chên, và cho hai tên đòi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'sắp hai tên đòi và con cái họ ở trước; kế đến Lê-a và con cái nàng; Ra-chên cùng Giô-sép ở sau chót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Còn người, thì đi trước họ và sấp mình xuống đất bảy lần cho đến khi tới gần anh mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Nhưng Ê-sau chạy đến trước mặt người, ôm choàng cổ mà hôn, rồi hai anh em đều khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Ðoạn, Ê-sau nhướng mắt lên thấy mấy người đờn bà và con cái, thì hỏi rằng: Các người mà em có đó là ai? Ðáp rằng: Ấy là con cái mà Ðức Chúa Trời đã cho kẻ tôi tớ anh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Hai tên đòi và con cái họ lại gần người, sấp mình xuống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Lê-a và các con cái nàng cũng lại gần, sấp mình xuống; đoạn, Ra-chên và Giô-sép lại gần, và sấp mình xuống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Ê-sau hỏi: Toán quân anh đã gặp đi trước đó, em tính làm chi? Ðáp rằng: Ấy để nhờ được ơn trước mặt chúa tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Ê-sau nói: Hỡi em! anh đã được đủ rồi; vậy, hãy lấy lại vật chi của em đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Thưa rằng: Xin anh, không. Nếu em được ơn trước mặt anh, hãy nhậm lấy lễ vật bởi tay em làm ra đi; vì em thấy được mặt anh khác nào người ta thấy được mặt Ðức Chúa Trời, và anh đã đẹp lòng tiếp rước em.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Xin anh hãy nhậm lấy lễ vật em đã dâng cho anh, vì Ðức Chúa Trời cho em đầy dẫy ân huệ, và em có đủ hết. Người nài xin Ê-sau quá đến đỗi phải chịu nhậm lấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Ê-sau nói: Hè, ta hãy lên đường! Anh sẽ đi trước em.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Gia-cốp đáp: Chúa biết rằng các đứa trả yếu lắm, và em lại mắc coi chừng chiên và bò cái đương có con bú; nếu ép đi mau chỉ trong một ngày, chắc cả bầy phải chết hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Xin chúa hãy đi trước kẻ tôi tớ chúa, còn tôi sẽ đi tới chậm chậm theo bước một của súc vật đi trước và của các trẻ, cho đến chừng nào tới nhà chúa tại xứ Sê -i-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Ê-sau nói: Vậy, anh xin để lại cùng em một vài người tùy tùng của anh. Gia-cốp đáp rằng: Chi vậy? miễn em được nhờ ơn trước mặt chúa thôi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Nội ngày đó, Ê-sau bắt đường trở về Sê -i-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Gia-cốp đi đến Su-cốt; bèn cất một nhà cho mình ở, và mấy cái lều cho súc vật; cho nên họ đặt tên chốn nầy là Su-cốt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Gia-cốp ở xứ Pha-ran-a-ram đến thành Si-chem thuộc về xứ Ca-na-an, được bình an. Người đóng tại trước thành,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'bèn mua miếng đất chỗ người đóng trại, giá một trăm miếng bạc của con Hê-mô, cha Si-chem.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Nơi đó người lập một bàn thờ, đặt trên là En-Eân-ô-hê -Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Nàng Ði-na, con gái của Lê-a sanh cho Gia-cốp, đi ra thăm bọn con gái của xứ đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Si-chem, con trai Hê-mô, người Hê-vít, hoàng tử xứ đó, thấy nàng, thì cướp đi, nằm với nàng và làm điếm nhục nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Tâm hồn chàng vấn-vít cùng Ði-na, con gái Gia-cốp, thương mến con gái tơ đó, lấy lời ngon ngọt nói cùng nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Si-chem nói cùng Hê-mô, cha mình, rằng: Hãy cho tôi con gái nầy làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Vả, Gia-cốp hay được rằng chàng làm hư danh giá Ði-na, con gái mình, nhưng các con trai mình mắc ở ngoài đồng cùng súc vật, nên người làm thinh đến khi họ trở về.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Lúc đó, Hê-mê, cha Si-chem, đến cùng Gia-cốp đặng nói chuyện cùng người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Các con trai Gia-cốp ở ngoài đồng trở về, vừa hay được việc ấy, bèn nổi nóng và giận lắm, vì việc ô danh mà Si-chem đã xui cho họ Y-sơ-ra-ên, nằm cùng con gái của Gia-cốp, là việc chẳng bao giờ nên làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Hê-mô nói cùng họ rằng: Tâm hồn Si-chem, con trai tôi, đã dan-díu cùng con gái các ông; xin hãy gả nàng cho nó làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Hãy kết sui-gia cùng nhau; các ông gả con gái cho chúng tôi, rồi cưới các con gái chúng tôi lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Hãy ở cùng chúng tôi; xứ sẵn dành cho các ông; hãy ở, buôn bán và dựng cơ nghiệp tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Si-chem thưa cùng cha và các anh em của người con gái rằng: Xin cho tôi được ơn trước mặt các ông, và điều chi các ông nói, tôi xin nạp cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Xin hãy đòi một lễ cưới cho lớn, sính nghi cho cao, tôi xin nạp theo y lời các ông nói; nhưng hãy gả con gái đó cho tôi làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Các con trai Gia-cốp đáp lại cùng Si-chem và Hê-mô, cha chàng, cùng dùng mưu nói chuyện với họ, vì Si-chem đã làm mất danh giá của Ði-na, em gái mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Các người ấy nói rằng: Gả em gái chúng tôi cho ai chẳng chịu phép cắt bì, ấy là một việc chúng tôi làm không được, vì sẽ là một nỗi nhuốc nha cho chúng tôi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Chúng tôi sẽ nhậm lời các ông được, là khi nào các ông trở nên giống như chúng tôi, tức là mọi người nam chịu phép cắt bì;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'vậy, chúng tôi sẽ gả con gái chúng tôi cho các ông, và sẽ cưới con gái các ông lại; đoạn ta sẽ ở chung nhau, thành ra một dân mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Còn nếu không khứng nghe theo lời, và không chịu phép cắt bì, thì chúng tôi bắt con gái lại và đi ở nơi khác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Bao nhiêu lời họ nói làm cho đẹp dạ Hê-mô và Si-chem, con trai người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Chàng trẻ tuổi đó không ngần ngại các việc họ đã định, vì con gái của Gia-cốp đẹp lòng chàng. Vả, chàng đây là một người quí trọng hơn mọi người trong nhà cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Vậy, Hê-mô và Si-chem, con trai người, đi đến cửa thành mình, nói cùng dân trong thành như vầy:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Các người đó ăn ở hòa thuận giữa vòng chúng ta; vậy cho họ ở trong xứ đặng buôn bán. Nầy, xứ cũng rộng cho họ ở; chúng ta sẽ cưới con gái họ làm vợ, và gả các con gái chúng ta lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Nhưng họ bằng lòng ở cùng chúng ta đặng thành một dân, miễn khi nào các người nam trong bọn mình phải chịu phép cắt bì chính như mọi người nam của họ vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Thế thì, há rằng các súc vật, các tài sản và các bầy của họ sẽ chẳng thuộc về chúng ta sao? thôi, ta hãy nhận theo họ điều đó đi, để họ ở chung cùng chúng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Mọi người đi ra cửa thành mình đều nghe theo lời Hê-mô và Si-chem, con trai người, và hết thảy người nam đi ra cửa thành mình đều chịu phép cắt bì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Ðến ngày thứ ba, khi mọi người đương đau đớn, thì hai con trai Gia-cốp, là Si-mê-ôn và Lê-vi, anh nàng Ði-na, cầm mỗi người một thanh gươm, thừa khi ai nấy yên ổn, xông vào thành giết hết thảy người nam.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Hai người lại lấy gươm giết Hê-mô và Si-chem, con trai người, đem nàng Ði-na ra khỏi nhà Si-chem, rồi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Vì cớ họ làm mất danh giá em gái mình, nên các con trai Gia-cốp xông vào những xác chết và phá cướp thành;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'bắt các bầy chiên, bò, lừa, cùng vật chi trong thành và ngoài đồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'cướp đem đi hết tài vật, các con trẻ và đờn bà, cùng mọi vật chi ở trong nhà vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Gia-cốp bèn nói cùng Si-mê-ôn và Lê-vi rằng: Bay xui cho tao bối rối, làm cho dân xứ nầy, là người Ca-na-an và người Phê-rê-sít, oán ghét tao vậy. Tao đây, chỉ có ít người; nếu họ hiệp lại đánh tao, thì chắc tao và nội nhà đều bị tàn hại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Ðáp rằng: Chúng tôi nỡ chịu người ta đãi em gái chúng tôi như con đĩ sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Ðức Chúa Trời phán cùng Gia-cốp rằng: Hãy chổi dậy, đi lên Bê-tên mà ở, và hãy lập nơi đó một bàn thờ cho Ðức Chúa Trời, là Ðấng hiện ra cùng ngươi đương lúc chạy trốn khỏi Ê-sau, anh ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Gia-cốp bèn nói cùng vợ con và mọi kẻ đi theo mình rằng: Hãy dẹp các tượng thần ngoại bang khỏi giữa các ngươi, làm cho mình được thanh sạch và thay áo xống đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Ðoạn, chúng ta hãy chổi dậy, đi đến Bê-tên, nơi đó ta sẽ lập một bàn thờ cho Ðức Chúa Trời, là Ðấng đã trả lời ta trong lúc nguy hiểm, và đã phù hộ ta trong khi đi đường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Họ bèn đưa cho Gia-cốp các tượng thần ngoại bang của mình, và các vòng đeo nơi tai; rồi người chôn mấy vật đó dưới gốc cây dẻ bộp, gần thành Si-chem.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Ðoạn, chúng khởi hành. Ðức Chúa Trời bèn giáng sự kinh hãi cho các thành ở chung quanh đó, nên họ chẳng dám đuổi theo các con trai của Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Gia-cốp cùng mọi kẻ đi theo đến tại Lu-xơ (là thành Bê-tên), thuộc về xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Người lập tại đó một bàn thờ, đặt tên chốn nầy Eân-Bê-tên, vì là nơi Ðức Chúa Trời đã hiện ra cùng người trong lúc chạy trốn khỏi anh mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Khi đó Ðê-bô-ra, mụ vú của Rê-be-ca, qua đời, được chôn thân dưới thành Bê-tên tại gốc dẻ bộp; nhơn đó người ta gọi là cây A-lôn-Ba-cút.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Khi ở xứ Pha-đan-a-ram đến, Ðức Chúa Trời lại hiện ra cùng Gia-cốp nữa, ban phước cho người,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'và phán rằng: Tên ngươi là Gia-cốp, sau nầy sẽ chẳng gọi Gia-cốp nữa, nhưng sẽ đặt là Y-sơ-ra-ên. Rồi Ngài đặt tên người là Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Ðức Chúa Trời lại phán rằng: Ta là Ðức Chúa Trời toàn năng; ngươi hãy sanh sản và thêm nhiều; một dân cho đến nhiều dân đều sẽ do nơi ngươi mà sanh, cùng các vua sẽ do nơi mình ngươi mà ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Xứ ta đã cho Áp-ra-ham và Y-sác thì ta sẽ cho ngươi cùng dòng dõi ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Ðức Chúa Trời bèn ngự lên khỏi nơi Ngài đã phải cùng Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Người dựng một cây trụ đó tại nơi Ðức Chúa Trời đã phán cùng mình, dâng lễ quán và tưới dầu vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Ðoạn, Gia-cốp đặt tên nơi Ðức Chúa Trời đã phán cùng mình là Bê-tên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Ở từ Bê-tên đi, họ còn cách Eân-phù-hộ-rát chừng vào thôi đường, thì Ra-chên sanh nở. Việc sanh nở của người thật đau đớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Trong khi khó sanh, bà mụ nói rằng: Ðừng sợ chi, vì nàng còn một con trai nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Vả, bởi Ra-chên gần trút linh hồn, vì đương cơn hấp hối, nên người đặt đứa con trai đó tên là Bê-nô-ni; còn cha nó lại đặt tên là Bên-gia-min.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Vậy, Ra-chên qua đời, được chôn bên con đường đi về Ê-phơ-rát, tức là Bết-lê-hem.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Gia-cốp dựng một mộ-bia; ấy là mộ-bia của Ra-chên đến ngày nay hãy còn di tích.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Kế đó, Y-sơ-ra-ên đi, đóng trại ở ngoài nơi tháp Ê-để.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Vả, nhầm khi Y-sơ-ra-ên ngụ tại xứ nầy, thì Ru-bên có đến nằm cùng Bi-la, vợ lẽ của cha mình; Y-sơ-ra-ên hay được việc đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Vả, Gia-cốp có được mười hai con trai. Con của Lê-a là Ru-bên, trưởng nam của Gia-cốp; kế nữa là Si-mê-ôn, Lê-vi, Giu-đa, Y-sa-ca và Sa-bu-lôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Con của Ra-chên và Giô-sép và Bên-gia-min.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Con của Bi-la, đòi của Ra-chên là Ðan và Nép-ta-li;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'và con của Xinh-ba, đòi của Lê-a, là Gát và A-se. Ấy đó là các con trai của Gia-cốp sanh tại xứ Pha-đan-a-ram.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Gia-cốp đến cùng Y-sác, cha mình, ở Mam-rê, tại thành Ki-ri-át-a-ra-ba, tức là Hếp-rôn, nơi Áp-ra-ham và Y-sác đã kiều ngụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Y-sác hưởng thọ được một trăm tám mươi tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Người tuổi cao tác lớn, thỏa mãn về đời mình, tắt hơi, được về cùng tổ phụ. Ê-sau và Gia-cốp, hai con trai, chôn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Ðây là dòng dõi của Ê-sau, tức là Ê-đôm vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ê-sau cưới các vợ trong bọn con gái xứ Ca-na-an, là A-đa, con gái Ê-lôn, người Hê-tít; Ô-hô-li-ba-ma, con gái A-na, cháu ngoại của Xi-bê-ôn, người Hê-vít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'cùng Bách-mát, con gái Ích-ma-ên, và là em gái của Nê-ba-giốt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'A-đa sanh Ê-li-pha cho Ê-sau; Bách-mát sanh Rê -u-ên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'còn Ô-hô-li-ba-ma sanh Giê-úc, Gia-lam và Cô-ra. Ấy đó là các con trai của Ê-sau sanh tại xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ê-sau dẫn các vợ, con trai, con gái mình, mọi người nhà, các bầy chiên, lục-súc, và tài vật mình đã gây dựng tại xứ Ca-na-an, dời qua xứ khác, cách xa Gia-cốp, em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Vả, vì cớ hai anh em của cải nhiều, bầy súc vật đông, xứ đương kiều ngụ không đủ đất dùng nữa, nên ở chung nhau chẳng được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Vậy, Ê-sau, tức là Ê-đôm, ở trên núi Sê -i-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Ðây là dòng dõi Ê-sau, tổ phụ dân Ê-đôm, ở trên núi Sê -i-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ðây là tên các con trai Ê-sau: A-đa-vợ người, sanh Ê-li-pha; Bách-mát, cũng vợ người, sanh Rê -u-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Con trai của Ê-li-pha là Thê-ma, Ô-ma, Xê-phô, Ga-tham và Kê-na.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Thim-na, vợ lẽ Ê-li-pha, con trai của Ê-sau, sanh A-ma-léc cho người. Ðó là cháu của A-đa, vợ Ê-sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Còn đây là con trai của Rê -u-ên: Na-hát, Xê-rách, Sam-ma và Mích-xa. Ấy là các cháu của Bách-mát, cùng vợ Ê-sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Và mấy người nầy là con trai của Ô-lô-li-ba-ma, vợ của Ê-sau, con gái A-na, cháu ngoại Xi-bê-ôn. Nàng sanh cho Ê-sau Giê-úc, Gai-lam, và Cô-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ðây là các trưởng tộc trong vòng con cháu Ê-sau: Các con trai Ê-li-pha con trưởng nam của Ê-sau, là trưởng tộc Thê-man, trưởng tộc Ô-ma, trưởng tộc Xê-phô, trưởng tộc Kê-na,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'trưởng tộc A-ma-léc. Ðó là các trưởng tộc do nơi Ê-li-pha sanh tại xứ Ê-đôm, và là các cháu của A-đa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Ðây là các con trai của Rê -u-ên, con Ê-sau: trưởng tộc Na-hát, trưởng tộc Xê-rách, trưởng tộc Sam-ma, và trưởng tộc Mích-xa. Ðó là các trưởng tộc do nơi Rê -u-ên sanh ra tại xứ Ê-đôm, và là các cháu của Bách-mát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Ðây là các con trai của Ô-lo-li-ba-ma, vợ Ê-sau: trưởng tộc Giê-úc, trưởng tộc Gia-lam, và trưởng tộc Cô-ra. Ðó là mấy trưởng tộc do Ô-hô-li-ba-ma, vợ Ê-sau, con gái của A-na, sanh ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ấy là các con trai của Ê-sau, tức là Ê-đôm, và đó là mấy trưởng tộc của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Ðây là các con trai của Sê -i-rơ, người Hô-rít, thuở xưa ở tại xứ đó: Lô-than, Sô-banh, Xi-bê-ôn, A-na,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Ði-sôn, Ét-xe, và Ði-san. Ðó là mấy con trai của Sê -i-rơ, trưởng tộc dân Hô-rít, ở tại xứ Ê-đôm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Các con trai của Lô-than là Hô-ri và Hê-man; còn Thim-na là em của gái Lô-than.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Ðây là các con trai của Sô-banh: Anh-van, Ma-na-hát, Ê-banh, Sê-phô, và Ô-nam.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Ðây là các con trai của Xi-bê-ôn: Ai-gia và A-na. Ấy là A-na có tìm đặng suối nước sôi nơi đồng vắng, trong khi chăn lừa cho Xi-bê-ôn, cha nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Ðây là con cái của A-na: Ði-sôn và Ô-hô-li-ba-ma, con gái người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Ðây là con trai của Ði-sôn: Hem-đan, Ếch-ban, Dít-ran và Kê-ran.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ðây là con trai của Ét-xe: Binh-han, Xa-van và A-can.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Ðây là con trai của Ði-san: Uùt-sơ và A-ran.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Còn đây là các trưởng tộc dân Hô-rít: trưởng tộc Lô-than, trưởng tộc Sô-banh, trưởng tộc Xi-bê-ôn, trưởng tộc A-na,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'trưởng tộc Ði-sôn, trưởng tộc Ét-xe, và trưởng tộc Ði-san. Ðó là các trưởng tộc của dân Hô-rít, ở tại xứ Sê -i-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Trước khi dân Y-sơ-ra-ên chưa có một vua nào cai trị, thì đây là các vua trị vì xứ Ê-đôm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bê-la, con trai Bê-ô, trì vì xứ Ê-đôm; tên thành người là Ðin-ha-ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Vua Bê-la băng, Giô-báp, con trai Xê-rách, người Bốt-ra, lên kế vị.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Vua Giô-báp băng, Hu-sam, người xứ Thê-man, lên kế vị.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Vua Hu-sam băng, Ha-đát, con trai Bê-đát, lên kế vị. Ấy là vua nầy đánh thắng dân Ma-đi-an tại đồng Mô-áp; và tên thành người là A-vít.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Vua Ha-đát băng, Sam-la, người Ma-rê-ca lên kế vị.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Vua Sam-la băng, Sau-lơ, người Rê-hô-bốt ở trên mé sông, lên kế vị.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Vua Sau-lơ băng, Ba-anh-Ha-man, con trai Aïc-bồ, lên kế vị.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'vua Ba-anh-Ha-nan băng, Ha-đa lên kế vị. Tên thành người là Ba -u; vợ người là Mê-hê-ta-bê-ên, con gái của Mát-rết, cháu ngoại Mê-xa-háp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Ðây là trưởng tộc do nơi Ê-sau sanh ra, kể theo chi tộc, địa hạt và tên mình: trưởng tộc Thim-na, trưởng tộc Anh-va, trưởng tộc Giê-hết,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'trưởng tộc Ô-hô-li-ba-ma, trưởng tộc Ê-la, trưởng tộc Phi-nôn,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'trưởng tộc Kê-na, trưởng tộc Thê-man, trưởng tộc Mép-xa,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'trưởng tộc Mác-đi-ên à trưởng tộc Y-ram. Ðó là các trưởng tộc của Ê-đôm, tùy theo nhà ở trong xứ của họ. Tổ phụ của dân Ê-đôm là Ê-sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Gia-cốp, tại xứ của cha mình đã kiều ngụ, là xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ðây là chuyện dòng dõi của Gia-cốp. Giô-sép, tuổi mười bảy, chăn chiên với các anh mình; người đi kết bạn cùng con trai Bi-la và con Xinh-ba, hai vợ cha mình. Giô-sép thuật lại với cha các chuyện xấu của họ nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Vả, Y-sơ-ra-ên thương yêu Giô-sép hơn những con trai khác, vì là con muộn mình, nên may cho chàng một cái áo dài có nhiều sắc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Các anh thấy cha thương Giô-sép hơn bọn mình, bèn sanh lòng ganh ghét, chẳng có thế lấy lời tử tế nói cùng chàng được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Giô-sép có nằm chiêm bao, thuật lại cho các anh mình nghe; họ càng thêm ganh ghét nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Người nói rằng: Tôi có điềm chiêm bao, xin các anh hãy nghe tôi thuật:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Chúng ta đương ở ngoài đồng bó lúa, nầy bó lúa tôi đứng dựng lên, còn bó lúa của các anh đều đến ở chung quanh, sấp mình xuống trước bó lúa tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Các anh người bèn đáp rằng: Vậy, mầy sẽ cai trị chúng ta sao? mầy sẽ hành-quyền trên chúng ta sao? Họ càng ganh ghét hơn nữa, vì điềm chiêm bao và lời nói của chàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Giô-sép lại nằm chiêm bao nữa, thuật cùng các anh mình rằng: Tôi còn một điềm chiêm bao nữa: Nầy mặt trời, mặt trăng, và mười một ngôi sao đều sấp mình xuống trước mặt tôi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Chàng thuật chiêm bao đó lại cho cha và các anh mình nghe; nhưng cha chàng quở mà hỏi rằng: Ðiềm chiêm bao của mầy đó có nghĩa chi? Có phải tao, mẹ, và các anh mầy đều phải đến sấp mình xuống đất trước mặt mầy chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Các anh lấy làm ganh ghét chàng; còn cha lại ghi nhớ lấy điều đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Các anh chàng đi chăn chiên của cha tại Si-chem.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Y-sơ-ra-ên nói cùng Giô-sép rằng: Các anh con có chăn bầy chiên tại Si-chem chăng? Lại đây, đặng cha sai con đi đến chúng nó. Giô-sép đáp rằng: Có con đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Y-sơ-ra-ên biểu rằng: Con hãy đi, xem thử các anh con ra sao, và các bầy chiên thể nào; rồi đem tin về cho cha hay. Vậy, từ trũng Hếp-rôn, người sai Giô-sép đi đến Si-chem.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Có một người gặp chàng đi lạc trong đồng ruộng, liền hỏi và nói cùng chàng rằng: Ngươi tìm chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Ðáp rằng: Tôi tìm các anh tôi. Xin hãy chỉ giùm tôi họ chăn bầy chiên nơi nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Người nói: Các anh ngươi ở đây đi rồi, vì tôi có nghe họ nói rằng: Ta hãy đi đến Ðô-ta-in. Vậy, Giô-sép, đi tìm các anh mình, gặp được tại Ðô-ta-in.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Các anh thấy chàng đi ở đàng xa, chưa đến gần, thì đã lập mưu để giết chàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Chúng bèn nói nhau rằng: Kìa, thằng nằm mộng đến kia!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Bây giờ, nào! chúng ta hãy giết nó đi, quăng xuống một cái hố nước nào đó; đoạn ta sẽ nói rằng nó đã bị thú rừng xé ăn, rồi sẽ xem các điềm chiêm bao của nó ra sao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Ru-bên nghe qua lời đó, liền giải cứu chàng ra khỏi ra các anh mà rằng: Chúng ta đừng giết chết nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'lại tiếp: Chúng ta chớ nên làm đổ máu ra; hãy liệng nó trong cái hố nước nơi đồng vắng kia, và đừng tra tay vào mình nó. Người nói vậy, có ý muốn giải cứu chàng khỏi tay họ, để trả chàng về cùng cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Vừa khi Giô-sép đến gần các anh, họ bèn lột áo chàng, là áo có nhiều sắc đương mặc trong mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'rồi, bắt chàng đem quăng trong hố nước. Vả, hố khô cạn, chẳng có nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Ðoạn, họ ngồi lại ăn. Nhướng mắt lên chợt thấy một đoàn dân Ích-ma-ên ở phía Ga-la-át đi đến, trên lưng lạc đà họ chở đầy thuốc thơm, nhũ hương và một dược đương đem đi đến xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Giu-đa bèn nói cùng các anh em rằng: Giết em ta mà giấu máu nó, có dùng cho ta được việc chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Hè! hãy đem bán nó cho dân Ích-ma-ên và đừng tra tay vào mình nó; vì nó là em, là cốt nhục của chúng ta. Các anh em đều nghe theo lời người nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Vả, khi những lái-buôn Ma-đi-an đi ngang qua, các anh kéo Giô-sép lên khỏi hố nước, rồi bán chàng giá hai mươi miếng bạc cho dân Ích-ma-ên đem qua xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Ru-bên trở lại hố; nầy Giô-sép đâu mất rồi; bèn xé áo mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'trở lại nơi các em mình mà rằng: Ôi! đứa trẻ đâu mất rồi! còn tôi, sẽ đi đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Các anh giết một con dê đực, rồi lấy áo Giô-sép nhúng vào trong máu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'đoạn, gởi cái áo nhiều sắc đó đem về cho cha mình và dặn nói rằng: Ðây là vật chúng tôi đã kiếm được. Vậy, xin hãy nhìn coi, có phải áo của con trai cha chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Gia-cốp nhìn và nói rằng: Ấy là áo của con trai ta đó; một thú dữ đã xé cấu nó! Quả thật Giô-sép đã bị phân thây rồi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Người xé quần áo mình ra, lấy bao quấn ngang hông, và để tang lâu ngày cho con trai mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Hết thảy con trai, con gái hiệp lại an ủy người, nhưng không chịu; bèn nói rằng: Ta để tang luôn xuống chốn âm phủ cùng con ta! Ấy đó, cha Giô-sép khóc than chàng như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Các lái buôn Ma-đi-an đem Giô-sép đến xứ Ê-díp-tô, bán cho Phô-ti-pha, quan thị vệ của Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Trong lúc đó, Giu-đa, lìa xa các anh em mình, đến ở cùng một người A-đu-lam, tên là Hi-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Tại đó, Giu-đa thấy con gái của một người Ca-na-an, tên là Su-a, bèn cưới làm vợ, và ăn ở cùng nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Nàng thọ thai, sanh được một con trai, đặt tên là Ê-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Nàng thọ thai nữa, sanh được một con trai đặt tên là Ô-nan;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'lại sanh thêm một con trai, đặt tên là Sê-la. Vả, lúc vợ sanh sản, thì Giu-đa ngụ tại Kê-xíp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Giu-đa cưới cho Ê-rơ, con trưởng nam, một người vợ tên là Ta-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Nhưng Ê-rơ độc ác trước mặt Ðức Giê-hô-va, nên Ngài giết người đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Giu-đa bèn biểu Ô-nan rằng: Con hãy lại gần vợ anh con, kết bạn cùng nàng như em chồng, đặng nối dòng dõi cho anh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Ô-nan biết rằng dòng dõi nầy sẽ chẳng thuộc về mình, nên đương khi đến cùng nàng, thì làm rơi rớt xuống đất, để đừng sanh dòng dõi cho anh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Nhưng điều người làm vậy không đẹp lòng Ðức Giê-hô-va, nên Ngài cũng giết người luôn đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Ðoạn, Giu-đa biểu Ta-ma, dâu mình, rằng: Hãy về ở góa bên nhà cha con, cho đến chừng nào Sê-la, con trai cha, sẽ trở nên khôn lớn. Vì người nói rằng: Chúng ta hãy coi chừng, e khi nó cũng chết như hai anh nó chăng. Ta-ma bèn đi về ở nhà cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Ngày qua tháng lại, con gái của Su-a, vợ Giu-đa, qua đời. Khi đã nguôi lòng, thì Giu-đa đi cùng bạn là Hi-ra, người A-đu-lam, lên đến nơi mấy thợ hớt lông chiên mình, tại Thim-na.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Người ta cho nàng Ta-ma hay điều đó mà rằng: Nầy, ông gia ngươi đi khiến Thim-na đặng hớt lông chiên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Nàng bèn cổi áo góa bụa mình lại, rồi ngồi trước cửa thành Ê-na-im, bên con đường đi về Thim-na; làm vậy là vì nàng đã thấy Sê-la khôn lớn rồi, nhưng họ không gả mình cho chàng làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Giu-đa thấy nàng, cho là một kỵ nữ, vì nàng che mặt,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'bèn lại gần mà nói rằng: Hãy cho ta đến cùng nàng; vì cớ ngươi không biết nàng là dâu mình. Nàng đáp rằng: Ngươi sẽ cho tôi món chi đặng đi đến cùng tôi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Ðáp rằng: Ta sẽ gởi cho nàng một con dê con của bầy ta. Nàng hỏi: Người sẽ cho tôi một của chi làm tin, cho đến chừng nào sẽ gởi con dê?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Ðáp rằng: Ta sẽ cho nàng của chi làm tin bây giờ? Nàng đáp: Con dầu, dây và cây gậy của người đương cầm nơi tay. Người liền cho, đi lại cùng nàng; nàng thọ thai vì người vậy. Ðoạn, nàng đứng dậy mà đi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'cổi lúp ra và mặc quần áo góa bụa lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Giu-đa cậy bạn A-đu-lam mình đem cho con dê con đặng chuộc mấy vật tin nơi tay người đờn bà nầy; nhưng tìm nàng chẳng thấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Bạn bèn hỏi dân tại nơi nàng ở rằng: Người kỵ nữ khi trước ở ngoài đường nơi cửa thành Ê-na-im đâu rồi? Họ đáp rằng: Ở đây chẳng có một kỵ nữ nào hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Bạn bèn trở về Giu-đa mà rằng: Tôi kiếm nàng không đặng; và dân nơi đó có nói: ở đây chẳng có một kỵ nữ nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Giu-đa rằng: Nầy, tôi đã gởi dê con đến, mà bạn chẳng thấy nàng; vậy, để cho nàng giữ lấy của tin đó, chẳng nên gây điều nhơ nhuốc cho chúng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Cách chừng ba tháng sau, người ta có học lại cùng Giu-đa rằng: Ta-ma, dâu ngươi, đã làm kỵ nữ, và vì nông nổi đó, nàng đã hoang-thai. Giu-đa đáp: Hãy đem nó ra thiêu đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Ðương khi người ta đem nàng ra, thì nàng sai đến nói cùng ông gia rằng: Xin cha hãy nhìn lại con dấu, dây và gậy nầy là của ai. Tôi thọ thai do nơi người mà có các vật nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Giu-đa nhìn biết mấy món đó, bèn nói rằng: Nàng phải hơn ta, vì ta không đưa Sê-la, con trai ta, cho nàng. Ðoạn, người không ăn ở cùng nàng nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Ðến kỳ sanh nở, nầy trong bụng nàng có thai đôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Ðương lúc sanh nở, một trong hai đứa đưa tay ra trước; bà mụ bắt lấy tay buộc một sợi chỉ điều, và nói rằng: Ðứa nầy ra trước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Nhưng nó rút tay vào, thì đây, anh nó lại ra. Bà mụ nói rằng: Mầy, tông rách dường nầy! Họ đặt tên là Phê-rết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Kế em nó ra sau, là đứa nơi tay có sợi chỉ điều, và họ đặt tên là Sê-rách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Vả, Giô-sép bị đem qua xứ Ê-díp-tô, thì Phô-ti-pha, người bổn xứ, làm quan thị vệ của Pha-ra-ôn, mua chàng nơi thay dân Ích-ma-ên đã dẫn đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Giô-sép ở trong nhà chủ mình, là người Ê-díp-tô, được Ðức Giê-hô-va phù hộ, nên thạnh lợi luôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Chủ thấy Ðức Giê-hô-va phù hộ chàng và xui cho mọi việc chi chàng lãnh làm nơi tay đều được thạnh vượng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Vậy, Giô-sép được ơn trước mặt chủ mình; chủ cắt chàng hầu việc, đặt cai quản cửa nhà, và phó của cải mình cho chàng hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Từ khi người đặt Giô-sép cai quản cửa nhà cùng hết thảy của cải mình rồi, thì Ðức Giê-hô-va vì Giô-sép ban phước cho nhà người; sự ban phước của Ðức Giê-hô-va bủa khắp mọi vật của người làm chủ, hoặc trong nhà, hoặc ngoài đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Người giao hết của cải mình cho Giô-sép coi sóc, chẳng lo đến việc nào nữa, trừ ra các phần vật thực của mình ăn mà thôi. Vả, Giô-sép hình dung đẹp đẽ, mặt mày tốt tươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Sau các việc nầy, vợ chủ đưa mắt cùng Giô-sép, mà nói rằng: Hãy lại nằm cùng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Chàng từ chối và đáp rằng: Chủ đã giao nơi tay tôi mọi vật của người, và nầy, chủ chẳng lo biết đến việc chi trong nhà nữa;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'trong nhà nầy chẳng ai lớn hơn tôi, và chủ cùng không cấm chi tôi, trừ ra một mình ngươi, vì là vợ của chủ tôi. Thế nào tôi dám làm điều đại ác dường ấy, mà phạm tội cùng Ðức Chúa Trời sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Thường ngày người dỗ dành mặc dầu, thì Giô-sép chẳng khấng nghe lời dụ dỗ nằm cùng hay là ở cùng người chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Một ngày kia, Giô-sép vào nhà đặng làm công việc; vả, chẳng có người nhà nào ở đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'thì người bèn nắm áo chàng mà rằng: Hãy nằm cùng ta! Nhưng chàng liền tuột áo để lại trong tay người mà chạy trốn ra ngoài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Khi người thấy áo còn lại nơi tay mình, và chàng đã chạy trốn ra ngoài như vậy,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'bèn gọi người nhà mà nói rằng: Bay coi! Họ khéo đem vào nhà một thằng Hê-bơ-rơ để chọc ghẹo ta. Nó lại gần toan nằm cùng ta, nhưng ta la lớn lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Vừa khi nó nghe ta cất tiếng la, thì tuột áo lại bên ta, chạy trốn ra ngoài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Người bèn để áo của Giô-sép bên mình đợi khi chủ về nhà,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'học lại cùng chủ y như lời trước, rằng: Thằng nô lệ Hê-bơ-rơ mà ông khéo đem về nhà đã đến gần đặng chọc ghẹo tôi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'nhưng khi tôi cất tiếng la lên, nó tuột áo lại bên tôi, rồi chạy trốn ra ngoài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Vừa khi chủ của Giô-sép nghe lời vợ nói rằng: Ðó, kẻ nô lệ ông làm điều như vậy, thì nổi giận phừng phừng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'bèn bắt chàng đem bỏ vào tù, là nơi cầm các kẻ phạm tội của vua. Vậy, ch@ ng ở tù tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Ðức Giê-hô-va phù hộ Giô-sép và tỏ lòng nhân từ cùng chàng, làm cho được ơn trước mặt chủ ngục.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Chủ ngục giao hết các kẻ tù trong tay Giô-sép, chẳng việc chi làm qua khỏi được chàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Chủ ngục chẳng soát lại những việc đã ở nơi tay Giô-sép, vì có Ðức Giê-hô-va phù hộ chàng, xui cho việc chi chàng làm cũng được thạnh vượng');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Mấy việc nầy qua rồi, xảy có quan tửu chánh và quan thượng thiện của vua Ê-díp-tô phạm đến chúa mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Pha-ra-ôn nổi giận cùng hai quan mình, là tửu chánh và thượng thiện,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'bèn đem họ cần ngục tại dinh quan thị vệ, là nơi đương cầm Giô-sép.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Quan thị vệ cắt phần Giô-sép hầu việc hai quan đó; họ bị ngồi ngục một ít lâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Cùng trong một đêm, quan tửu chánh và quan thượng thiện của vua Ê-díp-tô đương bị cầm ngục, thấy một điềm chiêm bao, mỗi người một chiêm bao, và mỗi chiêm bao có ý nghĩa rõ ràng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Sáng mai, Giô-sép đến cùng họ, nhìn thấy sắc buồn bực,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'bèn hỏi rằng: Ngày nay sao hai quan có sắc mặt âu sầu vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Ðáp rằng: Chúng tôi có thấy một điềm chiêm bao mà không ai bàn giùm. Giô-sép rằng: Sự bàn chiêm bao há chẳng do nơi Ðức Chúa Trời ư? Xin hãy thuật lại điềm chiêm bao của hai quan cho tôi nghe đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Quan tửu chánh thuật điềm chiêm bao mình lại cho Giô-sép mà rằng: Trong chiêm bao, tôi thấy một gốc nho ở trước mặt tôi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'gốc nho đó lại có ba nhành. Dường như thấy nhành nảy chồi, trổ bông, chùm có trái chín thì phải.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Tay tôi đương cầm cái chén của Pha-ra-ôn; tôi hái nho đó, ép nước nho vào, rồi dâng tửu bôi vào tay Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Giô-sép nói: Ý-nghĩa chiêm bao đó là thể nầy: Ba nhành nho tức là ba ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Trong ba ngày nữa, Pha-ra-ôn sẽ tha quan ra khỏi ngục, phục chức lại, quan sẽ dâng cái chén của Pha-ra-ôn vào tay người như cũ, như khi còn làm chức tửu chánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Song khi quan được hưởng lạc lại rồi, xin nhớ đến tôi, làm ơn tâu cùng Pha-ra-ôn về nổi tôi, và đem tôi ra khỏi chốn nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Vì tôi bị người ta bắt đem ra khỏi xứ của người Hê-bơ-rơ, và tại đây tôi cũng chẳng có làm gì mà bị cầm nơi lao-lung nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Quan thượng thiện thấy Giô-sép bàn mộng được tốt, bèn nói: Còn trong điềm chiêm bao của tôi đây, tôi đội ba giỏ bánh trắng trên đầu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'trong giỏ cao hơn hết, có đủ món thực vật của thợ làm bánh hấp cho Pha-ra-ôn; chim đáp vào giỏ trên đầu tôi ăn các món đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Giô-sép đáp rằng: Ý-nghĩa chiêm bao nầy là, ba giỏ, tức là ba ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Trong ba ngày nữa, Pha-ra-ôn sẽ xử trảm quan, sai đem treo lên cây cho chim chóc ăn thịt quan vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Ðến ngày thứ ba, là ngày sanh-nhựt của Pha-ra-ôn, người bèn bày tiệc đãi cả quần thần, và tha quan tửu chánh cùng quan thượng thiện ra khỏi ngục.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Pha-ra-ôn phục chức quan tửu chánh lại như xưa, đặng quan nầy dân tửu bôi vào tay mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'nhưng lại hạ lịnh đem treo quan thượng thiện, y như lời Giô-sép đã bàn ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Ðoạn, quan tửu chánh chẳng còn nhớ đến Giô-sép nữa; quên người đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Cách hai năm sau, Pha-ra-ôn nằm chiêm bao thấy mình đứng bên bờ sông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Nầy đâu dưới sông đi lên bảy con bò mập và tốt, ăn cỏ trong bung.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Rồi nầy, bảy con bò khác, xấu dạng, gầy guộc, ở dưới sông đi theo lên sau, đến đứng gần các con bò trước trên bờ sông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Bảy con bò xấu dạng, gầy guộc nuốt bảy con bò mập tốt. Pha-ra-ôn bèn thức giấc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Vua nằm ngủ lại, chiêm bao lần thứ nhì, thấy bảy gié lúa chắc, tốt tươi, mọc chung trên một cộng rạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Kế đó, bảy gié lúa khác lép và bị gió đông thổi háp, mọc theo bảy gié lúa kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Bảy gié lúa lép nuốt bảy gié lúa chắc. Pha-ra-ôn bèn thức giấc; và nầy, thành ra một điềm chiêm bao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Sáng mai, tâm thần người bất định, truyền đòi các pháp-sư và các tay bác sĩ xứ Ê-díp-tô đến, thuật lại điềm chiêm bao mình cho họ nghe; nhưng chẳng có ai bàn được điềm chiêm bao đó cho vua hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Quan tửu chánh bèn tâu cùng Pha-ra-ôn rằng: Bây giờ, tôi nhớ đến lỗi của tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Ngày trước, bệ hạ nổi giận cùng quần thần, có cầm ngục quan thượng thiện và tôi nơi dinh quan thị vệ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Trong lúc đó, cùng một đêm kia, chúng tôi có thấy điềm chiêm bao, chiêm bao mỗi người đều có ý nghĩa riêng rõ ràng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Tại đó, cùng chung ngục, có một người Hê-bơ-rơ, còn trẻ, kẻ gia-đinh của quan thị vệ; chúng tôi thuật lại cho chàng nghe điềm chiêm bao của mình; chàng bàn rõ ra cho ai mỗi chiêm bao nấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Rồi ra, công việc xảy đến y như lời chàng bàn: bệ hạ phục chức tôi lại, và xử treo quan kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Pha-ra-ôn bèn sai đi đòi Giô-sép; họ lập tức tha người ra khỏi ngục, cạo mặt mày cho, biểu thay đổi áo xống, rồi vào chầu Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Pha-ra-ôn phán cùng Giô-sép rằng: Trẫm có thấy một điềm chiêm bao mà chẳng ai bàn ra. Vậy, trẫm nghe rằng khi người ta thuật điềm chiêm bao lại cho, thì ngươi bàn được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Giô-sép tâu rằng: Ðó chẳng phải tôi, nhưng ấy là Ðức Chúa Trời đem sự bình an đáp cho bệ hạ vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Pha-ra-ôn phán rằng: Nầy, trong điềm chiêm bao trẫm đương đứng bên bờ sông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Nầy đâu bảy con bò mập và tốt dưới sông đi lên, đến ăn cỏ trong bưng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Rồi bảy con bò khác xấu dạng gầy guộc đi theo lên sau; thật trẫm chẳng thấy trong xứ Ê-díp-tô nầy có bò xấu dạng như vậy bao giờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Bảy con bò xấu dạng gầy guộc đó nuốt bảy con bò mập tốt trước kia,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'nuốt vào bụng, mà dường như không có nuốt, vì các con bò đó vẫn xấu dạng như xưa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Trẫm bèn thức giấc; rồi lại thấy điềm chiêm bao khác, là bảy gié lúa chắc tốt tươi mọc chung trên một cộng rạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Kế đó, bảy gié lúa khác, khô, lép, bị gió đông thổi háp, mọc theo bảy gié lúa kia;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'và bảy gié lúa lép đó lại nuốt bảy gié lúa chắc. Trẫm đã thuật điềm chiêm bao nầy cho các pháp-sư, nhưng không ai giải nghĩa ra được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Giô-sép tâu cùng Pha-ra-ôn rằng: Hai điềm chiêm bao của bệ hạ thấy đó đồng một nghĩa mà thôi; Ðức Chúa Trời mách cho bệ hạ biết trước những việc Ngài sẽ làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Bảy con bò mập tốt đó, tức là bảy năm; bảy gié lúa chắc đó cũng là bảy năm. Ấy chỉ đồng một điềm chiêm bao vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Bảy con bò xấu dạng gầy guộc lên theo sau bảy con bò kia, tức là bảy năm; và bảy gié lúa lép bị gió đông thổi háp đó, tức là bảy năm đói kém.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Ấy là điều tôi đã tâu cùng bệ hạ rồi: Ðức Chúa Trời có cho bệ hạ thấy những việc Ngài sẽ làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Nầy, trong khắp xứ Ê-díp-tô sẽ có bảy năm được mùa dư dật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Nhưng bảy năm đó lại liền tiếp bảy năm đói kém; dân bổn xứ đều sẽ quên sự dư dật đó, và ách đói kém sẽ làm cho toàn xứ hao mòn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Và vì sự đói kém liên tiếp nầy lớn quá, nên thiên hạ chẳng còn thấy chi về sự dư dật đó nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Nếu điềm chiêm bao đến hai lần cho bệ hạ, ấy bởi Ðức Chúa Trời đã quyết định điều đó rồi, và Ngài mau mau lo làm cho thành vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Bây giờ bệ hạ khá chọn một người thông minh trí-huệ, lập người lên làm đầu trong xứ Ê-díp-tô,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'cùng lập các ủy viên trong xứ, để góp một phần năm của số thâu vào trong bảy năm được mùa dư dật đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Họ hãy thâu góp hết thảy mùa màng trong bảy năm được mùa dư dật sẽ đến sau nầy, cùng thâu thập lúa mì sẵn dành cho Pha-ra-ôn, dùng làm lương để dành trong các thành, và họ hãy giữ gìn lấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Các lương thực nầy phải để dành cho bảy năm đói kém sẽ đến trong xứ Ê-díp-tô, hầu cho xứ nầy khỏi bị diệt bởi sự đói kém đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Các lời nầy đẹp ý Pha-ra-ôn và quần thần.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Pha-ra-ôn phán cùng quần thần rằng: Chúng ta há dễ tìm một người như người nầy, có thần minh của Ðức Chúa Trời được sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Pha-ra-ôn phán cùng Giô-sép rằng: Vì Ðức Chúa Trời xui cho ngươi biết mọi việc nầy, thì chẳng còn ai được thông minh trí-huệ như ngươi nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Vậy, ngươi sẽ lên cai trị nhà trẫm; hết thảy dân sự của trẫm đều sẽ vâng lời ngươi. Trẫm lớn hơn ngươi chỉ vì ngự ngôi vua mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Pha-ra-ôn lại phán cùng Giô-sép rằng: Hãy xem! trẫm lập ngươi cầm quyền trên cả xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Vua liền cổi chiếc nhẫn trong tay mình, đeo vào tay Giô-sép, truyền mặc áo vải gai mịn, và đeo vòng vàng vào cổ người;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'rồi, truyền cho lên ngồi sau xe vua, có người đi trước hô rằng: Hãy quì xuống! Ấy, Giô-sép được lập lên cầm quyền cả xứ Ê-díp-tô là vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Pha-ra-ôn phán cùng Giô-sép: Ta là Pha-ra-ôn, nhưng nếu chẳng có ngươi, thì trong cả xứ Ê-díp-tô không có ai giơ tay đưa chơn lên được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Pha-ra-ôn đặt tên Giô-sép là Xa-phơ-nát-Pha-nê-ách, đưa nàng Ách-nát, con gái Phô-ti-phê-ra, thầy cả thành Ôn, cho người làm vợ. Người thường tuần hành trong xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Vả, khi Giô-sép ra mắt Pha-ra-ôn, vua Ê-díp-tô, thì người đã ba mươi tuổi. Vậy, người từ tạ Pha-ra-ôn mà đi tuần khắp xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Trong bảy năm được mùa dư dật, đất sanh sản ra đầy dẫy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Giô-sép bèn thâu góp hết thảy lương thực của bảy năm đó trong xứ Ê-díp-tô, và chứa lương thực nầy khắp các thành; trong mỗi thành, đều dành chứa hoa lợi của các ruộng ở chung quanh thành đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Vậy, Giô-sép thâu góp lúa mì rất nhiều, như cát nơi bờ biển, cho đến đỗi người ta đếm không được, vì đầy dẫy vô số.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Trước khi đến năm đói kém, thì Ách-nát, con gái Phô-ti-phê-ra, thầy cả thành Ôn, sanh cho Giô-sép hai con trai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Giô-sép đặt tên đứa đầu lòng là Ma-na-se, vì nói rằng: Ðức Chúa Trời đã làm cho ta quên điều cực nhọc, và cả nhà cha ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Người đặt tên đứa thứ nhì là Ép-ra-im, vì nói rằng: Ðức Chúa Trời làm cho ta được hưng vượng trong xứ mà ta bị khốn khổ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Bảy năm được mùa dư dật trong xứ Ê-díp-tô bèn qua,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'thì bảy năm đói kém khởi đến, y như lời Giô-sép đã bàn trước. Khắp các xứ khác cũng đều bị đói, nhưng trong cả xứ Ê-díp-tô lại có bánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Ðoạn, cả xứ Ê-díp-tô đều bị đói, dân chúng đến kêu cầu Pha-ra-ôn xin lương. Pha-ra-ôn phán cùng bổn dân rằng: Hãy đi đến Giô-sép, rồi làm theo lời người sẽ chỉ bảo cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Khi khắp xứ bị đói kém, thì Giô-sép mở mọi kho lúa mà bán cho dân Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Xứ càng đói nhiều nữa; vả, vì khắp thế gian đều bị đói quá, nên đâu đâu cũng đổ đến Ê-díp-tô mùa lúa nơi Giô-sép bán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Gia-cốp thấy xứ Ê-díp-tô có lúa bán ra, bèn nói cùng các con trai mình rằng: Sao bay ngơ ngẩn nhìn nhau vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Lại rằng: Nầy, cha nghe dưới xứ Ê-díp-tô có lúa bán; bay hãy xuống đó mua lúa cho chúng ta, hầu cho chúng ta sống và khỏi chết, chớ!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Mười người anh của Giô-sép bèn xuống Ê-díp-tô đặng mua lúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Nhưng Gia-cốp không cho Bên-gia-min, em Giô-sép, đi cùng các anh; vì nghĩ rằng: Ta nên giữ chừng, kẻo xảy ra điều rủi ro cho nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Xứ Ca-na-an bấy giờ cũng đói, nên các con trai của Y-sơ-ra-ên cũng đổ xuống Ê-díp-tô mua lúa như các người khác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Vả, lúc nầy, chánh Giô-sép cai trị trong nước, và bán lúa cho cả dân bổn xứ. Các anh Giô-sép bèn đến, sấp mình xuống trước mặt người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Giô-sép thấy, nhìn biết các anh mình; nhưng giả làm mặt lạ cùng họ, nói một cách xẳng rằng: Các ngươi ở đâu đến? Ðáp rằng: Ở xứ Ca-na-an đến đặng mua lúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Vậy, Giô-sép nhìn biết các anh mình; nhưng họ nhìn lại chẳng ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Giô-sép nhớ lại điềm chiêm bao mình đã thấy về anh em mình, liền thét rằng: Các ngươi là thám tử, đến đây đặng dòm hành những nơi yếu óp của xứ ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Ðáp rằng: Thưa chúa, chẳng phải vậy; các tôi tớ chúa đến đặng mua lúa mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Chúng tôi đây đều là con một cha, vốn nhà lương thiện, chẳng phải là thám tử đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Người đáp lại rằng: Chẳng phải; các ngươi đến đặng dòm hành những nơi yếu óp của xứ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Ðáp rằng: Kẻ tôi tớ chúa có mười hai anh em, con của một cha, nguyên xứ Ca-na-an; nầy một người đã đi mất biệt, còn người út hiện bây giờ hãy ở tại nhà cùng cha chúng tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Giô-sép nói: Ấy quả thật như ta nói, các ngươi là thám tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Ðây là điều ta thử các ngươi: Ta chỉ mạng Pha-ra-ôn mà thề rằng, hễ em út các ngươi không đến đây thì chẳng bao giờ các ngươi ra khỏi chốn nầy được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Hãy sai một người nào trong bọn các ngươi về dẫn em út xuống; còn bao nhiêu thì phải ở tù lại đây. Lời các ngươi phải thử đã, rồi ta sẽ biết các ngươi nói đó có quả thật chăng. Nếu chẳng thật, thì ta chỉ mạng Pha-ra-ôn thề rằng, các ngươi là thám tử đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Ðoạn, Giô-sép truyền đem giam họ chung trong ngục ba ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Ngày thứ ba, Giô-sép nói cùng họ rằng: Ta kính sợ Ðức Chúa Trời; hãy làm như điều nầy, thì được sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Nếu các ngươi vốn nhà lương thiện, thì hãy để một người nào ở tù lại đây, còn bao nhiêu đem lương thực về nuôi đói cho nhà các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Ðoạn, hãy dẫn em út xuống đây, thì lời các ngươi sẽ cho là thật, và các ngươi chẳng phải chết. Vậy, họ nghe theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Họ bèn nói với nhau rằng: Quả thật chúng ta cam tội cùng em ta ra; vì lúc trước ta thấy tâm hồn nó buồn thảm khi nó xin nhờ ơn, nhưng ta không khứng cho; vậy nên tai vạ nầy mới xảy đến cho chúng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ru-bên đáp rằng: Anh há không có nói cùng các em rằng: Chớ phạm tội nầy cùng đứa trẻ đó sao? Nhưng các em không nghe; nên bây giờ huyết nó đòi chúng ta thường lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Vả, Giô-sép vẫn dùng người thông ngôn nói chuyện lại cùng các anh, nên họ tưởng Giô-sép chẳng nghe hiểu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Giô-sép xây mặt qua chỗ khác mà khóc. Ðoạn xây mặt lại nói chuyện cùng họ; bèn bắt Si-mê-ôn trong vòng anh em, truyền trói lại trước mặt họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Giô-sép truyền đầy tớ xúc lúa đổ đầy bao và để bạc lại trong đó cho mỗi người anh em, cũng để thêm lương thực dùng dọc đường. Ðầy tớ làm y như lời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Ðoạn, anh em chất mấy bao lúa lên lưng lừa, rồi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Ðến quán, một người trong bọn mở bao ra cho lừa ăn thóc, thấy bạc mình ở tại miệng bao;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'bèn nói cùng anh em rằng: Bạc của tôi trả lại, hiện trong bao tôi đây! Các anh em nhát gan, vừa nói với nhau, vừa run, mà rằng: Ðức Chúa Trời đã làm chi cho chúng ta đây?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Các anh em trở về cùng Gia-cốp, cha mình, tại xứ Ca-na-an, thuật lại cho người nghe mọi nỗi đã xảy đến, rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'người đương làm chúa tại xứ Ê-díp-tô nói với chúng tôi cách xẳng xớm, cho chúng tôi là thám tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Song chúng tôi có thưa cùng người rằng: Chúng tôi vốn nhà lương thiện, nào có phải là thám tử đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Chúng tôi được mười hai anh em, con một cha; một người đã đi mất biệt, còn người út hiện bây giờ ở nhà cùng cha, tại xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Người làm chúa xứ đó dạy rằng: Làm như vầy, ta mới cho các ngươi là lương thiện: Hãy để lại cùng ta một người nào trong bọn các ngươi, còn bao nhiêu sẽ đem lương thực về nuôi đói cho nhà các ngươi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'đoạn, hãy dẫn em út đến cho ta. Vậy, ta mới biết rằng các ngươi chẳng phải là thám tử, nhưng là người lương thiện; ta sẽ giao em lại cho, và các ngươi sẽ được buôn bán trong xứ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Vả, đương khi các anh em trút lúa mì ra bao, nầy đâu, trong mỗi bao có gói bạc của mỗi người; cha và các anh em thấy những gói bạc mình, đều lấy làm sợ hãi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Gia-cốp, cha họ bèn nói rằng: Bay làm mất các con tao; Giô-sép đã mất biệt, Si-mê-ôn cũng mất biệt; mà bây giờ, lại muốn dẫn Bê-gia-min đi nữa sao! Các nông nỗi nầy đều đổ lại cho tao hết!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ru-bên thưa lại cùng cha rằng: Cha hãy giao em nơi tôi, tôi sẽ dẫn về cho. Ví bằng chẳng dẫn em về, thì cha hãy giết hai đứa con trai tôi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Nhưng Gia-cốp đáp rằng: Con út tao sẽ chẳng đi xuống với bay đâu; vì anh nó đã chết rồi, chỉ còn một mình nó mà thôi. Nếu điều rủi ro chi xảy đến cho nó nơi dọc đường bay đi, tức nhiên bay làm cho kẻ tóc bạc nầy đau lòng xót dạ xuống âm phủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Vả, sự đói kém trong xứ lớn lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Khi nội nhà đã ăn hết lương thực ở xứ Ê-díp-tô đem về rồi, thì cha các người ấy dạy rằng: Bay hãy trở xuống mua một ít lương thực cho chúng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Giu-đa thưa: Người đó có nói quyết cùng các con rằng: Ví em út không theo xuống với các ngươi, thì sẽ không bao giờ thấy mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Nếu cha cho em đi với, thì chúng tôi mới xuống Ê-díp-tô mua lương thực cho cha được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Bằng không, thì chúng tôi chẳng trở xuống đâu, vì người đó đã nói rằng: Ví em út không theo xuống với các ngươi, thì sẽ không bao giờ thấy mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Y-sơ-ra-ên quở rằng: Sao bay khéo tệ cùng tao, mà tỏ cho người ấy rằng bay còn một em nữa?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Thưa rằng: Người đó hỏi kỹ càng về chúng tôi, và về bà con chúng tôi rằng: Thân-phụ các ngươi còn sống chăn? cò có một người anh em nào nữa chăng? Chúng tôi có đáp các lời hỏi đó. Há dễ biết người đó sẽ dặn chúng tôi rằng: Hãy đem em út xuống đây, sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Giu-đa lại thưa cùng Y-sơ-ra-ên cha mình, rằng: Hãy cho đứa trẻ theo con, thì chúng tôi sẽ đứng dậy đi, hầu cho chúng ta, nào các con, nào cha, nào các cháu của cha đây đều được sống và khỏi chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Con sẽ bảo lãnh em cho; cha sẽ cứ nơi con mà đòi em. Nếu không dẫn em về không để em trước mặt cha, thì con đây sẽ cam tội cùng cha mãi mãi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Vả, nếu không có điều dùng dằng, thì chúng tôi đã đi và về được hai lần rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Ðoạn, Y-sơ-ra-ên, cha các anh em, nói rằng: Nếu việc đã thể kia, thì bay phải làm thể nầy: Hãy lấy trong đồ hành lý những thổ sản quí nhứt của xứ ta: một ít nhũ hương và mật ong, các hương hoa và một dược, phi tử và hạnh nhân, đem dâng cho người đó làm của lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Hãy đem theo một số tiền bằng hai, đặng thối hồi tiền mà họ đã để lại nơi miệng bao của bay: có lẽ là một sự lộn chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Bay hãy đứng dậy đi, dẫn em út theo và trở xuống đến người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Cầu xin Ðức Chúa Trời toàn năng xui cho bay được ơn trước mặt người, và tha đứa em kia và Bên-gia-min cho bay. Còn phần cha, nếu phải mất con, thì cha chịu phận vậy!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Vậy, các anh em đem theo của lễ và một số tiền bằng hai, cùng dẫn Bên-gia-min đồng đứng dậy đi xuống Ê-díp-tô, mà ra mắt Giô-sép.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Vừa khi Giô-sép thấy Bên-gia-min đi theo xuống với, bèn truyền cho quản gia rằng: Hãy đua các người nầy vào nhà trong, bắt con gì làm thịt và nấu dọn đi; vì trưa nầy họ sẽ dùng bữa cùng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Quản gia làm theo y như lời dặn, đưa họ vào nhà Giô-sép.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Anh em thấy mình phải đưa vào nhà Giô-sép, thì sợ hãi, và nói với nhau rằng: Ấy cũng vì số tiền đã để lại vào bao chúng ta lần trước, nên họ mới đem chúng ta vào chốn nầy, đặng tìm cớ xông vào đánh chúng ta, bắt chúng ta làm tôi mọi, và chiếm đoạt mấy con lừa của chúng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Mấy anh em bèn đến gần quản gia của Giô-sép, thưa cùng người tại ngoài cửa');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'mà rằng: Xin chúa tha lỗi cho! anh em chúng tôi đã đến đây một lần rồi, đặng mua lương thực;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'và khi trở về đến nhà quán, mở các bao ra, nầy số bạc của mỗi người đều ở tại miệng bao mình; cân nặng bao nhiêu đều y như bấy nhiêu. Nầy, chúng tôi có đem lại số bạc đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'và cũng có đem thêm số bạc nữa đặng mua lương thực. Chẳng biết ai để bạc lại trong bao chúng tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Quản gia đáp rằng: Mọi việc đều bình yên! đừng sợ chi cả! Ấy là Ðức Chúa Trời của các ngươi, tức Ðức Chúa Trời của cha các ngươi, đã ban vật quí vào bao. Còn bạc các ngươi thì đã có giao cho ta. Ðoạn, người dẫn Si-mê-ôn đến cùng anh em;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'rồi đưa anh em vào nhà Giô-sép, đem nước ra cho rửa chơn, và cũng cho những lừa ăn cỏ nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Các anh em bèn sửa soạn của lễ, đợi trưa Giô-sép về; vì có hay rằng mình sẽ ăn bữa tại nhà nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Khi Giô-sép trở về, các anh em bèn lấy của lễ đã đem theo, dâng cho Giô-sép tại nhà; rồi cùng sấp mình xuống đất trước mặt người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Người liền hỏi thăm họ mạnh giỏi thể nào, và nói rằng: Người cha già mà các ngươi đã nói cùng ta đó được mạnh khỏe chăng? còn sống chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Ðáp rằng: Kẻ tôi tớ cháu, là cha chúng tôi, vẫn mạnh khỏe và còn sống. Ðoạn, họ cùi đầu và lạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Giô-sép nhướng mắt thấy Bên-gia-min, em ruột, con trai của mẹ mình, thì hỏi rằng: Ðó có phải em út mà các ngươi đã nói cùng ta chăng? Và tiếp rằng: Con út ơi! cầu xin Ðức Chúa Trời làm ơn cho ngươi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Vì thấy em mình, nên Giô-sép tất lòng cảm động, lật đật bước ra ngoài, tìm nơi nào đặng khóc. Người vào phòng nhà trong và khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Ðoạn, rửa mặt, bước ra, làm bộ chắc gan mà nói rằng: Hãy dọn bữa ăn đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Người ta dọn cho Giô-sép ăn riêng, và cho các anh em ăn riêng. Người Ê-díp-tô ăn chung cùng người cũng dọn cho ngồi riêng nữa; vì người Ê-díp-tô có tánh gớm người Hê-bơ-rơ, nên không ăn chung được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Vậy, các anh em bèn ngồi lại trước mặt Giô-sép, lớn nhỏ tùy theo thứ tự mình, ngơ ngẩn mà nhìn nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Giô-sép sai đem mấy món đồ ăn trước mặt mình cho các anh em; nhưng phần Bên-gia-min lại nhiều gấp năm của các người khác. Họ uống và ăn ngon vui cùng Giô-sép.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Giô-sép bèn truyền lịnh cho quản gia rằng: Hễ các người đó chở nổi bao nhiêu, thì hãy đổ lương thực cho họ đầy bao bấy nhiêu, rồi để bạc của mỗi người lại nơi miệng bao họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Lại hãy để cái chén bằng bạc ta tại miệng bao chung với bạc mua lúa của người út nữa. Quản gia bèn làm y như lời Giô-sép dặn mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Ngày mai, trời vừa sáng, người ta cho các người đó và lừa về.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Khi đi ra khỏi thành chưa xa, Giô-sép nói cùng quản gia rằng: Ngươi hãy đứng dậy, đuổi theo mấy người đó; khi theo kịp rồi, hãy nói rằng: Sao các ngươi lấy oán trả ơn như vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Có phải cái chén nầy là của chúa ta thường dùng uống rượu và bói chăng? Các ngươi đã làm một việc chẳng thiện đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Quản gia theo kịp, lặp lại mấy lời ấy;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'các anh em bèn đáp rằng: Sao chúa nói như vậy? Chẳng bao giờ kẻ tôi tớ chúa có tưởng làm đến việc thế nầy!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Ðây, từ xứ Ca-na-an chúng tôi có đem bạc đã được nơi miệng bao xuống giao lại cho người thay; dễ nào lại có ý mong ăn cắp bạc hay vàng của dinh chủ người sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Xin cho kẻ tôi tớ nào mà người tìm được cái chén đó phải chết đi, và chính chúng tôi sẽ làm tôi mọi cho chúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Quản gia đáp: Ừ thôi! hãy làm như lời các ngươi đã nói: ta tìm được chén nơi ai thì người đó sẽ làm tôi mọi cho ta đó; còn các người thì vô tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Tức thì, mỗi người lật đật hạ bao mình xuống đất và mở ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Quản gia lục soát, bắt từ bao anh cả lần đến bao em út. Cái chén bèn tìm đặng trong bao Bê-gia-min.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Mỗi người xé áo mình ra, chất bao lúa lên lưng lừa, rồi cùng trở lại thành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Giu-đa cùng anh em đồng vào đến nhà Giô-sép, người hãy còn ở nơi đó; họ bèn sấp mình xuống đất trước mặt người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Giô-sép hỏi: Các ngươi gây nên nông nỗi chi vậy? Há chẳng biết một kẻ như ta đây có tài bói sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Giu-đa đáp: Chúng tôi sẽ nói cùng chúa làm sao? sẽ phân lại làm sao? sẽ chữa mình chúng tôi làm sao? Ðức Chúa Trời đã thấu rõ điều gian ác của tôi tớ chúa rồi. Nầy, chúng tôi cùng kẻ đã bị bắt được chén nơi tay đều làm kẻ tôi tớ cho chúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Nhưng Giô-sép đáp rằng: Ta chẳng hề có ý làm như vậy đâu! Người mà đã bị bắt được chén nơi tay sẽ làm tôi mọi ta; còn các ngươi hãy trở về nhà cha mình bình yên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Giu-đa bèn lại gần Giô-sép mà thưa rằng: Vì chúa ngang vai Pha-ra-ôn, xin lỗi chúa, chớ nổi giận cùng kẻ tôi tớ, để tôi nói một lời cho chúa nghe.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Chúa có hỏi kẻ tôi tớ rằng: Các ngươi còn cha hay là anh em nào chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Có thưa lại cùng chúa rằng: Chúng tôi còn một cha già, cùng một con trai đã sanh muộn cho người. Anh ruột đứa nầy đã chết rồi, nên trong vòng các con của mẹ nó, nó còn một mình, và cha thương nó lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Vả, chúa có dặn rằng: Hãy dẫn nó xuống đến ta, hầu cho ta thấy nó được tận mắt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Và chúng tôi có thưa lại cùng chúa rằng: Ðứa trẻ chẳng lìa cha được; nếu lìa ra thì cha sẽ chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Nhưng chúa lại dạy: Nếu em út không theo các ngươi xuống đây, thì các ngươi chẳng còn thấy mặt ta nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Nên khi chúng tôi trở về nhà kẻ tôi tớ chúa, là cha tôi, thì chúng tôi có thuật lại cho người nghe những lời của chúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Kế ấy, cha lại biểu chúng tôi rằng: Hãy trở xuống đặng mua một ít lương thực.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Chúng tôi thưa lại rằng: Không được; nhưng nếu em út đi theo cùng, thì mới trở xuống được; bằng không, thì chúng tôi không thế ra mắt người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Kẻ tôi tớ chúa, là cha tôi, đáp rằng: Bây biết rằng vợ ta sanh cho ta hai đứa con trai;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'một đứa đã từ ta đi mất-biệt; ta cũng đã nói: Chắc đã bị thú dữ xé rồi, vì đến bây giờ chưa thấy lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Nếu bây còn dắt đứa nầy đi khỏi mặt ta nữa, rủi có điều tai hại chi xảy đến cho nó, tức nhiên bây sẽ làm cho kẻ tóc bạc nầy đau lòng xót dạ mà xuống âm phủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Cha thương em út tôi lắm đến đỗi hai linh hồn khắng khít nhau; nếu bây giờ, khi tôi trở về nơi kẻ tôi tớ chúa, là cha tôi, mà không có em út đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'thì khi vừa thấy con út không còn nữa, chắc người sẽ chết. Nếu vậy, các tôi tớ chúa sẽ làm cha già tóc bạc của chúng tôi, cũng là kẻ tôi tớ chúa, đau lòng xót dạ xuống âm phủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Vì kẻ tôi tớ nầy có chịu bảo lãnh đứa con út đó mà thưa rằng: Nếu con không đem em về cho cha, thì sẽ cam tội cùng cha mãi mãi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Vậy bây giờ, xin cho kẻ tôi tớ chúa ở tôi mọi thế cho đứa trẻ, đặng nó theo trở lên cùng các anh mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Vì, nếu đứa trẻ không theo về, làm sao tôi dám về cùng cha tôi? Ôi, tôi nỡ nào thấy điều tai họa của cha tôi ư!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Bây giờ, Giô-sép không còn thể nào cầm lòng cho đậu được trước mặt các người hầu chung quanh, bèn la lên rằng: Hãy đuổi họ ra hết thảy! Khi Giô-sép tỏ thật cùng các anh em mình, thì không có một người nào khác ở tại đó hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Người cất tiếng lên khóc; dân Ê-díp-tô nghe và nhà Pha-ra-ôn nghe nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Giô-sép nói cùng anh em rằng: Tôi là Giô-sép. Cha tôi còn sống chăng? Nhưng trước mặt người các anh em bối rối, chẳng đáp lời được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Người lại nói rằng: Các anh em hãy lại gần tôi. Họ bèn lại gần. Người nói: Tôi là Giô-sép, em mà các anh đã bán đặng bị dẫn qua xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Bây giờ, đừng sầu não, và cũng đừng tiếc chi về điều các anh đã bán tôi đặng bị dẫn đến xứ nầy; vì để giữ gìn sự sống các anh, nên Ðức Chúa Trời đã sai tôi đến đây trước các anh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Kìa, hai năm rồi trong xứ đã bị đói kém, và còn năm năm nữa sẽ không còn cày cấy chi, gặt hái chi được hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Ðức Chúa Trời sai tôi đến đây trước, đặng làm cho các anh còn nối dòng trên mặt đất, và nương một sự giải cứu lớn đặng giữ gìn sự sống cho anh em.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Không, chẳng phải các anh sai tôi đến đây đâu, ấy là Ðức Chúa Trời; Ngài dường đặt tôi làm cha Pha-ra-ôn, cai quản cả nhà người, vì trị khắp xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Các anh hãy mau mau trở về cha tôi đi, và nói với người rằng: Giô-sép, con của cha, có nói như vầy: Ðức Chúa Trời đã đặt tôi làm chúa cả xứ Ê-díp-tô, cha hãy xuống với tôi; xin đừng chậm trễ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'cha, các con, các cháu, các chiên, bò cùng tài vật của cha sẽ ở tại xứ Gô-sen gần tôi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ở đó tôi sẽ nuôi cha, (vì còn năm năm đói kém nữa), e khi cha, người nhà cha, và hết thảy loài vật của cha phải bị ách mà hao mòn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Này, các anh và Bên-gia-min, em tôi, đã thấy tận mắt rằng, chánh miệng tôi đã nói chuyện cùng các anh em đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Vậy, hãy thuật lại các điều vinh hiển của tôi tại xứ Ê-díp-tô, cùng mọi việc mà anh em đã thấy cho cha nghe, và hãy mau mau dời cha xuống đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Ðoạn, người ôm lấy cổ Bên-gia-min, em mình, mà khóc; Bên-gia-min cũng ôm cổ người mà khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Người cũng ôm các anh mình mà khóc. Ðoạn, anh em nói chuyện cùng người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Lập tức, tiếng đồn đến nhà Pha-ra-ôn rằng: Anh em Giô-sép đã đến. Pha-ra-ôn và quần thần nghe lấy làm đẹp dạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Pha-ra-ôn bèn phán cùng Giô-sép rằng: Hãy dặn các anh em ngươi rằng: Hãy chỡ đồ lên lừa, đi trở về xứ Ca-na-an,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'rước cha và người nhà của các ngươi xuống ở cùng ta. Ta sẽ nhượng cho vật tốt nhất trong xứ Ê-díp-tô, và các ngươi sẽ hưỡng mầu mỡ của đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Còn ta dặn ngươi hãy nói lại cùng họ như vậy: Hãy đem xe cộ từ xứ Ê-díp-tô về cho con nhỏ và vợ mình, cùng dời cha các ngươi xuống đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Ðừng tiếc tài vật mình, vì vật tốt nhất của xứ Ê-díp-tô sẽ về phần các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Các con trai của Y-sơ-ra-ên làm y như lời; Giô-sép vâng mạng Pha-ra-ôn, đưa những xe cộ cho anh em mình, và luôn vật thực dùng trong lúc đi đường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Người cũng đưa áo xống mặc đổi thay cho mỗi người, còn Bên-gia-min, người cho trăm miếng bạc cùng năm bộ áo xống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Người cũng sai đem về cho cha mình mười con lừa chỡ các vật quí nhất trong xứ Ê-díp-tô, mười con lừa cái chỡ lúa, bánh, và lương thực để dành dùng trong khi cha đi đường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Vậy, Giô-sép đưa anh em mình lên đường. Lại dặn họ rằng: Xin anh em đừng cải lẫy nhau dọc đường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Các anh em ở Ê-díp-tô trở lên và đến xứ Ca-na-an, nơi Gia-cốp, cha mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'thuật lại lời nầy mà rằng: Giô-sép hãy còn sống; lại ấy là người đang cai trị cả xứ Ê-díp-tô. Nhưng lòng Gia-cốp vẫn vô tình vì người không tin lời họ nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Anh em thuật lại cho người nghe mọi lời Giô-sép đã nói; Gia-cốp vừa thấy các xe cộ của Giô-sép sai đem về đặng rước mình, thì tâm thần người tỉnh lại,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'bèn nói rằng: Thôi, biết rồi; Giô-sép, con trai ta, hãy còn sống; ta sẽ đi thăm nó trước khi ta qua đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Y-sơ-ra-ên ra đi, đem theo các tài vật mình. Ðến Bê -e-Sê-ba, người bày của lễ dâng cho Ðức Chúa Trời của Y-sác, cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Trong một sự hiện thấy ban đêm kia, Ðức Chúa Trời có phán cùng Y-sơ-ra-ên rằng: Hỡi Gia-cốp, Gia-cốp! Y-sơ-ra-ên đáp rằng: Có tôi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Ðức Chúa Trời phán: Ta là Ðức Chúa Trời, Ðức Chúa Trời của cha ngươi. Hãy xuống Ê-díp-tô, đừng sợ chi, vì tại đó ta sẽ làm cho ngươi thành một nước lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Chánh ta sẽ xuống đến đó với ngươi, và chánh ta cũng sẽ dẫn ngươi về chẳng sai. Giô-sép sẽ vuốt mắt ngươi nhắm lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Từ Bê -e-Sê-ba, Gia-cốp khởi đi; các con trai Y-sơ-ra-ên để Gia-cốp, cha mình, cùng các vợ và con mình lên xe cộ của Pha-ra-ôn đã sai đến rước những người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Chúng cũng đem theo các súc vật và của cải mình đã gây dựng tại xứ Ca-na-an, mà đi đến cứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Vậy, Gia-cốp cùng cả nhà người, nào các con trai, nào các cháu trai, nào các con gái, nào các cháu gái, thảy đều xuống xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Ðây là tên các con trai của Y-sơ-ra-ên, tức là Gia-cốp, đến xứ Ê-díp-tô: Con trưởng nam của Gia-cốp là Ru-bên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Các con trai của Ru-bên là Hê-nóc, Pha-lu, Hết-rôn, và Cạt-mi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Các con trai của Si-mê-ôn là Giê-mu-ên, Gia-min, Ô-hát, Gia-kin, Xô-ha, và Sau-lơ, tức con của người vợ xứ Ca-na-an.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Các con trai của Lê-vi là Ghẹt-sôn, Kê-hát, và Mê-ra-ri.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Các con trai của Giu-đa là Ê-rơ, O-nan, Sê-la, Phê-rết và Sê-rách. Nhưng Ê-rơ và O-nan đã thác tại xứ Ca-na-an; con của Phê-rết là Hết-rôn, và Ha-mun.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Các con trai của Y-sa-ca là Thô-la, Phu-va, Gióp và Sim-rôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Các con trai của Sa-bu-lôn là Sê-rết, Ê-lôn, và Gia-lê-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Vả, các con trai, và một con gái tên là Ði-na, mà Lê-a sanh cho Gia-cốp khi ở tại Pha-đan-a-ram, cùng các cháu đó, hết thảy là ba mươi ba người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Các con trai của Gát là Xi-phi-ôn, Ha-ghi, Su-ni, Ét-bôn, Ê-ri, A-rô-đi và A-rê-li.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Các con trai của A-se là Dim-na, Dích-và, Dích-vi, và Bê-ri-a, cùng Sê-rách, em gái các người đó. Con của Bê-ri-a là Hê-be, và Manh-ki-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Vả, các con của nàng Xinh-ba sanh cho Gia-cốp, cùng các cháu đó, hết thảy là mười sáu người. Nàng là con đòi của của La-ban đã cho theo hầu Lê-a, con gái mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Các con trai của Ra-chên, vợ Gia-cốp, Giô-sép, và Bên-gia-min.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Giô-sép đã có con tại xứ Ê-díp-tô, là Ma-na-se, và Ép-ra-im, mà Ách-nát, con gái của Phô-ti-phê-ra, thầy cả thành Ôn, đã sanh cho người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Các con trai của Bên-gia-min là Bê-la, Bê-kê, Ách-bên, Giê-ra, Na-a-man, Ê-hi, Rô-sơ, Mốp-bim, Hốp-bim, và A-rết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Vả, các con trai của Ra-chên sanh cho Gia-cốp, cùng các cháu đó, hết thảy là mười bốn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Con trai của Ðan là Hu-sim.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Các con trai của Nép-ta-li là Giát-sê-ên, Gu-ni, Dít-se, và Si-lem.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Vả, các con trai của nàng Bi-la sanh cho Gia-cốp, cùng các cháu đó, hết thảy là bảy người. Nàng là con đòi của La-ban đã cho theo hầu Ra-chên, con gái mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Các người đi đến xứ Ê-díp-tô với Gia-cốp, tức là các người do nơi Gia-cốp sanh, nếu không kể các nàng dâu, thì hết thảy là sáu mươi sáu người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Con của Giô-sép đã sanh tại Ê-díp-tô được hai. Vậy, các người thuộc về nhà Gia-cốp đi đến Ê-díp-tô, cọng hết thảy là bảy mươi người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Gia-cốp sai Giu-đa đi đến trước đặng xin Giô-sép đưa mình vào bờ cõi Gô-sen. Vậy, họ đều vào xứ Gô-sen.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Giô-sép thắng xe đi lên Gô-sen, đón Y-sơ-ra-ên, cha mình. Người ra mắt cha, ôm choàng lấy người và khóc một hồi lâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Y-sơ-ra-ên nói cùng Giô-sép rằng: Chớ chi cho cha chết bây giờ đi! vì cha đã thấy được mặt con, và biết con vẫn còn sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Ðoạn Giô-sép nói cùng anh em và người nhà cha mình rằng: Tôi sẽ lên trước tâu cho Pha-ra-ôn hay rằng: Anh em và cả nhà cha tôi, ở xứ Ca-na-an đã đến cùng tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Họ vốn làm nghề chăn chiên, nuôi bầy súc vật; có dẫn theo hết bầy chiên, bò và các tài vật của mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Và khi Pha-ra-ôn truyền gọi anh em mà hỏi rằng: Các ngươi làm nghề chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Thì hãy tâu rằng: Kẻ tôi tớ chúa cùng tổ phụ chúng tôi vẫn làm nghề nuôi súc vật từ thuở còn nhỏ cho đến giờ. Ấy hầu cho anh em đặng ở lại xứ Gô-sen, vì dân Ê-díp-tô có tánh gớm ghê hết thảy kẻ chăn chiên lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Giô-sép đến tâu mọi điều đó cho Pha-ra-ôn hay, và nói rằng: Cha và anh em tôi đã ở xứ Ca-na-an đến, có đem theo chiên, bò, cùng các tài vật của mình. Hiện bây giờ đương ở trong xứ Gô-sen.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Người bèn đưa năm người trong bọn anh em mình vào yết kiến Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Pha-ra-ôn hỏi: Các ngươi làm nghề chi? Tâu rằng: Kẻ tôi tớ bệ hạ là kẻ chăn chiên, như tổ phụ chúng tôi khi trước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Rồi lại tâu rằng: Ấy đặng kiều ngụ trong xứ mà kẻ tôi tớ bệ hạ đã đến; vì xứ Ca-na-an đói kém lớn lắm, không còn đồng cỏ chi hết cho bầy súc vật ăn. Vậy, xin phép cho kẻ tôi tớ bệ hạ ngụ tại xứ Gô-sen.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Pha-ra-ôn phán cùng Giô-sép như vầy: Cha và anh em ngươi đã đến cùng ngươi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'vậy, xứ Ê-díp-tô sẵn dành cho ngươi; hãy cho cha và anh em ở chốn nào tốt hơn hết trong xứ; hãy cho ở tại xứ Gô-sen vậy. Và nếu trong các người đó, ngươi biết ai giỏi, hãy đặt họ chăn các bầy súc vật của ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Ðoạn, Giô-sép dẫn Gia-cốp, cha mình, đến yết-kiến Pha-ra-ôn. Gia-cốp chúc phước cho Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Pha-ra-ôn hỏi Gia-cốp rằng: Ngươi hưởng thọ được bao nhiêu tuổi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Gia-cốp tâu rằng: Người năm tôi sống ở đời phiêu lưu hết thảy là một trăm ba mươi năm; các năm của đời tôi lấy làm ngắn-ngủi và lại nhọc nhằn, chẳng bằng những năm bình sanh của tổ phụ tôi khi người ở phiêu lưu đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Gia-cốp chúc phước cho Pha-ra-ôn một lần nữa, rồi lui ra khỏi mặt người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Vậy, Giô-sép vâng mạng Pha-ra-ôn, định chỗ ở cho cha và anh em mình, cho họ một sở đất tốt nhứt trong xứ Ê-díp-tô làm sản nghiệp, tại miền Ram-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Giô-sép, tùy theo số người, cấp lương thực cho cha, anh em và cả nhà cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Vả, sự đói kém lớn lắm, nên trong khắp xứ chẳng còn lương thực nữa; xứ Ê-díp-tô và xứ Ca-na-an đều bị hao mòn vì ách đói kém đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Giô-sép thâu hết bạc tiền trong xứ Ê-díp-tô và xứ Ca-na-an, tức giá tiền của muôn dân mua lúa; rồi chứa bạc đó vào kho Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Khi bạc tiền trong xứ Ê-díp-tô và xứ Ca-na-an đã hết, thì tất cả dân Ê-díp-tô đều đến cùng Giô-sép mà kêu rằng: Xin cho chúng tôi lương thực; lẽ nào vì cớ hết tiền mà chúng tôi phải chết trước mặt chúa sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Giô-sép đáp rằng: Nếu hết bạc tiền rồi, hãy giao súc vật các ngươi cho ta, ta sẽ phát lương thực đổi lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Ðoạn, dân chúng bèn dẫn súc vật lại cho Giô-sép; Giô-sép phát lương thực đổi lấy ngựa, bầy chiên, bầy bò, và lừa. Năm đó, người thâu các bầy súc vật của họ mà đổi thế lương thực cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Mãn năm rồi, năm sau dân chúng lại đến kêu cùng người rằng: tiền bạc sạch trơn, bầy súc vật đã giao cho chúa; bây giờ chỉ sẵn dành cho chúa bổn thân và đất ruộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Lẽ nào chúng tôi và đất ruộng phải hao mòn trước mặt chúa sao? Hãy mua đổi lấy lương thực chúng tôi và đất ruộng luôn đi. Vậy, chúng tôi cùng đất ruộng sẽ làm tôi mọi cho Pha-ra-ôn. Hãy cho giống chi đặng gieo, hầu cho chúng tôi sống khỏi chết, và đất không phải bỏ hoang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Giô-sép bèn mua hết thảy ruộng đất trong xứ Ê-díp-tô cho Pha-ra-ôn; vì sự đói kém thúc giục nên mọi người Ê-díp-tô đều đem bán ruộng mình; vậy, ruộng đất đều thuộc về Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Còn dân chúng, từ đầu nầy đến đầu kia, người đều dời về ở trong các thành.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Song ruộng đất của những thầy cả thì Giô-sép không mua đến, vì những thầy cả có lãnh một phần lương của Pha-ra-ôn đã định; vậy, họ ăn phần lương thực của Pha-ra-ôn đã cấp cho. Thế cho nên những thầy cả chẳng đem bán đất của mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Giô-sép nói cùng dân chúng rằng: Nầy, ta đã mua các ngươi và ruộng đất cho Pha-ra-ôn; đây, hột giống cho các ngươi đặng gieo mạ trong ruộng đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Ðến mùa gặt, phải nộp cho Pha-ra-ôn một phần năm, còn bốn phần kia để cho các ngươi làm giống gieo mạ, dùng lương thực cho mình, cho người nhà cùng cho các con nhỏ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Dân chúng nói rằng: Chúa đã cứu mạng chúng tôi! Cầu xin cho chúng tôi được nhờ ơn trước mặt chúa, thì sẽ làm tôi mọi cho Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Về việc đó, Giô-sép bèn định một luật, cho đến ngày nay hãy còn, buộc đất Ê-díp-tô phải nộp thuế cho Pha-ra-ôn một phần năm hoa lợi mình. Chỉ đất ruộng của những thầy cả chẳng thuộc về Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Vậy, Y-sơ-ra-ên trú ngụ tại miền Gô-sen thuộc về xứ Ê-díp-tô, gây được cơ nghiệp tại đó, sanh sản và thêm lên bội phần.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Gia-cốp kiều ngụ trong xứ Ê-díp-tô được mười bảy năm, hưởng thọ được một trăm bốn mươi bảy tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Khi ngày gần chết, Y-sơ-ra-ên gọi Giô-sép, con trai mình, mà nói rằng: Nếu cha được nhờ ơn trước mặt con, xin hãy để tay trên đùi cha cậy hết lòng nhơn từ và thành thực ở cùng cha, xin con đừng chôn cha tại đất Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Khi cha an-giấc cùng tổ phụ rồi, hãy đem cha ra khỏi Ê-díp-tô; chôn chung cùng mồ mả của người. Giô-sép thưa rằng: Con sẽ làm y theo lời cha dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Giô-sép nói: Con hãy thề đi. Giô-sép bèn thề. Ðoạn, Y-sơ-ra-ên quì lạy nơi đầu giường mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Vả, khi các việc đó qua rồi, có người nói cùng Giô-sép rằng: Nầy cha người đau; Giô-sép bèn đem Ma-na-se và Ép-ra-im, hai đứa con trai mình, cùng đi đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Họ cho Gia-cốp hay và nói rằng: Nầy Giô-sép, con trai ông, đến thăm ông đó; Y-sơ-ra-ên cố gượng ngồi dậy trên giường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Gia-cốp nói cùng Giô-sép rằng: Ðức Chúa Trời toàn năng đã hiện ra, bà ban phước cho cha tại Lu-xơ, trong xứ Ca-na-an,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'mà phán rằng: Nầy ta sẽ làm cho ngươi sanh sản và thêm nhiều, làm thành một hội dân; ta sẽ cho dòng dõi ngươi xứ nầy làm cơ nghiệp đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Bây giờ, hai đứa con trai đã sanh cho con tại xứ Ê-díp-tô trước khi cha đến, là Ép-ra-im và Ma-na-se, cũng sẽ thuộc về cha như Ru-bên và Si-mê-ôn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Còn mấy đứa mà con sanh kế đó, thì sẽ thuộc về con; về phần hưởng cơ nghiệp, chúng nó sẽ đồng một thể cùng anh em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Khi cha ở Pha-đan trở về xứ Ca-na-an, thì Ra-chên chết dọc đường có mặt cha, gần Ê-phơ-rát; cha chôn người ở bên con đường đi về Ê-phơ-rát (tức là Bết-lê-hem).');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Y-sơ-ra-ên thấy các con trai Giô-sép, bèn hỏi rằng: Những đứa nầy là ai?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Giô-sép thưa rằng: Ấy là những con trai của con mà Ðức Chúa Trời đã cho tại xứ nầy. Y-sơ-ra-ên lại nói: Xin hãy đem đến đây, đặng cha chúc phước cho chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Vả, mắt của Y-sơ-ra-ên già nên làng, chẳng thấy chi nữa, bèn biểu chúng nó lại gần, ôm choàng và hôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Y-sơ-ra-ên nói cùng Giô-sép rằng: Trước cha tưởng chẳng còn thấy được mặt con, nhưng bây giờ Ðức Chúa Trời lại làm cho cha thấy được đến dòng dõi con nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Giô-sép dẫn hai đứa con trai ra khỏi hai đầu gối cha mình, rồi sấp mình xuống đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Ðoạn, người dẫn hai đứa trẻ lại gần cha; tay hữu thì dẫn Ép-ra-im sang qua phía tả của cha, còn tay tả dắt Ma-na-se sang qua phía hữu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Y-sơ-ra-ên đưa tay mặt ra, để trên đầu Ép-ra-im, là đứa nhỏ, còn tay trái lại để trên đầu Ma-na-se. Người có ý riêng để tay như vậy, vì Ma-na-se là đứa lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Rồi người chúc phước cho Giô-sép rằng: Cầu xin Ðức Chúa Trời mà tổ phụ tôi là Áp-ra-ham và Y-sác đã thờ phượng; là Ðức Chúa Trời đã chăn nuôi tôi từ khi mới lọt lòng cho đến ngày nay,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'thiên sứ đã cứu tôi ra ngoài vòng hoạn nạn, hãy ban phước cho hai đứa trẻ nầy; nối danh tôi và tổ phụ tôi là Áp-ra-ham và Y-sác, và cho chúng nó thêm lên nhiều vô số trên mặt đất!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Nhưng Giô-sép thấy cha mình để tay hữu trên đầu Ép-ra-im, thì có ý bất bình, liền nắm lấy tay cha đã để lên đầu Ép-ra-im mà tráo đổi qua đấu Ma-na-se,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'rồi thưa rằng: Chẳng phải vậy, cha. Ðứa nầy đầu lòng, để tay hữu cha trên đầu nó mới phải chớ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Nhưng cha người không chịu và cãi rằng: Cha biết, con, cha biết. Nó sẽ trở nên một dân; nó cũng sẽ lớn vậy, con; song thể nào em nó cũng sẽ lớn hơn và dòng dõi nó sẽ thành ra vô số nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Trong ngày đó, người chúc phước cho hai đứa con trai nầy mà nói rằng: Ấy vì ngươi mà dân Y-sơ-ra-ên sẽ chúc phước nhau rằng: Cầu xin Ðức Chúa Trời làm cho ngươi được giống như Ép-ra-im và Ma-na-se. Vậy, Gia-cốp đặt Ép-ra-im trước Ma-na-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Y-sơ-ra-ên lại nói cùng Giô-sép rằng: Nầy, cha sẽ thác, nhưng Ðức Chúa Trời sẽ phù hộ và đem các con trở về xứ tổ phụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Còn cha sẽ cho con một phần đất trổi hơn các anh em, là phần đất của cha đã dùng cung-kiếm đoạt lấy của dân A-mô-rít đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Gia-cốp gọi các con trai mình lại và nói rằng: Hãy hội lại đây, cha sẽ nói những điều phải xảy đến cho các con ngày sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Hỡi các con trai Gia-cốp, hãy hội lại mà nghe; Nghe lời Y-sơ-ra-ên, cha của các con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Hỡi Ru-bên! con là trưởng nam của cha, Sức lực cha, và đầu tiên sự mạnh mẽ cha; Vốn có sự tôn trọng và quyền năng tót chúng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Con sôi trào như nước, nên sẽ chẳng phần hơn ai! Vì con đã lên giường cha. Con lên giường cha bèn làm ô làm dơ đó!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Si-mê-ôn và Lê-vi là anh em ruột. Thanh gươm chúng nó thật khí giới hung tàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Cầu cho tâm hồn cha chớ có đồng mưu, Vinh hiển cha chớ hiệp cùng hội họ; Vì họ đã giết người trong cơn giận dữ, Cắt nhượng bò đực vì ý riêng mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Ðáng rủa sả thay cơn giận dữ họ, vì thật là hung mạnh! Ðáng rủa sả thay khí giận họ, vì dữ dằn thay! Ta sẽ phân chia họ ra trong nhà Gia-cốp, Tan lạc họ trong dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Hỡi Giu-đa! các anh em sẽ khen ngợi con, Tay con chận cổ quân nghịch, Các con trai cha sẽ quì lạy trước mặt con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Giu-đa là một sư tử tơ; Hỡi con! Con bắt được mồi rồi tha về. Nó sụm gối, nằm khác nào sư tử đực, Như sư tử cái; há ai dám khiến ngồi lên?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Cây phủ việt chẳng hề dời khỏi Giu-đa, Kẻ lập pháp không dứt khỏi giữa chơn nó, Cho đến chừng Ðấng Si-lô hiện tới, Và các dân vâng phục Ðấng đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Người buộc lừa tơ mình vào gốc nho, Lừa con mình vào nhành nho tốt nhứt. Người giặt áo xống mình vào rượu nho, Cùng lấy huyết nho lau áo tơi mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Mắt người đỏ vì cớ rượu, Răng nhiều trắng vì cớ sữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sa-bu-lôn sẽ ở nơi gành biển, Tức là nơi có tàu đậu; Bờ cõi người chạy về hướng Si-đôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Y-sa-ca là một con lừa mạnh mẽ, Nằm nghỉ giữa chuồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Thấy rằng sự yên ổn là tốt lành, Và đất-đai đẹp lắm thay. Người đã rùn vai vác gánh nặng, Phải vâng phục những điều sưu-dịch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Ðan sẽ xử đoán dân chúng mình, Như một trong các chi phái Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Ðan sẽ là một con rắn trên đường, Một con rắn lục trong chốn nẻo cùng, Cắn vó ngựa, Làm cho kẻ cỡi phải té nhào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Hỡi Giê-hô-va! tôi trông ơn chửng-cứu của Ngài!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Còn Gát sẽ bị một đạo binh xông đánh, Nhưng người xông đánh lại và đuổi theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Do nơi A-se có thực vật ngon, Người sẽ cung cấp mỹ vị cho các vua.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nép-ta-li là nai cái thả chuồng Nói bày nhiều lời văn hoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Giô-sép là chồi của cây tươi tốt, Mọc gần bên suối nước; Nhành nhánh phủ bao trên ngọn tường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Kẻ cầm cung đã ghẹo-chọc người, Bắn tên vào, và hãm đánh;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Nhờ tay Ðấng toàn năng của Gia-cốp, Nên cung người vẫn bền-chắc; Nhờ Ðấng Chăn chiên, là Ðá của Y-sơ-ra-ên, Nên hai tay người thêm mạnh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Ðức Chúa Trời của Cha sẽ giúp đỡ con; Ðấng toàn năng sẽ ban phước cho con, Tức là phước lành ở chốn trời cao xuống, Cùng phước lành ở nơi vực rộng thẳm lên, Phước lành của vú, và của lòng mẹ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Phước lành cha chúc cho con vượt lần lên Cao hơn các phước lành của tổ phụ cha, Cho đến các chót núi đời đời: Các phước nầy sẽ ở nơi đầu Giô-sép, Nơi trán của chúa các anh em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Bên-gia-min là một con chó sói hay cấu-xé; Ban mai đi đánh chết mồi, Chiều phân chia mồi đã được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Các người đó là đầu trưởng của mười hai chi phái Y-sơ-ra-ên; và đó là lời của cha họ nói đương khi chúc phước cho, chúc một lời phước riêng cho mỗi người vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Ðoạn, người ra lịnh cho các con trai mà rằng: Cha sẽ về nơi tổ tông, các con hãy chôn cha chung cùng tổ phụ, nơi hang đá tại đồng ruộng Ép-rôn, người Hê-tít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'tức là hang đá ở trong đồng Mặc-bê-la, ngang Mam-rê, thuộc về xứ Ca-na-an, mà Áp-ra-ham đã mua làm mộ địa luôn với đồng ruộng của Ép-rôn');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Ấy nơi đó, người ta đã chôn Áp-ra-ham và Sa-ra, vợ người; Y-sác và Rê-be-ca, vợ người; mà lại nơi đó cha cũng đã chôn Lê-a nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Cái đồng ruộng cùng hang đá ở tại đó đã mua của dân họ Hếch vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Khi trối mấy lời nầy cho các con mình xong, thì Gia-cốp để chơn vào giường lại, rồi tắt hơi, được về cùng tổ tông mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Giô-sép bèn cúi đầu xuống mặt cha mình, hôn người và khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Ðoạn, Giô-sép biểu mấy thầy thuốc hầu việc mình, dùng thuốc thơm xông cho xác cha; thầy thuốc bèn xông cho Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Bốn mươi ngày xông thuốc hầu qua, vì ấy là hạn ngày dùng xông thuốc; dân Ê-díp-tô khóc người trong bảy mươi ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Khi mãn tang rồi, Giô-sép bèn nói cùng quần thần Pha-ra-ôn rằng: Nếu tôi được ơn trước mặt các ngươi, xin hãy thuật lại lời nầy cho Pha-ra-ôn nghe:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Cha tôi có biểu tôi thề mà rằng: Nầy, cha sẽ chết, con hãy chôn cha nơi mộ địa ta đã mua sẵn rồi trong xứ Ca-na-an. Vậy bây giờ, tôi phải lên đó chôn cha tôi, rồi sẽ trở xuống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Pha-ra-ôn bèn phán rằng: Hãy trở lên chôn cha ngươi, y như lời người đã bắt thề đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Giô-sép dời xác cha mình trở lên chôn; quần thần Pha-ra-ôn, các bực trưởng lão trong đền, các bực trưởng lão trong xứ Ê-díp-tô,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'hết thảy nội nhà Giô-sép, các anh em và nội nhà cha mình đều đi lên theo đưa với người; trong Gô-sen chỉ còn những đứa trẻ và chiên, cùng bò của họ mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Lại cũng có đem ngựa và xe theo lên nữa: thật là một đám xác rất đông thay!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Khi đến sân đạp lúa của A-tát, ở bên kia sông Giô-đanh, thì họ làm lễ khóc than rất nên trọng thể tại đó; đoạn, Giô-sép để tang cha trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Dân Ca-na-an, tức là dân xứ ấy, thấy khóc than nơi sân đạp lúa A-tát, thì nói rằng: Ấy là một đám khóc than trọng thể của dân Ê-díp-tô đó! Bởi cớ ấy người ta gọi cái sân nầy tên là A-bên-Mích-ra-im ở bên kia sông Giô-đanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Vậy, các con trai Gia-cốp làm theo lời cha trối lại,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'dời xác người về xứ Ca-na-an, chôn trong hanh đá của đồng Mặc-bê-la ngang Mam-rê, mà Áp-ra-ham đã mua luôn với đồng ruộng Ép-rôn, người Hê-tít, để dùng làm mộ địa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Chôn cha xong rồi, Giô-sép cùng các anh em và các người đi lên theo đưa xác cha, đều trở xuống xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Các anh Giô-sép thấy cha mình chết rồi, thì nói với nhau rằng: Có lẽ Giô-sép sẽ ganh ghét chúng ta, và trả thù việc ác chúng ta đã làm cho người chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Các anh bèn sai người đến nói cùng Giô-sép rằng: Trước khi qua đời, cha em có trối rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Hãy nói lại cho Giô-sép như vầy: Ôi! xin hãy tha điều ác, tội phạm của các anh con đi, vì chúng nó đã lỗi cũng con đó; nhưng bây giờ cha xin con hãy tha tội kẻ tôi tớ của Ðức Chúa Trời cha. Nghe qua mấy lời nầy, Giô-sép bèn khóc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Chánh các anh người đến sắp mình xuống dưới chơn mà nói rằng: Các anh đây thật là kẻ tôi tớ của em đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Giô-sép đáp rằng: Các anh đừng sợ chi, vì tôi há thay mặt Ðức Chúa Trời sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Các anh toan hại tôi, nhưng Ðức Chúa Trời lại toan làm điều ích cho tôi, hầu cho cứu sự sống cho nhiều người, y như đã xảy đến ngày nay, và giữ gìn sự sống của dân sự đông đảo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Vậy, đừng sợ, tôi sẽ cấp dưỡng các anh và con cái các anh. Ðoạn, Giô-sép an ủy các anh, và lấy lời êm dịu mà nói cùng họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Giô-sép cùng nhà cha mình kiều ngụ tại xứ Ê-díp-tô; người hưởng thọ được một trăm mười tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Người thấy được các con cháu Ép-ra-im đến đời thứ ba, và cũng có được nâng niu trên gối mình các con của Ma-ki, tức con trai của Ma-na-se, nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Kế, Giô-sép nói cùng các anh em rằng: Em sẽ chết, nhưng Ðức Chúa Trời sẽ đến viếng các anh em thật; đem các anh em về xứ mà Ngài đã thề hứa cùng Áp-ra-ham, Y-sác, và Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Giô-sép biểu các con trai của Y-sơ-ra-ên thề mà rằng: Quả thật, Ðức Chúa Trời sẽ đến viḀ¿ng các anh em; xin anh em hãy dời hài cốt tôi khỏi xứ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Ðoạn, Giô-sép qua đời, hưởng thọ được một trăm mười tuổi. Người ta xông thuốc thơm cho xác Giô-sép, và liệm trong một quan tài tại xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Ðây là tên các con trai của Y-sơ-ra-ên, mỗi người đều dẫn người nhà mình đi với Gia-cốp đến xứ Ê-díp-tô:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ru-bên, Si-mê-ôn, Lê-vi và Giu-đa;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Y-sa-ca, Sa-bu-lôn và Bên-gia-min;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Ðan, Nép-ta-li, Gát, và A-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Hết thảy những người bởi Gia-cốp sanh ra, được bảy mươi người; Giô-sép đã ở tại xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Vả, Giô-sép và anh em người cùng mọi kẻ đồng đời đó đều chết hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Con cháu Y-sơ-ra-ên thêm nhiều lạ lùng, nẩy nở ra, và trở nên rất cường thạnh; cả xứ đều đầy dẫy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Nhưng bấy giờ tại nước Ê-díp-tô, có một vua mới lên ngôi, chẳng quen biết Giô-sép.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Vua phán cùng dân mình rằng: Nầy, dân Y-sơ-ra-ên đông và mạnh hơn chúng ta;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'hè! ta hãy dùng chước khôn ngoan đối cùng họ, kẻo họ thêm nhiều lên, một mai nếu có cơn chinh chiến xảy đến, họ sẽ hiệp cùng quân nghịch đánh lại ta, và ra khỏi xứ chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Vậy, người Ê-díp-tô bèn đặt các kẻ đầu xâu để bắt dân Y-sơ-ra-ên làm xâu khó nhọc; họ xây thành Phi-thom và Ram-se dùng làm kho tàng cho Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Nhưng người Ê-díp-tô càng bắt làm khó nhọc chừng nào, dân Y-sơ-ra-ên càng thêm nhiều lên, và tràn ra chừng nấy. Người Ê-díp-tô bèn đem lòng ghen ghét dân Y-sơ-ra-ên,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'bắt làm công việc nhọc nhằn,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'gây cho đời dân ấy nên cay đắng, vì nỗi khổ sở nhồi đất, làm gạch và mọi việc khác ở ngoài đồng. Các công việc nầy người Ê-díp-tô bắt dân Y-sơ-ra-ên làm nhọc nhằn lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Vua xứ Ê-díp-tô cũng phán cùng các bà mụ của dân Hê-bơ-rơ, một người tên Siếp-ra và một người tên Phu-a,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'mà rằng: Khi các ngươi đi rước thai cho người đàn bà Hê-bơ-rơ, hễ thấy sanh con trai, thì hãy làm cho chết đi; còn con gái, thì hãy để cho sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Nhưng các bà mụ kính sợ Ðức Chúa Trời, chẳng làm theo lời vua Ê-díp-tô phán dặn, đều để cho các con trai sống hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Vua xứ Ê-díp-tô bèn đòi những bà mụ mà phán rằng: Sao các ngươi làm như vậy, để cho những con trai sống?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Các bà mụ tâu rằng: Ấy tại người đàn bà Hê-bơ-rơ chẳng phải như người đàn bà Ê-díp-tô; vì họ mạnh khỏe hơn, đã sanh nở trước khi mụ đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Ðức Chúa Trời ban ơn cho những bà mụ; dân sự gia thêm và trở nên đông đúc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Ấy vậy, vì bà mụ có lòng kính sợ Ðức Chúa Trời, nên Ngài làm cho nhà họ được thạnh vượng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Pha-ra-ôn bèn truyền lịnh cho cả dân mình rằng: Phàm con trai của dân Hê-bơ-rơ mới sanh, hãy liệng xuống sông; còn con gái, thì để cho sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Vả, có một người trong họ Lê-vi đi cưới con gái Lê-vi làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Nàng thọ thai, và sanh một con trai; thấy con ngộ, nên đem đi giấu trong ba tháng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Nhưng giấu lâu hơn nữa không được, nàng bèn lấy một cái rương mây, trét chai và nhựa thông, rồi để đứa trẻ vào, đem thả trong đám sậy dựa mé sông.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Người chị đứa trẻ đứng xa nơi đó đặng cho biết nó sẽ ra sao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Vả, bấy giờ, con gái Pha-ra-ôn xuống sông tắm, còn các con đòi đi dạo chơi trên mé sông; công chúa thấy cái rương mây đó giữa đám sậy, bèn sai con đòi mình đi vớt lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Công chúa mở rương ra, thấy đứa trẻ, là một đứa con trai nhỏ đương khóc, bèn động lòng thương xót mà rằng: Ấy là một đứa con của người Hê-bơ-rơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Người chị đứa trẻ bèn nói cùng công chúa rằng: Tôi phải đi kêu một người vú trong bọn đàn bà Hê-bơ-rơ đặng cho dứa trẻ bú chớ?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Công chúa đáp rằng: Hãy đi đi. Người gái trẻ đó kêu mẹ của đứa trẻ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Công chúa nói rằng: Hãy đem đứa trẻ nầy về nuôi bú cho ta; ta sẽ trả tiền công cho. Người đàn bà ẵm đứa trẻ mà cho bú.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Khi lớn khôn rồi, người bèn dẫn nó vào cho công chúa, nàng nhận làm con, và đặt tên là Môi-se, vì nàng nói rằng: Ta đã vớt nó khỏi nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Vả, đang lúc đó, Môi-se đã lớn khôn rồi, ra đi đến cùng anh em mình, xem thấy công việc nhọc nhằn của họ; cũng thấy một người Ê-díp-tô đánh một người Hê-bơ-rơ trong vòng anh em mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'ngó quanh quất chẳng thấy ai, bèn giết người Ê-díp-tô đem vùi trong cát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Qua ngày sau, Môi-se đi ra nữa, thấy hai người Hê-bơ-rơ đánh lộn, bèn nói cùng người có lỗi rằng: Sao ngươi đánh người đồng loại mình?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Nhưng người đó đáp rằng: Ai đặt ngươi làm vua, làm quan án cho chúng ta? Có phải muốn giết ta như đã giết người Ê-díp-tô kia chăng? Môi-se sợ, nói rằng: Chắc thật, việc nầy phải lậu rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Pha-ra-ôn hay việc đó, thì tìm giết Môi-se; nhưng người trốn đi khỏi mặt Pha-ra-ôn, dừng chân tại xứ Ma-đi-an, và ngồi gần bên một cái giếng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Vả, thầy tế lễ xứ Ma-đi-an có bảy con gái; các nàng đó đến giếng xách nước đổ đầy máng đặng cho bầy chiên cha mình uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Nhưng các kẻ chăn chiên đến đuổi đi; Môi-se bèn đứng dậy, binh vực các nàng đó và cho những bầy chiên uống nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Khi mấy nàng trở về nhà Rê -u-ên, cha mình, thì người hỏi rằng: Sao bữa nay các con về sớm vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Thưa rằng: Một người Ê-díp-tô cứu chúng tôi ra khỏi tay bọn chăn chiên, và cũng có xách nước nhiều quá cho bầy chiên uống nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Cha lại hỏi rằng: Người đó bây giờ ở đâu? Sao các con bỏ người đi? Hãy mời đến đặng ăn bánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Môi-se ưng ở cùng người nầy, người bèn gả Sê-phô-ra, con gái mình, cho Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Nàng sanh một con trai; Môi-se đặt tên là Ghẹt-sôn vì nói rằng: Tôi kiều ngụ nơi ngoại bang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Sau cách lâu, vua xứ Ê-díp-tô băng; dân Y-sơ-ra-ên than thở kêu van vì phải phục dịch khổ sở; tiếng kêu van lên thấu Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Ngài nghe tiếng than thở chúng, nhớ đến sự giao ước mình kết lập cùng Áp-ra-ham, Y-sác và Gia-cốp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Ðức Chúa Trời đoái lại dân Y-sơ-ra-ên, nhận biết cảnh ngộ của chúng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Vả, Môi-se chăn bầy chiên cho Giê-trô, ông gia mình, là thầy tế lễ tại xứ Ma-đi-an; dẫn bầy chiên qua phía bên kia đồng vắng, đến núi của Ðức Chúa Trời, là núi Hô-rếp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Thiên sứ của Ðức Giê-hô-va hiện ra cùng người trong ngọn lửa, giữa bụi gai kia. Người nhìn thấy cả bụi gai đang cháy, nhưng không hề tàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Môi-se bèn nói rằng: Ta hãy tẻ bước lại đặng xem sự lạ lớn nầy, vì cớ sao bụi gai chẳng tàn chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Ðức Giê-hô-va thấy người tẻ bước lại xem, Ðức Chúa Trời bèn ở giữa bụi gai gọi rằng: Hỡi Môi-se, hỡi Môi-se! Người thưa rằng: Có tôi đây!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Ðức Chúa Trời phán rằng: Chớ lại gần chốn nầy, Hãy cổi giầy ngươi ra, vì chỗ ngươi đang đứng là đất thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Rồi Ngài lại nói: Ta là Ðức Chúa Trời của tổ phụ ngươi, Ðức Chúa Trời của Áp-ra-ham, Ðức Chúa Trời của Y-sác, và Ðức Chúa Trời của Gia-cốp. Môi-se liền che mặt, vì sợ nhìn đến Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Ðức Giê-hô-va phán rằng: Ta đã thấy rõ ràng sự cực khổ của dân ta tại xứ Ê-díp-tô, và có nghe thấu tiếng kêu rêu vì cớ người đốc công của nó; phải, ta biết được nỗi đau đớn của nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Ta ngự xuống đặng cứu dân nầy khỏi tay người Ê-díp-tô, dẫn từ xứ ấy lên đến một xứ kia đẹp đẽ và rộng rãi, đượm sữa và mật, tức là nơi dân Ca-na-an, dân Hê-tít, dân A-mô-rít, dân Phê-rê-sít, dân Hê-vít và dân Giê-bu-sít ở.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Nầy, tiếng kêu rêu của dân Y-sơ-ra-ên thấu đến ta, và ta đã thấy dân Ê-díp-tô hà hiếp chúng nó thể nào;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'vậy bây giờ, hãy lại đây, đặng ta sai ngươi đi đến Pha-ra-ôn, để dắt dân ta, là dân Y-sơ-ra-ên, ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Môi-se bèn thưa rằng: Tôi là ai, dám đi đến Pha-ra-ôn, đặng dắt dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Ðức Chúa Trời phán rằng: Ta sẽ ở cùng ngươi; nầy là điều làm dấu cho ngươi biết rằng ta đã sai ngươi đi: Khi ngươi dắt dân sự ra khỏi xứ Ê-díp-tô rồi, thì các ngươi sẽ phụng sự Ðức Chúa Trời tại trên núi nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Môi-se thưa cùng Ðức Chúa Trời rằng: Nầy, tôi sẽ đi đến dân Y-sơ-ra-ên, nói cùng họ rằng: Ðức Chúa Trời của tổ phụ các ngươi sai ta đến cùng các ngươi; nhưng nếu họ hỏi: Tên Ngài là chi? thì tôi nói với họ làm sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Ðức Chúa Trời phán rằng: Ta là Ðấng Tự Hữu Hằng Hữu; rồi Ngài lại rằng: Hãy nói cho dân Y-sơ-ra-ên như vầy: Ðấng Tự Hữu đã sai ta đến cùng các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Ðức Chúa Trời lại phán cùng Môi-se rằng: Ngươi sẽ nói cho dân Y-sơ-ra-ên như vầy: Giê-hô-va, Ðức Chúa Trời của tổ phụ các ngươi, Ðức Chúa Trời của Áp-ra-ham, Ðức Chúa Trời của Y-sác, Ðức Chúa Trời của Gia-cốp, sai ta đến cùng các ngươi. Ấy đó là danh đời đời của ta, ấy sẽ là kỷ niệm của ta trải qua các đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Hãy đi, hội hiệp các trưởng lão Y-sơ-ra-ên, mà nói cùng họ rằng: Giê-hô-va, Ðức Chúa Trời của tổ phụ các ngươi, Ðức Chúa Trời của Áp-ra-ham, Ðức Chúa Trời của Y-sác, Ðức Chúa Trời của Gia-cốp, đã hiện ra cùng ta mà phán rằng: Thật vậy, ta đã thăm viếng các ngươi, thấy điều họ đãi các ngươi tại xứ Ê-díp-tô,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'nên ta đã phán rằng: Ta sẽ rút các ngươi ra khỏi cảnh khổ tại xứ Ê-díp-tô, đặng đem lên xứ của dân Ca-na-an, dân Hê-tít, dân A-mô-rít, dân Phê-rê-sít, dân Hê-vít, và dân Giê-bu-sít, tức là một xứ đượm sữa và mật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Dân sự sẽ vâng theo lời ngươi; vậy, ngươi và các trưởng lão Y-sơ-ra-ên hãy đi yết-kiến vua xứ Ê-díp-tô mà tâu rằng: Giê-hô-va, Ðức Chúa Trời của dân Hê-bơ-rơ, đã hiện ra cùng chúng tôi. Vây bây giờ, xin để cho chúng tôi đi đến nơi đồng vắng, cách chừng ba ngày đường đặng dâng của lễ cho Giê-hô-va Ðức Chúa Trời chúng tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Vả, ta biết rằng dẫu lấy quyền lực ép buộc vua Ê-díp-tô, thì người cũng chẳng bao giờ cho các ngươi đi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Nhưng ta sẽ giơ tay ra hành xứ Ê-díp-tô bằng các phép lạ ta làm giữa xứ đó, sau rồi họ sẽ cho các ngươi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Ta sẽ làm cho dân nầy được ơn trước mắt người Ê-díp-tô; vậy, khi nào các ngươi ra đi, thì sẽ chẳng ra đi tay không;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'nhưng mỗi người đàn bà sẽ hỏi xin người nữ lân cận, cùng kẻ ở tạm nhà mình những đồ bằng vàng, bằng bạc và quần áo, mặc lấy cho con trai con gái mình. Các ngươi sẽ lột trần dân Ê-díp-tô là như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Môi-se thưa rằng: Nhưng dân đó sẽ chẳng tin và chẳng vâng lời tôi, vì sẽ nói rằng: Ðức Giê-hô-va chẳng có hiện ra cùng ngươi đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Ðức Giê-hô-va phán rằng: Trong tay ngươi cầm vật chi? Thưa rằng: Một cây gậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Phán rằng: Hãy ném xuống đất đi. Người bèn ném xuống đất, gậy hóa ra một con rắn; Môi-se chạy trốn nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy giơ tay ngươi ra nắm đuôi nó. Người giơ tay ra nắm, thì nó hườn lại cây gậy trong tay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Ðức Giê-hô-va phán rằng: Ấy để cho chúng nó tin rằng Giê-hô-va, Ðức Chúa Trời của tổ phụ mình, là Ðức Chúa Trời của Áp-ra-ham, Ðức Chúa Trời của Y-sác, Ðức Chúa Trời của Gia-cốp, đã hiện ra cùng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Ðức Giê-hô-va lại phán rằng: Hãy đặt tay ngươi vào lòng. Người liền đặt vào, rồi lấy ra. Nầy, tay người nổi phung trắng như tuyết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Ðoạn, Ngài phán rằng: Hãy đặt tay ngươi vào lòng lại; người bèn đặt vào, rồi lấy ra. Kìa, tay trở lại như thịt mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Lại phán: Nếu khi nào dân đó chẳng tin ngươi và chẳng vâng theo tiếng của dấu thứ nhất, thì sẽ tin theo tiếng của dấu thứ nhì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Vả lại, nếu dân chẳng tin cả hai dấu nầy, và không vâng theo lời ngươi, thì hãy lấy nước dưới sông mà làm tràn ngập trên mặt đất; nước mà ngươi đã lấy dưới sông lên đó, sẽ thành máu trên mặt đất vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Môi-se thưa cùng Ðức Giê-hô-va rằng: Ôi! lạy Chúa, từ hôm qua, hôm kia, hay là từ lúc Chúa phán dạy kẻ tôi tớ Chúa, tôi vẫn chẳng phải một tay nói giỏi, vì miệng và lưỡi tôi hay ngập ngừng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Ðức Giê-hô-va bèn phán rằng: Ai tạo miệng loài người ra? hay là ai đã làm câm, làm điếc, làm sáng, làm mờ? Có phải ta là Ðức Giê-hô-va chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Vậy bây giờ, hãy đi; ta sẽ ở cùng miệng ngươi và dạy ngươi những lời phải nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Môi-se thưa rằng: Ôi! lạy Chúa, Chúa muốn sai ai đi, thì sai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Ðức Giê-hô-va bèn nổi giận cùng Môi-se mà phán rằng: Có phải A-rôn, người Lê-vi, là anh ngươi chăng? Ta biết người đó có tài nói giỏi, và kìa, người đang đi đến đón ngươi kìa; khi thấy ngươi, chắc sẽ vui mừng trong lòng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Vậy ngươi hãy nói cùng người, và sắp để những lời trong miệng người. Khi hai ngươi nói, ta sẽ ở cùng miệng ngươi và miệng anh ngươi, dạy các ngươi những điều gì phải làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Ấy là người đó sẽ nói cùng dân sự thế cho ngươi, dùng làm miệng ngươi, còn ngươi sẽ dường như Ðức Chúa Trời cho người vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Ngươi hãy cầm lấy gậy nầy nơi tay, để dùng làm các dấu lạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Môi-se bèn đi, trở về Giê-trô, ông gia mình, mà thưa rằng: Xin cha hãy cho tôi trở về nơi anh em tôi tại xứ Ê-díp-tô, đặng thăm thử họ còn sống chăng. Giê-trô bèn nói cùng Môi-se rằng: Con hãy đi bình yên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Vả, Ðức Giê-hô-va có phán cùng Môi-se tại Ma-đi-an rằng: Hãy trở về xứ Ê-díp-tô, vì mấy người tìm giết ngươi đã chết hết rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Môi-se bèn đỡ vợ và con mình lên lưng lừa, trở về xứ Ê-díp-tô. Người cũng cầm cây gậy của Ðức Chúa Trời theo trong tay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Khi trở về xứ Ê-díp-tô, hãy cẩn thận về các dấu lạ của ta đã giao nơi tay ngươi mà làm trước mặt Pha-ra-ôn; nhưng ta sẽ khiến người cứng lòng chẳng cho dân sự đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Vậy, ngươi phải tâu cùng Pha-ra-ôn rằng: Ðức Giê-hô-va có phán như vầy: Y-sơ-ra-ên là con ta, tức trưởng nam ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'nên ta có phán cùng ngươi rằng: Hãy cho con ta đi, để nó phụng sự ta, mà ngươi đã từ chối không cho nó đi. Nầy, ta sẽ giết con trai ngươi, là con trưởng nam của ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Vả, đang khi đi đường, Ðức Giê-hô-va hiện ra trước mặt Môi-se nơi nhà quán, và kiếm thế giết người đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Sê-phô-ra lấy con dao bằng đá, cắt dương bì của con mình, và quăng dưới chân Môi-se, mà nói rằng: Thật, chàng là huyết lang cho tôi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Ðức Giê-hô-va tha chồng; nàng bèn nói rằng: Huyết lang! là vì cớ phép cắt bì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Ðức Giê-hô-va phán cùng A-rôn rằng: Hãy đi đến đồng vắng, đón rước Môi-se. A-rôn bèn đi, gặp Môi-se tại núi của Ðức Chúa Trời, và hôn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Môi-se thuật lại cho A-rôn mọi lời của Ðức Giê-hô-va sai mình truyền, và các dấu lạ mà Ngài đã dạy mình làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Vậy, Môi-se đi cùng A-rôn, nhóm lại các trưởng lão dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'A-rôn bèn thuật hết các lời của Ðức Giê-hô-va đã phán cùng Môi-se, và làm những dấu lạ trước mặt dân sự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Chúng bèn tin, hiểu rằng Ðức Giê-hô-va đã thăm viếng dân Y-sơ-ra-ên, và thấy điều cực khổ của mình; chúng bèn cúi đầu và thờ lạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Kế sau, Môi-se và A-rôn đến tâu cùng Pha-ra-ôn rằng: Giê-hô-va, Ðức Chúa Trời của dân Y-sơ-ra-ên có phán như vầy: Hãy cho dân ta đi, đặng nó giữ một lễ cho ta tại đồng vắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Nhưng Pha-ra-ôn đáp rằng: Giê-hô-va là ai mà trẫm phải vâng lời người, để cho dân Y-sơ-ra-ên đi? Trẫm chẳng biết Giê-hô-va nào hết; cũng chẳng cho dân Y-sơ-ra-ên đi nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Môi-se và A-rôn tâu rằng: Ðức Chúa Trời của dân Hê-bơ-rơ đã đến cùng chúng tôi; xin hãy cho phép chúng tôi đi vào nơi đồng vắng, cách chừng ba ngày đường, đặng dâng tế lễ cho Giê-hô-va Ðức Chúa Trời chúng tôi, kẻo Ngài khiến bịnh dịch hay việc gươm dao hành chúng tôi chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Vua xứ Ê-díp-tô phán rằng: Hỡi Môi-se và A-rôn, sao các ngươi xui cho dân chúng bỏ công việc như vậy? Hãy đi làm công việc mình đi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Pha-ra-ôn lại phán rằng: Kìa, dân sự trong xứ bây giờ đông đúc quá, hai người làm cho chúng nó phải nghỉ việc ư!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Trong ngày đó, Pha-ra-ôn truyền lịnh cho các đốc dịch và phái viên rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Các ngươi đừng phát rơm cho dân sự làm gạch như lúc trước nữa; chúng nó phải tự đi kiếm góp lấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Nhưng các ngươi hãy hạn số gạch y như cũ, chớ trừ bớt chi cả; vì họ biếng nhác, lấy cớ mà đồng kêu lên rằng: Hè! đi dâng tế lễ cho Ðức Chúa Trời chúng ta!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Hãy gán công việc nặng cho chúng nó, hầu cho chúng nó mắc công việc, chẳng xiêu về lời giả dối nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Các đốc dịch và phái viên bèn ra, nói cùng dân chúng rằng: Pha-ra-ôn có phán như vầy: Ta chẳng cho các ngươi rơm nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Hãy tự đi kiếm lấy rơm ở đâu đi; song chẳng trừ bớt công việc các ngươi chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Bấy giờ, dân chúng bèn đi rải khắp xứ Ê-díp-tô, đặng góp gốc rạ thế cho rơm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Các đốc dịch lại hối rằng: Hãy làm cho xong phần việc các ngươi, y cố định, ngày nào cho rồi ngày nấy, cũng như khi có phát rơm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Những phái viên trong vòng dân Y-sơ-ra-ên mà các đốc dịch của Pha-ra-ôn đã lập lên trên dân đó, bị đánh và quở rằng: Sao hôm qua và ngày nay, các ngươi chẳng làm xong phần định về việc mình làm gạch y như trước?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Các phái viên của dân Y-sơ-ra-ên bèn đến kêu cùng Pha-ra-ôn rằng: Sao bệ hạ đãi kẻ tôi tớ như vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Người ta chẳng phát rơm cho, lại cứ biểu chúng tôi rằng: Hãy làm gạch đi! Nầy tôi tớ của bệ hạ đây bị đòn; lỗi tại dân của bệ hạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Nhưng vua đáp rằng: Các ngươi là đồ biếng nhác, đồ biếng nhác! Bởi cớ đó nên nói với nhau rằng: Hè! đi tế Ðức Giê-hô-va!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Vậy bây giờ, cứ đi làm việc đi, người ta chẳng phát rơm cho đâu, nhưng các ngươi phải nộp gạch cho đủ số.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Vậy, các phái viên của dân Y-sơ-ra-ên lấy làm bối rối, vì người ta có nói cùng mình rằng: Các ngươi chẳng được trừ số gạch đã định cho mình ngày nào rồi ngày nấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Khi lui ra khỏi Pha-ra-ôn thì họ gặp Môi-se và A-rôn đợi tại đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'bèn nói rằng: Hai ngươi đã làm cho chúng tôi ra mùi hôi hám trước mặt Pha-ra-ôn và quần thần, mà trao thanh gươm vào tay họ đặng giết chúng tôi. Cầu xin Ðức Giê-hô-va xem xét và xử đoán hai ngươi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Môi-se bèn trở về cùng Ðức Giê-hô-va mà thưa rằng: Lạy Chúa! sao Chúa đã làm hại cho dân sự nầy? Chúa sai tôi đến mà chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Từ khi tôi đi yết kiến Pha-ra-ôn đặng nhân danh Chúa mà nói, thì người lại ngược đãi dân nầy, và Chúa chẳng giải cứu dân của Chúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Bây giờ ngươi hãy xem những điều ta sẽ hành Pha-ra-ôn; vì nhờ tay quyền năng ép buộc vua đó sẽ tha và đuổi dân Y-sơ-ra-ên ra khỏi xứ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Ðức Chúa Trời lại phán cùng Môi-se rằng: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ta đã hiện ra cùng Áp-ra-ham, cùng Y-sác, và cùng Gia-cốp, tỏ mình là Ðức Chúa Trời toàn năng; song về danh ta là Giê-hô-va, thì ta chưa hề tỏ cho họ biết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Ta cũng có lập giao ước cùng họ, để ban xứ Ca-na-an cho, là xứ họ đã kiều ngụ như khách ngoại bang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Ta cũng có nghe lời than thở của dân Y-sơ-ra-ên bị người Ê-díp-tô bắt làm tôi mọi, bèn nhớ lại sự giao ước của ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Vậy nên, ngươi hãy nói cùng dân Y-sơ-ra-ên rằng: Ta là Ðức Giê-hô-va sẽ rút các ngươi khỏi gánh nặng mà người Ê-díp-tô đã gán cho, cùng giải thoát khỏi vòng tôi mọi; ta sẽ giơ thẳng tay ra, dùng sự đoán phạt nặng mà chuộc các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Ta sẽ nhận các ngươi làm dân ta, và ta sẽ làm Ðức Chúa Trời của các ngươi; các ngươi sẽ biết ta là Giê-hô-va Ðức Chúa Trời của các ngươi, đã rút các ngươi khỏi gánh nặng của người Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Ta sẽ dắt các ngươi vào xứ ta đã thề ban cho Áp-ra-ham, cho Y-sác, cho Gia-cốp, mà cho các ngươi xứ đó làm cơ nghiệp: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Môi-se nói lại như vậy cho dân Y-sơ-ra-ên; nhưng vì bị sầu não và việc tôi mọi nặng nề, nên chẳng nghe Môi-se chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Hãy đi tâu cùng Pha-ra-ôn, vua xứ Ê-díp-tô, phải cho dân Y-sơ-ra-ên ra khỏi xứ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Nhưng Môi-se thưa cùng Ðức Giê-hô-va rằng: Nầy, tôi là một kẻ vụng miệng; dân Y-sơ-ra-ên chẳng có nghe lời tôi, Pha-ra-ôn há sẽ khứng nghe lời tôi sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Ðức Giê-hô-va lại phán cùng Môi-se và A-rôn, bèn truyền cho hai người phải đi đến dân Y-sơ-ra-ên và Pha-ra-ôn, vua xứ Ê-díp-tô, đặng đem dân đó ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ðây là các trưởng tộc của những họ hàng dân Y-sơ-ra-ên. Các con trai của Ru-bên, tức là trưởng nam Y-sơ-ra-ên, là: Hê-nóc, Pha-lu, Hết-rôn và Cạt-mi. Ðó là những họ hàng của Ru-bên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Các con trai của Si-mê-ôn là: Giê-mu-ên, Gia-min, Ô-hát, Gia-kin, Xô-ha và Sau-lơ là con của vợ xứ Ca-na-an. Ðó là họ hàng của Si-mê-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Ðây là tên các con trai của Lê-vi, tùy theo dòng dõi của họ: Ghẹt-sôn, Kê-hát, và Mê-ra-ri. Lê-vi hưởng thọ được một trăm ba mươi bảy tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Các con trai của Ghẹt-sôn, tùy theo họ hàng mình: Líp-ni và Si-mê -y.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Các con trai của Kê-hát là: Am-ram, Dít-sê-ha, Hếp-rôn, và U-xi-ên. Kê-hát hưởng thọ được một trăm ba mươi ba tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Các con trai của Mê-ra-ri là: Mách-li, và Mu-si. Ðó là các họ hàng của Lê-vi, tùy theo dòng dõi của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Vả, Am-ram lấy Giô-kê-bết, là cô mình, làm vợ; nàng sanh cho người A-rôn và Môi-se. Am-ram hưởng thọ được một trăm ba mươi bảy tuổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Các con trai của Dít-sê-ha là: Cô-rê, Nê-phết và Xiếc-ri.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Các con trai của U-xi-ên là: Mi-sa-ên, Eân-sa-phan, và Sít-ri.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'A-rôn cưới Ê-li-sê-ba, con gái của A-mi-na-đáp, em của Na-ha-sôn; nàng sanh cho người Na-đáp, A-bi-hu, Ê-lê-a-sa và Y-tha-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Các con trai của Cô-rê là: Át-si, Eân-ca-na và A-bi-a-sáp. Ðó là các họ hàng của dân Cô-rê.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Ê-lê-a-sa, con trai của A-rôn, cưới con gái của Phu-ti-ên làm vợ; nàng sanh Phi-nê-a cho người. Ðó là các trưởng tộc của nhà tổ phụ người Lê-vi, tùy theo họ hàng mình vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Ấy, A-rôn và Môi-se nầy, tức là người mà Ðức Giê-hô-va đã phán dạy rằng: Hãy tùy theo cơ đội, đem dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ấy là hai người tâu cùng Pha-ra-ôn, vua xứ Ê-díp-tô, đặng đem dân Y-sơ-ra-ên ra khỏi xứ đó; ấy là Môi-se và A-rôn nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Vậy, trong ngày Ðức Giê-hô-va phán cùng Môi-se tại xứ Ê-díp-tô,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'thì Ngài có truyền rằng: Ta là Ðức Giê-hô-va, hãy tâu lại cùng Pha-ra-ôn, vua xứ Ê-díp-tô, hết thảy mọi lời ta sẽ phán cùng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Môi-se bèn thưa rằng: Nầy, tôi là người vụng miệng: Pha-ra-ôn há sẽ nghe tôi sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy xem, ta lập ngươi như là Ðức Chúa Trời cho Pha-ra-ôn, còn A-rôn, anh ngươi, sẽ làm kẻ tiên tri của ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Hãy nói lại mọi lời ta sẽ truyền dạy ngươi, rồi A-rôn, anh ngươi, sẽ tâu cùng Pha-ra-ôn, đặng người thả dân Y-sơ-ra-ên ra khỏi xứ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ta sẽ làm cho Pha-ra-ôn cứng lòng, và thêm nhiều dấu lạ phép kỳ của ta trong xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Nhưng Pha-ra-ôn sẽ chẳng nghe các ngươi đâu; ta sẽ tra tay vào đất Ê-díp-tô, dùng những sự đoán-phạt nằng-nề, đặng rút khỏi xứ đó các quân đội ta, là dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Khi nào ta tra tay vào xứ Ê-díp-tô mà rút dân Y-sơ-ra-ên ra khỏi giữa vòng người Ê-díp-tô, thì họ sẽ biết ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Môi-se và A-rôn bèn làm y như lời Ðức Giê-hô-va đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Vả, khi hai người tâu cùng Pha-ra-ôn, thì Môi-se tuổi đã được tám mươi, còn A-rôn tám mươi ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Ðức Giê-hô-va phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Khi nào Pha-ra-ôn truyền cho các ngươi: Hãy làm phép lạ đi, thì ngươi sẽ nói cùng A-rôn rằng: Hãy lấy cây gậy của anh, liệng trước mặt Pha-ra-ôn, gậy sẽ hóa thành một con rắn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Vậy, Môi-se và Pha-ra-ôn đến cùng Pha-ra-ôn và làm như lời Ðức Giê-hô đã phán dặn. A-rôn liệng cây gậy mình trước mặt Pha-ra-ôn và quần thần, gậy liền hóa thành một con rắn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Còn Pha-ra-ôn bèn đòi các bác sĩ và thầy phù chú, là những thuật-sĩ Ê-díp-tô; phần họ, cũng cậy phép phù chú mình mà làm giống in như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Mỗi người liệng gậy mình, liền hóa thành rắn; nhưng gậy của A-rôn nuốt các gậy của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Thế mà lòng Pha-ra-ôn vẫn cứng cỏi, chẳng nghe Môi-se và A-rôn, y như lời Ðức Giê-hô-va đã phán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Pha-ra-ôn đã rắn lòng, từ chối không để cho dân sự đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Sớm mai Pha-ra-ôn sẽ ngự ra bờ sông, ngươi hãy ra mắt người và cầm theo tay cây gậy đã biến ra con rắn đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Ngươi hãy tâu rằng: Giê-hô-va, là Ðức Chúa Trời của dân Hê-bơ-rơ, sai tôi đến gần bệ hạ, đặng tâu rằng: Hãy tha cho dân ta đi, để chúng nó hầu việc ta trong đồng vắng; mà đến bây giờ ngươi không nghe ta chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Ðức Giê-hô-va có phán như vầy: Vì việc nầy, ngươi sẽ biết ta là Ðức Giê-hô-va: Nầy ta lấy gậy trong tay ta mà đập nước ở dưới sông, nước sẽ trở nên huyết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Cá dưới sông sẽ chết, và sông sẽ hôi thúi đi; người Ê-díp-tô uống nước sông lấy làm ghê gớm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Ðoạn, Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy truyền cho A-rôn rằng: Cầm lấy cây gậy anh, giơ tay ra trên nước xứ Ê-díp-tô, trên rạch, sông, bàu, và khắp mọi nơi có nước trong xứ, hầu cho nước hóa thành huyết; cả xứ Ê-díp-tô, và trong những bình chứa nước bằng gỗ, bằng đá đều sẽ có huyết hết thảy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Vậy, Môi-se và A-rôn bèn làm y như lời Ðức Giê-hô-va đã dặn mình. Trước mặt Pha-ra-ôn và quần thần, A-rôn giơ gậy lên, đập nước sông, hết thảy nước sông bèn hóa thành huyết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Cá dưới sông chết, nước sông hôi-thúi, người Ê-díp-tô không thể uống được; vậy, huyết lan khắp cả xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Song các thuật sĩ cậy phù chú mình cũng làm được như vậy, lòng Pha-ra-ôn cứng cỏi, không nghe Môi-se và A-rôn chút nào, y như lời Ðức Giê-hô-va đã phán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Pha-ra-ôn xây đi về đền mình, lòng chẳng để về mấy điều đó chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Vả, vì hết thảy người Ê-díp-tô uống nước sông chẳng được, nên đào xung quanh sông tìm nước mà uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Sau khi Ðức Giê-hô-va đập sông thì được bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Ðoạn, Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy đi ra mắt Pha-ra-ôn, và tâu cùng người rằng: Ðức Giê-hô-va có phán như vầy: Hãy tha cho dân ta đi, để chúng nó hầu việc ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Nếu ngươi không tha cho đi, nầy ta sẽ giáng tai nạn ếch nhái khắp bờ cõi ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Sông sẽ sanh đông đúc ếch nhái, bò lên vào cung điện, phòng ngủ, và trên giường người, vào nhà đầy tớ và dân sự ngươi, trong lò bếp, cùng nơi nhồi bột làm bánh của ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Ếch nhái sẽ bò lên mình ngươi, lên mình dân sự và mọi đầy tớ ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Vậy, Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy truyền cho A-rôn rằng: Hãy cầm gậy giơ tay ra trên rạch, trên sông và trên bàu, khiến ếch nhái tràn lên xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'A-rôn giơ tay mình trên các sông rạch xứ Ê-díp-tô, ếch nhái bò lên lan khắp xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Các thuật sĩ cũng cậy phù chú mình làm y như vậy, đặng khiến ếch nhái bò lên xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Pha-ra-ôn bèn đòi Môi-se và A-rôn mà phán rằng: Hãy cầu nguyện Ðức Giê-hô-va, để Ngài khiến ếch nhái cách xa ta và dân sự ta; thì ta sẽ tha dân Hê-bơ-rơ đi tế Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Môi-se bèn tâu cùng Pha-ra-ôn rằng: Xin hãy định chừng nào tôi phải vì bệ hạ, đầy tớ cùng dân sự bệ hạ mà cầu khẩn Ðức Giê-hô-va, để trừ ếch nhái lìa khỏi bệ hạ và cung điện, chỉ còn dưới sông mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Vua đáp rằng: Ðến ngày mai. Môi-se rằng: Sẽ làm y theo lời, hầu cho bệ hạ biết rằng chẳng có ai giống như Giê-hô-va là Ðức Chúa Trời chúng tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Vậy, ếch nhái sẽ lìa xa bệ hạ, cung điện, tôi tớ, cùng dân sự của bệ hạ; chỉ còn lại dưới sông mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Môi-se và A-rôn bèn lui ra khỏi Pha-ra-ôn; Môi-se kêu cầu Ðức Giê-hô-va về việc ếch nhái mà Ngài đã khiến đến cho Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Ðức Giê-hô-va làm y theo lời Môi-se; ếch nhái trong nhà, trong làng, ngoài đồng đều chết hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Người ta dồn ếch nhái lại từ đống, và cả xứ hôi thúi lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Nhưng Pha-ra-ôn thấy được khỏi nạn, bèn rắn lòng, chẳng nghe Môi-se và A-rôn chút nào, y như lời Ðức Giê-hô-va đã phán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy truyền cho A-rôn rằng: Hãy giơ gậy anh ra, đập bụi trên đất: bụi sẽ hóa muỗi khắp cả xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Hai người làm y như vậy. A-rôn cầm gậy giơ tay ra, đập bụi trên đất, bụi liền hóa thành muỗi, bu người và súc vật; hết thảy bụi đều hóa thành muỗi trong xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Các thuật sĩ cũng muốn cậy phù chú mình làm như vậy, để hóa sanh muỗi, nhưng làm chẳng đặng. Vậy, muỗi bu người và súc vật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Các thuật sĩ bèn tâu cùng Pha-ra-ôn rằng: Ấy là ngón tay của Ðức Chúa Trời; nhưng Pha-ra-ôn cứng lòng, chẳng nghe Môi-se và A-rôn chút nào, y như lời Ðức Giê-hô-va đã phán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Kế đó, Ðức Giê-hô-va phán cùng Môi-se rằng: Nầy Pha-ra-ôn sẽ ngự ra mé sông, ngươi hãy dậy sớm, đi ra mắt người, mà tâu rằng: Ðức Giê-hô-va có phán như vầy: Hãy tha cho dân ta đi, để chúng nó hầu việc ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Vì nếu ngươi không cho đi, nầy, ta sẽ sai ruồi mòng bu nơi ngươi, quần thần, dân sự và cung điện ngươi; nhà của người Ê-díp-tô đều sẽ bị ruồi mòng bu đầy, và khắp trên đất nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Nhưng ngày đó, ta sẽ phân biệt xứ Gô-sen ra, là nơi dân ta ở, không có ruồi mòng, hầu cho ngươi biết rằng ta, Giê-hô-va, có ở giữa xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ta sẽ phân biệt dân ta cùng dân ngươi. Ðến mai, dấu lạ nầy tất sẽ có.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Ðức Giê-hô-va bèn làm y như lời. Vậy, trong cung điện Pha-ra-ôn, nhà cửa của quần thần người cùng cả xứ Ê-díp-tô đều có ruồi mòng vô số, đất bị ruồi mòng hủy hoại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Pha-ra-ôn bèn đòi Môi-se và A-rôn mà phán rằng: Hãy đi dâng tế lễ cho Ðức Chúa Trời các ngươi trong xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Nhưng Môi-se tâu rằng: Làm như vậy chẳng tiện, vì các của lễ mà chúng tôi sẽ tế Giê-hô-va Ðức Chúa Trời chúng tôi, là một điều gớm ghê cho người Ê-díp-tô. Nếu chúng tôi dâng của lễ gớm ghê trước mắt người Ê-díp-tô, họ há chẳng liệng đá chúng tôi sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Chúng tôi sẽ đi trong đồng vắng, chừng ba ngày đường, dâng tế lễ cho Giê-hô-va Ðức Chúa Trời chúng tôi, y như lời Ngài sẽ chỉ bảo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Pha-ra-ôn bèn phán rằng: Ta sẽ tha các ngươi đi dâng tế lễ cho Giê-hô-va Ðức Chúa Trời các ngươi, ở nơi đồng vắng, nhưng đừng đi xa hơn. Hãy cầu nguyện cho ta với!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Môi-se tâu rằng: Nầy, tôi sẽ lui ra khỏi bệ hạ, cầu nguyện Ðức Giê-hô-va cho; ngày mai ruồi mòng sẽ lìa xa Pha-ra-ôn, quần thần, và dân sự người. Nhưng xin Pha-ra-ôn chớ cứ gạt chúng tôi mà không tha dân sự đi dâng tế lễ cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Môi-se bèn lui ra khỏi Pha-ra-ôn, và cầu nguyện Ðức Giê-hô-va;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Ngài làm y như lời Môi-se, ruồi mòng lìa xa Pha-ra-ôn, quần thần, và dân sự người, không còn lại một con nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Nhưng lần nầy, Pha-ra-ôn lại cứng lòng nữa, không cho dân sự đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy đi ra mắt Pha-ra-ôn mà tâu rằng: Giê-hô-va, là Ðức Chúa Trời của dân Hê-bơ-rơ, có phán như vầy: Hãy tha dân ta đi, đặng chúng nó hầu việc ta;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'vì nếu ngươi từ chối không tha đi, còn cầm lại nữa,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'nầy tay của Ðức Giê-hô-va sẽ tra vào các súc vật của người ngoài đồng, vào ngựa, lừa, lạc đà, bò và chiên: sẽ có dịch lệ rất lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Ðức Giê-hô-va sẽ phân biệt súc vật của dân Y-sơ-ra-ên cùng súc vật của người Ê-díp-tô, sẽ chẳng có một con nào của dân Y-sơ-ra-ên bị chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Ðức Giê-hô-va định kỳ mà rằng: Ðến mai, Ðức Giê-hô-va sẽ làm sự đó tại trong xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Vừa đến mai, Ðức Giê-hô-va làm sự đó, hết thảy súc vật của người Ê-díp-tô đều chết; nhưng của dân Y-sơ-ra-ên chẳng chết một con nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Pha-ra-ôn sai người đi xét, thấy chẳng có một con súc vật nào của dân Y-sơ-ra-ên chết hết. Nhưng Pha-ra-ôn rắn lòng, chẳng cho dân sự đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Ðức Giê-hô-va bèn phán cùng Môi-se và A-rôn rằng: Hãy hốt trong trong lò đầy tay các ngươi, rồi tại trước mặt Pha-ra-ôn, Môi-se sẽ vải tro đó lên trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Tro sẽ hóa thành bụi khắp cả xứ Ê-díp-tô, và sanh nhiều ghẻ chốc cương mủ trên mình người và súc vật trong khắp cả xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Vậy, hai người hốt tro trong lò, đứng trước mặt Pha-ra-ôn, rồi Môi-se vải tro lên trời, thì sanh ra ghẻ chốc cương mủ trên mình người ta và súc vật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Các thuật sĩ đứng trước mặt Môi-se không được, vì cớ ghẻ chốc đã sanh trên mình các thuật sĩ như trên mình của hết thảy người Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Ðức Giê-hô-va làm cho Pha-ra-ôn cứng lòng, không nghe Môi-se và A-rôn chút nào, y như lời Ðức Giê-hô-va đã phán cùng Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Ðoạn, Ðức Giê-hô-va phán cùng Môi-se rằng: Ngươi hãy thức dậy sớm, ra mắt Pha-ra-ôn mà tâu rằng: Giê-hô-va, là Ðức Chúa Trời của dân Hê-bơ-rơ, có phán như vầy: Hãy tha dân ta đi, để chúng nó hầu việc ta;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'vì lần nầy ta sẽ giáng các tai nạn cho lòng ngươi, quần thần, và dân sự ngươi, hầu cho ngươi biết rằng khắp thế gian chẳng có ai bằng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Nếu bây giờ, ta đã giơ tay ra hành hại ngươi bịnh dịch, thì ngươi cùng dân ngươi đều đã bị diệt khỏi đất rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Nhưng vì cớ nầy ta để ngươi còn sống, là cho ngươi thấy quyền năng của ta, hầu cho danh ta đồn khắp cả thiên hạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Nếu ngươi còn cản trở, không để cho dân ta đi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'thì mai, tại giờ nầy, ta sẽ làm một đám mưa đá lớn, đến đỗi tại xứ Ê-díp-tô từ khi khai sáng cho đến ngày nay chẳng có đám mưa nào giống như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Thế thì, bây giờ hãy sai đem lục súc và mọi vật thuộc về ngươi ở ngoài đồng vào, cho khỏi hiểm nghèo. Mưa đá sẽ rớt xuống trên mọi người và vật đang ở ngoài đồng không vào nhà, thì sẽ chết hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Những kẻ nào trong quần thần Pha-ra-ôn có lòng kính sợ lời Ðức Giê-hô-va, lật đật rút đầy tớ và súc vật mình về nhà;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'còn kẻ nào chẳng chú ý về lời Ðức Giê-hô-va, thì để đầy tớ và súc vật mình ở ngoài đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy giơ tay ngươi lên trời, làm mưa đá rớt xuống trên cả xứ Ê-díp-tô, trên mình người, súc vật, và khắp rau cỏ ngoài đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Môi-se bèn giơ gậy mình lên trời, Ðức Giê-hô-va làm cho sấm động, mưa đá sa, lửa chạy trên mặt đất. Vậy, Ðức Giê-hô-va khiến mưa đá sa trên xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Vả, có mưa đá sa xuống và lửa cháy rất mạnh pha lộn với, đến nỗi từ khi xứ Ê-díp-tô lập quốc đến giờ, chẳng có giống như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Thế thì, trong cả xứ Ê-díp-tô, mưa đá làm hại mọi vật ở ngoài đồng, nào người ta, nào súc vật, nào rau-cỏ, và làm gãy cây cối nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Chỉ đất Gô-sen, là nơi dân Y-sơ-ra-ên ở, chẳng có mưa đá mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Pha-ra-ôn bèn truyền đòi Môi-se và A-rôn mà phán rằng: Lần nầy trẫm đã phạm tội; Ðức Giê-hô-va là công bình; trẫm cùng dân sự trẫm là kẻ phạm tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Hãy cầu nguyện Ðức Giê-hô-va, hầu cho tan sấm sét và mưa đá; rồi trẫm sẽ tha các ngươi đi, không đợi lâu nữa đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Môi-se bèn đáp rằng: Vừa khi tôi ra khỏi thành, tôi sẽ giơ tay lên Ðức Giê-hô-va, sấm sét sẽ lặng, mưa đá sẽ tan, hầu cho bệ hạ biết rằng trái đất thuộc về Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Nhưng tôi biết rằng bệ hạ và quần thần chưa kính sợ Giê-hô-va Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Vả, trong lúc đó, lúa mạch trổ bông, cây gai có hoa, nên lúa mạch và gai bị đập nát;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'còn lúa mì và tiểu mạch trổ muộn, nên không bị đập.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Vậy, Môi-se lui khỏi Pha-ra-ôn, đi ra thành, giơ tay lên Ðức Giê-hô-va, sấm sét và mưa đá tạnh, mưa bèn ngớt hột trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Khi Pha-ra-ôn thấy mưa, mưa đá và sấm sét đã tạnh rồi, người và quần thần lại rắn lòng, cứ phạm tội nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Vậy Pha-ra-ôn cứng lòng, không tha dân Y-sơ-ra-ên đi, y như lời Ðức Giê-hô-va đã cậy Môi-se mà phán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy đi đến Pha-ra-ôn, vì ta đã làm rắn lòng người và lòng quần thần, để làm cho các dấu lạ của ta tỏ ra giữa họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'hầu cho ngươi thuật cùng con và cháu mình những công việc to tát ta đã làm trên dân Ê-díp-tô, các dấu lạ ta đã làm giữa vòng họ, đặng các ngươi biết rằng ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Môi-se và A-rôn bèn đi đến Pha-ra-ôn mà tâu rằng: Giê-hô-va là Ðức Chúa Trời dân Hê-bơ-rơ, có phán như vầy: Ngươi không chịu hạ mình trước mặt ta cho đến chừng nào? Hãy tha dân ta đi, để chúng nó hầu việc ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Nếu từ chối, không cho dân ta đi, nầy, ngày mai ta sẽ sai cào cào đến địa phận ngươi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'nó sẽ phủ rợp trên mặt đất, người ta chẳng còn thấy đất nữa; nó sẽ cắn xả những vật chi còn lại, tức vật nào trận mưa đá còn chừa lại; nó cũng cắn xả những cây mọc ngoài đồng ruộng các ngươi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'vào đầy cung điện ngươi, dinh thất của quần thần ngươi, và nhà cửa của người Ê-díp-tô: ấy là một điều tổ phụ ngươi, đến nỗi thỉ tổ ngươi, cũng chẳng bao giờ thấy từ khi họ đã có trên mặt đất cho đến ngày nay. Ðoạn, Môi-se xây mặt lui ra khỏi Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Quần thần Pha-ra-ôn tâu rằng: Ðến chừng nào người nầy mới thôi gài bẫy ta? Hãy tha dân ấy đi, để chúng nó hầu việc Giê-hô-va Ðức Chúa Trời chúng nó! Bệ hạ chưa biết rằng nước Ê-díp-tô đã bị nguy vong sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Họ bèn truyền đòi Môi-se và A-rôn trở lại cùng Pha-ra-ôn; người nói rằng: Hãy đi hầu việc Giê-hô-va Ðức Chúa Trời các ngươi. Hết thảy những ai là người phải đi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Môi-se tâu rằng: Chúng tôi đi, sẽ đem nam phụ lão ấu và chiên bò theo, vì về phần chúng tôi, ấy là một lễ của Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Pha-ra-ôn nói rằng: Cầu xin Ðức Giê-hô-va ở cùng các ngươi! Hồ dễ ta cho các ngươi cùng con cái đều đi sao! Không! quả thật không cho đâu, vì các ngươi có mưu ác!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Không được vậy đâu, chỉ các ngươi, là đàn ông, phải đi hầu việc Ðức Giê-hô-va, vì là điều các ngươi đã xin. Ðoạn, họ bèn đuổi Môi-se và A-rôn khỏi trước mặt Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy giơ tay ngươi ra trên xứ Ê-díp-tô, đặng khiến cào cào tràn lên xứ đó, cắn xả rau cỏ và mọi vật chi trên đất mưa đá còn chừa lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Vậy, Môi-se bèn giơ gậy mình ra trên xứ Ê-díp-tô, thì Ðức Giê-hô-va dẫn ngọn gió đông thổi trên xứ sòng ngày và đêm đó; qua sáng mai gió đông đã dẫn cào cào đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Cào cào tràn lên khắp cả xứ Ê-díp-tô, và sa xuống trong địa hạt xứ ấy nhiều vô số. Trước kia chẳng bao giờ có bằng số đó, sau nầy cũng chẳng hề sẽ có bằng như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Cào cào bao phủ khắp mặt đất của cả xứ, và xứ thành ra tối tăm, cắn xả các rau cỏ ngoài đồng cùng trái cây mà mưa đá còn chừa lại; trong khắp xứ Ê-díp-tô chẳng còn chút xanh tươi chi cho cây cối hay là cho cỏ rau ở ngoài đồng ruộng nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Pha-ra-ôn vội đòi Môi-se và A-rôn đến mà phán rằng: Trẫm đã phạm tội cùng Giê-hô-va Ðức Chúa Trời các ngươi, và cùng các ngươi nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Nhưng bây giờ, xin xá tội cho trẫm lần nầy; và hãy cầu giùm Giê-hô-va Ðức Chúa Trời các ngươi, hầu cho ít nữa Ngài khiến xa trẫm cái vạ chết nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Môi-se bèn lui ra khỏi Pha-ra-ôn, và khẩn nguyện Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Ðức Giê-hô-va dẫn ngọn gió tây đến rất mạnh, đem cào cào đi đuổi xuống Biển đỏ; khắp địa hạt Ê-díp-tô chẳng còn một con cào cào nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Nhưng Ðức Giê-hô-va làm cho Pha-ra-ôn cứng lòng: người chẳng tha dân Y-sơ-ra-ên đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy giơ tay ngươi lên trời, hầu cho trên xứ Ê-díp-tô có sự tối tăm dày đến nỗi người ta rờ đụng đến được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Vậy, Môi-se giơ tay mình lên trời, bèn có sự tối tăm rất dày trong ba ngày tại xứ Ê-díp-tô;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'trong ba ngày đó người ta không thấy nhau được, không ai nhớm khỏi chỗ mình được. Nhưng trong chốn dân Y-sơ-ra-ên ở thì có ánh sáng cho họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Pha-ra-ôn bèn đòi Môi-se mà phán rằng: Hãy đi hầu việc Ðức Giê-hô-va; con trẻ các ngươi đi theo nữa; chỉ bầy chiên và bò ở lại thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Nhưng Môi-se tâu rằng: Chính bệ hạ hãy cấp cho chúng tôi các con sinh và vật chi dùng làm của lễ thiêu để dâng cho Giê-hô-va Ðức Chúa Trời chúng tôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Các bầy lục súc sẽ theo chúng tôi nữa, không còn để lại một móng chân nào; vì chúng tôi sẽ dùng mấy con thú đó mà hầu việc Giê-hô-va Ðức Chúa Trời chúng tôi. Chúng tôi biết vật chi dùng để thờ phượng Ðức Giê-hô-va, chỉ khi nào sẽ đến nơi đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Nhưng Ðức Giê-hô-va làm cho Pha-ra-ôn cứng lòng, nên người không khứng cho dân Y-sơ-ra-ên đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Pha-ra-ôn nói rằng: Hãy lui ra khỏi ta cho rảnh! Khá giữ mình đừng thấy mặt ta nữa, vì ngày nào ngươi thấy mặt ta thì sẽ chết!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Môi-se bèn nói rằng: Bệ hạ nói phải lắm; tôi chẳng hề thấy mặt bệ hạ nữa đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Vả, Ðức Giê-hô-va có phán cùng Môi-se rằng: Ta sẽ giáng cho Pha-ra-ôn và xứ Ê-díp-tô một tai vạ nữa; đoạn, người sẽ tha các ngươi đi khỏi đây. Khi người định tha đi, thì sẽ đuổi các ngươi ra khỏi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Vậy, hãy nói cùng dân sự và dặn rằng mỗi người bất luận nam hay nữ phải xin kẻ lân cận mình những đồ bằng bạc và bằng vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Ðức Giê-hô-va làm cho dân sự được ơn trước mặt người Ê-díp-tô; Môi-se cũng là một người rất tôn trọng trong xứ Ê-díp-tô, trước mắt quần thần của Pha-ra-ôn và trước mắt dân ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Môi-se nói: Ðức Giê-hô-va có phán như vầy: Chừng giữa đêm ta sẽ ra tuần hành xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Hết thảy con trưởng nam trong xứ Ê-díp-tô sẽ chết, từ thái tử của Pha-ra-ôn ngồi trên ngai mình, cho đến con cả của người đòi ở sau cối, và luôn mọi con đầu lòng của súc vật nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Trong cả xứ Ê-díp-tô sẽ có tiếng kêu la inh ỏi, cho đến đỗi chưa hề có, và cũng sẽ chẳng bao giờ có giống như vậy nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Nhưng, trong cả dân Y-sơ-ra-ên dầu đến một con chó cũng sẽ chẳng sủa hoặc người, hoặc vật; hầu cho các ngươi biết rằng Ðức Giê-hô-va phân biệt dân Y-sơ-ra-ên cùng người Ê-díp-tô là dường nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Nầy, quần thần của bệ hạ sẽ xuống cùng tôi, sấp mình trước mặt tôi mà rằng: Ngươi và cả dân sự theo ngươi hãy đi đi! Ðoạn, tôi sẽ đi ra. Môi-se bèn lui ra khỏi Pha-ra-ôn lấy làm giận lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Vả, Ðức Giê-hô-va có phán cùng Môi-se rằng: Pha-ra-ôn chẳng khứng nghe ngươi đâu, hầu cho các dấu lạ ta thêm lên trong xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Môi-se và A-rôn bèn làm các dấu lạ trước mặt Pha-ra-ôn; nhưng Ðức Giê-hô-va làm cho Pha-ra-ôn cứng lòng, nên người chẳng tha dân Y-sơ-ra-ên đi khỏi xứ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Tại xứ Ê-díp-tô, Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Tháng nầy định làm tháng đầu cho các ngươi, tức là tháng giêng trong quanh năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Hãy nói cho toàn hội chúng Y-sơ-ra-ên rằng: Ðến ngày mồng mười tháng nầy, mỗi gia trưởng tùy theo nhà mình phải bắt một con chiên con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Nếu nhà ít người quá ăn không hết một chiên con, hãy chung cùng người rất lân cận mình, tùy theo số người; và hãy tính cho mỗi chiên con tùy sức người ăn hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Các ngươi hãy bắt hoặc trong bầy chiên, hoặc trong bầy dê, chiên con đực hay là dê con đực, tuổi giáp niên, chẳng tì vít chi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'đoạn để dành cho đến ngày mười bốn tháng nầy; rồi cả hội chúng Y-sơ-ra-ên sẽ giết nó, vào lối chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Họ sẽ lấy huyết đem bôi trên hai cây cột và mày cửa của nhà nào ăn thịt chiên con đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Ðêm ấy họ sẽ ăn thịt chiên quay với bánh không men và rau đắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Chớ ăn thịt nửa chín nửa sống hay là luộc trong nước, nhưng phải quay trên lửa cả và đầu, giò, với bộ lòng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Các ngươi chớ để chi còn lại đến sáng mai; nếu còn lại, hãy thiêu đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Vậy, ăn thịt đó, phải như vầy: Dây lưng cột, chân mang giày, tay cầm gậy, ăn hối hả; ấy là lễ Vượt-qua của Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Ðêm đó ta sẽ đi qua xứ Ê-díp-tô, hành hại mọi con đầu lòng xứ Ê-díp-tô, từ người ta cho đến súc vật; ta sẽ xét đoán các thần của xứ Ê-díp-tô; ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Huyết bôi trên nhà các ngươi ở, sẽ dùng làm dấu hiệu; khi ta hành hại xứ Ê-díp-tô, thấy huyết đó, thì sẽ vượt qua, chẳng có tai nạn hủy diệt các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Các ngươi hãy ghi ngày đó làm kỷ niệm; trải các đời hãy giữ làm một lễ cho Ðức Giê-hô-va, tức là một lễ lập ra đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Trong bảy ngày phải ăn bánh không men: vừa đến ngày thứ nhất, hãy dẹp men khỏi nhà đi; vì hễ ai ăn bánh có men từ ngày thứ nhất cho đến ngày thứ bảy, thì sẽ bị truất ra khỏi Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Ngày thứ nhất, sẽ có một sự nhóm hiệp thánh; qua ngày thứ bảy các ngươi cũng sẽ có một sự nhóm hiệp thánh nữa. Trong mấy ngày đó chẳng nên làm công việc chi, chỉ lo sắm đồ ăn cho mỗi người cần ăn mà thôi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Vậy, các ngươi hãy giữ lễ bánh không men, vì chánh ngày đó ta rút quân đội các ngươi ra khỏi xứ Ê-díp-tô; nên chi, trải các đời phải giữ ngày đó như một lễ lập ra đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Ngày mười bốn tháng giêng, chiều lại, các ngươi sẽ ăn bánh không men cho đến chiều ngày hai mươi mốt tháng đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Trong bảy ngày không nên còn thấy men tại nhà các ngươi; vì bất luận người ngoại bang hay là người bổn xứ, hễ ai ăn bánh có men sẽ bị truất khỏi hội chúng Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Chớ nên ăn bánh có men; khắp nơi các ngươi ở đều phải ăn bánh không men.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Vậy, Môi-se nhóm lại các trưởng lão Y-sơ-ra-ên mà nói rằng: Hãy đi bắt một con trong bầy cho mọi nhà các ngươi, và giết nó làm lễ Vượt-qua.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Rồi hãy lấy một chùm kinh giới nhúng vào huyết trong chậu, bôi lên mây và hai cây cột cửa, đoạn, trong các ngươi chớ ai ra khỏi cửa nhà mình cho đến sáng mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Ðức Giê-hô-va sẽ đi qua đặng hành hại xứ Ê-díp-tô; khi thấy huyết nơi mày và hai cây cột cửa, Ngài sẽ vượt qua, không cho kẻ tiêu diệt vào nhà các ngươi đặng hành hại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Hãy giữ lễ nầy như một lệ lập ra đời đời cho các ngươi và con cháu các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Khi nào các ngươi vào xứ mà Ðức Giê-hô-va sẽ ban cho, như lời Ngài đã phán, thì hãy giữ lễ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Khi con cháu các ngươi hỏi rằng: Lễ nầy là nghĩa chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Hãy đáp rằng: Ấy là của tế lễ Vượt-qua của Ðức Giê-hô-va, vì khi Ngài hành hại xứ Ê-díp-tô thì Ngài đi vượt qua các nhà dân Y-sơ-ra-ên, và cứu nhà chúng ta đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Dân Y-sơ-ra-ên bèn cúi đầu lạy, rồi đi, làm theo như lời Ðức Giê-hô-va đã phán dặn Môi-se và A-rôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Vả, khi giữa đêm, Ðức Giê-hô-va hành hại mọi con đầu lòng tại xứ Ê-díp-tô, từ thái tử của Pha-ra-ôn ngồi trên ngai mình, cho đến con cả người bị tù, và hết thảy con đầu lòng của súc vật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Ðang lúc ban đêm, Pha-ra-ôn, quần thần cùng hết thảy người Ê-díp-tô đều chờ dậy; có tiếng kêu la inh ỏi trong xứ Ê-díp-tô, vì chẳng một nhà nào là không có người chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Trong đêm đó, Pha-ra-ôn bèn đòi Môi-se và A-rôn mà phán rằng: Hai ngươi và dân Y-sơ-ra-ên hãy chờ dậy, ra khỏi giữa vòng dân ta mà đi hầu việc Ðức Giê-hô-va, như các ngươi đã nói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Cũng hãy dẫn bò và chiên đi, như lời các ngươi đã nói, và cầu phước cho ta nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Người Ê-díp-tô thúc giục dân Y-sơ-ra-ên ra khỏi xứ mau mau, vì nói rằng: Chúng ta đều chết hết!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Vậy, dân sự đều đem bột nhồi rồi chưa men đi, và bọc những thùng nhồi bột trong áo tơi vác lên vai mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Vả, dân Y-sơ-ra-ên có làm y theo lời Môi-se đã dặn, xin người Ê-díp-tô những đồ bằng bạc và bằng vàng cùng áo xống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Ðức Giê-hô-va làm cho dân sự được ơn trước mắt người Ê-díp-tô, nên họ bằng lòng cho; và dân Y-sơ-ra-ên lột trần người Ê-díp-tô vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Dân Y-sơ-ra-ên đi từ Ram-se đến Su-cốt, số không kể con nít, được chừng sáu mươi vạn người đàn ông đi bộ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Lại có vô số người ngoại bang đi lên chung luôn với chiên, bò, súc vật rất nhiều.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Chúng bèn hấp bánh không men bằng bột của mình đã đem theo từ xứ Ê-díp-tô; bột không men, vì cớ bị đuổi khỏi xứ Ê-díp-tô không thế chậm trễ, và cũng chẳng sắm kịp lương thực chi được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Vả, thì kiều ngụ của dân Y-sơ-ra-ên tại xứ Ê-díp-tô được bốn trăm ba mươi năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Khi mãn bốn trăm ba mươi năm rồi, thì, cũng trong ngày đó, các quân đội của Ðức Giê-hô-va ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Ấy là một đêm người ta phải giữ cho Ðức Giê-hô-va, vì Ngài rút dân Y-sơ-ra-ên khỏi xứ Ê-díp-tô. Trải các đời, cả dân Y-sơ-ra-ên phải giữ đêm đó, để tôn trọng Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Ðức Giê-hô-va phán cùng Môi-se và A-rôn rằng: Ðây là luật lệ về lễ Vượt-qua: Phàm người ngoại bang chẳng được ăn lễ đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Còn về phần kẻ tôi mọi, là người bỏ tiền ra mua, ngươi hãy làm phép cắt bì cho, thì họ mới được ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Khách ngoại bang và kẻ làm thuê cũng chẳng được phép ăn lễ đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Lễ đó chỉ ăn nội trong nhà; ngươi đừng đem thịt ra ngoài, và cũng đừng làm gãy một cái xương nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Hết thảy hội chúng Y-sơ-ra-ên phải giữ lễ Vượt-qua.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Khi một khách ngoại bang nào kiều ngụ nhà ngươi, muốn giữ lễ Vượt-qua của Ðức Giê-hô-va, thì mọi người nam của họ phải chịu phép cắt bì; đoạn, họ mới được đến gần giữ lễ nầy, và được coi như người sanh trong xứ. Nhưng ai không chịu phép cắt bì, thì chẳng được ăn đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Cũng đồng một luật cho người sanh trong xứ cùng khách ngoại bang nào đến kiều ngụ giữa các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Toàn dân Y-sơ-ra-ên đều làm như lời Ðức Giê-hô-va đã phán dặn Môi-se và A-rôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Cũng trong ngày đó, Ðức Giê-hô-va rút dân Y-sơ-ra-ên, tùy theo quân đội, ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Trong vòng dân Y-sơ-ra-ên bất luận người hay vật, hãy vì ta biệt riêng ra thánh mọi con đầu lòng; bởi con đầu lòng thuộc về ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Môi-se nói cùng dân sự rằng: Hãy kỷ niệm ngày nầy, vì là ngày Ðức Giê-hô-va dùng tay quyền năng rút các ngươi ra khỏi xứ Ê-díp-tô, tức là khỏi nhà nô lệ; nên chớ ai ăn bánh có men.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Ngày nay, nhằm tháng lúa trỗ, các ngươi ra đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Vậy khi nào Ðức Giê-hô-va đưa ngươi vào bờ cõi xứ dân Ca-na-an, dân Hê-tít, dân A-mô-rít, dân Hê-vít, và dân Giê-bu-sít rồi, là một xứ đượm sữa và mật, và là xứ Ngài đã thề cùng tổ phụ sẽ ban cho ngươi, thì đến trong tháng nầy hãy giữ lễ thánh đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Trong bảy ngày hãy ăn bánh không men; đến ngày thứ bảy sẽ có lễ kính Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Phải ăn bánh không men trong bảy ngày; khắp cả địa hạt ngươi sẽ không thấy bánh có men, hoặc men tại nơi ngươi nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Trong ngày đó hãy giải nghĩa cho con trai ngươi rằng: Ấy vì việc Ðức Giê-hô-va làm cho ta, khi ta ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Ðiều đó sẽ làm một dấu hiệu nơi tay ngươi, làm một kỷ niệm ghi nơi trán ở giữa cặp mắt ngươi, hầu cho luật pháp của Ðức Giê-hô-va ở nơi miệng ngươi, vì Ðức Giê-hô-va đã dùng tay quyền năng rút ngươi ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Hằng năm, đến kỳ, ngươi phải giữ lễ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Khi Ðức Giê-hô-va đã đưa ngươi vào bờ cõi xứ Ca-na-an, như Ngài đã thề cùng ngươi, và tổ phụ ngươi, khi Ngài đã ban xứ đó cho rồi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'thì hãy đem dâng cho Ðức Giê-hô-va những con trưởng nam cùng cả con đầu lòng đực của súc vật ngươi, vì chúng nó đều sẽ thuộc về ÐṀ©c Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Nhưng mỗi con lừa đầu lòng, ngươi phải bắt chiên con hay là dê con mà chuộc; bằng không, ngươi hãy vặn cổ nó. Ngươi cũng chuộc mọi trưởng nam trong vòng con trai ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Vả, một mai con trai ngươi hỏi rằng: Ðiều đó có ý nghĩa chi? thì hãy đáp rằng: Ấy vì cớ Ðức Giê-hô-va đã dùng tay quyền năng rút chúng ta ra khỏi xứ Ê-díp-tô, tức là nhà nô lệ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'và khi Pha-ra-ôn cứng lòng không tha chúng ta đi, Ngài bèn giết hết các con đầu lòng trong xứ đó, từ con trưởng nam người ta cho đến con đầu lòng súc vật. Vì cớ đó, ta dâng tế lễ cho Ðức Giê-hô-va mọi con đực sanh đầu lòng, và ta chuộc con trưởng nam trong vòng con trai ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Ấy sẽ làm một dấu hiệu nơi tay ngươi, và ấn chí nơi trán giữa cặp mắt ngươi, để nhắc cho nhớ rằng Ðức Giê-hô-va đã dùng tay quyền năng rút chúng ta ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Vả, khi Pha-ra-ôn tha dân Y-sơ-ra-ên đi, Ðức Chúa Trời không dẫn dân ấy đi theo đường về xứ Phi-li-tin, là đường gần hơn hết, vì Ngài nói rằng: E khi dân thấy trận mạc, dời lòng trở về xứ Ê-díp-tô chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Cho nên Ðức Chúa Trời dẫn chúng đi vòng theo đường trong đồng vắng, về hướng Biển-dỏ. Dân Y-sơ-ra-ên cầm khí giới ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Môi-se dời hài cốt Giô-sép theo mình, vì Giô-sép có bắt dân Y-sơ-ra-ên thề quyết rằng: Chắc Ðức Chúa Trời sẽ viếng các ngươi; hãy dời hài cốt ta theo các ngươi khỏi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Vả, chúng đi khỏi Su-cốt, đóng trại tại Ê-tam, ở cuối đầu đồng vắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Ðức Giê-hô-va đi trước dân sự, ban ngày ở trong một trụ mây, để dẫn đường đi; ban đêm trong một trụ lửa, để soi sáng cho chúng, hầu cho được đi luôn ngày và đêm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Ban ngày trụ mây chẳng bao giờ cách xa dân sự, trụ lửa ban đêm cũng vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Hãy truyền cho dân Y-sơ-ra-ên trở lại đóng trại tại trước Phi-Ha-hi-rốt, ngang Ba-anh-Sê-phôn, giữa khoảng Mít-đôn và biển. Các ngươi hãy đóng trại đối diện nơi nầy, gần biển.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Chắc Pha-ra-ôn sẽ nói về dân Y-sơ-ra-ên rằng: Dân đó lạc đường bị khốn trong đồng vắng rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Ta sẽ làm cho Pha-ra-ôn cứng lòng, người sẽ đuổi theo dân đó; nhưng ta sẽ vì Pha-ra-ôn và cả toán binh người được rạng danh; người Ê-díp-tô sẽ biết ta là Ðức Giê-hô-va. Dân Y-sơ-ra-ên bèn làm như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Vả, họ báo cùng vua Ê-díp-tô rằng dân Hê-bơ-rơ đã trốn đi rồi. Lòng Pha-ra-ôn và quần thần đối cùng dân đó bèn thay đổi, nói rằng: Chúng ta đã làm chi vậy, tha dân Y-sơ-ra-ên đi để khỏi phục dịch ta nữa sao?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Pha-ra-ôn bèn thắng xe và đem dân mình theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Người đem sáu trăm xe thượng hạng và hết thảy xe trong xứ Ê-díp-tô, trên mỗi xe đều có chiến binh cả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Ðức Giê-hô-va làm cho Pha-ra-ôn, vua xứ Ê-díp-tô, cứng lòng, đuổi theo dân Y-sơ-ra-ên; nhưng dân nầy đã ra đi một cách dạn dĩ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Người Ê-díp-tô và cả ngựa xe, lính kỵ, cùng toán binh của Pha-ra-ôn đều đuổi theo dân Y-sơ-ra-ên, gặp đang đóng đồn nơi bờ biển, gần Phi-ha-hi-rốt, ngang Ba-anh-Sê-phôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Vả, khi Pha-ra-ôn đến gần, dân Y-sơ-ra-ên ngước mắt lên, thấy dân Ê-díp-tô đuổi theo, bèn lấy làm hãi hùng, kêu van Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Chúng lại nói cùng Môi-se rằng: Xứ Ê-díp-tô há chẳng có nơi mộ phần, nên nỗi người mới dẫn chúng tôi vào đồng vắng đặng chết sao? Người đưa chúng tôi ra xứ Ê-díp-tô để làm chi?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Chúng tôi há chẳng có nói cùng người tại xứ Ê-díp-tô rằng: Ðể mặc chúng tôi phục dịch dân Ê-díp-tô, vì thà rằng phục dịch họ còn hơn phải chết nơi đồng vắng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Môi-se đáp cùng dân sự rằng: Chớ sợ chi, hãy ở đó, rồi ngày nay xem sự giải cứu Ðức Giê-hô-va sẽ làm cho các ngươi; vì người Ê-díp-tô mà các ngươi ngó thấy ngày nay, thì chẳng bao giờ ngó thấy nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Ðức Giê-hô-va sẽ chiến cự cho, còn các ngươi cứ yên lặng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Sao ngươi kêu van ta? Hãy bảo dân Y-sơ-ra-ên cứ đi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'còn ngươi hãy giơ gậy lên, đưa tay trên mặt biển, phân rẽ nước ra, thì dân Y-sơ-ra-ên sẽ xuống biển đi như trên đất cạn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Còn ta sẽ làm cho dân Ê-díp-tô cứng lòng theo dân Y-sơ-ra-ên xuống biển, rồi ta sẽ được rạng danh vì Pha-ra-ôn, cả đạo binh, binh xa, và lính kỵ người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Khi nào ta được rạng danh vì Pha-ra-ôn, binh xa, cùng lính kỵ người, thì người Ê-díp-tô sẽ rõ ràng ta là Ðức Giê-hô-va vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Thiên sứ của Ðức Chúa Trời đã đi trước trại quân của dân Y-sơ-ra-ên lộn lại đi sau; còn trụ mây vốn đi trước trại quân, lại ở về sau;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'trụ mây đứng về giữa khoảng trại người Ê-díp-tô và trại dân Y-sơ-ra-ên, làm áng mây tối tăm cho đàng nầy, soi sáng ban đêm cho đàng kia; nên trọn cả đêm hai trại chẳng hề xáp gần nhau được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Vả, Môi-se giơ tay ra trên biển, Ðức Giê-hô-va dẫn trận gió đông thổi mạnh đến đùa biển lại trọn cả đêm; Ngài làm cho biển bày ra khô, nước phân rẽ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Dân Y-sơ-ra-ên xuống biển, đi như trên đất cạn; còn nước làm thành một tấm vách ngăn bên hữu và bên tả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Người Ê-díp-tô bèn đuổi theo; hết thảy ngựa, binh xa cùng lính kỵ của Pha-ra-ôn đều theo xuống giữa biển.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Vả, đến canh sáng, Ðức Giê-hô-va ở trong lòng trụ mây và lửa, nhìn ra thấy trại quân Ê-díp-tô, bèn làm cho họ phải rối loạn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Ngài tháo bánh xe của họ, khiến dẫn dắt cực nhọc. Người Ê-díp-tô bèn nói nhau rằng: Ta hãy trốn khỏi dân Y-sơ-ra-ên đi, vì Ðức Giê-hô-va thế dân đó mà chiến cự cùng chúng ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy giơ tay ngươi ra trên biển, nước sẽ trở lấp người Ê-díp-tô, binh xa và lính kỵ của chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Môi-se bèn giơ tay mình ra trên biển, lối sáng mai, nước trở lấp phủ đáy biển lại, người Ê-díp-tô chạy trốn bị nước chận; vậy Ðức Giê-hô-va xô họ xuống giữa biển.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Thế thì, nước trở lại bao phủ binh xa, lính kỵ của cả đạo binh Pha-ra-ôn đã theo dân Y-sơ-ra-ên xuống biển, chẳng còn sót lại một ai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Song dân Y-sơ-ra-ên đi giữa biển như trên đất cạn; nước làm thành vách ngăn bên hữu và bên tả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Trong ngày đó, Ðức Giê-hô-va giải cứu dân Y-sơ-ra-ên thoát khỏi tay người Ê-díp-tô; dân ấy thấy người Ê-díp-tô chết trên bãi biển.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Dân Y-sơ-ra-ên thấy việc lớn lao mà Ðức Giê-hô-va đã làm cho người Ê-díp-tô, nên kính sợ Ngài, tin Ngài và Môi-se, là tôi tớ Ngài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Ðoạn, Môi-se và dân Y-sơ-ra-ên hát bài ca nầy cho Ðức Giê-hô-va, rằng: Tôi ca tụng Ðức Giê-hô-va, vì Ngài rất vinh hiển oai nghiêm. Ngài đã liệng xuống biển ngựa và người cỡi ngựa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Ðức Giê-hô-va là sức mạnh và sự ca tụng của tôi: Ngài đã trở nên Ðấng cứu tôi. Ngài là Ðức Chúa Trời tôi, tôi ngợi khen Ngài; Ðức Chúa Trời của tổ phụ tôi, tôi tôn kính Ngài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Ðức Giê-hô-va là một chiến sĩ; Danh Ngài là Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Ngài đã ném xuống biển binh xa Pha-ra-ôn và cả đạo binh của người; Quan tướng kén chọn của người đã bị đắm nơi Biển đỏ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Những lượn sóng đã vùi lấp họ rồi; Họ chìm đến đáy biển như một hòn đá vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Hỡi Ðức Giê-hô-va! Tay hữu Ngài có sức mạnh vinh hiển thay. Hỡi Ðức Giê-hô-va! Tay hữu Ngài hủy quân nghịch tan đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Bởi sự cả thể của oai nghiêm Ngài, Ðánh đổ kẻ dấy nghịch cùng mình. Ngài nổi giận phừng phừng, Ðốt họ cháy như rơm ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Lỗ mũi Ngài thở hơi ra, nước bèn dồn lại, Lượn sóng đổ dựng như một bờ đê; Vực sâu đọng lại nơi rún biển.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Quân nghịch rằng: Ta đuổi theo, ta sẽ đuổi kịp Ta sẽ chia phân của giặc; Tâm hồn ta sẽ thỏa nguyện nơi họ; Ta rút gươm ra, tay ta hủy diệt họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Ngài đã thở hơi ra Biển vùi lấp quân nghịch lại; Họ bị chìm như cục chì Nơi đáy nước sâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Hỡi Ðức Giê-hô-va! trong vòng các thần, ai giống như Ngài? Trong sự thánh khiết, ai được vinh hiển như Ngài. Ðáng sợ, đáng khen Hay làm các phép lạ?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Ngài đã đưa tay hữu ra, Ðất đã nuốt chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Ngài lấy lòng thương xót dìu dắt Dân nầy mà Ngài đã chuộc lại; Ngài đã dùng năng lực đưa nó Về nơi ở thánh của Ngài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Các dân tộc nghe biết việc nầy đều run sợ, Cơn kinh hãi áp-hãm dân xứ Pha-lê-tin.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Các quan trưởng xứ Ê-đôm bèn lấy làm bối rối; Mấy mặt anh hùng nơi Mô-áp đều kinh hồn; Cả dân Ca-na-an đều mất vía');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Sự hoảng hốt kinh hãi giáng cho chúng nó; Hỡi Ðức Giê-hô-va! vì quyền cao nơi cánh tay Ngài, Chúng nó đều bị câm như đá, Cho đến chừng nào dân Ngài vượt qua; Cho đến khi dân mà Ngài đã chuộc, vượt qua rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Hỡi Ðức Giê-hô-va! Ngài đưa dân ấy vào, và lập nơi núi cơ nghiệp Ngài, Tức là chốn Ngài đã sắm sẵn, để làm nơi ở của Ngài, Hỡi Chúa! là đền thánh mà tay Ngài đã lập.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Ðức Giê-hô-va sẽ cai trị đời đời kiếp kiếp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Vì ngựa của Pha-ra-ôn, binh xa, cùng lính kỵ người đã xuống biển; Và Ðức Giê-hô-va đã vùi dập nước biển lên trên, Nhưng dân Y-sơ-ra-ên đi giữa biển như đi trên đất cạn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Nữ tiên tri Mi-ri-am, là em gái A-rôn, tay cầm trống cơm, các đàn bà đều đi ra theo người, cầm trống cơm và múa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Mi-ri-am đáp lại rằng: Hãy ca tụng Ðức Giê-hô-va, vì Ngài rất vinh hiển oai nghiêm; Ngài đã liệng xuống biển ngựa và người cỡi ngựa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Ðoạn, Môi-se đem dân Y-sơ-ra-ên đi khỏi Biển đỏ, đến nơi đồng vắng Su-rơ; trọn ba ngày đi trong đồng vắng, kiếm chẳng được nước đâu cả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Kế đến đất Ma-ra, nhưng vì nước tại đó đắng, uống chẳng được, nên chi chỗ nầy gọi là Ma-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Dân sự bèn oán trách Môi-se rằng: Chúng tôi lấy chi uống?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Môi-se kêu van Ðức Giê-hô-va; Ngài bèn chỉ cho người một cây gỗ, người lấy liệng xuống nước, nước bèn hóa ra ngọt. Ấy tại đó, Ðức Giê-hô-va định luật lệ cùng lập pháp độ cho dân sự, và tại đó Ngài thử họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Ngài phán rằng: Nếu ngươi chăm chỉ nghe lời Giê-hô-va Ðức Chúa Trời ngươi, làm sự ngay thẳng trước mặt Ngài, lắng tai nghe các điều răn và giữ mọi luật lệ Ngài, thì ta chẳng giáng cho ngươi một trong các bịnh nào mà ta đã giáng cho xứ Ê-díp-tô; vì ta là Ðức Giê-hô-va, Ðấng chữa bịnh cho ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Ðoạn, dân sự đến đất Ê-lim; nơi đó có mười hai suối nước, và bảy mươi cây chà là; dân sự đóng trại tại đó, gần bên suối nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Nhằm ngày mười lăm tháng hai, sau khi ra khỏi xứ Ê-díp-tô, cả hội chúng Y-sơ-ra-ên ở nơi Ê-lim đi đến đồng vắng Sin, nằm về giữa khoảng Ê-lim và Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Cả hội chúng Y-sơ-ra-ên oán trách Môi-se và A-rôn tại nơi đồng vắng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'nói cùng hai người rằng: Ôi! thà rằng chúng tôi chịu chết về tay Ðức Giê-hô-va tại xứ Ê-díp-tô, khi còn ngồi kề nồi thịt và ăn bánh chán hê! Vì hai người dẫn dắt chúng tôi vào nơi đồng vắng nầy đều bị chết đói.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Nầy, ta sẽ từ trên trời cao làm mưa bánh xuống cho các ngươi. Dân sự sẽ đi ra, mỗi ngày nào thâu bánh đủ cho ngày nấy, đặng ta thử dân coi có đi theo luật lệ của ta hay chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Qua ngày thứ sáu, dân sự sẽ dự bị phần đã góp, và sẽ được phần gấp bằng hai của mình thường thâu hằng ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Môi-se và A-rôn bèn nói cùng dân Y-sơ-ra-ên rằng: Chiều nay các ngươi sẽ nhận biết rằng ấy là Ðức Giê-hô-va đã rút các ngươi ra khỏi xứ Ê-díp-tô,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'và sáng mai sẽ thấy sự vinh quang của Ðức Giê-hô-va, vì Ngài đã nghe lời các ngươi oán trách Ngài rồi. Vả lại, chúng ta là ai mà các ngươi oán trách chúng ta?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Môi-se nói: Chiều nầy Ðức Giê-hô-va sẽ phát thịt cho các ngươi ăn, rồi sáng mai bánh nhiều dư dật, vì Ngài đã nghe lời các ngươi oán trách Ngài rồi. Thế thì, chúng ta là ai? Những lời oán trách chẳng phải đổ về chúng ta đâu, nhưng về Ðức Giê-hô-va vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Môi-se nói cùng A-rôn rằng: Hãy nói cho cả hội chúng Y-sơ-ra-ên rằng: Các ngươi hãy đến trước mặt Ðức Giê-hô-va, vì Ngài đã nghe lời oán trách của các ngươi rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Vả, khi A-rôn nói cùng cả hội chúng Y-sơ-ra-ên, thì họ xây mặt về phía đồng vắng, thấy sự vinh quang của Ngài hiện ra trong đám mây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ta đã nghe lời oán trách của dân Y-sơ-ra-ên. Vậy, ngươi hãy nói cùng chúng nó rằng: Lối chiều các ngươi sẽ ăn thịt; sáng mai sẽ ăn bánh no nê, và sẽ biết ta là Giê-hô-va Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Vậy, chiều lại, có chim cút bay lên phủ trên trại quân; đến sáng mai lại có một lớp sương ở chung quanh trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Lớp sương đó tan đi, trên mặt đồng vắng thấy có vật chi nhỏ, tròn, như hột sương đóng trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Khi dân Y-sơ-ra-ên thấy, bèn hỏi nhau rằng: Cái chi vậy? Vì chẳng biết vật đó là gì. Môi-se bèn nói cùng dân sự rằng: Ấy là bánh mà Ðức Giê-hô-va ban cho các ngươi làm lương thực đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Nầy là lời Ðức Giê-hô-va đã phán dặn: Hãy tùy sức ăn của mỗi người, và tùy số người trong trại mà góp cho mỗi tên một ô-me.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Dân Y-sơ-ra-ên bèn làm như vậy, kẻ thì lượm nhiều, người thì lượm ít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'cứ lường từ mô-me; ai lượm nhiều chẳng được trội, ai lượm ít cũng chẳng thiếu; mỗi người lượm vừa đủ sức mình ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Môi-se nói cùng dân sự rằng: Ðừng ai để dư lại cho đến sáng mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Nhưng dân sự chẳng nghe theo lời Môi-se, một vài người để dư lại đến sáng mai; thì sâu hóa ở trong, vật sanh mùi hôi hám. Môi-se bèn nổi giận cùng họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Vậy, hằng buổi sớm mai mỗi người lượm vừa đủ sức mình ăn; khi mặt trời nắng nóng thì vật đó tan ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Ðến ngày thứ sáu, dân sự lượm lương thực gấp hai; mỗi người hai ô-me. Các hội trưởng đến thuật lại cho Môi-se rõ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Người đáp rằng: Ấy là lời Ðức Giê-hô-va đã phán rằng: Mai là ngày nghỉ, tức ngày Sa-bát thánh cho Ðức Giê-hô-va, hãy nướng món chi các ngươi muốn nướng, hãy nấu món chi các ngươi muốn nấu; hễ còn dư, hãy để dành đến sáng mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Dân sự bèn để dành cho đến sáng mai, y như lời Môi-se đã truyền; vật đó chẳng sanh mùi hôi hám và cũng chẳng hóa sâu chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Môi-se bèn nói rằng: Bữa nay hãy ăn đồ đó đi, vì là ngày Sa-bát của Ðức Giê-hô-va; hôm nay các ngươi chẳng tìm thấy vật đó ở trong đồng đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Các ngươi lượm trong sáu ngày, nhưng qua ngày thứ bảy là ngày Sa-bát, sẽ chẳng có đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Ngày thứ bảy, một vài người trong vòng dân sự ra đặng lượm lấy, nhưng tìm chẳng thấy chi hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Các ngươi chẳng chịu vâng giữ điều răn và luật pháp ta cho đến chừng nào?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Hãy suy nghĩ rằng Ðức Giê-hô-va đã cho các ngươi ngày Sa-bát; vậy nên, đến ngày thứ sáu Ngài lại cho các ngươi lương thực đủ hai ngày. Trong ngày thứ bảy, mỗi người phải ở yên chỗ mình, chớ ai ra khỏi nhà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Thế thì, ngày thứ bảy dân sự đều nghỉ ngơi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Nhà Y-sơ-ra-ên đặt tên lương thực nầy là ma-na; nó giống như hột ngò, sắc trắng, mùi như bánh ngọt pha mật ong.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Môi-se nói rằng: Lời Ðức Giê-hô-va đã phán dặn như vầy: Hãy đổ đầy một ô-me ma-na, đặng lưu truyền trải các đời, hầu cho thiên hạ thấy thứ bánh ta đã cho các ngươi ăn nơi đồng vắng, khi ta rút các ngươi ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Môi-se lại nói cùng A-rôn rằng: Hãy lấy một cái bình đựng đầy một ô-me ma-na, để trước mặt Ðức Giê-hô-va, đặng lưu truyền các đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'A-rôn bèn để bình đó trước sự chứng cớ, hầu cho được lưu truyền y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Dân Y-sơ-ra-ên ăn ma-na trải bốn mươi năm, cho đến khi vào bờ cõi xứ Ca-na-an, là xứ có người ta ở.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Vả, ô-me là một phần mười của ê-pha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Cả hội chúng Y-sơ-ra-ên đi từ đồng vắng Sin, đi từng trạm, tùy theo lịnh Ðức Giê-hô-va, đóng trại tại Rê-phi-đim; ở đó chẳng có nước cho dân sự uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Dân sự bèn kiếm cớ cãi lộn cùng Môi-se mà rằng: Hãy cho chúng tôi nước uống. Môi-se đáp rằng: Sao các ngươi kiếm cớ cãi lộn cùng ta? Sao ướm thử Ðức Giê-hô-va vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Dân sự ở đó không có nước, bị khát, nên oán trách Môi-se mà rằng: Sao người khiến chúng tôi ra xứ Ê-díp-tô, hầu cho chúng tôi, con và các bầy súc vật phải chịu chết khát thế nầy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Môi-se bèn kêu cầu Ðức Giê-hô-va mà rằng: Tôi phải xử thế nào cùng dân nầy? Thiếu điều họ ném đá tôi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Ðức Giê-hô-va đáp cùng Môi-se rằng: Hãy cầm gậy của ngươi đã đập dưới sông, dẫn theo những trưởng lão Y-sơ-ra-ên, rồi đi trước mặt dân sự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Nầy ta sẽ đứng đằng trước ngươi, ở trên hòn đá tại Hô-rếp kia, ngươi hãy đập hòn đá, thì nước từ đó chảy ra, dân sự sẽ uống lấy. Môi-se bèn làm như vậy trước mặt các trưởng lão Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Người đặt tên nơi nầy là Ma-sa và Mê-ri-ba, vì cớ việc cãi lộn mà dân Y-sơ-ra-ên kiếm cớ gây cùng người, và vì họ đã ướm thử Ðức Giê-hô-va mà nói rằng: Có Ðức Giê-hô-va ở giữa chúng ta hay chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Vả, khi đó, dân A-ma-léc đến khêu chiến cùng Y-sơ-ra-ên tại Rê-phi-đim.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Môi-se bèn nói cùng Giô-suê rằng: Hãy chọn lấy tráng sĩ cho chúng ta, ra chiến đấu cùng dân A-ma-léc; ngày mai ta sẽ đứng nơi đầu nổng, cầm gậy của Ðức Chúa Trời trong tay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Giô-suê bèn làm y như lời Môi-se nói, để cự chiến dân A-ma-léc; còn Môi-se, A-rôn và Hu-rơ lên trên đầu nổng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Vả, hễ đang khi Môi-se giơ tay lên, thì dân Y-sơ-ra-ên thắng hơn; nhưng khi người xụi tay xuống, dân A-ma-léc lại thắng hơn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Tay Môi-se mỏi, A-rôn và Hu-rơ bèn lấy đá kê cho người ngồi, rồi ở hai bên đỡ tay người lên; tay người chẳng lay động cho đến khi mặt trời lặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Giô-suê lấy lưỡi gươm đánh bại A-ma-léc và dân sự người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy chép điều nầy trong sách làm kỷ niệm, và hãy nói cho Giô-suê biết rằng ta sẽ bôi sạch kỷ niệm về A-ma-léc trong thiên hạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Môi-se lập lên một bàn thờ, đặt tên là \"Giê-hô-va cờ xí của tôi\";');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'và nói rằng: Bởi vì A-ma-léc có giơ tay lên nghịch cùng ngôi Ðức Giê-hô-va, nên Ðức Giê-hô-va chinh chiến với A-ma-léc từ đời nầy qua đời kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Giê-trô, thầy tế lễ xứ Ma-đi-an, ông gia của Môi-se, hay được mọi điều Ðức Chúa Trời đã làm cho Môi-se cùng Y-sơ-ra-ên, là dân sự Ngài, và nghe Ngài đã dẫn dân ấy ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Người bèn dẫn Sê-phô-ra, vợ Môi-se, đã cho trở về nhà cha,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'cùng hai con trai, một tên là Ghẹt-sôn, vì Môi-se đã nói rằng: Tôi kiều ngụ nơi ngoại bang;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'và một tên là Ê-li-ê-se, vì người lại có nói: Ðức Chúa Trời của tổ phụ tôi đã vùa giúp và giải cứu tôi khỏi gươm Pha-ra-ôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Vậy, Giê-trô, ông gia của Môi-se, đến với hai con trai và vợ Môi-se, thăm người nơi đồng vắng, chỗ đóng trại gần bên núi Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Người bèn sai báo cùng Môi-se rằng: Ta là Giê-trô, ông gia của ngươi, ta cùng vợ ngươi và hai con trai nàng đến thăm ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Môi-se ra đón rước ông gia mình, mọp xuống và hôn người, hỏi thăm nhau, rồi vào trại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Môi-se liền thuật cho ông gia mình biết mọi điều Ðức Giê-hô-va vì Y-sơ-ra-ên đã làm cho Pha-ra-ôn và người Ê-díp-tô, mọi điều khổ nhọc xảy đến cho mình dọc đường và Ðức Giê-hô-va đã giải thoát dân Y-sơ-ra-ên thế nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Giê-trô lấy làm vui mừng về các ơn mà Ðức Giê-hô-va đã làm cho Y-sơ-ra-ên, giải cứu dân ấy khỏi tay người Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Giê-trô nói rằng: Ðáng ngợi khen Ðức Giê-hô-va thay! là Ðấng đã giải cứu các ngươi ra khỏi tay người Ê-díp-tô và tay Pha-ra-ôn, và giải cứu dân sự ra khỏi quyền của người Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Bây giờ ta biết rằng Ðức Giê-hô-va là lớn hơn hết các thần, vì khi người Ê-díp-tô cậy lòng kiêu ngạo dấy lên, thì Ngài thắng được chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Giê-trô, ông gia của Môi-se, bèn bày một của lễ thiêu và các lễ vật mà dâng cho Ðức Chúa Trời; rồi A-rôn và các trưởng lão Y-sơ-ra-ên đến ăn bánh cùng ông gia của Môi-se, trước mặt Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Qua ngày sau, Môi-se ra ngồi xét đoán dân sự; dân sự đứng chực trước mặt người từ sớm mai đến chiều.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Ông gia thấy mọi điều người làm cho dân sự, bèn hỏi rằng: Con làm chi cùng dân sự đó? Sao con chỉ ngồi một mình, còn cả dân sự đứng chực trước mặt từ sớm mai cho đến chiều như vậy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Môi-se bèn thưa rằng: Ấy vì dân sự đến cùng tôi đặng hỏi ý Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Khi nào họ có việc chi, thì đến cùng tôi, tôi xét đoán người nầy cùng người kia, và cho họ biết những mạng lịnh và luật pháp của Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Nhưng ông gia lại nói rằng: Ðiều con làm đó chẳng tiện.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Quả thật, con cùng dân sự ở với con sẽ bị đuối chẳng sai, vì việc đó nặng nề quá sức con, một mình gánh chẳng nổi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Bây giờ, hãy nghe cha khuyên con một lời, cầu xin Ðức Giê-hô-va phù hộ cho. Về phần con, hãy làm kẻ thay mặt cho dân sự trước mặt Ðức Chúa Trời, và đem trình mọi việc cho Ngài hay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Hãy lấy mạng lịnh và luật pháp Ngài mà dạy họ, chỉ cho biết con đường nào phải đi, và điều chi phải làm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Nhưng hãy chọn lấy trong vòng dân sự mấy người tài năng, kính sợ Ðức Chúa Trời, chân thật, ghét sự tham lợi, mà lập lên trên dân sự, làm trưởng cai trị hoặc ngàn người, hoặc trăm người, hoặc năm mươi người, hoặc mười người,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'đặng xét đoán dân sự hằng ngày. Nếu có việc can hệ lớn, họ hãy giải lên cho con; còn những việc nhỏ mọn, chính họ hãy xét đoán lấy. Hãy san bớt gánh cho nhẹ; đặng họ chia gánh cùng con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Nếu con làm việc nầy, và Ðức Chúa Trời ban lịnh cho con, con chắc sẽ chịu nổi được, và cả dân sự nấy sẽ đến chỗ mình bình yên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Môi-se vâng lời ông gia mình, làm y như lọi điều người đã dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Vậy, Môi-se bèn chọn trong cả Y-sơ-ra-ên những người tài năng, lập lên trên dân sự, làm trưởng cai trị, hoặc ngàn người, hoặc trăm người, hoặc năm mươi người, hoặc mười người;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'họ xét đoán dân sự hằng ngày. Các việc khó họ giãi lên cho Môi-se; nhưng chính họ xét lấy các việc nhỏ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Ðoạn, Môi-se để cho ông gia mình trở về xứ người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Tháng thứ ba, sau khi ra khỏi xứ Ê-díp-tô, trong ngày đó dân Y-sơ-ra-ên đến nơi đồng vắng Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Từ Rê-phi-đim ra đi, đến nơi đồng vắng Si-na -i, đóng trại tại đó, đối diện cùng núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Môi-se bèn lên đến Ðức Chúa Trời, Ðức Giê-hô-va ở trên núi gọi người mà phán rằng: Ngươi hãy nói như vầy cho nhà Gia-cốp, và tỏ điều nầy cho dân Y-sơ-ra-ên:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Các ngươi đã thấy điều ta làm cho người Ê-díp-tô, ta chở các ngươi trên cánh chim ưng làm sao, và dẫn các ngươi đến cùng ta thể nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Vậy, bây giờ, nếu các ngươi vâng lời ta và giữ sự giao ước ta, thì trong muôn dân, các ngươi sẽ thuộc riêng về ta, vì cả thế gian đều thuộc về ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Các ngươi sẽ thành một nước thầy tế lễ, cùng một dân tộc thánh cho ta. Bấy nhiêu lời đó ngươi sẽ nói lại cùng dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Môi-se đến đòi các trưởng lão trong dân sự, thuật cùng họ mọi lời Ðức Giê-hô-va đã dặn mình nói lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Cả dân sự đồng thinh đáp rằng: Chúng tôi xin làm mọi việc Ðức Giê-hô-va đã phán dặn. Môi-se bèn thuật lại lời của dân sự cùng Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Ngài phán rằng: Nầy, ta sẽ ở trong đám mây mịt mịt đi đến ngươi; đặng khi nào ta phán cùng ngươi, thì dân sự nghe và tin cậy ngươi luôn luôn. Ðoạn, Môi-se đem lời của dân sự thưa lại cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy đi đến cùng dân sự, khiến dân giữ mình thánh sạch ngày nay và ngày mai, cùng phải giặt áo xống mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Qua ngày thứ ba, dân khá sẵn sàng, vì ngày đó Ðức Giê-hô-va sẽ giáng lâm trước mắt dân sự tại núi Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Vả, ngươi hãy phân định giới hạn cho dân sự ở chung quanh núi, và dặn rằng: Khá giữ mình đừng leo lên núi, hoặc đụng đến chân; hễ kẻ nào đụng đến thì sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Chớ ai tra tay vào mình người đó, nhưng người đó phải bị liệng đá hoặc bắn tên; bất luận vật hay người, cũng chẳng để cho sống đâu. Khi kèn thổi lên, dân sự sẽ đến gần núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Môi-se xuống núi đến cùng dân sự, khiến họ giữ mình thánh sạch, và giặt áo xống mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Người dặn dân sự rằng: Trong ba ngày hãy sẵn sàng chớ đến gần đàn bà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Qua sáng ngày thứ ba, có sấm vang chớp nhoáng, một áng mây mịt mịt ở trên núi, và tiếng kèn thổi rất vang động; cả dân sự ở trong trại quân đều run hãi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Môi-se bèn biểu dân ra khỏi trại quân nghinh tiếp Ðức Chúa Trời; dân sự dừng lại tại chân núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Vả, bấy giờ, khắp núi Si-na -i đều ra khói, vì Ðức Giê-hô-va ở trong lửa giáng lâm nơi đó; khói ra khác nào khói của lò lửa lớn kia, và cả hòn núi đều rung động cách kịch liệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Tiếng kèn càng vang động; Môi-se nói, Ðức Chúa Trời đáp tiếng lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Ðức Giê-hô-va giáng-lâm trên chót núi Si-na -i, đòi Môi-se lên, Môi-se bèn lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Ðức Giê-hô-va phán rằng: Hãy xuống cấm dân sự đừng xông pha đến gần Ðức Giê-hô-va mà nhìn, e nhiều người trong bọn phải chết chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Dầu những thầy tế lễ đến gần Ðức Giê-hô-va cũng phải giữ mình thánh sạch, kẻo Ngài hại họ chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Môi-se thưa cùng Ðức Giê-hô-va rằng: Dân sự chẳng được lên núi Si-na -i đâu, vì Ngài có cấm chúng tôi mà phán rằng: Hãy phân định giới hạn chung quanh núi, và phân biệt nơi đó là đất thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Ðức Giê-hô-va phán rằng: Hãy đi xuống, rồi đem A-rôn lên cùng ngươi, song những thầy tế lễ và dân sự chớ xông pha đặng lên đến gần Ðức Giê-hô-va, e Ngài hại họ chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Vậy, Môi-se đi xuống, nói lại cho dân sự nghe.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Bấy giờ, Ðức Chúa Trời phán mọi lời nầy, rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ta là Giê-hô-va Ðức Chúa Trời ngươi, đã rút ngươi ra khỏi xứ Ê-díp-tô, là nhà nô lệ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Trước mặt ta, ngươi chớ có các thần khác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Ngươi chớ làm tượng chạm cho mình, cũng chớ làm tượng nào giống những vật trên trời cao kia, hoặc nơi đất thấp nầy, hoặc trong nước dưới đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Ngươi chớ quì lạy trước các hình tượng đó, và cũng đừng hầu việc chúng nó; vì ta là Giê-hô-va Ðức Chúa Trời ngươi, tức là Ðức Chúa Trời kỵ tà, hễ ai ghét ta, ta sẽ nhơn tội tổ phụ phạt lại con cháu đến ba bốn đời,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'và sẽ làm ơn đến ngàn đời cho những kẻ yêu mến ta và giữ các điều răn ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Ngươi chớ lấy danh Giê-hô-va Ðức Chúa Trời ngươi mà làm chơi, vì Ðức Giê-hô-va chẳng cầm bằng vô tội kẻ nào lấy danh Ngài mà làm chơi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Hãy nhớ ngày nghỉ đặng làm nên ngày thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Ngươi hãy làm hết công việc mình trong sáu ngày;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'nhưng ngày thứ bảy là ngày nghỉ của Giê-hô-va Ðức Chúa Trời ngươi: trong ngày đó, ngươi, con trai, con gái tôi trai tớ gái, súc vật của ngươi, hoặc khách ngoại bang ở trong nhà ngươi, đều chớ làm công việc chi hết;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'vì trong sáu ngày Ðức Giê-hô-va đã dựng nên trời, đất, biển, và muôn vật ở trong đó, qua ngày thứ bảy thì Ngài nghỉ: vậy nên Ðức Giê-hô-va đã ban phước cho ngày nghỉ và làm nên ngày thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Hãy hiếu kính cha mẹ ngươi, hầu cho ngươi được sống lâu trên đất mà Giê-hô-va Ðức Chúa Trời ngươi ban cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Ngươi chớ giết người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Ngươi chớ phạm tội tà dâm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Ngươi chớ trộm cướp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Ngươi chớ nói chứng dối cho kẻ lân cận mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Ngươi chớ tham nhà kẻ lân cận ngươi, cũng đừng tham vợ người, hoặc tôi trai tớ gái, bò, lừa, hay là vật chi thuộc về kẻ lân cận ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Vả, cả dân sự nghe sấm vang, tiếng kèn thổi, thấy chớp nhoáng, núi ra khói, thì run rẩy và đứng cách tận xa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Dân sự bèn nói cùng Môi-se rằng: Chính mình người hãy nói cùng chúng tôi thì chúng tôi sẽ nghe; nhưng cầu xin Ðức Chúa Trời chớ phán cùng, e chúng tôi phải chết chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Môi-se đáp rằng: Ðừng sợ chi, vì Ðức Chúa Trời giáng lâm đặng thử các ngươi, hầu cho sự kính sợ Ngài ở trước mặt các ngươi, cho các ngươi không phạm tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Vậy, dân sự đứng cách tận xa, còn Môi-se đến gần đám mây đen kịt có Ðức Chúa Trời ngự ở trong.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Ngươi hãy nói cho dân Y-sơ-ra-ên như vầy: Các ngươi đã thấy ta từ trên trời phán xuống cùng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'vậy, chớ đúc tượng thần bằng bạc hay bằng vàng mà sánh với ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Ngươi hãy lập cho ta một bàn thờ bằng đất, trên đó phải dâng của lễ thiêu, cùng của lễ thù ân của ngươi, hoặc chiên hay bò. Phàm nơi nào có ghi nhớ danh ta, ta sẽ đến và ban phước cho ngươi tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Nếu ngươi lập cho ta một bàn thờ bằng đá, chớ dùng đá chạm, vì nếu ngươi dùng đồ để chạm thì sẽ làm đá đó ra ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Ngươi chớ đi từ bực thang lên bàn thờ ta, hầu cho sự lõa lồ ngươi không tố lộ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Ðây là luật lệ ngươi phải truyền cho dân sự:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Nếu ngươi mua một người đầy tớ Hê-bơ-rơ, nó sẽ hầu việc cho sáu năm; nhưng qua năm thứ bảy nó sẽ được thả ra, không phải thối tiền.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Nếu nó vào ở một mình, thì sẽ ra một mình; nếu có vợ, thì sẽ ra với vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Nếu người chủ cưới vợ cho, và nếu vợ sanh được con trai hay gái, thì nó sẽ ra một mình, vợ và con thuộc về chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Nếu kẻ tôi mọi nói rằng: Tôi thương chủ, vợ và con tôi, không muốn ra được tự do,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'thì người chủ sẽ dẫn nó đến trước mặt Ðức Chúa Trời, biểu lại gần cửa hay là cột, rồi lấy mũi dùi xỏ tai; nó sẽ hầu việc người chủ đó trọn đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Nếu ai bán con gái mình làm con đòi, con gái đó không được ra như các đầy tớ kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Nếu chủ trước đã ưng lấy con đòi làm hầu, rồi sau lại chẳng muốn, thì chủ phải biểu chuộc nàng lại, chớ không có phép gạt, rồi đem bán nàng cho kẻ ngoại bang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Nhưng nếu chủ định để cho con trai mình, thì phải xử với nàng theo phép như con gái mình vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Nếu chủ có lấy người khác, thì đối với người thứ nhất chẳng được phép giảm đồ ăn, đồ mặc, và tình nghĩa vợ chồng chút nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Nếu người chủ không làm theo ba điều nầy, nàng được phép ra không, chẳng phải thối tiền lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kẻ nào đánh chết một người, sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Nhược bằng kẻ đó chẳng phải mưu giết, nhưng vì Ðức Chúa Trời đã phú người bị giết vào tay kẻ đó, thì ta sẽ lập cho ngươi một chỗ đặng kẻ giết người ẩn thân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Còn nhược bằng kẻ nào dấy lên cùng người lân cận mà lập mưu giết người, thì dẫu rằng nó núp nơi bàn thờ ta, ngươi cũng bắt mà giết đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Kẻ nào đánh cha hay mẹ mình, sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kẻ nào bắt người và bán, hoặc giữ lại trong tay mình, sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Kẻ nào mắng cha hay mẹ mình, sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Khi hai người đánh lộn nhau, người nầy đánh người kia bằng đá hay là đấm cú, không đến đỗi phải chết, nhưng phải nằm liệt giường,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'nếu đứng dậy chống gậy đi ra ngoài được, người đánh đó sẽ được tha tội. Nhưng chỉ phải đền tiền thiệt hại trong mấy ngày nghỉ và nuôi cho đến khi lành mạnh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Khi người chủ lấy gậy đánh đầy tớ trai hay gái mình và chết liền theo tay, thì chắc phải bị phạt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Song nếu đầy tớ trai hay gái còn sống một hai ngày, người chủ khỏi tội, vì nó vốn là tài sản của chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Nếu người ta đánh nhau, đụng nhằm một người đàn bà có thai, làm cho phải sảo, nhưng chẳng bị sự hại chi khác, thì kẻ đánh nhằm đó phải bồi thường theo lời chồng người sẽ định, và trả tiền trước mặt quan án.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Còn nếu có sự hại chi, thì ngươi sẽ lấy mạng thường mạng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'lấy mắt thường mắt, lấy răng thường răng, lấy tay thường tay, lấy chân thường chân,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'lấy phỏng thường phỏng, lấy bầm thường bầm, lấy thương thường thương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Nếu ai đánh nhằm con mắt đầy tớ trai hay gái mình, làm cho mất đi, thì hãy tha nó ra tự do, vì cớ mất con mắt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Nếu ai làm rụng một răng của đầy tớ trai hay gái mình, thì hãy tha nó ra tự do, vì cớ mất một răng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Ví có một con bò báng nhằm một người đàn ông hay đàn bà phải chết đi, con bò sẽ bị ném đá chết, người ta không nên ăn thịt nó; còn người chủ bò sẽ được vô tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Nhưng ngộ từ trước con bò có tật hay báng và chủ đã bị mắng vốn mà không cầm giữ, nếu bò nầy còn giết một người đàn ông hay đàn bà, thì nó sẽ bị ném đá, và chủ sẽ bị xử tử nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Nhược bằng người ta định giá cho chủ bò chuộc mạng, chủ phải chuộc mạng mình y như giá đã định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Nếu bò báng nhằm một đứa con trai hay là con gái, người ta cũng sẽ chiếu theo luật nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Con bò báng nhằm một đứa đầy tớ trai hay gái, chủ bò phải trả ba chục siếc lơ bạc cho chủ nó; rồi bò sẽ bị ném đá chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Nếu ai mở miệng hầm hay là đào hầm mà chẳng đậy lại, và nếu có bò hay là lừa té xuống đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'chủ hầm sẽ bồi thường giá tiền cho chủ của súc vật, nhưng súc vật bị giết đó sẽ về phần mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Bằng bò của ai báng nhằm bò của kẻ lân cận mình phải chết đi, hai người hãy bán bò sống đó, chia tiền và chia luôn con bò chết nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Nếu người chủ đã tỏ tường trước rằng bò mình có tật hay báng, mà không lo cầm giữ, chủ phải lấy bò thường bò, nhưng bò chết sẽ về phần người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Ví ai bắt trộm bò hay chiên, rồi giết hoặc bán đi, thì phải thường năm con bò cho một con, và bốn con chiên cho một con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Nếu kẻ trộm đang cạy cửa mà bị bắt và đánh chết đi, thì kẻ đánh chết chẳng phải tội sát nhân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Song nếu đánh chết trong khi mặt trời đã mọc rồi, thì bị tội sát nhân. Kẻ trộm phải bồi thường; bằng chẳng có chi, thì sẽ bị bán vì tội trộm cắp mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Nếu vật mà kẻ trộm đã lấy, hoặc bò, lừa hay chiên, hãy còn thấy sống trong tay, thì kẻ trộm phải bồi thường gấp hai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Ngộ ai làm hư hại trong ruộng hay là vườn nho, thả súc vật mình vào ăn trong ruộng người khác, thì ai đó phải lấy hoa lợi tốt nhất của ruộng hay là vườn nho mình mà thường bồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Nếu lửa nổi đốt bụi gai và cháy lan qua lúa đã bó, mùa màng, hay là đồng ruộng, thì kẻ nổi lửa đó phải bồi thường trọn mọi vật đã bị cháy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Khi ai giao tiền bạc bay đồ vật cho kẻ lân cận mình giữ, rủi bị trộm cắp tại nhà kẻ lân cận đó, nếu tên trộm đã bị bắt được, thì nó phải thường gấp hai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Nếu kẻ trộm không bị bắt được, thì chủ nhà cho gởi phải dẫn đến trước mặt Ðức Chúa Trời, đặng thề rằng mình chẳng hề đặt tay vào tài vật của kẻ lân cận mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Trong mọi việc gian lận nào, hoặc về một con bò, một con lừa, một con chiên, áo xống hay là một vật chi bị mất, mà có người nói rằng: \"quả thật là đồ đó\", thì phải đem duyên cớ hai đàng đến trước mặt Ðức Chúa Trời; kẻ nào bị Ngài xử phạt phải thường bồi cho kẻ lân cận mình gấp hai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Nhược bằng người nào giao lừa, bò, chiên, hoặc súc vật nào khác cho kẻ lân cận mình giữ và bị chết, gãy một giò hay là bị đuổi đi, không ai thấy,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'thì hai đàng phải lấy danh Ðức Giê-hô-va mà thề, hầu cho biết rằng người giữ súc vật có đặt tay trên tài vật của kẻ lân cận mình chăng. Người chủ con vật phải nhận lời thề, và người kia chẳng bồi thường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Còn nếu con vật bị bắt trộm, thì người lãnh giữ phải thường bồi cho chủ nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Nếu con bật bị thú rừng xé chết, người lãnh giữ phải đem nó ra làm chứng, sẽ không phải bồi thường vật bị xé đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Vì ai mượn người lân cận mình một con vật mà nó gãy một giò, hoặc bị chết, không có mặt chủ, thì ai đó phải bồi thường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Nếu chủ có mặt tại đó, thì không phải bồi thường. Nếu con vật đã cho mướn, thì giá muớn thế cho tiền bồi thường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Nếu kẻ nào hòa dụ và nằm với một người gái đồng trinh chưa hứa giá, thì kẻ đó phải nộp tiền sính và cưới nàng làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Nhược bằng cha nàng quyết từ chối không gả, thì kẻ đó phải nộp tiền bằng số tiền sính của người gái đồng trinh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Ngươi chớ để các đồng cốt sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Kẻ nào nằm cùng một con vật sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kẻ nào tế các thần khác hơn một mình Ðức Giê-hô-va sẽ bị diệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Ngươi chớ nên bạc đãi khách ngoại bang, và cũng chẳng nên hà hiếp họ, vì các ngươi đã làm khách kiều ngụ tại xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Các ngươi chớ ức hiếp một người góa bụa hay là một kẻ mồ côi nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Nếu ức hiếp họ, và họ kêu van ta, chắc ta sẽ nghe tiếng kêu của họ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'cơn nóng giận ta phừng lên, sẽ lấy gươm giết các ngươi, thì vợ các ngươi sẽ trở nên góa bụa, và con các ngươi sẽ mồ côi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Trong dân ta có kẻ nghèo nàn ở cùng ngươi, nếu ngươi cho người mượn tiền, chớ xử với họ như người cho vay, và cũng chẳng nên bắt họ chịu lời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Nếu ngươi cầm áo xống của kẻ lân cận mình làm của tin, thì phải trả cho họ trước khi mặt trời lặn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'vì là đồ chỉ có che thân, là áo xống che đậy da mình; người lấy chi mà ngủ? Nếu người đến kêu van ta, tất ta sẽ nghe lời người, vì ta là Ðấng hay thương xót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Ngươi chớ nên nói lộng ngôn cùng Ðức Chúa Trời, và cũng đừng rủa sả vua chúa của dân sự ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Ngươi chớ trễ nải mà dâng cho ta những hoa quả đầu mùa của ngươi chứa trong vựa và rượu ép chảy nơi bàn ép. Ngươi cũng phải dâng cho ta con trai đầu lòng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Về phần chiên và bò ngươi cũng hãy làm như vậy; trong bảy ngày đầu, con đầu lòng ở cùng mẹ nó, qua ngày thứ tám ngươi hãy dâng nó cho ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Các ngươi sẽ làm người thánh của ta, chớ nên ăn thịt chi bị thú rừng xé ở ngoài đồng; hãy liệng cho chó ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Ngươi chớ đồn huyễn; chớ hùa cùng kẻ hung ác đặng làm chứng dối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Ngươi chớ hùa đảng đông đặng làm quấy; khi ngươi làm chứng trong việc kiện cáo, chớ nên trở theo bên phe đông mà phạm sự công bình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ngươi chớ tư vị kẻ nghèo trong việc kiện cáo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Nhược bằng ngươi gặp bò hay lừa của kẻ thù nghịch mình đi lạc thì buộc phải đem về cho họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Ngộ ngươi thấy lừa của kẻ ghét mình bị chở nặng phải quị, chớ khá bỏ ngơ, phải cứu nó cho được nhẹ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Trong cơn kiện cáo, ngươi chớ phạm quyền lợi của người nghèo ở giữa vòng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Ngươi phải tránh xa các lời giả dối; chớ giết kẻ vô tội và kẻ công bình, vì ta chẳng hề tha kẻ gian ác đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Ngươi chớ nhậm của hối lộ, vì của hối lộ làm mờ mắt người thượng trí, và làm mất duyên do của kẻ công bình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Ngươi chớ hiếp đáp người ngoại bang, vì các ngươi đã kiều ngụ tại xứ Ê-díp-tô, chính các ngươi hiểu biết lòng khách ngoại bang là thế nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Trải sáu năm ngươi hãy gieo trong đất, thâu lấy hoa lợi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'nhưng qua năm thứ bảy hãy để đất hoang cho nghỉ; hầu cho kẻ nghèo khổ trong dân sự ngươi được nhờ lấy hoa quả đất đó, còn dư lại bao nhiêu, thú vật ngoài đồng ăn lấy. Cũng hãy làm như vậy về vườn nho và cây ô-li-ve.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Luôn trong sáu ngày ngươi hãy làm công việc mình, nhưng qua ngày thứ bảy hãy nghỉ, hầu cho bò và lừa ngươi được nghỉ; cùng con trai của đầy tớ gái và người ngoại bang được dưỡng sức lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Ngươi khá giữ hết mọi lời ta phán cùng ngươi. Chớ xưng đến danh các thần khác; chớ cho nghe danh đó ở nơi miệng ngươi ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Mỗi năm ba kỳ ngươi sẽ giữ lễ kính ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Ngươi hãy giữ lễ bánh không men; phải ăn bánh không men trong bảy ngày về mùa tháng lúa trỗ, như lời ta đã phán dặn; vì trong tháng đó ngươi ra khỏi xứ Ê-díp-tô. Lại chẳng ai nên tay không đến trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Ngươi hãy giữ lễ mùa màng, tức là mùa hoa quả đầu tiên của công lao ngươi về các giống ngươi đã gieo ngoài đồng; và giữ lễ mùa gặt về lúc cuối năm, khi các ngươi đã hái hoa quả của công lao mình ngoài đồng rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Mỗi năm ba kỳ các người nam phải đến trước mặt Chúa, tức là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Ngươi chớ dâng huyết của con sinh tế ta chung với bánh có pha men; còn mỡ của nó dâng nhằm ngày lễ kính ta, chớ để trọn đêm đến sáng mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Những hoa quả đầu mùa của đất, ngươi phải đem đến đền thờ Giê-hô-va Ðức Chúa Trời ngươi. Ngươi chớ nên nấu dê con trong sữa mẹ nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Ðây nầy, ta sai một thiên sứ đi trước mặt ngươi, đặng phù hộ trong lúc đi đường, và đưa ngươi vào nơi ta đã dự bị.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Trước mặt người, ngươi khá giữ mình, phải nghe theo lời, chớ nên phản nghịch; người sẽ chẳng tha tội ngươi đâu, vì danh ta ngự trong mình người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Nhưng nếu ngươi chăm chỉ nghe lời người, cùng làm theo mọi lời ta sẽ phán, ta sẽ thù nghịch cùng kẻ thù nghịch ngươi, và đối địch với kẻ đối địch ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Vì thiên sứ ta sẽ đi trước mắt, đưa ngươi vào xứ của dân A-mô-rít, dân Hê-tít, dân Phê-rê-sít, dân Ca-na-an, dân Hê-vít, và dân Giê-bu-sít, rồi ta sẽ diệt chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Ngươi chớ quì lạy và hầu việc các thần chúng nó; chớ bắt chước công việc họ, nhưng phải diệt hết các thần đó và đạp nát các pho tượng họ đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Ngươi hãy hầu việc Giê-hô-va Ðức Chúa Trời ngươi; Ngài sẽ ban ơn cho vật ăn uống của ngươi và tiêu trừ các bịnh hoạn giữa vòng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Trong xứ ngươi sẽ chẳng có đàn bà sảo thai hay là đàn bà son sẻ. Ta sẽ cho ngươi được trường thọ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Ta sẽ sai sự kinh khiếp ta đi trước, hễ ngươi đến dân nào, ta sẽ làm cho dân ấy vỡ chạy lạc đường, và cho kẻ thù nghịch ngươi xây lưng trước mặt ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Ta sẽ sai ong lỗ đi trước đánh đuổi dân Hê-vít, dân Ca-na-an, dân Hê-tít khỏi trước mặt ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Ta sẽ chẳng đuổi chúng nó đi hết trong một năm đâu, e khi xứ sẽ trở nên đồng vắng, và loài thú rừng sanh sản ra đông, hại ngươi chăng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'nhưng ta sẽ đuổi chúng nó lần lần khỏi trước mặt ngươi, cho đến chừng nào số ngươi thêm nhiều và có thể cầm đất đó làm sản nghiệp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Ta sẽ phân định bờ cõi ngươi từ Biển đỏ chí biển Phi-li-tin, từ đồng vắng đến sông cái; vì ta sẽ giao phú dân đó vào tay ngươi, và ngươi sẽ đuổi chúng nó khỏi mặt mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Ngươi đừng kết giao ước cùng chúng nó, hoặc cùng các thần của chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Họ sẽ chẳng ở trong xứ ngươi đâu, e khi chúng nó xui cho ngươi phạm tội cùng ta mà hầu việc các thần họ chăng; điều đó chắc sẽ thành một cái bẫy cho ngươi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Ðức Chúa Trời phán cùng Môi-se rằng: Ngươi và A-rôn, Na-đáp, và A-bi-hu cùng bảy mươi trưởng lão Y-sơ-ra-ên hãy lên cùng Ðức Giê-hô-va ở đằng xa mà lạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Chỉ một mình Môi-se sẽ đến gần Ðức Giê-hô-va mà thôi, còn họ không đến gần, và dân sự cùng không lên cùng người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Môi-se bèn đến thuật lại cho dân sự mọi lời phán của Ðức Giê-hô-va và các luật lệ, thì chúng đồng thinh đáp rằng: Chúng tôi sẽ làm mọi lời Ðức Giê-hô-va phán dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Môi-se chép hết mọi lời của Ðức Giê-hô-va; rồi dậy sớm, xây một bàn thờ nơi chân núi, dựng mười hai cây trụ chỉ về mười hai chi phái Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Người sai kẻ trai trẻ của dân Y-sơ-ra-ên đi dâng của lễ thiêu và của lễ thù ân cho Ðức Giê-hô-va bằng con bò tơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Môi-se lấy phân nửa huyết đựng trong các chậu, còn phân nửa thì rưới trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Ðoạn, người cầm quyển sách giao ước đọc cho dân sự nghe, thì dân sự nói rằng: Chúng tôi sẽ làm và vâng theo mọi lời Ðức Giê-hô-va phán chỉ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Môi-se bèn lấy huyết rưới trên mình dân sự mà nói rằng: Ðây là huyết giao ước của Ðức Giê-hô-va đã lập cùng các ngươi y theo mọi lời nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Ðoạn, Môi-se và A-rôn, Na-đáp và A-bi-hu cùng bảy mươi trưởng lão dân Y-sơ-ra-ên đều lên núi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'ngó thấy Ðức Chúa Trời của Y-sơ-ra-ên, dưới chân Ngài có một vật giống bích ngọc trong ngần, khác nào như sắc trời thanh-quang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Ngài chẳng tra tay vào những người tôn trọng trong vòng dân Y-sơ-ra-ên; nhưng họ ngó thấy Ðức Chúa Trời, thì ăn và uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy lên núi, đến cùng ta và ở lại đó; ta sẽ ban cho ngươi bảng đá, luật pháp và các điều răn của ta đã chép đặng dạy dân sự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Môi-se bèn chờ dậy cùng Giô-suê, kẻ hầu mình, rồi Môi-se đi lên núi Ðức Chúa Trời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Người bèn nói cùng các trưởng lão rằng: Hãy đợi chúng tôi tại đây cho đến chừng nào trở về cùng các ngươi. Nầy, A-rôn và Hu-rơ ở lại cùng các ngươi, ai có việc chi hãy hỏi hai người đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Vậy, Môi-se lên núi, mây che phủ núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Sự vinh quang của Ðức Giê-hô-va ở tại núi Si-na -i; trong sáu ngày mây phủ núi, qua ngày thứ bảy Ðức Giê-hô-va ngự trong đám mây gọi Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Cảnh trạng của sự vinh quang Ðức Giê-hô-va nơi đỉnh núi, trước mặt dân Y-sơ-ra-ên, khác nào như đám lửa hừng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Môi-se vào giữa đám mây, lên núi, ở tại đó trong bốn mươi ngày và bốn mươi đêm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Hãy nói cùng dân Y-sơ-ra-ên đặng họ dâng lễ vật cho ta; các ngươi hãy nhận lấy lễ vật của mọi người có lòng thành dâng cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Nầy là lễ vật các ngươi sẽ nhận lấy của họ: vàng, bạc, và đồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'chỉ tím, đỏ điều, đỏ sặm, vải gai mịn, lông dê, da chiên đực nhuộm đỏ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'da cá nược, cây si-tim,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'dầu thắp, hương liệu đặng làm dầu xức và hương,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'bích ngọc cùng các thứ ngọc khác để gắn vào ê-phót và bảng đeo ngực.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Họ sẽ làm cho ta một đền thánh và ta sẽ ở giữa họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Hãy làm điều đó y như kiểu đền tạm cùng kiểu các đồ dùng mà ta sẽ chỉ cho ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Vậy, chúng hãy đóng một cái hòm bằng cây si-tim; bề dài hai thước rưỡi, bề ngang một thước rưỡi, và bề cao cũng một thước rưỡi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'lấy vàng ròng bọc trong, bọc ngoài, và chạy đường viền chung quanh hòm bằng vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Ngươi cũng hãy đúc bốn khoen bằng vàng để tại bốn góc hòm: hai cái bên hông nầy, hai cái bên hông kia,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'cùng làm hai cây đòn bằng cây si-tim, bọc vàng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'rồi lòn đòn vào khoen hai bên hông hòm, để dùng đòn khiêng hòm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Ðòn sẽ ở trong khoen luôn, không nên rút ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Ngươi hãy cất vào trong hòm bảng chứng mà ta sẽ ban cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Ngươi cũng hãy làm một cái nắp thi ân bằng vàng ròng, bề dài hai thước rưỡi, bề ngang một thước rưỡi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Lại làm hai tượng chê-ru-bin bằng vàng giát mỏng, để hai đầu nắp thi ân,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'ló ra ngoài, một tượng ở đầu nầy và một tượng ở đầu kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Hai chê-ru-bin sẽ sè cánh ra, che trên nắp thi ân, đối diện nhau và xây mặt vào nắp thi ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Ngươi hãy để nắp thi ân trên hòm, rồi để vào trong hòm bảng chứng mà ta sẽ ban cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Ta sẽ gặp ngươi tại đó, và ở trên nắp thi ân, giữa hai tượng chê-ru-bin, trên hòm bảng chứng, ta sẽ truyền cho ngươi các mạng lịnh về dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Ngươi cũng hãy đóng một cái bàn bằng cây si-tim; bề dài hai thước, bề ngang một thước, và bề cao một thước rưỡi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'bọc bằng vàng ròng, và chạy một đường viền chung quanh;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'rồi lên be cho tứ vi bàn, cao chừng bốn ngón tay và chạy cho be một đường viền vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Lại đúc bốn cái khoen vàng, tra vào bốn góc nơi chân bàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Khoen sẽ ở gần be, để xỏ đòn khiêng bàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Ngươi hãy chuốt đòn bằng cây si-tim, bọc vàng, rồi người ta sẽ dùng khiêng bàn đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Lại hãy lấy vàng ròng mà làm dĩa, chén, chậu, và ly đặng dùng làm lễ quán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Trên bàn ngươi sẽ để bánh trần thiết cho có luôn luôn trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Ngươi cũng hãy làm chân đèn bằng vàng ròng. Cái chân, cái thân, cái đài, cái bầu cùng cái hoa của đèn đều làm bằng vàng đánh giát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Hai bên thân đèn sẽ có sáu nhánh nứt ra, hạ nhánh ở bên nầy và ba nhánh ở bên kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Trong sáu nhánh nứt ra trên chân đèn, mỗi nhánh đều sẽ có ba cái đài hình như hột hạnh nhân cùng bầu và hoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Trên thân chân đèn, lại cũng sẽ có bốn cái đài hình hột hạnh nhân, bầu và hoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Trong sáu nhánh từ thân chân đèn nứt ra, hễ cứ mỗi hai nhánh thì dưới có một cái bầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Bầu cùng nhánh của chân đèn đều bằng vàng ròng nguyên miếng đánh giát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Ngươi cũng hãy làm bảy cái thếp đèn, đặng hễ khi thắp thì chiếu trước chân đèn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Kéo bắt tim cùng đồ đựng tàn đèn cũng sẽ bằng vàng ròng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Người ta sẽ dùng một ta lâng vàng ròng làm chân đèn nầy và các đồ phụ tùng của chân đèn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Vậy, ngươi hãy xem, cứ làm y như kiểu đã chỉ cho trên núi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Ngươi hãy dùng mười bức màn mà làm đền tạm, màn dệt bằng vải gai mịn, chỉ tím, đỏ điều và đỏ sặm, có thêu các hình chê-ru-bin cực xảo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Mỗi bức màn bề dài hai mươi tám thước, bề rộng bốn thước. Các bức đều đồng cỡ với nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Mỗi năm bức màn sẽ kết dính lại nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Ngươi hãy thắt vòng chỉ tím nơi triêng của bức màn thứ nhất ở đầu bức nguyên; và cũng làm như vậy cho đầu chót của bức màn cuối trong bức nguyên thứ nhì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Lại làm năm chục cái vòng cho bức màn thứ nhất, và năm chục cái vòng nơi đầu triêng bức nguyên thứ nhì; các vòng hai bên sẽ đối nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Cũng hãy làm năm mươi cái móc bằng vàng, rồi móc bức nguyên nầy qua bức nguyên kia, hầu cho đền tạm kết lại thành một.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Ngươi cũng hãy kết mười một bức màn bằng lông dê, để dùng làm bong che trên đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Bề dài mỗi bức màn ba chục thước, bề rộng bốn thước, mười một bức đồng một cỡ với nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Ngươi hãy kết năm bức màn nầy riêng ra, và sáu bức màn kia riêng ra; nhưng hãy gấp đôi bức màn thứ sáu ở trước đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Lại thắt năm chục cái vòng nơi triêng màn thứ nhất, ném về cuối của bức nguyên thứ nhất, và năm chục cái vòng nơi triêng màn của bức nguyên thứ nhì;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'cũng làm năm chục cái móc bằng đồng, móc vào vòng, rồi hiệp cái bong lại, để nó thành ra một.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Nhưng còn dư, tức là phân nửa của bức màn dư trong bức bong nguyên, thì sẽ xủ xuống phía sau đền tạm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'phần bề dài dư trong các bức màn của bong, bên nầy một thước, bên kia một thước, thì sẽ xủ xuống hai bên hông đền tạm đặng che vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Ngươi hãy làm một tấm lá phủ bằng da chiên đực nhuộm đỏ để trên bong, và kết một tấm lá phủ bằng da cá nược đắp lên trên nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Ngươi cũng hãy làm những ván cho vách đền tạm bằng cây si-tim.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Mỗi tấm trướng mười thước, hoành một thước rưỡi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'có hai cái mộng liền nhau; hết thảy các tấm ván vách đền tạm ngươi cũng sẽ làm như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Về phía nam đền tạm, ngươi hãy làm hai mươi tấm ván;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'dưới hai mươi tấm ván hãy đặt bốn mươi lỗ mộng bằng bạc; cứ hai lỗ mộng ở dưới, để chịu hai cái mộng của mỗi tấm ván.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Lại hãy làm hai mươi tấm ván về phía bắc đền tạm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'và bốn mươi lỗ mộng bằng bạc, cứ dưới mỗi tấm có hai lỗ mộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Ngươi cũng hãy làm sáu tấm ván về phía sau đền tạm, tức là về hướng tây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Về hai góc phía sau đền tạm, phải làm hai tấm ván,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'khít nhau tự dưới chí trên bởi một cái khoen ở nơi đầu; hai cái góc đều làm như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Thế thì, có tám tấm ván và mười sáu lỗ mộng bằng bạc; cứ hai lỗ mộng ở dưới mỗi một tấm ván.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Lại, ngươi hãy làm năm cây xà ngang bằng gỗ si-tim cho những tấm ván về phía bên nầy,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'năm cây xà ngang về phía bên kia và năm cây xà ngang khác nữa về phía sau của đền tạm, tức là hướng tây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Cây xà ngang giữa sẽ ở về thân giữa những tấm ván, chạy suốt từ đầu nầy đến đầu kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Cũng hãy lấy vàng bọc ván cùng xà ngang, và làm những khoen bằng vàng, đặng xỏ các cây xà ngang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Ngươi phải dựng đền tạm y như kiểu đã chỉ cho ngươi trên núi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Ngươi hãy làm một bức màn bằng vải gai đậu mịn, chỉ tím, đỏ điều, đỏ sặm, có thêu những hình chê-ru-bin cực xảo;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'rồi xủ màn đó trên bốn trụ bằng cây si-tim, bọc vàng, dựng trên bốn lỗ trụ bằng bạc; các móc trụ đều bằng vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Ngươi sẽ treo màn đó vào móc dưới bức bong, rồi ở phía trong màn để hòm bảng chứng; màn nầy dùng phân biệt cho các ngươi nơi thánh và nơi chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Ðoạn, hãy để cái nắp thi ân trên hòm bảng chứng, đặt trong nơi chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Bên ngoài bức màn về phía bắc đền tạm thì để cái bàn; còn cây chân đèn thì để về phía nam đối ngang cái bàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Về cửa Trại ngươi hãy làm một bức màn bằng chỉ tím, đỏ điều, đỏ sặm, vải gai đậu mịn, có thêu cực xảo;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'rồi làm cho bức màn nầy năm cái trụ bằng cây si-tim, bọc vàng; đinh nó cũng bằng vàng, và đúc năm lỗ trụ bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Ngươi cũng hãy đóng một bàn thờ bằng cây si-tim, hình vuông, năm thước bề dài, năm thước bề ngang, và bề cao ba thước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Nơi bốn góc bàn thờ hãy làm sừng ló ra và bọc đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Những đồ phụ tùng của bàn thờ thì hãy làm bằng đồng: bình đựng tro, vá, ảng, nỉa và bình hương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Lại làm cho bàn thờ một tấm rá bằng lưới đồng; và nơi bốn góc rá làm bốn cái khoen bằng đồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'rồi để rá đó dưới thành bàn thờ, từ dưới chân lên đến nửa bề cao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Cũng hãy chuốt đòn khiêng bàn thờ bằng cây si-tim, bọc đồng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'rồi xỏ vào những khoen; khi khiêng đi, đòn sẽ ở hai bên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Bàn thờ sẽ đóng bằng ván, trống bộng, làm y như đã chỉ cho ngươi trên núi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Ngươi cũng hãy làm cái hành lang cho đền tạm. Về phía nam của hành lang làm bố vi bằng vải gai đậu mịn, dài trăm thước,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'cùng hai chục cây trụ và hai chục lỗ trụ bằng đồng; đinh và nuông trụ thì bằng bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Về phía bắc cũng vậy; bố vi đó có trăm thước bề dài, hai chục cây trụ và hai chục lỗ trụ bằng đồng; đinh và nuông trụ thì bằng bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Bố vi của hành lang về phía tây có năm chục thước bề dài, mười cây trụ và mười lỗ trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Bề ngang của hành lang phía trước, tức là phía đông, có năm chục thước: phía hữu');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'có mười lăm thước bố vi, ba cây trụ và ba lỗ trụ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'phía tả có mười lăm thước bố vi, ba cây trụ và ba lỗ trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Còn cửa hành lang có một bức màn dài hai chục thước bằng vải gai đậu mịn, chỉ tím, đỏ điều, đỏ sặm, có thêu, cùng vốn cây trụ và bốn lỗ trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Hết thảy trụ xung quanh hành lang đều sẽ có nhờ nuông bạc chắp lại với nhau; đinh trụ thì bằng bạc, lỗ trụ thì bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Bề dài của hành lang được một trăm thước, bề ngang, mỗi phía, năm chục thước, bề cao năm thước; bố vi sẽ bằng vải gai đậu mịn, còn những lỗ trụ thì bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Hết thảy đồ phụ tùng dùng về các việc phụng sự trong đền tạm, cùng cây nọc của đền tạm và cây nọc của hành lang, đều sẽ làm bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Ngươi hãy truyền cho dân Y-sơ-ra-ên đem đến dầu lọc ô-li-ve ép, đặng thắp đèn cho đèn sáng luôn luôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Trong hội mạc, ở ngoài màn, trước hòm bảng chứng, A-rôn cùng các con trai người sẽ lo sửa soạn đèn, hầu cho trước mặt Ðức Giê-hô-va đèn cháy luôn luôn từ tối cho đến sáng. Ấy là một luật đời đời cho dòng dõi dân Y-sơ-ra-ên phải giữ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Trong vòng dân Y-sơ-ra-ên, ngươi hãy chọn A-rôn, anh ngươi, cùng các con trai ngươi, là Na-đáp, A-bi-hu, Ê-lê-a-sa, và Y-tha-ma, lập lên làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Ngươi hãy chế bộ áo thánh cho A-rôn, anh ngươi, để người được vinh hiển trang sức.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Hãy truyền cho hết thảy kẻ thông minh, là người ta đã ban đầy tính trí huệ, chế bộ áo cho A-rôn, đặng biệt người riêng ra thánh, hầu cho người làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Ðây là bộ áo mà họ sẽ chế: Bảng đeo ngực, ê-phót, áo dài, áo lá trong thêu, mũ và đai. Thế thì, họ sẽ chế bộ áo thánh cho A-rôn, anh ngươi, cùng các con trai người, để các người đó làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Họ sẽ dùng kim tuyến, chỉ màu tím, đỏ điều, đỏ sặm, và vải gai mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Họ sẽ chế ê-phót bằng kim tuyến, chỉ màu tím, đỏ điều, đỏ sặm, và vải gai đậu mịn thêu cực xảo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Hai bên ê-phót làm hai đai vai, đâu đầu vào ê-phót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Ðai để cột ê-phót ở phía ngoài, sẽ làm nguyên miếng một cũng như công việc ê-phót, bằng kim tuyến, chỉ tím, đỏ điều, đỏ sặm, và vải gai đậu mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Ngươi hãy lấy hai viên bích ngọc mà khắc các tên con trai Y-sơ-ra-ên ở trên:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'sáu tên trên viên bích ngọc nầy, sáu tên trên viên bích ngọc kia, tùy theo thứ tự ngày sinh của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Phải khắc các tên con trai Y-sơ-ra-ên trên hai viên bích ngọc đó, như cách của thợ khắc con dấu, và khảm trong khuôn bằng vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Ðoạn gắn hai viên bích ngọc đó trên hai đai vai ê-phót, dùng làm ngọc kỷ niệm về con cháu Y-sơ-ra-ên; A-rôn sẽ mang tên của họ trên hai vai mình làm kỷ niệm trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Ngươi cũng hãy làm móc gài bằng vàng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'đánh hai sợi dây chuyền nhỏ bằng vàng ròng như hình dây, rồi để chuyền đánh như thế vào móc gài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Bảng đeo ngực về sự xét đoán, ngươi cũng phải làm cho cực xảo, y như ê-phót; tức là bằng kim tuyến, chỉ tím, đỏ điều, đỏ sặm, và vải gai đậu mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Bảng đeo ngực hình vuông và may lót; bề dài một em-ban, bề ngang một em-ban.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Ngươi hãy gắn bốn hàng ngọc vào bảng đeo ngực: hàng thứ nhất gắn ngọc mã não, ngọc hồng bích, và ngọc lục bửu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'hàng thứ nhì, ngọc phỉ túy, ngọc lam bửu và ngọc kim cương;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'hàng thứ ba, ngọc hồng bửu, ngọc bạch mã não, và ngọc tử tinh;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'hàng thứ tư, ngọc huỳnh bích, ngọc hồng mã não, và bích ngọc. Các ngọc nầy sẽ khảm vào khuôn bằng vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Số các ngọc đó hết thảy là mười hai viên, tùy theo tên các con trai Y-sơ-ra-ên; trên mỗi viên ngọc sẽ khắc tên của một trong mười hai chi phái Y-sơ-ra-ên, như người ta khắc con dấu vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Ngươi hãy làm các sợi chuyền bằng vàng ròng đánh như hình dây, chuyền trên bảng đeo ngực;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'rồi làm hai khoanh bằng vàng để ở hai góc đầu trên bảng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'cùng cột hai sợi chuyền vàng vào hai khoanh nơi hai đầu bảng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'và hai đầu sợi chuyền cột vào móc gài, đoạn gắn trên hai đai vai ê-phót về phía đằng trước ngực.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Ngươi cũng hãy làm hai cái khoanh bằng vàng nữa, để vào hai góc đầu dưới của bảng đeo ngực, về phía trong ê-phót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Lại làm hai khoanh khác nữa bằng vàng, gắn vào hai đầu dưới đai vai ê-phót ném về phía trước, ở trên đai gần chỗ giáp mối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Rồi một sợi dây màu tím sẽ cột hai cái khoanh của bảng đeo ngực lại cùng hai cái khoanh ê-phót, hầu cho nó dính với đai, đừng rớt khỏi ê-phót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Thế thì, khi nào A-rôn vào nơi thánh, sẽ mang trên lòng mình tên các con trai Y-sơ-ra-ên nơi bảng đeo ngực về sự xét đoán, đặng giữ làm kỷ niệm luôn luôn trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Trên bảng đeo ngực của sự xét đoán, ngươi hãy gắn u-rim và thu-mim vào, đặng khi A-rôn đến trước mặt Ðức Giê-hô-va thì các món đó sẽ ở trên lòng mình. Ấy vậy, trước mặt Ðức Giê-hô-va, A-rôn sẽ mang sự xét đoán của con trai Y-sơ-ra-ên trên lòng mình luôn luôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Ngươi cũng hãy may áo dài của ê-phót toàn bằng vải tím.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Ở giữa áo có một lỗ tròng đầu vào; viền chung quanh, dệt như lỗ áo giáp mặt lưới, để cho khỏi tét.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Nơi biên dưới hãy thắt trái lựu màu tím, đỏ điều, đỏ sặm, cùng chuông vàng nhỏ đan tréo nhau ở vòng theo viền,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'nghĩa là một cái chuông rồi kế một trái lựu, ở vòng khắp chung quanh viền áo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Khi A-rôn hầu việc tế lễ, sẽ mặc áo đó; và khi vào hay ra nơi thánh trước mặt Ðức Giê-hô-va, người ta sẽ nghe tiếng chuông vàng nhỏ, và A-rôn khỏi chết vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Ngươi cũng hãy làm một cái thẻ bằng vàng ròng, trên đó khắc như người ta khắc con dấu, rằng: Thánh Cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Rồi lấy một sợi dây màu tím buộc thẻ đó để trên đằng trước cái mũ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Thẻ đó sẽ ở trên trán A-rôn; A-rôn gánh tội lỗi của dân Y-sơ-ra-ên phạm trong khi họ dâng của lễ thánh; thẻ đó sẽ ở nơi trán A-rôn luôn luôn, để dân sự được đẹp ý Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Ngươi hãy chế một cái áo lá mặc trong bằng vải gai mịn, một cái mũ bằng vải gai mịn và một cái đai thêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Ngươi cũng hãy chế cho các con trai A-rôn áo lá, đai và mũ, hầu cho họ được vinh hiển và trang sức.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Ðoạn, hãy lấy các bộ áo đó mặc cho A-rôn, anh ngươi, cùng các con trai người; hãy xức dầu cho, lập và biệt riêng ra thánh, để họ làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Hãy chế cho họ quần lót trong bằng vải gai, đặng che sự lõa lồ, mặc từ ngang lưng quần cho đến bắp vế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'A-rôn cùng các con trai người sẽ mặc quần đó trong khi vào hội mạc hay là đến gần bàn thờ đặng làm việc tế lễ trong nơi thánh, thì chẳng mắc tội và chẳng chết đâu. Ấy là một mạng lịnh đời đời cho A-rôn và dòng dõi người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Ðây là điều ngươi sẽ làm đặng biệt riêng A-rôn và con trai người riêng ra thánh, để họ làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Hãy bắt một con bò tơ đực và hai con chiên đực không tì vít, dùng bột mì thiệt mịn làm bánh không men, bánh nhỏ không men nhồi với dầu, và bánh tráng không men tẩm dầu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'rồi để các bánh đó trong một giỏ dâng luôn lên cùng bò tơ đực và hai chiên đực.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Ðoạn, ngươi sẽ biểu A-rôn cùng các con trai người đến gần nơi cửa hội mạc, rồi lấy nước tắm cho họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Kế đó, lấy bộ áo mặc cho A-rôn, tức là áo lá mặc trong, áo dài của ê-phót, ê-phót, và bảng đeo ngực, rồi lấy đai của ê-phót thắt lưng cho người;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'đoạn đội cái mũ lên đầu và để thẻ thánh trên mũ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'cùng lấy dầu xức đổ trên đầu và xức cho người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Lại biểu các con trai A-rôn đến gần mặc áo lá cho họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'rồi lấy đai thắt lưng và đội mũ cho A-rôn cùng các con trai người. Thế thì, chức tế lễ sẽ bởi mạng lịnh định đời đời cho họ. Ngươi lập A-rôn và các con trai người là thế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Ðoạn, hãy dắt con bò tơ đực lại gần trước hội mạc, A-rôn cùng các con trai người sẽ nhận tay mình trên đầu con bò đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Ngươi hãy giết bò đực trước mặt Ðức Giê-hô-va, tại nơi cửa hội mạc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'rồi lấy huyết bò đó, nhúng ngón tay vào, bôi các sừng của bàn thờ, và đổ khắp dưới chân bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Cũng hãy lấy hết thảy những mỡ bọc ruột, tấm da mỏng bọc gan, hai trái cật và mỡ trên trái cật, mà đem xông trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Nhưng ở ngoài trại quân hãy thiêu hết thịt, da, và phẩn của con bò đực đó; ấy là một của lễ chuộc tội vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Ngươi cũng hãy bắt một trong hai con chiên đực, A-rôn và các con trai ngươi sẽ nhận tay mình trên đầu nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'rồi giết chiên đực đó, lấy huyết mà rưới khắp chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Kế đó, sả chiên ra từng miếng, rửa sạch bộ lòng và giò đi, rồi để lên trên các miếng đã sả và đầu nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'đoạn xông cả con chiên đực tại trên bàn thờ; ấy là một của lễ thiêu, có mùi thơm dâng cho Ðức Giê-hô-va, tức là một của lễ dùng lửa dâng lên cho Ðức Giê-hô-va vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Ðoạn, ngươi hãy bắt con chiên đực thứ nhì, A-rôn cùng các con trai người sẽ nhận tay mình trên đầu nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'rồi ngươi giết chiên đực đó, lấy huyết bôi nơi trái tai hữu của A-rôn và của các con trai người, trên ngón cái bàn tay mặt và ngón cái bàn chân mặt; huyết còn dư hãy rưới chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Ngươi hãy lấy huyết ở nơi bàn thờ và dầu xức mà rảy trên mình và quần áo A-rôn, cùng trên mình và quần áo các con trai người. Như vậy, A-rôn cùng quần áo mình, các con trai người cùng quần áo họ sẽ được biệt riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Vì cớ chiên đực đó dùng làm lễ truyền chức, nên ngươi hãy lấy mỡ, đuôi, mỡ bọc ruột, tấm da mỏng bọc gan, hai trái cật, cùng mỡ trên trái cật và giò bên hữu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'lại lấy luôn một ổ bánh, một bánh nhỏ nhồi với dầu, và một cái bánh tráng ở trong giỏ bánh không men để trước mặt Ðức Giê-hô-va;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'rồi ngươi để mấy món đó trong lòng bàn tay A-rôn, và trong lòng bàn tay của các con trai ngươi, mà đưa qua đưa lại trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Ðoạn, hãy lấy ra khỏi bàn tay họ đem xông trên bàn thờ, ở trên của lễ thiêu, để cho có mùi thơm trước mặt Ðức Giê-hô-va; ấy là một của lễ dùng lửa dâng lên cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Cũng hãy lấy cái o chiên đực về lễ lập A-rôn mà đưa qua đưa lại trước mặt Ðức Giê-hô-va. Ấy sẽ về phần ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Vậy, ngươi sẽ biệt riêng ra thánh cái o và giò của chiên đực đã dùng làm lễ lập A-rôn cùng các con trai người, tức là o đã đưa qua đưa lại, và giò đã giơ lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Lễ vật nầy sẽ do nơi Y-sơ-ra-ên dâng cho A-rôn cùng các con trai người tùy theo mạng lịnh đời đời đã lập, vì là một điều ban cho bởi trong các của lễ thù ân của dân Y-sơ-ra-ên, tức là một của lễ giơ lên mà họ dâng cho Ðức Giê-hô-va vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Những áo thánh của A-rôn sẽ để lại cho các con trai nối sau người, để họ mặc áo đó, được xức dầu và lập trong chức tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Ai trong vòng con trai người được làm thầy tế lễ thế cho ngươi, mà đến hội mạc đặng hầu việc tại nơi thánh, thì sẽ mặc áo đó trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Ðoạn, ngươi hãy bắt con chiên đực dùng làm lễ thiết lập mà nấu thịt nó trong một nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'A-rôn cùng các con trai người sẽ ăn thịt chiên đực đó, cùng bánh trong giỏ nơi cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Vậy, họ sẽ ăn các món nầy, bởi đó được chuộc tội, để lập và biệt họ riêng ra thánh; nhưng khách ngoại bang chẳng được ăn, vì các món đó đã biệt riêng ra thánh rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Nếu thịt lễ thiết lập và bánh còn dư lại đến ngày mai, ngươi hãy thiêu trong lửa, chớ nên ăn, vì là của đã biệt riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Vậy, theo mọi điều ta phán dặn, ngươi hãy làm cho A-rôn cùng các con trai người, và lập họ trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Mỗi ngày hãy dâng một con bò tơ đực đặng chuộc tội, và dâng vì bàn thờ một của lễ chuộc tội cùng xức dầu cho để biệt bàn thờ riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Trong bảy ngày ngươi hãy làm lễ chuộc tội cho bàn thờ và biệt riêng ra thánh; bàn thờ sẽ trở nên rất thánh, phàm vật chi đụng đến đều sẽ được nên thánh vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Ðây là các điều ngươi sẽ dâng lên bàn thờ: Hai chiên con một tuổi, mỗi ngày thường thường như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Buổi sớm mai ngươi hãy dâng một trong hai chiên con; con thứ nhì hãy dâng vào buổi chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Với con chiên thứ nhất, hãy dâng một phần mười bột mì mịn nhồi với một phần tư hin dầu ép, và cùng lễ quán một phần tư hin rượu nho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Về con chiên thứ nhì hãy dâng vào buổi chiều tối với một của lễ và một lễ quán y như lễ sớm mai; ấy là một của lễ thiêu, có mùi thơm dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Ấy là một của lễ thiêu mà các ngươi phải dâng luôn luôn, trải qua các đời, tại cửa hội mạc trước mặt Ðức Giê-hô-va, là nơi ta sẽ giáng lâm mà phán cùng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Vậy, ta sẽ có tại đó cùng dân Y-sơ-ra-ên; chỗ nầy sẽ vì sự vinh hiển ta mà được biệt riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Ta sẽ biệt hội mạc cùng bàn thờ riêng ra thánh; cùng biệt A-rôn và các con trai người riêng ra thánh nữa, đặng họ làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Ta sẽ ở giữa dân Y-sơ-ra-ên, làm Ðức Chúa Trời dân ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Dân ấy sẽ biết ta là Giê-hô-va Ðức Chúa Trời của chúng nó, đã đem chúng nó ra khỏi xứ Ê-díp-tô đặng ở giữa vòng họ. Ta là Giê-hô-va Ðức Chúa Trời của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Ngươi cũng hãy đóng một cái bàn thờ bằng cây si-tim, để xông hương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Mặt bàn sẽ vuông, bề dài một thước, bề ngang một thước, và bề cao hai thước; bàn thờ sẽ có bốn sừng ló ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Ngươi hãy bọc vàng ròng trên mặt, bốn cạnh chung quanh và các sừng; còn tứ vi chạy đường viền vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Dưới đường viền đó, nơi hai bên, hãy làm hai cái khoen bằng vàng, để xỏ đòn dùng đặng khiêng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Hãy chuốt đòn khiêng bằng cây si-tim, bọc vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Ngươi sẽ để bàn thờ đó trước bức màn che hòm bảng chứng đối cùng nắp thi ân trên hòm, là nơi ta sẽ gặp ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Mỗi buổi sớm mai, khi A-rôn làm đèn, sẽ xông hương tại nơi đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Vào lúc chiều tối, khi A-rôn thắp đèn, cũng sẽ xông hương: ấy là một thứ hương phải xông trước mặt Ðức Giê-hô-va luôn luôn, trải qua các đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Trên bàn thờ nầy chớ xông hương lạ, hoặc dâng của lễ thiêu, của lễ chay hay là lễ quán nào hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Nhưng trải qua các đời, mỗi năm một lần, A-rôn sẽ lấy huyết của con sinh tế chuộc tôi, bôi trên sừng bàn thờ nầy đặng chuộc tội cho nó. Ấy sẽ là một việc rất thánh cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Ðức Giê-hô-va cũng phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Khi nào ngươi điểm số dân Y-sơ-ra-ên đặng kê sổ, mỗi tên phải nộp tiền đền mạng mình cho Ðức Giê-hô-va, hầu cho khỏi mắc tai nạn chi trong khi kê sổ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Kẻ nào có tên trong sổ phải nộp nửa siếc-lơ, tùy siếc-lơ của nơi thánh, cận nặng hai mươi ghê-ra; vậy, nửa siếc-lơ, tức là của dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Mọi người có tên vào sổ từ hai mươi tuổi sắp lên sẽ dâng của nầy cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Khi dâng của nầy cho Ðức Giê-hô-va đặng đền mạng mình, người giàu không nộp trội, người nghèo không nộp thiếu nửa siếc-lơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Vậy, ngươi thâu tiền đền mạng của dân Y-sơ-ra-ên, rồi dùng tiền đó vào việc hội mạc; ấy là một kỷ niệm của dân Y-sơ-ra-ên trước mặt Ðức Giê-hô-va, đặng đền mạng mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Ðức Giê-hô-va lại phán cùng Môi-se nữa rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Ngươi hãy làm một cái thùng với chân thùng bằng đồng, đặng rửa mình ở trong, rồi để giữa khoảng của hội mạc và bàn thờ, và đổ nước vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'A-rôn cùng các con trai người sẽ rửa tay và chân mình ở trong.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Khi họ vào hội mạc sẽ lấy nước rửa mình, hầu cho họ khỏi chết; và khi lại gần bàn thờ đặng phụng sự, tức là xông của lễ dùng lửa dâng cho Ðức Giê-hô-va, họ cũng phải giữ như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Thế thì, họ hãy rửa tay và chân, hầu cho khỏi chết. Ấy là một lệ đời đời cho A-rôn, cùng dòng dõi người trải qua các đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Hãy góp các hương liệu tốt nhất: một dược nước năm trăm siếc-lơ; hương nhục quế phân nửa số đó, tức là hai trăm rưỡi; hương xương bồ hai trăm rưỡi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'quế-bì năm trăm, đều theo siếc-lơ nơi thánh, và một hin dầu ô-li-ve.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Ngươi hãy lấy các hương liệu đó theo phép hòa hương, chế ra một thứ dầu thơm dùng làm dầu xức thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Ðoạn, lấy xức cho hội mạc cùng hòm bảng chứng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'bàn thờ cùng các đồ phụ tùng, chân đèn cùng các đồ phụ tùng, bàn thờ xông hương,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'bàn thờ của lễ thiêu cùng các đồ phụ tùng, cái thùng và chân thùng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Ấy vậy, ngươi sẽ biệt các vật nầy riêng ra thánh, hầu cho làm rất thánh, hễ món chi đụng đến, đều sẽ được nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Ngươi cũng hãy xức dầu cho A-rôn cùng các con trai người, biệt họ riêng ra thánh, để làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Lại hãy nói cùng dân Y-sơ-ra-ên rằng: Về phần ta, dầu nầy sẽ là dầu xức thánh trải qua mọi đời các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Chớ nên đổ trên xác thịt loài người, và cũng đừng làm dầu nào khác theo phép hòa hương đó; dầu nầy là thánh, cũng sẽ thánh cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Hễ ai chế một thứ hòa hương giống như vậy, và đem rưới trên mình người ngoại bang, sẽ bị truất khỏi vòng dân sự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Ðức Giê-hô-va phán cùng Môi-se nữa rằng: Hãy lấy các hương liệu, tức tô hiệp hương, loa yểm hương, phong chi hương, cùng thanh nhũ hương, mỗi thứ bằng nhau,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'theo phép hòa hương, chế ra một thứ hương, mặn, trong và thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Hãy nghiền nó ra bột, rồi để trước hòm bảng chứng trong hội mạc, tức là nơi ta sẽ gặp ngươi: về phần các ngươi, hương nầy sẽ là một vật rất thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Còn thứ hương mà ngươi sẽ chế, chớ chế giống như phép hòa hương nầy; ấy là một vật ngươi nên biệt riêng ra thánh cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Hễ kẻ nào làm giống y như vậy đặng ngửi mùi, sẽ bị truất khỏi vòng dân sự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Ðức Giê-hô-va phán cùng Môi-se nữa rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Nầy, ta đã kêu tên Bết-sa-lê-ên, con trai của U-ri, cháu của Hu-rơ, trong chi phái Giu-đa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Ta đã làm cho người đầy dẫy Thần của Ðức Chúa Trời, sự khôn ngoan, sự thông sáng, và sự hiểu biết để làm mọi thứ nghề thợ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'đặng bày ra và chế tạo đồ vàng, bạc và đồng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'đặng khác và khảm ngọc, đẽo gỗ và làm được mọi thứ nghề thợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Ðây, ta lại cho một người phụ việc, tên là Ô-hô-li-áp, con trai của A-hi-sa-mạc, trong chi phái Ðan. Ta cũng đã ban sự thông minh cho mọi người tài năng, hầu cho họ làm các việc ta đã phán dặn ngươi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'là hội mạc, hòm bảng chứng, nắp thi ân ở trên hòm, cùng đồ dùng trong hội mạc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'bàn thờ cùng đồ phụ tùng, chân đèn bằng vàng ròng và đồ phụ tùng, bàn thờ xông hương,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'bàn thờ dâng của lễ thiêu cùng đồ phụ tùng, cái thùng và chân thùng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'áo lễ, áo thánh cho A-rôn thầy tế lễ cả, và bộ áo cho các con trai người, đặng làm chức tế lễ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'dầu xức, và hương thơm của nơi thánh. Các người đó phải làm hết thảy theo lời ta đã phán dặn ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Phần ngươi, hãy nói cùng dân Y-sơ-ra-ên rằng: Nhất là các ngươi hãy giữ ngày sa-bát ta, vì là một dấu giữa ta và các ngươi, trải qua mọi đời, để thiên hạ biết rằng ta, là Ðức Giê-hô-va, làm cho các ngươi nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Vậy, hãy giữ ngày sa-bát, vì là một ngày thánh cho các ngươi. Kẻ nào phạm đến ngày đó, phải bị xử tử; kẻ nào làm một việc chi trong ngày đó, cũng sẽ bị truất khỏi vòng dân sự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Người ta sẽ làm công việc trong sáu ngày, nhưng qua ngày thứ bảy là ngày sa-bát, tức là ngày nghỉ, biệt riêng ra thánh cho Ðức Giê-hô-va. Trong ngày sa-bát hễ ai làm một việc chi sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Ấy vậy, dân Y-sơ-ra-ên sẽ giữ ngày sa-bát trải các đời của họ, như một giao ước đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Ấy là một dấu đời đời cho ta cùng dân Y-sơ-ra-ên, vì Ðức Giê-hô-va đã dựng nên trời và đất trong sáu ngày, qua ngày thứ bảy Ngài nghỉ và lấy sức lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Khi Ðức Giê-hô-va đã phán xong cùng Môi-se tại núi Si-na -i, bèn cho người hai bảng chứng bằng đá, với ngón tay Ðức Chúa Trời viết ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Dân sự thấy Môi-se ở trên núi chậm xuống, bèn nhóm lại chung quanh A-rôn mà nói rằng: Nào! hãy làm các thần để đi trước chúng tôi đi, vì về phần Môi-se nầy, là người đã dẫn chúng tôi ra khỏi xứ Ê-díp-tô, chúng tôi chẳng biết điều chi đã xảy đến cho người rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'A-rôn đáp rằng: Hãy một những vòng vàng đeo nơi tai vợ, con trai và con gái các ngươi đi, rồi đem lại cho ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Hết thảy đều lột vòng vàng nơi tai mình mà đem lại cho A-rôn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'người nhận lấy nơi tay họ, và dùng đục làm thành một bò con đúc. Dân chúng nói rằng: Hỡi Y-sơ-ra-ên! nầy là các thần của ngươi đã đem ngươi ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'A-rôn thấy vậy, bèn lập một bàn thờ trước mặt tượng bò đó; đoạn, người la lên rằng: Sáng mai sẽ có lễ tôn trọng Ðức Giê-hô-va!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Sáng mai dân chúng bèn thức dậy sớm, dâng các của lễ thiêu và lễ thù ân; ngồi mà ăn uống, đoạn đứng dậy mà vui chơi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy xuống đi, vì dân mà ngươi đưa ra khỏi xứ Ê-díp-tô đã bại hoại rồi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'vội bỏ đạo ta truyền dạy, đúc một con bò tơ, mọp trước tượng bò đó và dâng của lễ cho nó mà nói rằng: Hỡi Y-sơ-ra-ên! đây là các thần đã dẫn ngươi lên khỏi xứ Ê-díp-tô!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Ðức Giê-hô-va cũng phán cùng Môi-se rằng: Ta đã xem thấy dân nầy, kìa là một dân cứng cổ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Vả, bây giờ hãy để mặc ta làm, hầu cho cơn thạnh nộ ta nổi lên cùng chúng nó, diệt chúng nó đi; nhưng ta sẽ làm cho ngươi thành một dân lớn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Môi-se bèn nài xin Giê-hô-va Ðức Chúa Trời người rằng: Lạy Ðức Giê-hô-va, sao nổi thạnh nộ cùng dân Ngài? là dân mà Ngài đã dùng quyền lớn lao mạnh mẽ đưa ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Sao để cho người Ê-díp-tô nói rằng: Ngài đưa chúng nó ra khỏi xứ đặng làm hại cho, giết đi tại trong núi, cùng diệt chúng nó khỏi mặt đất? Cầu xin Chúa hãy nguôi cơn giận và bỏ qua điều tai họa mà Ngài muốn giáng cho dân Ngài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Xin Chúa hãy nhớ lại Áp-ra-ham, Y-sác, Y-sơ-ra-ên, là các tôi tớ Ngài, mà Ngài có chỉ mình thề cùng họ rằng: Ta sẽ thêm dòng dõi các ngươi lên nhiều như sao trên trời, ta sẽ ban cho dòng dõi đó cả xứ mà ta chỉ phán, và họ sẽ được xứ ấy làm cơ nghiệp đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Ðức Giê-hô-va bèn bỏ qua điều tai họa mà Ngài nói rằng sẽ giáng cho dân mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Ðoạn, Môi-se ở trên núi trở xuống, tay cầm hai bảng chứng; hai bảng chứng có viết hai bên, mặt nầy và mặt kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Hai bảng đó là việc của Ðức Chúa Trời làm ra; chữ cũng là chữ của Ðức Chúa Trời khắc trên bảng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Vả, Giô-suê nghe dân chúng la lên, bèn nói cùng Môi-se rằng: Trong trại quân có tiếng chiến đấu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Môi-se đáp rằng: Chẳng phải tiếng kêu về thắng trận, cũng chẳng phải tiếng kêu về thua trận; nhưng ta nghe tiếng kẻ hát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Khi đến gần trại quân, Môi-se thấy bò con và sự nhảy múa, bèn nổi giận, liệng hai bảng chứng khỏi tay mịnh, bể ra nơi chân núi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'đoạn lấy bò con của chúng đã đúc đem đốt trong lửa, rồi nghiền cho đến thành ra bụi, rải trên mặt nước, và cho dân Y-sơ-ra-ên uống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Môi-se bèn nói cùng A-rôn rằng: Dân nầy làm chi anh, mà anh xui cho chúng phạm tội nặng dường ấy?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'A-rôn đáp rằng: Xin chúa tôi đừng nổi giận, chúa biết rằng dân nầy chuyên làm điều ác!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Họ có nói cùng tôi rằng: Hãy làm các thần đi trước chúng tôi; vì về phần Môi-se nầy, là người đã dẫn chúng tôi ra khỏi xứ Ê-díp-tô, chúng tôi chẳng biết có điều chi xảy đến cho người rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Tôi bèn nói cùng chúng rằng: Ai có vàng hãy lột ra! Họ bèn đưa cho tôi, tôi bỏ vào lửa, và bởi đó thành ra bò con nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Vả, Môi-se thấy dân sự buông lung, vì A-rôn để họ buông lung, đến đỗi bị sỉ nhục trong vòng các thù nghịch,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'thì người đứng nơi cửa trại quân mà nói rằng: Ai thuộc về Ðức Giê-hô-va, hãy đến cùng ta đây! Hết thảy người Lê-vi đều nhóm lại gần bên người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Người truyền cho họ rằng: Giê-hô-va, là Ðức Chúa Trời của Y-sơ-ra-ên, có phán như vầy: Mỗi người trong các ngươi hãy đeo gươm bên mình, đi qua đi lại trong trại quân, từ cửa nầy đến cửa kia, và mỗi người hãy giết anh em, bạn hữu, và kẻ lân cận mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Dân Lê-vi bèn làm y như lời Môi-se; trong ngày đó có chừng ba ngàn người bị chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Vả, Môi-se đã truyền rằng: Ngày nay mỗi người trong vòng các ngươi hãy dâng tay mình cho Ðức Giê-hô-va, chẳng sá chi đến con trai hay là anh em mình, hầu cho các ngươi được ơn phước vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Ngày mai, Môi-se nói cùng dân sự rằng: Các ngươi đã phạm một tội rất trọng; song bây giờ ta lên đến Ðức Giê-hô-va, có lẽ ta sẽ được chuộc tội các ngươi chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Vậy, Môi-se trở lên đến Ðức Giê-hô-va mà thưa rằng: Ôi! dân sự nầy có phạm một tội trọng, làm cho mình các thần bằng vàng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'nhưng bây giờ xin Chúa tha tội cho họ! Bằng không, hãy xóa tên tôi khỏi sách Ngài đã chép đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Kẻ nào phạm tội cùng ta, ta sẽ xóa nó khỏi sách ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Bây giờ, hãy đi, dẫn dân sự đến nơi ta đã chỉ phán. Nầy thiên sứ ta sẽ đi trước ngươi; nhưng ngày nào ta hình phạt thì sẽ phạt tội chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Ðức Giê-hô-va hành phạt dân sự là vậy, vì dân sự là gốc phạm về tượng bò vàng mà A-rôn đã làm ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Nầy, ngươi cùng dân sự mà ngươi đã dẫn ra khỏi xứ Ê-díp-tô hãy từ đây đi lên xứ ta đã thề ban cho Áp-ra-ham, Y-sác, và Gia-cốp, rằng: Ta sẽ ban xứ đó cho dòng dõi ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ta sẽ sai một thiên sứ đi trước ngươi, và sẽ đuổi dân Ca-na-an, dân A-mô-rít, dân Hê-tít, dân Phê-rê-sít, dân Hê-vít, và dân Giê-bu-sít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'đặng đưa các ngươi vào xứ đượm sữa và mật; nhưng ta không cùng lên với ngươi đâu, vì ngươi là dân cứng cổ, e ta diệt ngươi dọc đường chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Khi dân sự nghe lời hăm nầy, bèn đều để tang, không ai đeo đồ trang sức hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Vì Ðức Giê-hô-va đã phán cùng Môi-se rằng: Hãy nói cùng dân Y-sơ-ra-ên: Các ngươi là dân cứng cổ, nếu ta cùng lên với các ngươi chỉ trong một lúc, thì ta sẽ diệt các ngươi! Vậy, bây giờ, hãy cất đồ trang sức trong mình ngươi đi, đặng ta biết liệu đãi ngươi cách nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Thế thì, từ núi Hô-rếp, dân Y-sơ-ra-ên đã lột các đồ trang sức mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Môi-se lấy Trại đem dựng xa ra ngoài trại quân, gọi là hội mạc, phàm ai muốn cầu khẩn Ðức Giê-hô-va, thì ra đến hội mạc ở ngoài trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Vừa khi Môi-se ra đến Trại, thì cả dân sự chổi dậy, mỗi người đứng nơi cửa trại mình, ngó theo Môi-se cho đến khi nào người vào trong Trại rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Vừa khi người vào đó, thì trụ mây giáng xuống dừng tại cửa Trại, và Ðức Giê-hô-va phán cùng Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Cả dân sự thấy trụ mây dừng tại cửa Trại, bèn đứng dậy, rồi mỗi người đều sấp mình xuống nơi cửa trại mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Ðức Giê-hô-va đối diện phán cùng Môi-se, như một người nói chuyện cùng bạn hữu mình. Ðoạn, Môi-se trở về trại quân, còn kẻ hầu trẻ của người, tên là Giô-suê, con trai của Nun, không ra khỏi Trại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Môi-se thưa cùng Ðức Giê-hô-va rằng: Nầy, Chúa phán cùng tôi rằng: Hãy đem dân sự nầy lên! Song Chúa chẳng cho tôi biết Chúa sai ai đi cùng tôi. Vả, Chúa có phán rằng: Ta biết ngươi vì danh ngươi, và ngươi được ơn trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Vậy bây giờ, nếu tôi được ơn trước mặt Chúa, xin cho tôi biết đường của Chúa, để cho tôi biết Chúa và được ơn trước mặt Ngài. Xin cũng hãy nghĩ rằng dân nầy là dân của Ngài!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Ðức Giê-hô-va đáp rằng: Chính mình ta sẽ đi cùng ngươi, và ta sẽ cho ngươi an nghỉ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Môi-se thưa rằng: Nếu chính mình Ngài chẳng đi, xin đừng đem chúng tôi lên khỏi đây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Lấy cớ chi mà người ta sẽ biết rằng tôi cùng dân sự Ngài được ơn trước mặt Ngài? Có phải khi nào Ngài cùng đi với chúng tôi chăng? Thế thì, tôi cùng dân sự Ngài sẽ được phân biệt với muôn dân trên mặt đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Ta sẽ làm điều ngươi cầu xin ta, vì ngươi được ơn trước mặt ta, và ta biết ngươi bởi danh ngươi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Môi-se thưa rằng: Tôi xin Ngài cho tôi xem sự vinh hiển của Ngài!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Ðức Giê-hô-va phán ràng: Ta sẽ làm cho các sự nhân từ ta phát ra trước mặt ngươi; ta hô danh Giê-hô-va trước mặt ngươi; làm ơn cho ai ta muốn làm ơn, và thương xót ai ta muốn thương xót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Ngài lại phán rằng: Ngươi sẽ chẳng thấy được mặt ta, vì không ai thấy mặt ta mà còn sống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Ðức Giê-hô-va lại phán: Ðây có một chỗ gần ta, ngươi hãy đứng trên hòn đá;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'khi sự vinh hiển ta đi ngang qua, ta sẽ để ngươi trong bộng đá, lấy tay ta che ngươi, cho đến chừng nào ta đi qua rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Ta sẽ rút tay lại, và ngươi thấy phía sau ta; nhưng thấy mặt ta chẳng được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy đục hai bảng đá như hai bảng trước; rồi ta sẽ viết trên hai bảng nầy các lời đã ở nơi hai bảng kia, mà ngươi đã làm bể.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Ngày mai, hãy chực cho sẵn, vừa sáng lên trên đỉnh núi Si-na -i, đứng trước mặt ta tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Không ai nên lên theo cùng ngươi hết, khắp núi không nên thấy có người, và chiên, bò cũng chẳng nên ăn cỏ nơi núi nầy nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Môi-se bèn đục hai bảng đá, y như hai bảng trước; dậy sớm, cầm theo tay hai bảng đó lên trên núi Si-na -i, y như lời Ðức Giê-hô-va đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Ðức Giê-hô-va ngự xuống trong đám mây, đứng gần bên Môi-se và hô danh Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Ngài đi ngang qua mặt người, hô rằng: Giê-hô-va! Giê-hô-va! là Ðức Chúa Trời nhân từ, thương xót, chậm giận, đầy dẫy ân huệ và thành thực,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'ban ơn đến ngàn đời, xá điều gian ác, tội trọng, và tội lỗi; nhưng chẳng kể kẻ có tội là vô tội, và nhơn tội tổ phụ phạt đến con cháu trải ba bốn đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Môi-se lật đật cúi đầu xuống đất và thờ lạy, mà thưa rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Lạy Chúa! Nếu tôi được ơn trước mặt Chúa, xin hãy đi giữa chúng tôi, vì dân nầy là một dân cứng cổ. Xin hãy tha sự gian ác cùng tội lỗi, và nhận chúng tôi làm cơ nghiệp Chúa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Ðức Giê-hô-va phán rằng: Nầy, ta lập một giao ước. Trước mặt các dân sự của ngươi, ta sẽ làm các phép lạ chưa hề có làm trên cả mặt đất, hay là nơi dân nào; và toàn dân sự mà trong đó có ngươi, sẽ xem thấy việc Ðức Giê-hô, vì điều ta sẽ làm cùng ngươi là một điều đáng kinh khiếp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Hãy cẩn thận về điều ta truyền cho ngươi hôm nay. Nầy, ta sẽ đuổi khỏi trước mặt ngươi dân A-mô-rít, dân Ca-na-an, dân Hê-tít, dân Phê-rê-sít, dân Hê-vít, và dân Giê-bu-sít.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hãy cẩn thận đừng lập giao ước cùng dân của xứ mà ngươi sẽ vào, e chúng nó sẽ thành cái bẫy giữa ngươi chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Nhưng các ngươi hãy phá hủy bàn thờ, đập bể pho tượng và đánh hạ các thần chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Vì ngươi đừng sấp mình xuống trước mặt Chúa nào khác, bởi Ðức Giê-hô-va tự xưng là Ðức Chúa Trời kỵ tà; Ngài thật là một Ðức Chúa Trời kỵ tà vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Hãy cẩn thận đừng lập giao ước cùng dân của xứ đó, e khi chúng nó hành dâm cùng các tà thần chúng nó và tế các tà thần của chúng nó, có kẻ mời, rồi ngươi ăn của chúng họ chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Lại đừng cưới con gái chúng nó cho con trai ngươi, e khi con gái chúng nó hành dâm với các tà thần chúng nó, quyến dụ con trai ngươi cũng hành dâm cùng các tà thần của chúng nó nữa chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Ngươi chớ đúc thần tượng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Ngươi hãy giữ lễ bánh không men. Nhằm kỳ tháng lúa trỗ, hãy ăn bánh không men trong bảy ngày, như ta đã truyền dặn ngươi; vì nhằm tháng đó ngươi ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Các con trưởng nam đều thuộc về ta; cùng các con đực đầu lòng của bầy súc vật ngươi, hoặc bò hoặc chiên cũng vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Nhưng ngươi sẽ bắt một chiên con hay là dê con mà chuộc một con lừa đầu lòng. Nếu chẳng chuộc nó, ngươi hãy bẻ cổ nó. Ngươi sẽ chuộc các con trưởng nam mình; và chớ ai đi tay không đến chầu trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Trong sáu ngày ngươi hãy làm công việc, nhưng qua ngày thứ bảy hãy nghỉ, dẫu mùa cày hay mùa gặt ngươi cũng phải nghỉ vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Ðầu mùa gặt lúa mì, ngươi hãy giữ lễ của các tuần lễ; và cuối năm giữ lễ mùa màng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Thường năm ba lần, trong vòng các ngươi, mỗi người nam sẽ ra mắt Chúa Giê-hô-va, là Ðức Chúa Trời của Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Vì ta sẽ đuổi các dân khỏi trước mặt ngươi, ta sẽ mở rộng bờ cõi ngươi; và trong khi ngươi lên ra mắt Giê-hô-va Ðức Chúa Trời ngươi, mỗi năm ba lần, thì sẽ chẳng ai tham muốn xứ ngươi hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Ngươi chớ dâng huyết của con sinh tế ta cùng bánh pha men; thịt của con sinh về lễ Vượt-qua chớ nên giữ đến sáng mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Ngươi sẽ đem dâng hoa quả đầu mùa của đất sanh sản vào đến Giê-hô-va, là Ðức Chúa Trời ngươi. Ngươi chớ nấu thịt dê con trong sữa mẹ nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Ðức Giê-hô-va cũng phán cùng Môi-se rằng: Hãy chép các lời nầy; vì theo các lời nầy mà ta lập giao ước cùng ngươi và cùng Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Môi-se ở đó cùng Ðức Giê-hô-va trong bốn mươi ngày và bốn mười đêm, không ăn bánh, cũng không uống nước; Ðức Giê-hô-va chép trên hai bảng đá các lời giao ước, tức là mười điều răn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Khi Môi-se tay cầm hai bảng chứng đi xuống núi Si-na -i, chẳng biết rằng da mặt mình sáng rực bởi vì mình hầu chuyện Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Nhưng A-rôn cùng cả dân Y-sơ-ra-ên nhìn Môi-se thấy mặt người sáng rực, sợ không dám lại gần.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Môi-se bèn gọi họ, A-rôn cùng các hội trưởng đến gần; rồi nói chuyện cùng họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Kế sau, cả dân Y-sơ-ra-ên đến gần, người truyền dặn các điều của Ðức Giê-hô-va đã phán dặn mình nơi núi Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Môi-se thôi nói chuyện cùng họ, liền lấy lúp che mặt mình lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Khi Môi-se vào trước mặt Ðức Giê-hô-va đặng hầu chuyện Ngài, thì dở lúp lên cho đến chừng nào lui ra; đoạn ra nói lại cùng dân Y-sơ-ra-ên mọi lời Ngài đã phán dặn mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Dân Y-sơ-ra-ên nhìn mặt Môi-se thấy da mặt người sáng rực, thì Môi-se lấy lúp che mặt mình cho đến khi nào vào hầu chuyện Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Môi-se nhóm hết hội chúng Y-sơ-ra-ên lại mà nói rằng: Ðây là các việc của Ðức Giê-hô-va đã phán dạy làm:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Người ta sẽ làm công việc trong sáu ngày, nhưng đến ngày thứ bảy sẽ là một lễ thánh, tức là ngày sa-bát biệt riêng ra thánh cho Ðức Giê-hô-va. Ai làm công việc trong ngày đó sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Nhằm ngày sa-bát chớ nổi lửa trong nhà nào của các ngươi hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Môi-se nói cùng cả hội chúng Y-sơ-ra-ên rằng: Ðây là các lời Ðức Giê-hô-va đã phán dặn:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Hãy lấy một lễ vật chi ở nhà các ngươi mà dâng cho Ðức Giê-hô-va. Hễ người nào có lòng thành dâng cho, hãy đem lễ vật cho Ðức Giê-hô-va: vàng, bạc và đồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'chỉ tím, đỏ điều, đỏ sặm, vải gai mịn, lông dê,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'da chiên đực nhuộm đỏ, da cá nược, cây si-tim,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'dầu thắp, các thứ hương liệu đặng chế dầu xức và hương thơm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'bích ngọc, và các thứ ngọc khác để dùng khảm cho ê-phót và bảng đeo ngực.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Trong vòng các ngươi mấy người khôn ngoan hơn hết hãy đến làm mọi điều Ðức Giê-hô-va đã phán dặn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'đền tạm, trại và bong của đền tạm, móc, ván, xà ngang, trụ và lỗ trụ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'hòm bảng chứng và đòn khiêng, nắp thi ân cùng màn che nơi chí thánh;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'cài bàn và đòn khiêng, các đồ phụ tùng của bàn cùng bánh trần thiết;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'chân đèn, đồ phụ tùng, các đèn và dầu thắp đèn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'bàn thờ xông hương cùng đòn khiêng; dầu xức, hương liệu, và bức màn cửa đền tạm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'bàn thờ dâng của lễ thiêu và rá đồng; đòn khiêng và các đồ phụ tùng của bàn thờ; cái thùng và chân thùng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'bố vi che hành lang, trụ, lỗ trụ, và bức màn của cửa hành lang;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'các nọc của đền tạm, cùng nọc và dây của hành lang;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'bộ áo lễ dùng về công việc trong nơi thánh; bộ áo thánh cho A-rôn, thầy tế lễ cả, và bộ áo cho các con trai người đặng làm chức tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Cả hội chúng Y-sơ-ra-ên bèn lui ra khỏi mặt Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Mọi người có lòng cảm động, và mọi người có lòng thành, đều đem lễ vật đến dâng cho Ðức Giê-hô-va, để làm công việc hội mạc, các đồ phụ tùng và bộ áo thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Phàm người nam cùng nữ, tức mọi kẻ có lòng thành, đều đến đem những hoa tai, nhẫn, khâu, kiềng, các thứ trang sức bằng vàng và hết thảy đều dâng lễ vật bằng vàng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Kẻ nào ở nhà mình có chỉ tím, đỏ điều, đỏ sặm, vải gai mịn, lông dê, da chiên đực nhuộm đỏ, và da cá nược đều đem đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Hễ ai có chi làm lễ vật bằng bạc hay bằng đồng, đều đem dâng cho Ðức Giê-hô-va, và hễ ai có cây si-tim nơi nhà mình dùng hiệp về các công việc tế lễ, đều đem đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Phàm người đàn bà khéo thì chánh tay mình kéo chỉ lấy và đem đến món chi họ đã kéo rồi, chỉ tím, đỏ điều, đỏ sặm, và chỉ gai mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Còn mấy người đàn bà có cảm động và tài khéo thì kéo chỉ lông dê.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Các bực tôn trưởng trong dân sự đem bích ngọc và các thứ ngọc khác để khảm cho ê-phót và bảng đeo ngực;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'dầu thắp đèn, các hương liệu để chế dầu xức và dầu thơm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Cả dân Y-sơ-ra-ên, nam hay nữ, phàm ai có lòng cảm động xui cho mình tình nguyện quyên vào các công việc Ðức Giê-hô-va đã phán dặn nơi Môi-se, đều đem dâng cho Ðức Giê-hô-va các lễ tình nguyện vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Môi-se nói cùng dân Y-sơ-ra-ên rằng: Nầy Ðức Giê-hô-va đã kêu danh Bết-sa-lê-ên, con trai của U-ri, cháu của Hu-rơ, trong chi phái Giu-đa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Ngài phú cho người đầy dẫy Thần của Ðức Chúa Trời, sự khôn ngoan, sự thông sáng, và sự hiểu biết, để làm mọi thứ nghề thợ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'đặng bày ra và làm đồ vàng, bạc và đồng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'đặng khắc và khảm các thứ ngọc, đặng chạm cây làm các đồ khéo léo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Ngài lại phú cho người tài dạy dỗ, và cũng đồng ban cho Ô-hô-li-áp, con của A-hi-sa-mạc, trong chi phái Ðan nữa;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Ngài phú cho hai người đó đầy sự khôn ngoan đặng làm các công nghệ về thợ thêu, thợ dệt nhiều màu, tức là màu tím, đỏ điều, đỏ sặm, và vải gai mịn; để bày ra và làm các thứ công nghệ khéo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Bết-sa-lê-ên, Ô-hô-li-áp và các người khôn khéo, tức là người Ðức Giê-hô-va đã phú cho sự khôn ngoan và sự thông sáng đặng làm các công việc định dùng về việc tế lễ nơi thánh, đều làm mọi việc mà Ðức Giê-hô-va đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Vậy, Môi-se bèn gọi Bết-sa-lê-ên, Ô-hô-li-áp, và các người khôn khéo mà trong lòng họ Ðức Giê-hô-va phú sự thông sáng cùng các người có lòng cảm động xui mình đến gần, đặng làm công việc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Trước mặt Môi-se, họ thâu các lễ vật của dân Y-sơ-ra-ên đã đem đến, để làm các công việc định dùng và sự tế lễ nơi thánh. Nhưng mỗi buổi sớm mai, dân sự lại đem đến lễ vật tình nguyện nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Thế thì, các người khôn khéo làm mọi công việc của nơi thánh, đều tạm đình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'đến nỗi cùng Môi-se rằng: Dân sự đem đến dư bội phần đặng làm các công việc mà Ðức Giê-hô-va đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Theo lịnh truyền của Môi-se, họ bèn đi rao từ trại quân rằng: Bất kỳ người nam hay nữ, chớ làm công việc về lễ vật của nơi thánh nữa! Vậy họ cấm dân sự không cho đem đến chi thêm nữa hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Vì đã đủ các vật liệu đặng làm hết thảy công việc, cho đến đỗi còn dư lại nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Các người khôn khéo trong vòng những người làm công việc, dùng mười bức màn bằng vải gai đậu mịn, chỉ tím, đỏ điều, đỏ sặm, thêu hình chê-ru-bin cực xảo, mà dựng đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Mỗi bức màn đều dài hai mươi tám thước, rộng bốn thước; các bức đều đồng cỡ nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Họ kết mỗi năm bức màn dính lại nhau;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'thắt vòng bằng chỉ tím nơi triêng của bức màn thứ nhất, ở đầu bức nguyên; và cũng làm như vậy cho triêng của bức màn ở nơi chót trong bức nguyên thứ nhì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Họ thắt năm chục vòng theo triêng của bức màn ở đầu của bức nguyên thứ nhất, và năm chục vòng theo triêng bức màn ở chót của bức nguyên thứ nhì; các vòng đối nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Ðoạn chế năm chục cái móc bằng vàng, móc bức nầy với bức kia, để cho đền tạm kết lại thành một.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Kế đó, họ dùng lông dê kết mười một bức màn, để làm bong trên đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Bề dài mỗi bức màn ba mươi thước, bề rộng bốn thước: mười một bức màn đều đồng cỡ nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Họ kết năm bức màn riêng ra; và sáu bức màn khác riêng ra;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'thắt năm chục cái vòng nơi triêng bức chót của bức nguyên thứ nhất, và năm chục vòng nơi triêng bức ở đầu của bức nguyên thứ nhì;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'làm năm chục cái móc bằng đồng, móc bức bong hiệp lại thành một.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Họ cũng làm cho đền tạm một tấm lá phủ bằng da chiên đực nhuộm đỏ, và một tấm là phủ bằng da cá nược đắp lên trên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Họ dùng ván bằng cây si-tim làm vách cho đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Mỗi tấm ván mười thước về dài, một thước rưỡi bề ngang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Mỗi tấm có hai cái mộng liên nhau: cả ván đền tạm đều làm một cách.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Vậy, họ làm ván cho đền tạm: hai chục tấm về phía nam;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'dưới hai chục tấm làm bốn chục lỗ mộng bằng bạc: dưới mỗi tấm có hai lỗ mộng, để chịu hai cái mộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Họ cũng làm hai chục tấm ván ở phía bắc đền tạm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'và bốn chục lỗ mộng bằng bạc; dưới mỗi tấm có hai lỗ mộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Về phía đằng sau của đền tạm, tức là phía tây, họ làm sáu tấm ván,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'và về hai góc sau thì làm hai tấm ván.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Hai tấm ván góc ra khít với nhau từ dưới chí trên bởi một cái khoen ở nơi đầu; hai góc hai bên đều làm như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Thế thì, có tám tấm ván và mười sáu lỗ mộng bằng bạc, dưới mỗi tấm có hai lỗ mộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Họ làm năm cây xà ngang bằng gỗ si-tim cặp mấy tấm ván về phía bên nầy của đền tạm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'năm cây xà ngang khác về phía bên kia, và năm cây xà ngang khác nữa về phía sau đền tạm, tức là phía tây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Họ làm cây xà ngang giữa, đặng lòn qua thân giữa các tấm ván từ đầu nầy đến đầu kia,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'và bọc vàng mấy tấm ván. Họ làm các khoen của ván bằng vàng, đặng xỏ xà ngang qua, và bọc vàng các cây xà ngang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Họ lại chế một bức màn bằng chỉ tím, đỏ điều, đỏ sặm, và vải gai đậu mịn, thêu hình chê-ru-bin cực xảo,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'rồi làm bốn cây trụ bằng gỗ si-tim, bọc vàng, cùng đinh bằng vàng; đúc bốn lỗ trụ bằng bạc cho mấy cây trụ đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Họ cũng chế cho cửa vào Trại một tấm màn bằng chỉ tím, đỏ điều, đỏ sặm, và vải gai đậu mịn: ấy là một công việc thêu thùa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Họ cũng làm năm cây trụ cùng đinh, rồi bọc vàng trên đầu trụ, và các cây nuông; còn năm lỗ trụ thì bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Ðoạn, Bết-sa-lê-ên đóng hòm bằng cây si-tim, bề dài hai thước rưỡi, bề ngang một thước rưỡi, và bề cao một thước rưỡi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Người bọc vàng ròng bề trong và bề ngoài, cùng chạy đường viền chung quanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Ðúc bốn cái khoen vàng đặng gắn bốn góc: hai cái bên hông nầy, hai cái bên hông kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Người cũng chuốt các đòn bằng cây si-tim, bọc vàng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'rồi xỏ đòn đó vào khoen hai bên hông, đặng khiêng hòm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Người cũng làm một cái nắp thi ân bằng vàng ròng, bề dài hai thước rưỡi, bề ngang một thước rưỡi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Làm hai tượng chê-ru-bin bằng vàng đánh giát để nơi hai đầu nắp thi ân,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'một tượng ở đầu nầy và một tượng ở đầu kia, ló ra nơi hai đầu nắp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Hai chê-ru-bin sè cánh ra che trên nắp thi ân, đối diện nhau và xây mặt vào nắp thi ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Người cũng đóng một cái bàn bằng cây si-tim; bề dài hai thước, bề ngang một thước, bề cao một thước rưỡi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'bọc bằng vàng ròng, và chạy một đường viền chung quanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Lại cùng lên be cho tứ vi bàn cao chừng bốn ngón tay, và chạy cho be một đường viền vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Người đúc bốn cái khoen vàng tra vào bốn góc, tại nơi chân bàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Các khoen ở gần nơi be để xỏ đòn vào, đặng khiêng bàn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'người chuốt đòn bằng cây si-tim, bọc vàng, đặng khiêng bàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Lại cũng lấy vàng ròng mà làm các đồ dùng bày trên bàn: dĩa, chén, ly, và chậu, để dùng làm lễ quán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Người cũng làm chân đèn bằng vàng ròng; cái chân, cái thân, cái đài, cái bầu, và cái hoa đều làm ra bằng vàng đánh giát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Hai bên thân đèn có sáu nhánh nứt ra, ba nhánh ở bên nầy và ba nhánh ở bên kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Trong sáu nhánh nứt ra trên thân chân đèn, mỗi nhánh đều có ba cái đài hình như hột hạnh nhân, cùng bầu và hoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Trên thân chân đèn lại cũng có bốn cái đài hình như hột hạnh nhân, cùng bầu và hoa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Trong sáu nhánh từ thân chân đèn nứt ra, hễ cứ mỗi hai nhánh, thì dưới có một cái bầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Bầu và nhành của chân đèn đều bằng vàng ròng nguyên miếng đánh giát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Người cũng làm bảy cái thếp đèn, kéo bắt tim và đồ đựng tàn bằng vàng ròng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Người dùng một ta lâng vàng ròng, mà làm chân đèn và các đồ phụ tùng của chân đèn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Người cũng đóng một cái bàn thờ xông hương bằng cây si-tim, hình vuông, bề dài một thước, bề ngang một thước, và bề cao hai thước. Bàn thờ có bốn sừng ló ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Người bọc vàng ròng trên mặt, bốn cạnh chung quanh và các sừng; tứ vi cũng chạy dường viền vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Dưới đường viền đó, nơi hai bên góc, người làm hai cái khoen vàng để xỏ đòn, đặng khiêng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Người chuốt đòn bằng cây si-tim và bọc vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Người cũng chế dầu thánh để xức, và hương thanh sạch bằng các hương liệu theo nghề thợ chế hương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Người cũng đóng bàn thờ về của lễ thiêu bằng cây si-tim, hình vuông, bề dài năm thước, bề ngang năm thước và bề cao ba thước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Người làm nơi bốn góc bàn thờ những sừng ló ra, bọc đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Rồi làm các đồ phụ tùng của bàn thờ bằng đồng: chảo nhỏ, vá, ảng, nỉa, và bình hương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Lại làm một tấm rá bằng lưới đồng để dưới thành bàn thờ, từ chân lên đến ngang giữa,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'và đúc cái khoen cho bốn góc rá lưới đồng, đặng xỏ đòn khiêng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Ðoạn, chuốt đòn khiêng bằng cây si-tim, và bọc đồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'xỏ đòn vào khoen nơi hai bên bàn thờ, đặng khiêng bàn đi. Người đóng bàn thờ bằng ván, trống bộng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Người dùng các tấm gương của mấy người đàn bà hầu việc nơi cửa hội mạc, chế ra một cái thùng và chân thùng bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Người cũng làm hành lang: về phía nam mấy bức bố vi của hành lang bằng vải gai đậu mịn, dài trăm thước;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'hai chục cây trụ và hai chục lỗ trụ bằng đồng, đinh và nuông trụ bằng bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Về phía bắc, cũng một trăm thước bố vi, hai chục cây trụ và hai chục lỗ trụ bằng đồng, đinh và nuông trụ bằng bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Về phía tây, năm chục thước bố vi, mười cây trụ, và mười lỗ trụ bằng đồng, đinh và nuông trụ bằng bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Về phía trước, là phía đông, cũng năm chục thước:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'nghĩa là bên hữu của hành lang mười lăm thước bố vi ba cây trụ và ba lỗ trụ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'bên tả của hành lang cũng mười lăm thước bố vi, ba cây trụ và ba lỗ trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Hết thảy bố vi của hành lang ở chung quanh đều bằng vải gai đậu mịn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'các lỗ trụ bằng đồng, đinh, nuông bằng bạc, và đầu trụ bọc bạc. Hết thảy trụ của hành lang đều nhờ có nuông bạc chắp với nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Tấm màn nơi cửa hành lang làm thêu thùa bằng chỉ tím, đỏ điều, đỏ sặm, và vải gai đậu mịn; bề dài hai chục thước, bề cao (tùy theo bề khổ của vải) năm thước, đồng cỡ với bề cao của các bố vi chung quanh hành lang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Bốn cây trụ và bốn lỗ trụ bằng đồng, đinh, đồ bọc đầu trụ, và những nuông đều bằng bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Các nọc của đền tạm và của hành lang chung quanh đều bằng đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Ðây là sổ tổng cộng về đền tạm, là đền tạm chứng cớ theo lịnh truyền của Môi-se biểu người Lê-vi làm ra, nhờ Y-tha-ma, con trai của thầy tế lễ cả A-rôn, cai quản.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bết-sa-lê-ên, con trai U-ri, cháu Hu-rơ, thuộc về chi phái Giu-đa, làm theo mọi điều Ðức Giê-hô-va đã phán dặn Môi-se,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'và kẻ giúp người là Ô-hô-li-áp, con trai A-hi-sa-mạc, thuộc về chi phái Ðan, làm thợ chạm, kẻ bày vẽ, thợ thêu thùa bằng chỉ tím, đỏ điều, đỏ sặm, và bằng chỉ gai mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Hết thảy vàng đã hiệp dùng vào các công việc nơi thánh (ấy là vàng dâng) được hai mươi chín ta lâng, bảy trăm ba chục siếc-lơ, theo siếc-lơ của nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Bạc của mấy người hội chúng có kể sổ tổng cộng được một trăm ta lâng, một ngàn bảy trăm bảy mươi lăm siếc-lơ, theo siếc-lơ của nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Hết thảy người nào có kể sổ, từ hai mươi tuổi sắp lên, nghĩa là sáu trăm ba ngàn năm trăm năm chục người, mỗi người nộp nửa siếc-lơ, theo siếc-lơ của nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Vậy, phải một trăm ta lâng bạc đặng đúc các lỗ trụ của nơi thánh, và lỗ trụ màn; một trăm ta lâng cho một trăm lỗ trụ, tức một ta lâng vào mỗi lỗ trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Còn một ngàn bảy trăm bảy mươi lăm siếc-lơ dư lại, thì dùng làm đinh trụ, bọc đầu trụ và lấy nuông chắp các trụ với nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Ðồng đem dâng cộng được bảy chục ta lâng, hai ngàn bốn trăm siếc-lơ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Họ dùng đồng đó làm lỗ trụ của cửa hội mạc, bàn thờ bằng đồng, rá bằng đồng, các đồ phụ tùng của bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'các lỗ trụ của hành lang chung quanh, các lỗ trụ của cửa hành lang, các nọc của đền tạm, và các nọc của hành lang chung quanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Họ dùng chỉ màu tím, đỏ điều, đỏ sặm mà chế bộ áo định cho sự tế lễ trong nơi thánh, và bộ áo thánh cho A-rôn, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Vậy, họ chế ê-phót bằng kim tuyến, chỉ tím, đỏ điều, đỏ sặm, và vải gai đậu mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Họ căng vàng lá ra, cắt thành sợi chỉ mà xen cùng chỉ tím, đỏ điều, đỏ sặm, và chỉ gai mịn, chế thật cực xảo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Họ may hai đai vai ê-phót, đâu hai đầu dính lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Ðai để cột ê-phót, phía ngoài, làm nguyên miếng một y như công việc của ê-phót: bằng kim tuyến, chỉ tím, đỏ điều, đỏ sặm, và bằng chỉ gai đậu mịn, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Họ khảm trong khuôn vàng các bích ngọc có khắc tên các chi phái Y-sơ-ra-ên, như người ta khắc con dấu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Họ để các ngọc đó trên đai vai ê-phót đặng làm ngọc kỷ niệm về dân Y-sơ-ra-ên, y như lời Ðức Giê-hô-va phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Họ cũng chế bảng đeo ngực cực xảo, như công việc ê-phót: bằng kim tuyến, chỉ tím, đỏ điều, đỏ sặm, và chỉ gai đậu mịn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Bảng đeo ngực may lót, hình vuông, bề dài một em-ban, bề ngang một em-ban.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Họ nhận bốn hàng ngọc: hàng thứ nhất, ngọc mã não, ngọc hồng bích, và ngọc lục bửu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'hàng thứ nhì, ngọc phỉ túy, ngọc lam bửu, và ngọc kim cương;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'hàng thứ ba, ngọc hồng bửu, ngọc bạch mã não, và ngọc tử tinh;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'hàng thứ tư, ngọc huỳnh bích, ngọc hồng mã não, và bích ngọc. Các ngọc nầy đều khảm vàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Số ngọc là mười hai, tùy theo số danh của các con trai Y-sơ-ra-ên. Mỗi viên ngọc có khắc một tên trong mười hai chi phái Y-sơ-ra-ên như người ta khắc con dấu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Ðoạn, trên bảng đeo ngực họ chế các sợi chuyền bằng vàng ròng, đánh lại như hình dây.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Cũng làm hai cái móc và hai cái khoanh bằng vàng, để hai khoanh nơi hai góc đầu bảng đeo ngực;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'cùng cột hai sợi chuyền vàng vào hai khoanh đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Rồi chuyền hai đầu của hai sợi chuyền vào móc gài nơi đai vai ê-phót, về phía trước ngực.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Cũng làm hai khoanh vàng khác để vào hai góc đầu dưới của bảng đeo ngực, về phía trong ê-phót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Lại làm hai khoanh vàng khác nữa để nơi đầu dưới của hai đai vai ê-phót, về phía trước, ở trên đai, gần chỗ giáp mối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Họ lấy một sợi dây màu tím, cột hai cái khoanh của bảng đeo ngực lại cùng hai cái khoanh ê-phót, hầu cho nó dính với đai và đừng rớt khỏi ê-phót, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Họ cũng chế áo dài của ê-phót bằng vải thường toàn màu tím.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Cổ để tròng đầu vào, ở về chính giữa áo, như lỗ áo giáp, có viền chung quanh cho khỏi tét.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Nơi trôn áo, thắt những trái lựu bằng chỉ xe mịn màu tím, đỏ điều, đỏ sặm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'lại làm chuông nhỏ bằng vàng ròng, gắn giữa hai trái lựu, vòng theo chung quanh trôn áo;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'cứ một trái lựu, kế một cái chuông nhỏ, vòng theo chung quanh trôn áo dùng để hầu việc, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Họ cũng chế áo lá mặc trong bằng vải gai mịn, dệt thường, cho A-rôn cùng các con trai người;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'luôn cái mũ, đồ trang sức của mũ, và quần lót trong, đều bằng vải gai đậu mịn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'cùng cái đai bằng vải gai đậu mịn, chỉ tím, đỏ điều, đỏ sặm, có thêu, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Họ cũng dùng vàng lá ròng chế cái thẻ thánh, khắc trên đó như người ta khắc con dấu, rằng: Thánh Cho Ðức Giê-hô-va!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Rồi lấy một sợi dây tím đặng cột để trên mũ, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Các công việc của đền tạm và hội mạc làm xong là như vậy. Dân Y-sơ-ra-ên làm y như mọi lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Họ đem đền tạm đến cho Môi-se: Trại và các đồ phụ tùng của Trại, nọc, ván, xà ngang, trụ và lỗ trụ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'bong da chiên đực nhuộm đỏ, bong da cá nược và cái màn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'hòm bảng chứng và đòn khiêng, cùng nắp thi ân;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'bàn và đồ phụ tùng của bàn cùng bánh trần thiết;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'chân đèn bằng vàng ròng, thếp đèn đã sắp sẵn, các đồ phụ tùng của chân đèn và dầu thắp,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'bàn thờ bằng vàng, dầu xức, hương liệu, tấm màn của cửa Trại;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'bàn thờ bằng đồng và rá đồng, đòn khiêng, các đồ phụ tùng của bàn thờ, thùng và chân thùng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'các bố vi của hành lang, trụ, lỗ trụ, màn của cửa hành lang, dây, nọc, hết thảy đồ phụ tùng về việc tế lễ của đền tạm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'bộ áo lễ đặng hầu việc trong nơi thánh, bộ áo thánh cho A-rôn, thầy tế lễ cả, và bộ áo của các con trai người để làm chức tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Dân Y-sơ-ra-ên làm mọi công việc nầy y như mạng lịnh của Ðức Giê-hô-va đã truyền cho Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Môi-se xem các công việc làm, thấy họ đều làm y như lời Ðức Giê-hô-va đã phán dặn; đoạn Môi-se chúc phước cho họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Ngày mồng một tháng giêng, ngươi sẽ dựng đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Hãy để trong đó cái hòm bảng chứng, rồi lấy màn phủ lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Cũng hãy đem bàn đến, chưng bày các đồ trên bàn cho có thứ tự, cùng chân đèn và thắp các đèn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'cũng hãy để bàn thờ bằng vàng dùng xông hương trước hòm bảng chứng, rồi xủ tấm màn nơi cửa đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Cũng hãy để bàn thờ về của lễ thiêu đằng trước cửa đền tạm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'và để cái thùng ở giữa khoảng hội mạc và bàn thờ; rồi đổ nước vào;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'lại chừa hành lang chung quanh và xủ tấm màn nơi cửa hành lang.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Ðoạn, ngươi hãy lấy dầu xức mà xức đền tạm và các đồ để trong đó; biệt riêng đền tạm ra thánh, thì sẽ làm thánh vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Cũng hãy xức dầu bàn thờ về của lễ thiêu, và các đồ phụ tùng của bàn thờ; rồi biệt riêng ra thánh, thì bàn thờ sẽ làm rất thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Cũng hãy xức dầu cho thùng và chân thùng; biệt thùng riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Ðoạn, hãy dẫn A-rôn cùng các con trai người đến gần cửa hội mạc, rồi tắm họ trong nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Ngươi hãy mặc áo thánh cho A-rôn, xức dầu và biệt người riêng ra thánh; vậy người sẽ làm chức tế lễ trước mặt ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Hãy dẫn các con trai người đến gần, rồi mặc áo lá cho họ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'xức dầu cho như ngươi đã xức cho cha họ, thì họ sẽ làm chức tế lễ trước mặt ta. Sự xức dầu sẽ phong cho họ chức tế lễ mãi mãi trải qua các đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Môi-se làm y như mọi điều Ðức Giê-hô-va đã phán dặn mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Ðến ngày mồng một tháng giêng về năm thứ hai, thì đền tạm đã dựng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Môi-se dựng đền tạm, để mấy lỗ trụ, đóng ván, thả xà ngang và dựng trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Người căng bong trên đền tạm, rồi trải lá phủ bong lên trên, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Ðoạn, người cũng lấy bảng chứng, để trong hòm, xỏ đòn khiêng vào, để nắp thi ân lên trên hòm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Người khiêng hòm vào đền tạm và treo màn để che chỗ chí thánh, phủ hòm bảng chứng lại, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Người cũng để cái bàn trong hội mạc, về phía bắc đền tạm ở ngoài bức màn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'rồi sắp một hàng bánh ở trên, trước mặt Ðức Giê-hô-va, y như lời Ngài đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Ðể chân đèn trong hội mạc về phía nam, đối diện cùng cái bàn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Người thắp đèn trước mặt Ðức Giê-hô-va, y như lời Ngài đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Ðể bàn thờ bằng vàng trước bức màn trong hội mạc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'trên đó người xông hương, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Người cũng xủ màn nơi cửa đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Ðoạn, người để bàn thờ về của lễ thiêu nơi cửa đền tạm, dâng trên đó của lễ thiêu và của lễ chay, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Cũng để thùng về giữa khoảng hội mạc và bàn thờ, cùng đổ nước vào đặng tắm rửa;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Môi-se, A-rôn cùng các con trai của A-rôn, rửa tay và chân mình vào đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Khi nào họ vào hội mạc và lại gần bàn thờ thì rửa mình, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Chung quanh đền tạm và bàn thờ, người cũng chừa hành lang, và xủ màn nơi cửa hành lang. Ấy, Môi-se làm xong công việc là như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Áng mây bao phủ hội mạc và sự vinh hiển của Ðức Giê-hô-va đầy dẫy đền tạm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'cho đến nỗi Môi-se vào chẳng đặng, vì áng mây bao phủ ở trên và sự vinh hiển của Ðức Giê-hô-va đầy dẫy đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Vả, trong các sự hành trình của dân Y-sơ-ra-ên, khi nào áng mây từ đền tạm ngự lên thì họ ra đi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'còn nếu áng mây không ngự lên thì họ cũng không đi, cho đến ngày nào áng mây ngự lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Vì trong các sự hành trình của dân Y-sơ-ra-ên, thì áng mây của Ðức Giê-hô-va ở trên đền tạm ban ngày, và có lửa ở trên đó ban đêm hiện trước mặt cả dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Ðức Giê-hô-va từ trong hội mạc gọi Môi-se mà phán rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Hãy nói cùng dân Y-sơ-ra-ên rằng: Khi người nào trong vòng các ngươi dâng của lễ cho Ðức Giê-hô-va, thì phải dâng súc vật, hoặc bò, hoặc chiên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Nếu lễ vật của ngươi là của lễ thiêu bằng bò, thì phải dùng con đực không tì vít, dâng lên tại cửa hội mạc, trước mặt Ðức Giê-hô-va, để được Ngài đẹp lòng nhậm lấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Ngươi sẽ nhận tay mình trên đầu con sinh, nó sẽ được nhậm thế cho, hầu chuộc tội cho người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Ðoạn, người sẽ giết bò tơ trước mặt Ðức Giê-hô-va, rồi các con trai A-rôn, tức những thầy tế lễ, sẽ dâng huyết lên, và rưới chung quanh trên bàn thờ tại nơi cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Kế đó, lột da con sinh, và sả thịt ra từng miếng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Các con trai thầy tế lễ A-rôn sẽ châm lửa trên bàn thờ, chất củi chụm lửa;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'rồi các con trai A-rôn, tức những thầy tế lễ sắp các miếng thịt, đầu và mỡ lên trên củi đã chụm lửa nơi bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Người sẽ lấy nước rửa bộ lòng và giò, rồi thấy tế lễ đem hết mọi phần xông nơi bàn thờ; ấy là của lễ thiêu, tức một của lễ dùng lữa dâng lên, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Nếu lễ vật người là của lễ thiêu bằng súc vật nhỏ, hoặc chiên hay dê, thì phải dâng một con đực không tì vít,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'giết nó nơi hướng bắc của bàn thờ, trước mặt Ðức Giê-hô-va; rồi các con trai A-rôn, tức những thầy tế lễ, sẽ rưới huyết chung quanh trên bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'sả thịt từng miếng, để riêng đầu và mỡ ra; thầy tế lễ sẽ chất các phần đó trên củi đã chụm lửa nơi bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Người sẽ lấy nước rửa bộ lòng và giò; đoạn thầy tế lễ dâng và xông hết mọi phần trên bàn thờ; ấy là của lễ thiêu, tức một của lễ dùng lửa dâng lên, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Nếu lễ vật người dâng cho Ðức Giê-hô-va là một của lễ thiêu bằng chim, thì phải dùng cu đất hay là bò câu con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Thầy tế lễ sẽ đem nó đến bàn thờ, vặn rứt đầu ra, rồi xông trên bàn thờ; vắt huyết chảy nơi cạnh bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Người sẽ gỡ lấy cái diều và nhổ lông, liệng gần bàn thờ, về hướng đông, là chỗ đổ tro;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'đoạn xé nó ra tại nơi hai cánh, nhưng không cho rời, rồi thầy tế lễ sẽ đem xông trên bàn thờ, tại trên củi đã chụm lửa; ấy là của lễ thiêu, tức một của lễ dùng lửa dâng lên, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Khi nào ai dâng cho Ðức Giê-hô-va một của lễ chay, thì lễ vật người phải bằng bột lọc có chế dầu, và để nhũ hương lên trên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Người sẽ đem đến cho các con trai A-rôn, tức những thầy tế lễ; thầy tế lễ sẽ lấy một nắm bột lọc chế dầu và hết thảy nhũ hương, đem xông làm kỷ niệm trên bàn thờ; ấy là một của lễ dùng lửa dâng lên, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Phần chi trong của lễ chay còn lại sẽ thuộc về A-rôn và các con trai người; ấy là một vật chí thánh trong các của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Khi nào ngươi dùng vật chi hấp lò làm của lễ chay, thì phải lấy bột mịn làm bánh nhỏ không men nhồi dầu, và bánh tráng không men thoa dầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Nếu ngươi dùng vật chiên trong chảo đặng làm của lễ chay, thì phải bằng bột mịn không pha men, nhồi với dầu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'bẻ ra từ miếng và chế dầu trên. Ấy là của lễ chay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Nếu ngươi dùng vật chiên trong chảo lớn đặng làm của lễ chay, thì phải bằng bột mịn với dầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Của lễ chay đã sắm sửa như cách nầy, ngươi sẽ đem dâng cho Ðức Giê-hô-va, giao cho thầy tế lễ, và ngươi sẽ đem đến bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Thầy tế lễ sẽ lấy ra phần phải dâng làm kỷ niệm, xông trên bàn thờ; ấy là một của lễ dùng lửa dâng lên, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Phần chi trong của lễ chay còn lại sẽ thuộc về A-rôn và các con trai người; ấy là một vật chí thánh trong các của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Hễ của lễ chay các ngươi dâng cho Ðức Giê-hô-va, thì chớ dâng với men; vì các ngươi chớ dùng men hay mật xông với của lễ chi dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Các ngươi được dâng những vật đó cho Ðức Giê-hô-va như của lễ đầu mùa; nhưng chẳng nên đốt trên bàn thờ như của lễ có mùi thơm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Phải nêm muối các của lễ chay; chớ nên dâng lên thiếu muối; vì muối là dấu hiệu về sự giao ước của Ðức Chúa Trời đã lập cùng ngươi; trên các lễ vật ngươi phải dâng muối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Nếu ngươi dùng hoa quả đầu mùa đặng làm của lễ chay tế Ðức Giê-hô-va, thì phải bằng gié lúa rang, hột lúa mới tán ra,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'đổ dầu vào và thêm nhũ hương. Ấy là của lễ chay.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Ðoạn, thầy tế lễ lấy một phần hột tán ra với dầu và hết thảy nhũ hương mà xông làm kỷ niệm. Ấy là của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Phàm khi nào ai dâng của lễ thù ân bằng bò, hoặc đực hoặc cái, thì phải dâng lên trước mặt Ðức Giê-hô-va, không tì vít chi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Người sẽ nhận tay mình trên đầu con sinh của mình, rồi giết nó tại cửa hội mạc; các con trai A-rôn, tức những thầy tế lễ, sẽ rảy huyết chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Do của lễ thù ân nầy, người sẽ dâng làm của lễ dùng lửa dâng cho Ðức Giê-hô-va, mỡ chài và mỡ bộ lòng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'hai trái cật, mỡ trên hai trái cật nơi cạnh hông, và tấm da mỏng bọc gan, gỡ gần nơi hai trái cật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Các con trai A-rôn sẽ xông mấy món đó nơi bàn thờ trên của lễ thiêu đã chất trên củi chụm lửa rồi; ấy là một của lễ dùng lửa dâng lên, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Nếu người dâng cho Ðức Giê-hô-va của lễ thù ân bằng chiên, hoặc đực hoặc cái, thì phải dâng lên không tì vít chi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Vì của lễ bằng chiên con thì phải dâng nó lên trước mặt Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'nhận tay mình trên đầu con sinh, rồi giết nó trước cửa hội mạc; các con trai A-rôn sẽ rảy huyết chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Do của lễ thù ân nầy, người phải dâng làm của lễ dùng lửa dâng cho Ðức Giê-hô-va, mỡ và cái đuôi nguyên, chặt gần cuối xương sống, mỡ chài và mỡ bộ lòng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'hai trái cật, mỡ trên hai trái cật nơi cạnh hông, và tấm da mỏng bọc gan, gỡ gần nơi hai trái cật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Thầy tế lễ sẽ xông các món đó trên bàn thờ; ấy là thực vật về của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Nếu của lễ người bằng con dê cái, thì phải dâng lên trước mặt Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'nhận tay mình trên đầu con sinh, rồi giết nó trước hội mạc; các con trai A-rôn sẽ rảy huyết chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Do của lễ thù ân nầy, người phải dâng làm của lễ dùng lửa dâng cho Ðức Giê-hô-va, mỡ chài và mỡ bộ lòng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'hai trái cật, mỡ trên hai trái cật nơi cạnh hông và tấm da mỏng bọc gan, gỡ gần nơi hai trái cật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Thầy tế lễ sẽ xông các món đó trên bàn thờ; ấy là thực vật về của lễ dùng lửa dâng lên có mùi thơm. Hết thảy mỡ đều thuộc về Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Ấy đó là luật lệ đời đời cho dòng dõi các ngươi, mặc dầu ở nơi nào: ngươi chẳng nên ăn mỡ hay là huyết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Hãy nói cùng dân Y-sơ-ra-ên rằng: Khi nào ai lầm lỡ mà phạm một trong các điều răn của Ðức Giê-hô-va, và làm điều chẳng nên làm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'nếu là thầy tế lễ chịu xức dầu rồi mà phạm tội, và vì cớ đó gây cho dân sự phải mắc tội, thì vì tội mình đã phạm, người phải dâng cho Ðức Giê-hô-va một con bò tơ không tì vít chi, đặng làm của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Người sẽ dẫn bò tơ đó đến cửa hội mạc trước mặt Ðức Giê-hô-va, nhận tay mình trên đầu nó, rồi giết nó trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Thầy tế lễ chịu xức dầu rồi sẽ lấy huyết bò tơ đem vào trong hội mạc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'nhúng ngón tay mình trong huyết, rảy bảy lần trước mặt Ðức Giê-hô-va, đối ngang bức màn nơi đền thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Ðoạn, thầy tế lễ sẽ bôi huyết trên các sừng của bàn thờ xông hương ở trong hội mạc, trước mặt Ðức Giê-hô-va, và đổ hết thảy huyết bò tơ nơi chân bàn thờ về của lễ thiêu, để trước cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Người phải gỡ những mỡ của con bò dùng làm của lễ chuộc tội, tức là mỡ chài và mỡ bộ lòng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'hai trái cật, mỡ trên hai trái cật nơi cạnh hông, tấm da mỏng bọc gan, gỡ gần nơi hai trái cật,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'như gỡ các phần nầy của bò tơ dùng làm của lễ thù ân; rồi thầy tế lễ sẽ xông các món đó trên bàn thờ về của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Còn da, hết thảy thịt, đầu, giò, bộ lòng và phẩn,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'tức con bò tơ nguyên, người phải đem ra khỏi trại quân đến một nơi tinh sạch, là chỗ họ đổ tro, rồi chất trên củi nơi lửa và thiêu nó đi: tức là thiêu nó tại chỗ đổ tro vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Nếu cả hội chúng Y-sơ-ra-ên vì lầm lỡ phạm một trong các điều răn của Ðức Giê-hô-va, và làm điều không nên làm, mà vốn không tự biết, và vì cớ đó phải mắc tội;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'nếu tội phạm ấy vừa mới lộ ra, thì hội chúng phải dâng một con bò tơ đặng làm của lễ chuộc tội, dẫn nó đến trước hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Các hội trưởng phải nhận tay mình trên đầu bò tơ, rồi giết nó trước mặt Ðức Giê-hô-va;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'thầy tế lễ chịu xức dầu rồi sẽ đem huyết con bò tơ vào hội mạc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'nhúng ngón tay mình trong huyết, rảy bảy lần trước mặt Ðức Giê-hô-va, đối ngang bức màn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Ðoạn, người sẽ bôi huyết trên các sừng của bàn thờ trong hội mạc trước mặt Ðức Giê-hô-va, rồi đổ huyết hết dưới chân bàn thờ về của lễ thiêu, để trước cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Người cũng gỡ hết thảy mỡ đem xông trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Cách dâng con bò tơ nầy cũng như cách dâng con bò dùng làm lễ chuộc tội: ấy vậy, thầy tế lễ sẽ chuộc tội cho hội chúng và tội hội chúng sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Ðoạn, người phải đem con bò tơ đó ra ngoài trại quân, thiêu đi như đã thiêu con bò tơ trước: ấy là của lễ chuộc tội cho hội chúng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Ví bằng một quan trưởng nào, vì lẫm lỡ phạm một trong các điều răn của Ðức Giê-hô-va, là Ðức Chúa Trời mình, mà làm điều không nên làm, và vì cớ đó mắc tội;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'khi nào người ta tỏ ra cho quan trưởng đó biết tội mình đã phạm, thì người phải dẫn đến làm của lễ mình, một con dê đực không tì vít chi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'nhận tay mình trên đầu dê đực đó, rồi giết nó trước mặt Ðức Giê-hô-va tại nơi giết các con sinh dùng làm của lễ thiêu: ấy là của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Thầy tế lễ sẽ nhúng ngón tay mình trong huyết của con sinh tế chuộc tội, bôi trên các sừng bàn thờ về của lễ thiêu, và đổ huyết dưới chân bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'đoạn xông hết mỡ trên bàn thờ như cách xông mỡ về của lễ thù ân. Ấy vậy, thầy tế lễ sẽ chuộc tội cho người, và tội người sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Nếu một người nào trong dân chúng, vì lẫm lỡ phạm một trong các điều răn của Ðức Giê-hô-va mà làm điều không nên làm, và vì cớ đó phải mắc tội;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'khi nào người ta tỏ cho người đó biết tội mình đã phạm, thì người phải vì cớ tội mình dẫn đến một con dê cái không tì vít chi, dùng làm của lễ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'nhận tay mình trên đầu con sinh tế chuộc tội, rồi giết nó trong nơi giết con sinh dùng làm của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Thầy tế lễ sẽ nhúng ngón tay mình trong huyết, bôi trên các sừng bàn thờ về của lễ thiêu, và đổ hết huyết dưới chân bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'rồi, gỡ hết mỡ như cách gỡ mỡ về của lễ thù ân, đem xông trên bàn thờ, làm của lễ có mùi thơm dâng cho Ðức Giê-hô-va. Ấy vậy, thầy tế lễ sẽ chuộc tội cho người đó, thì tội người sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Nếu của lễ chuộc tội người bằng chiên con, thì phải dâng một con cái chẳng tì vít chi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'nhận tay mình trên đầu con sinh tế chuộc tội, rồi giết nó tại nơi giết con sinh dùng làm của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Ðoạn, thầy tế lễ sẽ nhúng ngón tay mình trong huyết, bôi trên các sừng bàn thờ về của lễ thiêu, và đổ hết huyết dưới chân bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'gỡ hết mỡ như cách gỡ mỡ của chiên con dùng làm của lễ thù ân, đem xông trên bàn thờ như các của lễ dùng lửa dâng cho Ðức Giê-hô-va. Ấy vậy, thầy tế lễ sẽ chuộc tội cho người đó, thì tội người sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Khi người nào làm chứng bị bắt thề rồi, và phạm tội vì không tỏ ra điều mình đã thấy hay là đã biết, thì người đó sẽ mang tội mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Khi ai sẽ đụng đến một vật ô uế, hoặc thây của con thú nhà không tinh sạch, hoặc thây của con thú rừng không tinh sạch, hoặc thây của loài côn trùng nào không tinh sạch, mà không tự biết, thì sẽ bị ô uế và mắc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Khi ai, hoặc tự biết hay không biết, sẽ đụng đến sự ô uế nào của loài người, không cứ bị ô uế cách nào, thì cũng sẽ mắc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Khi ai nói sơ ý thề thốt làm ác hay là làm thiện, mặc dầu cách nào, trước không ngờ đến, rồi sau lại tự biết, thì ai đó sẽ mắc tội trong điều nầy hay là điều kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Vậy, khi nào ai mắc tội về một trong các điều nầy, thì phải xưng mình phạm tội chi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'rồi vì tội mình đã phạm, dẫn đến Ðức Giê-hô-va một con cái trong bầy súc vật nhỏ, hoặc chiên cái hay là dê cái, đặng làm của lễ chuộc tội; thì thầy tế lễ sẽ làm lễ chuộc tội cho người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Nếu không phương thế lo cho có một chiên cái hay là một dê cái được, thì phải vì tội mình đã phạm, đem đến cho Ðức Giê-hô-va một cặp cu hay là cặp bồ câu con: một con dùng làm của lễ chuộc tội, một con dùng làm của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Người sẽ đem cặp đó đến cho thầy tế lễ; thầy tế lễ sẽ dâng trước con dùng làm của lễ chuộc tội, vặn rứt đầu gần nơi gáy cổ không gãy lìa ra;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'đoạn rảy huyết của con sinh tế chuộc tội trên một phía của bàn thờ; huyết còn dư lại thì vắt dưới chân bàn thờ; ấy là một của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Còn chim kia, người phải tùy theo lệ đã định, dùng làm một của lễ thiêu. Ấy vậy, thầy tế lễ sẽ vì người đó làm lễ chuộc tội người đã phạm, thì tội người sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Nếu không phương thế lo cho có một cặp cu hay là cặp bồ câu con được, thì người vì tội mình đã phạm, phải đem một phần mười ê-pha bột lọc làm của lễ chuộc tội, không nên đổ dầu trên và cũng không nên thêm nhũ hương, vì là một của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Người sẽ đem bột đó đến thầy tế lễ; thầy tế lễ sẽ bốc một nắm làm kỷ niệm. và xông trên bàn thờ như cách xông của lễ dùng lửa dâng cho Ðức Giê-hô-va: ấy là một của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Ấy vậy, thầy tế lễ sẽ vì người đó làm lễ chuộc tội người đã phạm về một trong mấy điều nầy, thì tội người sẽ được tha; bột còn dư lại sẽ thuộc về thầy tế lễ như trong cuộc của lễ chay vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Khi nào ai ở bất trung, lầm lỡ phạm đến vật thánh của Ðức Giê-hô-va, thì ai đó vì sự mắc lỗi mình, phải dẫn đến Ðức Giê-hô-va một con chiên đực không tì vít chi bắt ở trong bầy, đánh giá bằng siếc-lơ bạc, tùy theo siếc-lơ của đền thánh: ấy sẽ là một của lễ chuộc sự mắc lỗi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Người đó phải bồi thường và phụ thêm một phần năm giá trị của vật mình đã phạm đến nơi đền thánh, rồi giao vật đó cho thầy tế lễ. Thầy tế lễ sẽ dùng chiên con đực về của lễ chuộc sự mắc lỗi mà làm lễ chuộc tội cho người ấy, và tội người sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Khi nào ai phạm một trong các điều răn của Ðức Giê-hô-va mà không tự biết, và làm điều không nên làm, thì ai dó sẽ mắc lỗi và mang lấy tội mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Người vì sự lỗi mình phải dẫn đến thầy tế lễ một con chiên đực, không tì vít chi bắt trong bầy, tùy theo ý ngươi đánh giá; rồi thầy tế lễ sẽ làm lễ chuộc lỗi cho người đã lầm lỡ phạm tội và không tự biết, thì lỗi người sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Ấy là của lễ chuộc sự mắc lỗi: người hẳn phải mắc lỗi cùng Ðức Giê-hô-va vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Khi nào ai mắc tội phạm đến Ðức Giê-hô-va, hoặc nói dối cùng người lân cận mình về đồ vật gởi hay là tin mà giao cho, hoặc về một tài vật trộm cắp, hoặc giựt lấy của người lân cận mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'hoặc nếu xí được một của mất mà nói dối về của đó, hoặc thề dối về một trong các việc người ta phạm tội được;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'khi nào đã phạm và mắc lỗi như vậy, thì phải trả lại vật mình đã ăn cắp, hoặc vật đã giựt lấy, hoặc vật đã tin gởi cho, hoặc vật làm mất xí được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'hoặc về các món người đã thề dối: người phải thường nguyên lại và phụ thêm một phần năm giá trị mà giao cho chủ vật đó ngày nào mình dâng của lễ chuộc sự mắc lỗi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Tùy theo sự đánh giá của ngươi, người ấy phải bắt trong bầy một chiên đực không tì vít chi, dẫn đến thầy tế lễ mà dâng cho Ðức Giê-hô-va đặng làm của lễ chuộc sự mắc lỗi mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'thầy tế lễ sẽ làm lễ chuộc tội cho người trước mặt Ðức Giê-hô-va, thì lỗi người sẽ được tha, bất luận lỗi nào người đã mắc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Hãy truyền lịnh nầy cho A-rôn cùng các con trai người: Nầy là luật về của lễ thiêu: Của lễ thiêu phải ở trên đống lửa tại bàn thờ trọn đêm cho đến sáng mai, và lửa của bàn thờ giữ cho cháy luôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Thầy tế lễ sẽ mặc áo lá trong và quần bằng vải gai che thân mình, rồi hốt tro của lửa đã đốt của lễ thiêu trên bàn thờ, và đổ gần bên bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'đoạn cổi áo nầy, mặc áo khác, đem tro nầy ra ngoài trại quân, đổ trong một nơi tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Lửa trên bàn thờ phải cháy luôn luôn, không nên tắt. Mỗi buổi sáng thầy tế lễ sẽ lấy củi chụm lửa thêm, sắp của lễ thiêu lên trên, và xông những mỡ về của lễ thù ân tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Lửa hằng cháy luôn luôn trên bàn thờ, chẳng nên tắt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Ðây là luật về của lễ chay: Các con trai A-rôn phải dâng của lễ nầy tại phía trước bàn thờ, trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Họ sẽ lấy một nắm bột lọc trong của lễ chay và dầu, cùng hết thảy nhũ hương ở trên, đem xông trên bàn thờ làm kỷ niệm về một của lễ có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Phần còn dư lại, A-rôn và các con trai người sẽ ăn không pha men, tại một nơi thánh, tức là ăn tại hành lang của hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Họ không nên nấu bột đó với men; ấy là phần ta cho họ do trong các của lễ ta, dùng lửa dâng lên; thật là một vật chí thánh như của lễ chuộc tội và của lễ chuộc sự mắc lỗi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Phàm người nam trong vòng con cái A-rôn, sẽ ăn lấy; ấy là một luật lệ đời đời cho dòng dõi các ngươi về những của lễ dùng lửa dâng cho Ðức Giê-hô-va: ai đụng đến những của lễ đó sẽ nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Nầy là của lễ A-rôn và các con trai người phải dâng cho Ðức Giê-hô-va trong ngày họ chịu phép xức dầu: Một phần mười ê-pha bột lọc làm của lễ chay thường thường; sáng một phân nửa, chiều một phân nửa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Của lễ đó sẽ chiên sẵn trên chảo trộn với dầu; chín rồi, ngươi phải đem đến cắt ra từ miếng sẵn dâng lên có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Con trai nào của A-rôn chịu xức dầu đặng thế cho người làm thầy tế lễ cũng phải dâng của lễ nầy. Ấy là một luật lệ đời đời trước mặt Ðức Giê-hô-va: họ phải xông hết trọn của lễ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Phàm của lễ chay của thầy tế lễ nào thì phải đốt hết, không nên ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Hãy truyền cho A-rôn và các con trai người rằng: Ðây là luật về của lễ chuộc tội: Phải giết con sinh tế chuộc tội trước mặt Ðức Giê-hô-va tại nơi người ta giết con sinh về của lễ thiêu; ấy là một vật chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Thầy tế lễ đứng dâng con sinh tế chuộc tội, phải ăn thịt nó trong một nơi thánh, tức là trong hành lang của hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Hễ ai đụng đến thịt con sinh sẽ nên thánh, và nếu huyết nó văng trên áo nào, thì phải giặt áo đó trong một nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Nồi đất dùng nấu thịt đó sẽ đập bể đi, nếu nồi nấu bằng đồng thì sẽ cạo và rửa nước cho sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Hễ người nam trong vòng những thầy tế lễ sẽ ăn thịt đó: ấy là một vật chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Nhưng chẳng nên ăn thịt con sinh tế chuộc tội có huyết nó đem vào hội mạc đặng làm lễ chuộc tội nơi đền thánh: hãy đốt nó đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Ðây là luật lệ về của lễ chuộc sự mắc lỗi, ấy là một vật chí thánh:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Trong nơi người ta giết con sinh dùng làm của lễ thiêu, thì hãy giết con sinh tế chuộc sự mắc lỗi, rồi rưới huyết ở chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Ðoạn dâng hết thảy mỡ, đuôi và mỡ chài,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'hai trái cật và mỡ hai trái cật nơi cạnh hông và tấm da mỏng bọc gan, gỡ gần nơi hai trái cật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Thầy tế lễ sẽ xông hết trên bàn thờ làm của lễ dùng lửa dâng cho Ðức Giê-hô-va: ấy là một của lễ chuộc sự mắc lối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Mọi người nam trong vòng những thầy tế lễ sẽ ăn thịt đó tại trong một nơi thánh; ấy là một vật chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Của lễ chuộc sự mắc lỗi cũng như của lễ chuộc tội, đồng một luật lệ nhau; con sinh sẽ thuộc về thầy tế lễ nào đã dùng nó làm lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Còn thầy tế lễ dâng của lễ thiêu cho ai, sẽ được miếng da của con sinh dùng làm của lễ thiêu đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Phàm của lễ chay nào, hoặc nấu trong lò, hoặc chiên trên chảo hay là nướng trên vĩ, thì thuộc về thầy tế lễ đã đứng dâng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Phàm của lễ chay, hoặc chế dầu, hoặc khô, phải cứ một mực phân cho các con trai A-rôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Ðây là luật lệ về của lễ thù ân mà người ta phải dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Nếu ai dâng của lễ đó đặng cảm tạ, thì phải dâng chung với của lễ thù ân những bánh nhỏ không pha men, chế dầu, bánh tráng không pha men thoa dầu, bột lọc trộn làm bánh nhỏ chế dầu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'lại phải thêm bánh có pha men mà dâng với của lễ thù ân cảm tạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Họ sẽ lấy một phần trong mỗi lễ vật làm của lễ chay giơ lên dâng cho Ðức Giê-hô-va; của lễ đó sẽ thuộc về thầy tế lễ đã rưới huyết của con sinh tế thù ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Thịt của con sinh tế cảm tạ thù ân thì phải ăn hết nội ngày đã dâng lên, không nên để sót chi lại đến sáng mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Nếu của lễ dâng về việc thường nguyện hay là lạc ý, thì phải ăn con sinh đó nội trong ngày đã dâng lên; còn dư lại thì ăn ngày mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Nhưng phần còn dư lại đến ngày thứ ba thì phải thiêu đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Nếu ai ăn thịt của lễ thù ân trong ngày thứ ba, thì người nào dâng của lễ đó sẽ chẳng được nhậm và chẳng kể chi của lễ đó cho người nữa; ấy là một điều gớm ghê, ai ăn thịt đó sẽ mang lấy tội mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Cũng chẳng nên ăn thịt đã đụng đến vật chi ô uế; phải thiêu đi. Còn thịt nào ăn được, ai tinh sạch mới nên ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Ai đã bị ô uế, lại ăn thịt của lễ thù ân vẫn thuộc về Ðức Giê-hô-va, thì sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Nếu ai đụng đến sự ô uế, hoặc của loài người, hoặc của loài vật hay là điều gì ghê gớm, mà lại ăn thịt của lễ thù ân vẫn thuộc về Ðức Giê-hô-va, thì sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Chẳng nên ăn một thứ mỡ nào của bò, chiên hay là dê.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Mỡ của con thú nào chết hay là bị xé sẽ được dùng về mọi việc, nhưng các ngươi không nên ăn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'vì ai ăn mỡ của những thú người ta dùng lửa dâng cho Ðức Giê-hô-va, sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Trong nơi nào các ngươi ở chẳng nên ăn huyết, hoặc của loài chim hay là của loài súc vật.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Phàm ai ăn một thứ huyết nào sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Ðức Giê-hô-va còn phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Người nào dâng của lễ thù ân cho Ðức Giê-hô-va, phải đem đến cho Ngài lễ vật do trong của lễ thù ân mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Chánh tay người sẽ đem phần phải dùng lửa dâng cho Ðức Giê-hô-va; tức là mỡ và cái o, cái o để đặng dùng làm của lễ đưa qua đưa lại trước mặt Ðức Giê-hô-va;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'rồi thầy tế lễ sẽ xông mỡ trên bàn thờ, còn cái o thì thuộc về phần A-rôn và các con trai người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Các ngươi cũng sẽ cho thầy tế lễ cái giò hữu về của lễ thù ân đặng làm của lễ giơ lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Còn ai trong vòng các con trai A-rôn dâng huyết và mỡ của con sinh tế thù ân, thì sẽ được phần cái giò hữu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Vì trong những của lễ thù ân của dân Y-sơ-ra-ên ta lấy cái o mà họ đưa qua đưa lại trước mặt ta, và cái giò mà họ dâng giơ lên, đặng ban cho thầy tế lễ A-rôn và các con trai người, chiếu theo luật lệ đời đời mà dân Y-sơ-ra-ên phải giữ theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Ấy là phần trong những của lễ dùng lửa dâng cho Ðức Giê-hô-va mà phép xức dầu sẽ truyền cho A-rôn và các con trai người trong ngày nào lập họ làm chức tế lễ trước mặt Ðức Giê-hô-va;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'ấy là điều Ðức Giê-hô-va đã phán dặn dân Y-sơ-ra-ên phải ban cho họ từ ngày họ chịu phép xức dầu. Ấy là một luật lệ đời đời trải qua các thế đại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Ðó là luật về của lễ thiêu, về của lễ chay, về của lễ chuộc tội, về của lễ chuộc sự mắc lỗi, về của lễ phong chức và về của lễ thù ân,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'mà Ðức Giê-hô-va đã truyền cho Môi-se tại trên núi Si-na -i khi Ngài dặn biểu dân Y-sơ-ra-ên dâng của lễ mình cho Ðức Giê-hô-va trong đồng vắng Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Hãy đem A-rôn cùng các con trai người, áo xống, dầu xức, con bò tơ làm của lễ chuộc tội, hai con chiên đực, và giỏ bánh không men;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'rồi nhóm hiệp cả hội chúng tại cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Môi-se bèn làm y như lời Ðức Giê-hô-va phán dặn, hội chúng nhóm hiệp tại nơi cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Môi-se nói cùng hội chúng rằng: Ðây là các điều Ðức Giê-hô-va đã phán dặn làm theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Ðoạn, Môi-se biểu A-rôn và các con trai người lại gần, rồi lấy nước rửa họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Người mặc áo lá trong cho A-rôn, cột đai lưng, mặc áo dài, mặc ê-phót và cột đai ê-phót.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Người cũng đeo bảng đeo ngực và gắn vào bảng u-rim và thu-mim,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'đội cái mão lên đầu, phía trước mão buộc thẻ vàng, tức là tràng thánh, y như lời Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Kế đó, Môi-se lấy dầu xức, xức cho đền tạm và các vật ở tại đó biệt riêng ra thánh,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'rảy dầu bảy lần trên bàn thờ và xức dầu cho bàn thờ cùng các đồ phụ tùng của bàn thờ, cái thùng và chân thùng, đặng biệt riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Người cũng đổ dầu xức trên đầu A-rôn, xức cho người đặng biệt riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Ðoạn, Môi-se biểu các con trai A-rôn lại gần, mặc áo lá trong cho, cột đai, đội mão lên đầu, y như Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Người biểu đem con bò tơ dùng làm của lễ chuộc tội lại gần, A-rôn và các con trai người nhận tay mình trên đầu nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Môi-se giết nó, lấy huyết, rồi dùng ngón tay bôi huyết trên chung quanh sừng của bàn thờ, làm cho bàn thờ nên thanh sạch; đoạn đổ huyết dưới chân bàn thờ; như vậy, người biệt bàn thờ riêng ra thánh, để làm lễ chuộc tội tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Người lấy hết thảy mỡ chài, tấm da mỏng bọc gan, hai trái cật với mỡ của hai trái cật, rồi đem xông trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Còn con bò, da, thịt và phẩn nó, thì người đem thiêu ở ngoài trại quân, y như Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Người cũng biểu đem con chiên đực dùng làm của lễ thiêu lại gần, A-rôn và các con trai người nhận tay mình trên đầu nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'rồi Môi-se giết nó và rưới huyết chung quanh trên bàn thờ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'đoạn sả thịt ra từ miếng, đem xông cái đầu, mấy miếng đó và mỡ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Người lấy nước rửa bộ lòng và giò, rồi xông trọn con chiên đực trên bàn thờ; ấy là một của lễ thiêu có mùi thơm, tức một của lễ dùng lửa dâng cho Ðức Giê-hô-va, y như Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Người cũng biểu đem con chiên đực thứ nhì lại gần, tức là con chiên đực về lễ phong chức; A-rôn và các con trai người nhận tay mình trên đầu con chiên đực đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Môi-se giết nó, lấy huyết bôi trên trái tai hữu của A-rôn, trên ngón cái của bàn tay mặt và trên ngón cái của bàn chân mặt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Môi-se cũng biểu các con trai A-rôn đến gần, bôi huyết nơi trái tai hữu họ, trên ngón cái của bàn tay mặt và trên ngón cái của bàn chân mặt; đoạn, Môi-se rưới huyết chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Kế đó, người lấy mỡ, đuôi, hết thảy mỡ chài, tấm da mỏng bọc gan, hai trái cật với mỡ của hai trái cật và cái giò hữu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'lại lấy trong giỏ bánh không men để trước mặt Ðức Giê-hô-va, một cái bánh nhỏ không men, một cái bánh nhỏ có dầu, và một cái bánh tráng, để mấy bánh đó trên những mỡ và giò hữu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'đoạn để hết thảy trong tay A-rôn và tay các con trai người; họ đưa qua đưa lại trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Môi-se lấy các món đó khỏi tay họ, đem xông nơi bàn thờ tại trên của lễ thiêu; ấy là của lễ về sự phong chức có mùi thơm, tức là của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Môi-se cũng lấy cái o của con chiên đực về lễ phong chức và đưa qua đưa lại trước mặt Ðức Giê-hô-va; ấy là phần thuộc về Môi-se, y như Ðức Giê-hô-va đã phán dặn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Kế ấy, Môi-se lấy dầu xức và huyết trên bàn thờ rảy trên A-rôn và trên quần áo người, trên các con trai người và trên quần áo họ, biệt A-rôn và quần áo người, các con trai người và quần áo họ riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Ðoạn, Môi-se nói cùng A-rôn và các con trai người rằng: Các người hãy nấu thịt tại cửa hội mạc, và ăn tại đó với bánh ở trong giỏ về lễ phong chức, y như ta đã phán dặn rằng: A-rôn và các con trai người sẽ ăn thịt đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Nhưng các ngươi phải thiêu thịt và bánh còn dư lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Trong bảy ngày các ngươi không nên đi ra khỏi cửa hội mạc cho đến chừng nào những ngày phong chức mình được trọn rồi, vì việc phong chức các ngươi sẽ trải qua bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Ðức Giê-hô-va đã phán dặn làm y như hôm nay người ta đã làm, để làm lễ chuộc tội cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Vậy, hãy ở trọn ngày cả đêm tại cửa hội mạc trong bảy bữa, gìn giữ mạng lịnh của Ðức Giê-hô-va, hầu cho các ngươi khỏi thác, vì Ngài đã truyền dặn ta như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'A-rôn và các con trai người làm mọi điều y như Ðức Giê-hô-va cậy Môi-se truyền dặn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Qua ngày thứ tám, Môi-se gọi A-rôn và các con trai người cùng những trưởng lão của Y-sơ-ra-ên,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'rồi dạy A-rôn rằng: Hãy bắt một con bò con đực đặng làm của lễ chuộc tội, một con chiên đực làm của lễ thiêu, đều không tì vít chi, và dâng lên trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Ngươi hãy nói cùng dân Y-sơ-ra-ên rằng: Các ngươi hãy bắt một con dê đực làm của lễ chuộc tội, một con bò con và một con chiên con không tì vít chi, một tuổi, đặng dùng làm của lễ thiêu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'một con bò tơ, một con chiên đực đặng dùng làm của lễ thù ân, để dâng lên trước mặt Ðức Giê-hô-va, và một của lễ chay chế dầu; vì ngày nay Ðức Giê-hô-va sẽ hiện ra cùng các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Vậy, họ dẫn đến trước hội mạc những vật Môi-se đã dặn biểu; rồi cả hội chúng đến gần đứng trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Môi-se nói rằng: Ðây là các điều Ðức Giê-hô-va phán dặn; hãy làm đi, thì sự vinh quang của Ðức Giê-hô-va sẽ hiện ra cùng các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Ðoạn, Môi-se nói cùng A-rôn rằng: Ngươi hãy đến gần bàn thờ dâng của lễ chuộc tội và của lễ thiêu của ngươi đi, để vì ngươi và vì dân sự làm lễ chuộc tội; lại cùng hãy dâng của lễ của dân sự và làm lễ chuộc tội cho họ, y như Ðức Giê-hô-va đã phán dặn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'A-rôn bèn lại gần bàn thờ, giết bò con đực dùng làm của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Các con trai người đem huyết đến; người nhúng ngón tay vào, bôi trên các sừng bàn thờ, rồi đổ huyết dưới chân bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Người lấy đem xông trên bàn thờ mỡ, hai trái cật và tấm da mỏng bọc gan của con sinh tế chuộc tội, y như Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Còn thịt và da, người đem ra thiêu ngoài trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Ðoạn, người giết con sinh dùng làm của lễ thiêu. Các con trai A-rôn đem huyết đến, người rưới chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Họ cũng đem cho A-rôn thịt của lễ thiêu sả ra từ miếng và dầu, rồi người xông hết trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Ðoạn, người rửa bộ lòng và các giò, đem xông trên của lễ thiêu nơi bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Người cũng dâng của lễ của dân sự; bắt con dê đực dùng làm của lễ chuộc tội cho dân sự, giết nó và dâng lên đặng chuộc tội, y như của lễ đầu tiên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'lại người cũng dâng của lễ thiêu theo luật lệ đã định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Kế đó, người dâng của lễ chay, trút đầy bụm tay mình đem xông trên bàn thờ, ngoại trừ của lễ thiêu hồi ban mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Người cũng vì dân sự giết con bò tơ và con chiên đực làm của lễ thù ân. Các con trai A-rôn đem huyết đến, và người rưới chung quanh trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Họ cũng đem đến cho người mỡ của con bò tơ và con chiên đực, đuôi, mỡ trên bộ lòng, hai trái cật, và tấm da mỏng bọc gan;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'để những mỡ nầy trên o, rồi xông mỡ nơi bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Ðoạn, A-rôn lấy cái o và giò hữu đưa qua đưa lại trước mặt Ðức Giê-hô-va, y như Môi-se đã dặn biểu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'A-rôn giơ tay mình trên dân sự chúc phước cho; sau khi dâng của lễ chuộc tội, của lễ thiêu, và của lễ thù ân, thì người bước xuống khỏi bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Môi-se và A-rôn bèn vào hội mạc, kế lại ra chúc phước cho dân sự; sự vinh quang của Ðức Giê-hô-va hiện ra cùng cả dân sự:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'một ngọn lửa từ trước mặt Ðức Giê-hô-va lóe ra thiêu hóa của lễ thiêu và mỡ trên bàn thờ. Cả dân sự thấy, đều cất tiếng reo mừng và sấp mặt xuống đất.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Hai con trai A-rôn, Na-đáp và A-bi-hu, mỗi người đều cầm lư hương mình, để lửa vào, bỏ hương lên và dâng một thứ lửa lạ trước mặt Ðức Giê-hô-va; ấy là điều Ngài không phán dặn họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Một ngọn lửa từ trước mặt Ðức Giê-hô-va lòe ra, nuốt tiêu họ và họ chết trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Môi-se bèn nói cùng A-rôn rằng: Ấy là điều Ðức Giê-hô-va đã tỏ ra khi Ngài phán rằng: Ta sẽ nhờ những kẻ lại gần ta mà được tôn thánh và được vinh hiển trước mặt cả dân sự. A-rôn nín lặng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Môi-se gọi Mi-sa-ên và Eân-sa-phan, hai con trai của U-xi-ên, chú của A-rôn, mà dạy rằng: Hãy lại gần khiêng thây hai anh em các ngươi khỏi trước nơi thánh, đem ra ngoài trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Vậy, họ đến gần khiêng thây còn mặc áo lá trong ra ngoài trại quân, y như lời Môi-se đã biểu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Ðoạn, Môi-se nói cùng A-rôn, Ê-lê-a-sa và Y-tha-ma, hai con trai người, mà rằng: Các ngươi chớ để đầu trần và chớ xé áo mình, e khi phải chết và Ðức Giê-hô-va nổi giận cùng cả hội chúng chăng; nhưng anh em các ngươi, là cả nhà Y-sơ-ra-ên, phải nên khóc vì cớ lửa thiêu hóa mà Ðức Giê-hô-va nổi phừng lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ðừng ra khỏi cửa hội mạc, e các ngươi phải chết chăng; vì dầu xức của Ðức Giê-hô-va ở trên các ngươi. Họ bèn làm theo lời Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Ðoạn, Ðức Giê-hô-va phán cùng A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Khi nào vào hội mạc, ngươi và các con trai ngươi chớ nên uống rượu hay là uống vật chi có tánh say, e phải chết chăng: ấy là một mạng lịnh đời đời, trải các thế đại,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'hầu cho các ngươi được phân biệt đều thánh và điều chẳng thánh, sự khiết và sự chẳng khiết,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'và dạy dân Y-sơ-ra-ên các mạng lịnh mà Ðức Giê-hô-va đã cậy Môi-se truyền dặn cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Môi-se nói cùng A-rôn, Ê-lê-a-sa và Y-tha-ma, là hai con trai A-rôn còn lại, mà rằng: Hãy lấy của lễ chay còn dư lại về của lễ dùng lửa dâng cho Ðức Giê-hô-va, và hãy ăn đi không pha men, gần bàn thờ, vì là một vật chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Phải ăn của lễ nầy tại nơi thánh, vì là phần của ngươi và của các con trai ngươi trong những của lễ dùng lửa dâng cho Ðức Giê-hô-va; bởi vì đã phán dặn ta làm như vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Còn cái o dâng đưa qua đưa lại, và cái giò dâng giơ lên, ngươi, các con trai và các con gái ngươi hãy ăn tại một nơi tinh sạch, vì các điều đó đã ban cho làm phần riêng của ngươi và của các con trai ngươi, do những của lễ thù ân của dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Họ sẽ đem đến cái giò dâng giơ lên và cái o dâng đưa qua đưa lại với những mỡ định thiêu hóa, để dâng đưa qua đưa lại trước mặt Ðức Giê-hô-va. Những điều đó sẽ thuộc về ngươi và các con trai ngươi chiếu theo luật lệ đời đời, y như Ðức Giê-hô-va đã phán dặn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Vả, Môi-se tìm con dê đực dùng làm của lễ chuộc tội, thấy nó đã bị thiêu, bèn nổi giận cùng Ê-lê-a-sa và Y-tha-ma, hai con trai A-rôn còn lại và nói rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Sao các ngươi không ăn thịt con sinh tế chuộc tội trong nơi thánh? Vì là một vật chí thánh mà Ðức Giê-hô-va đã ban cho các ngươi, hầu gánh lấy tội của hội chúng, và làm lễ chuộc tội cho họ trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Nầy, huyết nó không có đem vào trong nơi thánh; quả đáng các ngươi ăn sinh lễ trong nơi thánh, y như lời ta đã dặn biểu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Nhưng A-rôn đáp rằng: Kìa, ngày nay họ đã dâng của lễ chuộc tội và của lễ thiêu của mình trước mặt Ðức Giê-hô-va; và sau khi việc rủi nầy xảy ra, nếu lại ngày nay tôi ăn của lễ chuộc tội, há có đẹp lòng Ðức Giê-hô-va chăng?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Môi-se phải nghe lời đáp ấy, bèn nhận cho phải.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Ðức Giê-hô-va phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Hãy nói với dân Y-sơ-ra-ên rằng: Trong các loài vật trên mặt đất, nầy là những con các ngươi được phép ăn:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Hễ loài vật nào có móng rẽ ra, chân chia hai và nhơi, thì các ngươi được phép ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Nhưng chẳng nên ăn con nào chỉ nhơi không, hay là chỉ có móng rẽ không: con lạc đà, nó nhơi, nhưng không có móng rẽ; nên hãy cầm nó là loài vật không sạch;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'con chuột đồng, nó nhơi, nhưng không có móng rẽ, nên hãy cầm nó là loài vật không sạch;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'con thỏ rừng, nó nhơi nhưng không móng rẽ; nên hãy cầm nó là loài vật không sạch;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'con heo, nó có móng rẽ, chân chia hai, nhưng không nhơi; nên hãy cầm nó là loài vật không sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Các ngươi không nên ăn thịt và cũng không nên đụng đến thây các thú đó; phải cầm là vật không sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Những loài vật ở dưới nước mà các ngươi được phép ăn, là loài vật nào, hoặc ở dưới biển, hoặc ở dưới sông, có vây và có vảy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Phàm vật nào hoặc dưới biển, hoặc dưới sông, tức các loài sanh sản trong nước, mà không có vây và chẳng có vảy, thì các người không nên ăn, phải lấy làm gớm ghiếc cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Những loài nầy, khá lấy làm gớm ghiếc cho mình, chớ nên ăn thịt nó, và hãy cầm thây nó là điều gớm ghiếc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Các loài vật nào ở trong nước không có vây và chẳng có vảy, thì phải lấy làm gớm ghiếc cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Trong các loài chim, những giống các ngươi phải cầm bằng gớm ghiếc, không nên ăn, là chim ưng, chim ngạc, ó biển;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'chim lão ưng và con diều, tùy theo loại chúng nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'các thứ quạ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'chim đà điểu, chim ụt, chim thủy kê, chim bò cắc và các loại giống chúng nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'chim mèo, chim thằng cộc, con cò quắm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'con hạc, chim thằng bè, con cồng cộc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'con cò, con diệc và các loại giống chúng nó; chim rẽ quạt và con dơi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Hễ côn trùng nào hay bay, đi bốn cẳng, thì các ngươi hãy lấy làm gớm ghiếc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Nhưng trong loại côn trùng nào hay bay và đi bốn cẳng, các ngươi được ăn con nào có cẳng đặng nhảy trên đất;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'là con cào cào tùy theo loại nó, con ve tùy theo loại nó, châu chấu tùy theo loại nó, con dế tùy theo loại nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Các loài côn trùng khác hay bay và có bốn cẳng, thì các ngươi phải lấy làm gớm ghiếc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Các ngươi sẽ vì loại đó mà bị ô uế; ai đụng đến xác chết loài đó sẽ bị ô uế cho đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Ai mang xác chết loài đó phải giặt áo xống mình, và bị ô uế cho đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Các thú nào có móng rẽ ra, nhưng không có chân chia hai và không nhơi, tất phải lấy làm ô uế cho các ngươi; ai đụng đến sẽ bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Trong giống đi bốn cẳng, hễ con nào đi trên bàn cẳng, thì kể là không sạch cho các ngươi; ai đụng đến xác chết nó sẽ bị ô uế đến chiều tối;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'còn ai mang xác chết nó sẽ giặt áo xống mình, và bị ô uế đến chiều tối; các loài đó là không sạch cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Trong loài đi bò trên mặt đất, nầy là những loài lấy làm không sạch cho các ngươi: con chuột nhủi, con chuột lắt, con rắn mối, tùy theo loại chúng nó;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'con cắc kè, kỳ đà, con thạch sùng, con kỳ nhông và con cắc ké.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Trong các loài côn trùng, những loài đó lấy làm không sạch cho các ngươi: ai đụng đến xác chết nó sẽ bị ô uế cho đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Bất luận vật nào, hễ loài nầy chết rớt nhằm trên, thì đều bị ô uế, hoặc đồ bằng cây, áo xống, da, bao, tức các vật người ta thường dùng; phải ngâm đồ đó trong nước, sẽ bị ô uế cho đến chiều tối, rồi mới tinh sạch lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Nếu vật chi của nó rớt nhằm đồ sành, các vật chi đựng ở trong đều sẽ bị ô uế; phải đập bể đồ sành đó đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Phàm đồ ăn nào và các vật uống, mặc dầu để trong đồ sành nào mà bị nước đồ sành đó nhểu vào, sẽ lây ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Phàm vật nào bị một vài miếng xác chết nó rớt nhằm, sẽ lây ô uế; dầu lò, dầu bếp, cũng phải phá tan; nó đã bị ô uế; các ngươi phải cầm nó là ô uế vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Còn một cái suối, hoặc một hồ chứa nhiều nước, đều cứ được kể tinh sạch; nhưng hễ ai đụng đến xác chết nó thì sẽ lây ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Nếu vật chi của xác chết nó rớt nhằm trên hột giống nào người ta gieo, thì hột giống đó cứ kể tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Nhưng nếu người ta có đổ nước trên hột giống đó và nếu vật gì của xác chết rớt nhằm, thì hột giống đó sẽ bị ô uế cho các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Khi một con thú nào các ngươi được dùng làm thực vật chết đi, hễ ai đụng đến xác nó sẽ bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Kẻ nào ăn thịt của xác nó phải giặt áo xống mình, và bị lây ô uế cho đến chiều tối; còn ai khiêng xác nó sẽ giặt áo xống, và bị ô uế cho đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Phàm loài côn trùng nào bò trên mặt đất đều là sự gớm ghiếc, không nên ăn thịt nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Vậy, không nên ăn thịt các loài côn trùng đi bò trên mặt đất, là con nào bò bằng bụng, con nào đi bốn cẳng hay là đi nhiều cẳng, vì chúng nó là một sự gớm ghiếc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Các ngươi chớ vì một con nào trong loài côn trùng mà lây cho thân mình phải gớm ghiếc, không tinh sạch hay là ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Vì ta là Giê-hô-va Ðức Chúa Trời của các ngươi; ta là thánh, nên các ngươi phải nên thánh, thì sẽ được thánh. Các ngươi chớ vì một con nào của loài côn trùng trên mặt đất mà làm lây ô uế cho thân mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Vì ta là Ðức Giê-hô-va, Ðấng đã đem các ngươi ra khỏi xứ Ê-díp-tô đặng làm Ðức Chúa Trời của các ngươi; các ngươi phải nên thánh, vì ta là thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Ðó là luật lệ về loài súc vật, loài chim trời, các sinh vật động dưới nước và các loài côn trùng trên mặt đất,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'để phân biệt con không sạch với con tinh sạch, con thú ăn được cùng con thú không ăn được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Hãy nói cùng dân Y-sơ-ra-ên rằng: Khi nào một người đàn bà thọ thai và sanh một con trai, thì phải bị ô uế trong bảy ngày, như trong kỳ kinh nguyệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Qua ngày thứ tám, người ta phải làm phép cắt bì cho đứa trẻ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Ðoạn, người đàn bà phải kiêng trong ba mươi ba ngày đương khi huyết mình được sạch, không nên đụng một vật thánh nào hay là đi tới nơi thánh cho đến kỳ làm thanh sạch được trọn rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Còn nếu người sanh con gái, thì sẽ bị ô uế trong hai tuần, như trong kỳ kinh nguyệt; phải kiêng trong sáu mươi sáu ngày hầu cho huyết mình được sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Khi kỳ làm mình cho thanh sạch về đứa trai hay gái đã trọn rồi, người đàn bà phải dâng cho thầy tế lễ tại cửa hội mạc một chiên con một tuổi, đặng làm của lễ thiêu, và một bò câu con hoặc một cu con đặng làm của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Thầy tế lễ sẽ dâng con sinh đó trước mặt Ðức Giê-hô-va, làm lễ chuộc tội cho người; sự lưu huyết người sẽ được sạch. Ðó là luật lệ về người đàn bà sanh con trai hay là con gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Còn nếu người không thế lo cho có một chiên con, thì phải bắt hai chim cu, hoặc hai con bò câu con, con nầy dùng làm của lễ thiêu, con kia dùng làm của lễ chuộc tội; thầy tế lễ sẽ làm lễ chuộc tội cho người, và người sẽ được sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Khi một người nào da trên mình nổi sưng, mụt lở, hoặc một đém trắng, dường sẽ trở thành trên da mình một vít phung, thì người ta phải dẫn người đó đến thầy tế lễ A-rôn, hay là đến một trong các con trai người là những thầy tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Thầy tế lễ sẽ khám vít ở trên da thân người; nếu lông vít đó đã trở thành trắng, và nếu vít hủng xuống sâu hơn da thân mình, ấy là một vít phung: thầy tế lễ khám rồi sẽ định người nầy là ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Còn nếu có một đém trắng trên da thân người, đém không sủng xuống sâu hơn da, và nếu lông không trở thành trắng, thì thầy tế lễ phải giam người đó trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Qua ngày thứ bảy, thầy tế lễ sẽ khám người, nếu vít đó ngừng lại, không ăn lan trên da, thì phải giam người một lần thứ nhì bảy ngày nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Qua ngày thứ bảy, thầy tế lễ sẽ khám người lại; nếu vít đó đã tái, không ăn lan trên da, thì thầy tế lễ sẽ định người đó là tinh sạch; ấy là mụt lở mà thôi. Người đó phải giặt áo xống mình, thì sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Nhưng nếu sau khi người đã đến trước mặt thầy tế lễ để được định là tinh sạch, mụt lở còn phát lại trên da, thì người phải đến thầy tế lễ một lần thứ nhì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Thầy tế lễ sẽ khám cho, nếu mụt lở đã ăn lan trên da thì phải định người là ô uế; ấy là bịnh phung vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Khi có một vít phung trên người nào, thì phải dẫn người đó đi tỏ mình cùng thầy tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Thầy tế lễ khám cho; nếu có nổi sưng sắc trắng trên da làm cho lông trở thành trắng, và có một lằn thịt chín đó nơi chỗ sưng đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'ấy là bịnh phung thâm niên trong da của thân người, thầy tế lễ sẽ định người là ô uế, không nên giam họ, vì đã bị ô uế rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Còn nếu phung lở trên da, bao phủ hết da của người có vít đó, từ đầu chí chân, khắp nơi nào thầy tế lễ dòm thấy được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'thì thầy tế lễ phải khám cho; nếu phung bao phủ cùng hết thịt, thì sẽ định người có vít là tinh sạch; người đã hóa trắng cùng mình, nên được tinh sạch vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Nhưng ngày nào phát ra thịt chín đỏ, thì người bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Khi thầy tế lễ thấy thịt chín đỏ thì phải định người là ô uế; thịt chín đỏ là ô uế; ấy là bịnh phung vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Nhưng nếu thịt chín đỏ thay đi, hóa ra trắng, thì người phải đi tỏ mình cùng thầy tế lễ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'thầy tế lễ khám cho, và nếu vít đã trở thành trắng, thì phải định người có vít là tinh sạch, vì đã được tinh sạch rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Khi một người nào trên da thân mình có mụt chốc đã chữa lành,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'và tại chỗ mụt chốc có nổi sưng sắc trắng hay là một đém trắng hồng, thì người đó phải đi tỏ mình cùng thầy tế lễ;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'thầy tế lễ khám cho; nếu cái đém hủng sâu hơn da, và nếu lông trở thành trắng, thì thầy tế lễ phải định người là ô uế; ấy là một vít phung đã lở trong mụt chốc vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Còn nếu thầy tế lễ khám, không thấy lông trắng trong chỗ đém, không hủng sâu hơn da, và thấy đã trở thành tái, thì hãy giam người đó trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Nều đém ăn lan trên da thì thầy tế lễ phải định người là ô uế; ấy là một vít phung vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Còn nếu vít cầm cự một chỗ, không ăn lan ra, ấy là thẹo của mụt chốc; thầy tế lễ phải định người là tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Khi người nào bị phỏng lửa trên da, và dấu phỏng là một đém trắng hồng hay là trắng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'thì thầy tế lễ khám cho; nếu trong đém lông trở thành trắng, và nếu đém hủng sâu hơn da, ấy là bịnh phung lở trong mụt phỏng vậy. Thầy tế lễ phải định người nầy là ô uế; ấy là một vít phung.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Còn nếu thầy tế lễ khám, không thấy lông trắng trong đém, không hủng sâu hơn da, và thấy đã tái rồi, thì hãy giam người nầy trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Qua ngày thứ bảy thầy tế lễ khám người, nếu đém ăn lan trên da, thì phải định người là ô uế; ấy là vít phung.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Còn nếu đém cầm cự một chỗ, không ăn lan trên da và tái đi, ấy là sưng phỏng. Thầy tế lễ phải định người là tinh sạch, vì là thẹo phỏng lửa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Khi nào một người nam hay nữ có vít trên đầu, hoặc nơi râu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'thì thầy tế lễ khám vít đó. Nếu vít hủng sâu hơn da, có lông nhỏ vàng vàng, thì thầy tế lễ phải định người ra ô uế; ấy là tật đòng đanh, tức là bịnh phung của đầu hay là của râu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Còn nếu khi thầy tế lễ khám vít đòng đanh, thấy vít không hủng sâu hơn da, và không thấy có lông đen, thì phải giam người có vít đòng đanh trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Qua ngày thứ bảy thầy tế lễ khám vít; nếu đòng đanh không ăn lan ra, không có lông vàng vàng, và không hủng sâu hơn da,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'thì người đó phải cạo gọt, nhưng không nên cạo gọt chỗ vít đòng đanh, rồi thầy tế lễ sẽ giam người một lần thứ nhì bảy ngày nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Ðoạn ngày thứ bảy, thầy tế lễ khám cho; nếu đòng đanh không ăn lan trên da, không hủng sâu hơn da, thì thầy tế lễ phải định người là tinh sạch; kẻ bịnh phải giặt áo xống mình, thì sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Nhưng nếu sau khi người đã được định là tinh sạch, đòng đanh lại còn ăn lan trên da, thì thầy tế lễ phải khám cho.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Nếu đòng đanh đã ăn lan trên da rồi, thầy tế lễ không cần tìm thấy lông vàng vàng, người đã bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Nhưng nếu đòng đanh xem bộ ngừng lại, và đã lố mọc lông đen, đòng đanh đã lành: người đã được tinh sạch, và thầy tế lễ phải định người là tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Khi nào người nam hãy nữ trên da thân mình có những đém trắng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'thầy tế lễ sẽ khám cho. Nếu trên da thân người có những đém trắng xanh, ấy là một đém trắng lở trên da mà thôi: người vẫn tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Khi một người nào đầu rụng tóc, ấy là một người sói đầu: người vẫn tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Nếu người rụng tóc về phía mặt, ấy là một người sói trán: người vẫn tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Còn nếu trong chỗ sói phía trước hay là phía sau có một vít trắng hồng, ấy là bịnh phung lở ra ở chỗ sói phía trước hay là phía sau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Thầy tế lễ phải khám cho; nếu nơi sưng của vít trong chỗ sói phía trước hay là phía sau có màu trắng hồng, giống như bịnh phung tại da của thân người,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'thì người nầy bị phung, thầy tế lễ sẽ định người là ô uế; vít người ở nơi đầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Vả, người đã bị vít phung rồi phải xé quần áo, đầu trần, che râu lại la rằng: Ô-uế! Ô-uế!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Trọn lúc nào người có vít, thì sẽ bị ô uế, phải ở một mình ngoài trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Khi nào lên mốc trên quần áo, như vít phung, bất luận trên quần áo bằng lông chiên hay quần áo bằng vải gai,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'trên canh hay trên chỉ bằng gai, hoặc bằng lông chiên, trên da hay là trên món nào bằng da;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'nếu vít đó màu xanh xanh hay đỏ đỏ, trên quần áo hoặc trên da, trên canh hoặc trên chỉ hay là trên món nào bằng da, thì phải coi như bịnh phung, đem đến tỏ cho thầy tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Thầy tế lễ sẽ khám cho, và giam món có vít ấy trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Qua ngày thứ bảy, thầy tế lễ khám vít lại; nếu vít ăn lan trên quần áo, trên canh hay chỉ, trên da hay trên món chi bằng da, thì phải coi như bịnh phung ăn luồn; món đó bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Vậy, người phải đốt quần áo, canh hay chỉ bằng lông chiên hoặc bằng gai, hoặc các món chi làm bằng da, ở trên nó mà đã bị vít, vì là một bịnh phung ăn ruồng: phải thiêu đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Còn nếu thầy tế lễ khám, chẳng thấy vít đó ăn lan trên quần áo, trên canh hay trên chỉ, hoặc các món chi làm bằng da,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'thì người hãy biểu họ đem giặt món có vít đó đi, rồi giam nó một lần thứ nhì trong bảy ngày nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Khi giặt rồi, thầy tế lễ sẽ khám lại, nếu vít đó không phai màu và cũng chẳng ăn lan ra, thì món đó là ô uế: ngươi hãy đem thiêu đi, vì là một thứ vít mốc ăn vào bề trái hay là bề mặt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Còn nếu sau khi giặt rồi, thầy tế lễ thấy vít đã tái, thì phải gỡ nó khỏi quần áo, da, canh hay chỉ đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Nếu vít mốc còn ló lên lại trên quần áo, trên canh hay chỉ, hoặc trên món chi bằng da, thì phải coi như một vít phung, và thiêu món có vít đó đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Nhưng quần áo, canh hay chỉ, hoặc món nào bằng da mà ngươi đã giặt, và vít đã lặn rồi, thì hãy đem giặt một lần thứ nhì nữa, đoạn sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Ðó là luật lệ về vít lên mốc như phung trên quần áo bằng lông chiên hay bằng vải gai, trên canh hay chỉ, hoặc trên món chi bằng da, chiếu theo luật lệ đó là phải định là tinh sạch hay là ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Nầy là luật lệ cho kẻ phung về ngày nó được sạch. Người ta sẽ dẫn người phung đến thầy tế lễ:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'thầy tế lễ sẽ ra ngoài trại quân mà khám bịnh cho. Nếu vít phung của người bịnh lành rồi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'thì về phần người phải được sạch, thầy tế lễ sẽ truyền đem hai con chim vẫn sống và tinh sạch, cây hương nam, màu đỏ sặm và nhành kinh giới.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Thầy tế lễ biểu cắt cổ một trong hai chim đó trong chậu sành, trên nước chảy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Ðoạn, bắt lấy chim còn sống với cây hương nam, màu đỏ sặm, nhành kinh giới, đem nhúng trong huyết của chim kia đã cắt cổ trên nước chảy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Thầy tế lễ phải rảy huyết bảy lần trên người được sạch phung, và định người là tinh sạch, rồi thả con chim còn sống ra ngoài đồng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Kẻ được sạch sẽ giặt áo xống mình, cạo hết lông, tắm trong nước, rồi sẽ được tinh sạch. Kế đó người được vào trại quân, nhưng phải ở ngoài trại mình trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Qua ngày thứ bảy người sẽ cạo hết lông, tóc, râu, và lông mày mình, giặt quần áo và tắm mình trong nước, thì sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Qua ngày thứ tám, người bắt hai chiên con đực không tì vít chi, một chiên con cái chưa giáp năm, không tì vít chi, ba phần mười ê-pha bột lọc, chế dầu, làm của lễ chay, và một lót dầu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'thầy tế lễ làm lễ nên thanh sạch sẽ đem người đương được sạch và các vật đó đến trước mặt Ðức Giê-hô-va tại cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Kế đó, thầy tế lễ sẽ bắt một trong hai chiên con đực dâng làm của lễ chuộc sự mắc lỗi với một lót dầu, và đưa qua đưa lại trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Ðoạn, người giết chiên con đó trong nơi thường giết các con sinh dùng làm của lễ chuộc tội và của lễ thiêu, tức là trong một nơi thánh, vì của lễ chuộc sự mắc lỗi thuộc về thầy tế lễ như của lễ chuộc tội vậy; ấy là một vật chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Thầy tế lễ sẽ lấy huyết của con sinh tế chuộc sự mắc lỗi bôi trên trái tai hữu của người được sạch, trên ngón cái tay mặt và trên ngón cái chân mặt;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'đoạn lấy lót dầu đổ trong bàn tay tả mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'nhúng ngón tay hữu vào dầu trong bàn tay tả mình, mà rảy bảy lần trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Dầu còn lại trong bàn tay mình, thầy tế lễ sẽ lấy bôi trên trái tai hữu của người được sạch, trên ngón cái tay mặt và ngón cái chân mặt, tức trên lớp huyết của lễ chuộc sự mắc lỗi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Dầu còn dư lại trong bàn tay mình, thầy tế lễ sẽ đổ trên đầu người được sạch; vậy thầy tế lễ sẽ làm lễ chuộc tội cho người trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Ðoạn, thầy tế lễ sẽ dâng của lễ chuộc tội đặng làm lễ chuộc tội cho người được sạch sự ô uế mình. Kế đó, thầy tế lễ sẽ giết con sinh dùng làm của lễ thiêu,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'dâng lên với của lễ chay trên bàn thờ; vậy, thầy tế lễ sẽ làm lễ chuộc tội cho người nầy, thì người nầy sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Nhưng nếu người đó nghèo nàn, không phương thế đủ dâng những lễ vật nầy, thì phải bắt một chiên con đực dùng làm của lễ chuộc sự mắc lỗi, dâng đưa qua đưa lại đặng làm lễ chuộc tội cho mình, một phần mười bột lọc chế dầu làm của lễ chay và một lót dầu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Tùy theo phương thế mình, người cũng đem nộp hai con chim cu hay là hai bò câu con; con nầy dùng làm của lễ chuộc tội, con kia dùng làm của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Qua ngày thứ tám, người phải vì sự nên thanh sạch mình, đem nộp các lễ vật nầy cho thầy tế lễ tại cửa hội mạc, trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Thầy tế lễ sẽ bắt chiên con đực định làm của lễ chuộc sự mắc lỗi, và một lót dầu, rồi dâng lên đưa qua đưa lại trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Ðoạn, người giết chiên con dùng làm của lễ chuộc sự mắc lỗi, lấy huyết bôi trên trái tai hữu của kẻ được sạch, trên ngón cái tay mặt và trên ngón cái chân mặt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Rồi thầy tế lễ đổ dầu vào bàn tay tả mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'ngón tay hữu nhúng lấy dầu đổ trong bàn tay tả, rảy bảy lần trước mặt Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'và bôi trên trái tai hữu của người được sạch, trên ngón cái tay mặt và trên ngón cái chân mặt, tại nơi đã bôi huyết của lễ chuộc sự mắc lỗi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Dầu còn dư lại trong bàn tay, thầy tế lễ sẽ đổ trên đầu người được sạch, đặng làm lễ chuộc tội cho người trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Ðoạn, thầy tế lễ sẽ dâng một trong hai con chim cu, hoặc một trong hai con bồ câu con, tùy theo vật họ nộp,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'dâng con nầy dùng làm của lễ chuộc tội, con kia dùng làm của lễ thiêu, với của lễ chay. Vậy, thầy tế lễ sẽ làm lễ chuộc tội cho người được sạch trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Ðó là luật lệ về lễ nên thanh sạch của kẻ nghèo nàn bị vít phung.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Ðức Giê-hô-va cũng phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Khi nào các ngươi sẽ vào xứ Ca-na-an, mà ta sẽ cho các ngươi làm sản nghiệp, nếu ta giáng mốc vít mốc như vít phung trong nhà nào của xứ các ngươi sẽ được làm sản nghiệp,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'chủ nhà đó phải đến cáo cùng thầy tế lễ rằng: Tôi thấy như có một vít mốc trong nhà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Trước khi vào khám vít mốc đó, thầy tế lễ phải truyền họ đem đồ đạc trong nhà ra hết, hầu cho khỏi bị lây ô uế; sau dời xong, thầy tế lễ sẽ vào đặng khám nhà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Người sẽ xem vít đó, nếu nó ở nơi vách có lỗ màu xanh xanh, hoặc đỏ đỏ, bộ sâu hơn mặt vách,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'thì thầy tế phải đi ra đến cửa ngoài, niêm nhà lại trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Ngày thứ bảy, thầy tế lễ trở lại, nếu thấy vít ăn lan ra trên vách nhà,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'thì phải truyền gỡ mấy cục đá bị vít lây, liệng ra ngoài thành trong một nơi dơ dáy;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'đoạn biểu người ta cạo trong nhà và chung quanh nhà, và hốt bỏ bụi cạo đó ra ngoài thành trong một nơi dơ dáy;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'rồi lấy đá khác trám vào chỗ đá cũ, và đem hồ mới tô lại khắp nhà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Nhưng nếu sau khi đã gỡ mấy cục đá, cạo nhà và tô lại, vít đó trở lại ở trong nhà,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'thì thầy tế lễ phải đến khám nữa. Nếu thấy vít ăn lan ra, ấy là một vít phung ăn ruồng nhà; nhà đã bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Vậy, họ phải phá nhà đi, đá, gỗ và hồ, rồi đem đổ hết thảy ngoài thành trong một nơi dơ dáy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Trong lúc niêm nhà, ai đi vào thì sẽ bị lây ô uế cho đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Ai ngủ, hoặc ăn trong nhà đó phải giặt quần áo mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Nhưng sau khi nhà đã tô rồi, nếu thầy tế lễ trở lại, khám thấy vít không ăn lan trong nhà, thì phải định nhà là tinh sạch, vì vít đó đã lành rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Ðặng làm lễ nên thanh sạch cho nhà, người phải lấy hai con chim, cây hương nam, màu đỏ sặm và nhành kinh giới;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'giết một con chim trong chậu sành, trên nước chảy,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'rồi lấy cây hương nam, nhành kinh giới, màu đỏ sặm, và con chim sống, nhúng hết trong huyết con chim đã cắt cổ trên nước chảy, và rảy bảy lần trên nhà.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Vậy, người dùng huyết con chim, nước chảy, con chim sống, cây hương nam, nhành kinh giới, và màu đỏ sặm đặng làm lễ khiến nhà nên thanh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Ðoạn, người thả con chim sống bay ra ngoài thành đến nơi ruộng; người sẽ làm lễ chuộc tội cho nhà, thì nhà sẽ được sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Ðó là luật lệ về các thứ vít phung và tật đòng đanh,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'về vít mốc trên quần áo và nhà ở, như vít phung,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'về chỗ sưng, chỗ lở ra và chỗ đém,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'đặng dạy cho biết khi nào ô uế, và khi nào tinh sạch. Ðó là luật lệ về bịnh phung vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Phàm người nam nào thân mình bị bịnh bạch trược, thì vì cớ đó bị ô uế;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'sự ô uế người bởi nơi bạch trược: hoặc thân mình chảy bạch trược ra hay là ứ lại, thì người bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Hễ giường nào người bịnh bạch trược nằm, đều sẽ bị ô uế: và các vật nào người ngồi trên cũng sẽ bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Ai đụng đến giường người, phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Ai ngồi trên vật chi mà người bịnh bạch trược đã ngồi, phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Ai đụng đến mình người bịnh bạch trược, phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Nếu người bịnh bạch trược nhổ nhằm người nào tinh sạch, thì người đó phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Hễ xe nào người bịnh bạch trược ngồi lên đều sẽ bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Hễ ai đụng đến bất kỳ vật chi dưới mình người bịnh bạch trược, đều sẽ bị ô uế đến chiều tối. Còn ai mang các vật đó, phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Ai bị người bịnh bạch trược rờ đến mà nếu người bịnh đó không rửa tay mình trong nước, thì ai đó phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Ðồ sành bị người bịnh bạch trược đụng đến, phải đập bể đi, còn đồ gỗ, thì rửa trong nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Vả, khi người nam bị bịnh bạch trược đã lành rồi, thì phải tính từ ngày lành đến bảy ngày, kế giặt quần áo mình và tắm trong nước chảy; đoạn, người sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Qua ngày thứ tám, người bắt cho mình hai chim cu, hay là hai con bò câu con, đến trước mặt Ðức Giê-hô-va, tại cửa hội mạc, và đưa cho thầy tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Thầy tế lễ sẽ dâng con nầy làm của lễ chuộc tội, con kia làm của lễ thiêu; vậy, thầy tế lễ vì cớ bịnh bạch trược, sẽ làm lễ chuộc tội cho người trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Hễ người nam di tinh, phải tắm trọn mình trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Phàm quần áo và da bị dính, phải giặt rửa trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Khi nào người nam và người nữ giao cấu nhau, thì phải tắm trong nước, và bị ô uế cho đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Khi nào một người nữ có kinh nguyệt, phải chịu ô uế trong bảy ngày; hễ ai đụng đến người, sẽ bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Phàm vật gì người nằm hay ngồi trên trong lúc mình không sạch, sẽ bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Ai đụng đến giường người, phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Ai đụng đến vật gì người đã ngồi trên, phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Nếu có vật chi nơi giường, hoặc trên đồ người ngồi, hễ ai đụng đến, sẽ bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Ví bằng một người nam giao cấu cùng người nữ đó, và sự ô uế kinh nguyệt dính người nam, thì người nam sẽ bị ô uế trong bảy ngày; phàm giường nào người nằm đều cũng sẽ bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Khi một người nữ ngoài kỳ kinh nguyệt mình lại có lưu huyết nhiều ngày, hoặc là bị mất quá kỳ, sẽ bị ô uế trọn trong lúc lưu huyết như trong lúc kinh nguyệt mình vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Trong trọn lúc lưu huyết, bất kỳ giường nào người nằm trên sẽ như cái giường của kỳ kinh nguyệt, và mọi vật nào người ngồi trên, đều sẽ bị ô uế như trong kỳ kinh nguyệt vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Ai đụng đến các vật đó sẽ bị ô uế; phải giặt quần áo mình, tắm trong nước, và bị ô uế đến chiều tối.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Khi nào huyết người nữ cầm lại rồi, phải tính từ ngày lành đến bảy ngày, đoạn sẽ được tinh sạch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Qua ngày thứ tám, người bắt hai con chim cu, hoặc hai con bò câu con, đem đến thầy tế lễ tại cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Thầy tế lễ phải dâng con nầy làm của lễ chuộc tội, và con kia làm của lễ thiêu; vậy, thầy tế lễ vì cớ sự lưu huyết ô uế người sẽ làm lễ chuộc tội cho người trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Thế thì, các ngươi sẽ phân cách dân Y-sơ-ra-ên ra xa sự ô uế của họ, kẻo họ làm ô uế hội mạc ta vẫn ở giữa họ, mà phải chết trong sự ô uế mình chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Ðó là luật lệ về người nào bị bịnh bạch trược hay là vì cớ di tinh bị ô uế,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'về người nữ có kỳ kinh nguyệt, về mọi người, hoặc nam hay nữ, bị bạch trược, và về người nam giao cấu cùng người nữ trong khi kinh nguyệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Sau khi hai con trai của A-rôn chết trong lúc đến gần trước mặt Ðức Giê-hô-va, thì Ngài phán cùng Môi-se,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'mà rằng: Hãy nói cùng A-rôn, anh ngươi, chớ vào luôn luôn trong nơi thánh ở phía trong bức màn, trước nắp thi ân trên hòm bảng chứng, e người phải chết chăng; vì ta ở trong mây hiện ra trên nắp thi ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Nầy, A-rôn sẽ vào nơi thánh như vầy: Người phải bắt một con bò đực tơ, dùng làm của lễ chuộc tội, và một con chiên đực dùng làm của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Người sẽ mặc áo lá trong thánh bằng vải gai mịn, thân dưới mặc một cái quần bằng vải gai, thắt một đai bằng vải gai và đội trên đầu một cái mão bằng vải gai. Ấy là bộ áo thánh mà ngươi sẽ mặc lấy khi đã tắm mình trong nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Do nơi hội chúng Y-sơ-ra-ên, người sẽ bắt hai con dê đực dùng làm của lễ chuộc tội và một con chiên đực dùng làm của lễ thiêu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'A-rôn sẽ dâng con bò tơ mình làm của lễ chuộc tội, và người sẽ làm lễ chuộc tội cho mình và cho nhà mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Kế đó người phải bắt hai con dê đực, đem để trước mặt Ðức Giê-hô-va, tại nơi cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Ðoạn, A-rôn bắt thăm cho hai con dê đực, một thăm về phần Ðức Giê-hô-va, một thăm về phần A-xa-sên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'A-rôn sẽ biểu dẫn con dê đực bắt thăm về phần Ðức Giê-hô-va lại gần và dâng nó làm của lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Còn con bắt thăm về phần A-xa-sên, sẽ để sống trước mặt Ðức Giê-hô-va, để làm lễ chuộc tội trên nó, rồi thả nó ra nơi đồng vắng đặng nó về A-xa-sên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Vậy, A-rôn sẽ dâng con bò tơ mình, là con sinh tế chuộc tội, giết nó làm lễ chuộc tội cho mình và cho nhà mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'đoạn lấy lư hương đầy than hực đỏ trên bàn thờ trước mặt Ðức Giê-hô-va, và một vốc hương bột, mà đem vào phía trong bức màn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Người phải bỏ hương trên lửa, trước mặt Ðức Giê-hô-va, hầu cho ngọn khói hương bao phủ nắp thi ân ở trên hòm bảng chứng, thì người không chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Người cũng phải lấy huyết con bò tơ đó, dùng ngón tay rảy trên nắp thi ân, về phía đông, và rảy bảy lần về phía trước nắp thi ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Ðoạn, người giết con dê đực dùng về dân chúng làm của lễ chuộc tội; đem huyết nó vào phía trong bức màn; dùng huyết con dê đực đó cũng như đã dùng huyết con bò tơ, tức là rảy trên nắp thi ân và trước nắp thi ân vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Người vì cớ sự ô uế, sự vi phạm và tội lỗi của dân Y-sơ-ra-ên phải làm lễ chuộc tội cho nơi thánh và cho hội mạc ở giữa sự ô uế của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Khi thầy tế lễ vào đặng làm lễ chuộc tội nơi thánh cho đến khi người ra, thì chẳng nên có ai ở tại hội mạc; vậy, người sẽ làm lễ chuộc tội cho mình, cho nhà mình, và cho cả hội chúng Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Ðoạn, người ra, đi đến bàn thờ ở trước mặt Ðức Giê-hô-va, đặng làm lễ chuộc tội cho bàn thờ; người lấy huyết con bò tơ đực và con dê đực, bôi chung quanh những sừng của bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Rồi dùng ngón tay rảy huyết bảy lần trên bàn thờ, làm cho bàn thờ nên sạch và thánh, vì cớ những sự ô uế của dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Khi thầy tế lễ đã làm lễ chuộc tội cho nơi thánh, cho hội mạc, và cho bàn thờ rồi, thì người phải dâng con dê đực còn sống kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'A-rôn sẽ nhận hai tay mình trên đầu con dê đực còn sống, xưng trên nó các gian ác và sự vi phạm, tức những tội lỗi của dân Y-sơ-ra-ên, và chất trên đầu nó, rồi nhờ một người chực sẵn việc nầy mà sai đuổi nó ra, thả vào đồng vắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Vậy, con dê đực đó sẽ gánh trên mình các tội ác của dân Y-sơ-ra-ên ra nơi hoang địa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'A-rôn sẽ trở vào hội mạc, cổi bộ áo bằng vải gai mịn mình đã mặc đặng vào nơi thánh, và để tại đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Rồi lấy nước tắm mình trong một nơi thánh, mặc áo lại, đi ra, dâng của lễ thiêu về phần mình, và của lễ thiêu về phần dân chúng, đặng làm lễ chuộc tội cho mình và cho dân chúng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Người cũng phải lấy mỡ của con sinh tế chuộc tội mà xông trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Người nào dẫn con dê đực về phần A-xa-sên, phải giặt quần áo mình, tắm mình trong nước, đoạn mới sẽ được vào trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Nhưng người ta phải đem ra ngoài trại quân con bò tơ đực và con dê đực đã dâng lên làm của lễ chuộc tội, mà huyết nó đã đem vào nơi thánh đặng làm lễ chuộc tội; rồi phải lấy da, thịt và phẩn của hai thú đó mà đốt trong lửa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Kẻ nào đứng đốt phải giặt quần áo mình, tắm mình trong nước, đoạn mới được vào trại quân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Ðiều nầy sẽ là một lệ định đời đời cho các ngươi: đến mồng mười tháng bảy, các ngươi phải ép linh hồn mình, không nên làm một việc nào, bất kỳ người bổn xứ hay là kẻ khách kiều ngụ giữa các ngươi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'vì trong ngày đó người ta sẽ làm lễ chuộc tội cho các ngươi, để các ngươi được tinh sạch: chắc các ngươi sẽ được sạch những tội lỗi mình trước mặt Ðức Giê-hô-va vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ấy sẽ là một lễ Sa-bát, một ngày nghỉ cho các ngươi, phải ép linh hồn mình; đó là một lệ định đời đời vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Thầy tế lễ đã được phép xức dầu và lập làm chức tế lễ cho cha mình, sẽ mặc lấy bộ áo vải gai, tức là bộ áo thánh, mà làm lễ chuộc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Người sẽ chuộc tội cho nơi thánh, cho hội mạc, cho bàn thờ, cho những thầy tế lễ, và cho cả dân của hội chúng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Mỗi năm một lần phải làm lễ chuộc tội cho dân Y-sơ-ra-ên, đặng làm cho sạch các tội lỗi của chúng; ấy sẽ một lệ định đời đời cho các ngươi vậy. A-rôn làm y như Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Hãy nói cùng cả dân Y-sơ-ra-ên rằng: Nầy là lời Ðức Giê-hô-va phán dặn:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Nếu một người nam trong nhà Y-sơ-ra-ên giết một con bò, một con chiên con, hoặc một con dê trong trại quân hay là ngoài trại quân,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'chẳng đem đến cửa hội mạc đặng dâng cho Ðức Giê-hô-va, trước đền tạm của Ngài, thì huyết sẽ đổ tội về người; người đã làm đổ huyết ra, nên sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Ấy hầu cho dân Y-sơ-ra-ên lấy của lễ mình giết ngoài đồng, dẫn đến thầy tế lễ, trước mặt Ðức Giê-hô-va, tại cửa hội mạc, đặng dâng lên làm của lễ thù ân cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Thầy tế lễ sẽ rưới huyết con sinh trên bàn thờ của Ðức Giê-hô-va để tại cửa hội mạc, và xông mỡ có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Dân Y-sơ-ra-ên cũng chẳng nên dâng của lễ mình cho ma quỉ nữa, mà thông dâm cùng nó. Ðiều nầy sẽ làm một lệ định đời đời cho họ trải qua các thế đại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Vậy, ngươi hãy nói cùng dân Y-sơ-ra-ên rằng: Phàm người nào trong vòng dân Y-sơ-ra-ên hay là kẻ khách kiều ngụ giữa họ, dâng một của lễ thiêu hay là một của lễ chi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'mà chẳng đem đến tại cửa hội mạc đặng dâng cho Ðức Giê-hô-va, thì người đó sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Phàm người nào của nhà Y-sơ-ra-ên hay là kẻ khách kiều ngụ giữa họ, ăn huyết chi cũng mặc, thì ta sẽ nổi giận cùng kẻ ăn đó, truất nó khỏi dân sự mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'vì sanh mạng của xác thịt ở trong huyết; ta đã cho các ngươi huyết rưới trên bàn thờ đặng làm lễ chuộc tội cho linh hồn mình; vì nhờ sanh mạng mà huyết mới chuộc tội được.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Bởi cớ đó ta đã phán cùng dân Y-sơ-ra-ên rằng: Trong vòng các ngươi không ai nên ăn huyết; kẻ khách kiều ngụ giữa các ngươi cũng không nên ăn huyết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Còn nếu ai, hoặc dân Y-sơ-ra-ên. hoặc kẻ khách kiều ngụ giữa họ, đi săn được một con thú hay là con chim ăn thịt được, thì phải đổ huyết nó ra, rồi lấy bụi đất lấp lại;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'vì sanh mạng của mọi xác thịt, ấy là huyết nó, trong huyết có sanh mạng. Bởi cớ ấy, ta đã phán cùng dân Y-sơ-ra-ên rằng: Các ngươi không nên ăn huyết của xác thịt nào; vì sanh mạng của mọi xác thịt, ấy là huyết nó; ai ăn sẽ bị truất diệt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Hễ người nào, hoặc sanh đẻ tại xứ, hoặc kẻ khách, ăn thịt của một con thú chết hay là bị xé, phải giặt quần áo mình, tắm trong nước, bị ô uế đến chiều tối, đoạn được tinh sạch lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Còn nếu người không giặt quần áo và không tắm, thì sẽ mang tội mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Hãy nói cùng dân Y-sơ-ra-ên rằng: Ta là Giê-hô-va Ðức Chúa Trời các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Các ngươi chớ làm theo những điều người ta làm hoặc tại xứ Ê-díp-tô, là nơi các ngươi đã kiều ngụ, hoặc tại xứ Ca-na-an, là xứ ta dẫn các ngươi đi đến: chớ đi theo thói tục họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Các ngươi hãy tuân mạng lịnh ta, gìn giữ luật pháp ta đặng noi theo: Ta là Giê-hô-va Ðức Chúa Trời các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Vậy, hãy giữ luật pháp và mạng lịnh ta, người nào làm theo, thì sẽ nhờ nó mà được sống: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Chớ một ai trong vòng các ngươi đến gần cùng người nữ bà con mình đặng cấu hiệp: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Chớ cấu hiệp cùng mẹ mình; bằng cấu hiệp, tất làm nhục cho cha mẹ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Chớ cấu hiệp cùng kế mẫu, bằng cấu hiệp, ấy làm nhục cho cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Chớ cấu hiệp cùng chị em mình, hoặc một cha khác mẹ, hoặc một mẹ khác cha, hoặc sanh tại trong nhà, hoặc sanh ở ngoài.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Chớ cấu hiệp cùng cháu gái, hoặc cháu gái nội, hoặc cháu gái ngoại; bằng cấu hiệp, ấy là gây nhục cho mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Chớ cấu hiệp cùng con gái của kế mẫu bởi cha mình sanh ra, vì là em gái ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Chớ cấu hiệp cùng chị em của cha ngươi; vì là cốt nhục của cha ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Chớ cấu hiệp cùng chị em của mẹ ngươi; vì là cốt nhục của mẹ ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Chớ cấu hiệp cùng bác gái hay thím ngươi; bằng cấu hiệp, ấy là gây nhục cho anh em của cha ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Chớ cấu hiệp cùng dâu ngươi; vì là vợ của con trai mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Chớ cấu hiệp cùng chị dâu hay em dâu ngươi; nếu cấu hiệp, ấy làm nhục cho anh em ngươi vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Chớ cấu hiệp cùng một người đàn bà luôn với con gái của người đàn bà nữa. Chớ lấy cháu gái nội ngươi, hoặc cháu gái ngoại ngươi đặng cấu hiệp cùng họ; chúng nó đều là cốt nhục gần; làm vậy, ấy là một việc ác dục.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Chớ lấy vợ luôn với chị em người mà cấu hiệp cùng nó gần bên vợ chánh mình đương khi người còn sống, e khi sanh ghen tương.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Trong lúc người nữ có kinh nguyệt, chớ đến gần mà cấu hiệp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Chớ nằm cùng vợ người lân cận mình, mà gây cho mình bị ô uế với người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Chớ bắt con cái mình đặng dâng cho thần Mo-lóc, chớ làm ô danh Ðức Chúa Trời ngươi: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Chớ nằm cùng một người nam như người ta nằm cùng một người nữ; ấy là một sự quái gớm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Chớ nằm cùng một con thú nào, mà gây cho mình bị ô uế với nó; một người đàn bà chớ nằm cùng thú vật nào; ấy là một sự quái gớm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Các ngươi chớ làm một trong mấy việc đó mà tự gây cho mình ô uế; bởi dân mà ta sẽ đuổi khỏi trước mặt các ngươi đã thành ô uế vì cớ làm các việc đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Ðất vì chúng nó mà bị ô uế; ta sẽ phạt tội ác họ; đất sẽ mửa dân nó ra vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Còn các ngươi, hoặc dân bổn xứ, hoặc kẻ khách kiều ngụ giữa các ngươi, phải giữ luật pháp và mạng lịnh ta, đừng làm một trong những điều quái gớm nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Vì những điều quái gớm ấy, những người ở tại xứ trước các ngươi đã làm; và đất vì cớ đó phải thành ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Vậy, chớ làm đất thành ô uế, e khi đất mửa các ngươi ra, như đã mửa dân cư trú tại xứ trước các ngươi chăng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'vì phàm ai làm một trong những điều quái gớm ấy sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Thế thì, các ngươi phải giữ điều ta phán dặn, để đừng làm theo một trong các thói tục gớm ghiếc nào đã làm trước các ngươi, và các ngươi chớ vì các thói tục đó mà gây cho mình ô uế. Ta là Giê-hô-va Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Hãy truyền cho cả hội chúng Y-sơ-ra-ên rằng: Hãy nên thánh, vì ta Giê-hô-va Ðức Chúa Trời các người, vốn là thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ai nấy phải tôn kính cha mẹ mình và giữ những ngày sa-bát ta: Ta là Giê-hô-va Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Chớ xây về hình tượng và cũng chớ đúc tượng tà thần: Ta là Giê-hô-va Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Khi các ngươi dâng của lễ thù ân cho Ðức Giê-hô-va, thì phải dâng một cách cho được nhậm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'ăn nội trong ngày dâng đó và ngày mai; còn phần chi dư lại qua ngày thứ ba, thì phải thiêu đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Nếu người ta để ăn đến ngày thứ ba, ấy là một điều gớm ghiếc chẳng được nhậm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ai ăn của lễ như vậy sẽ mang lấy tội ác mình, vì đã làm vật thánh của Ðức Giê-hô-va ra ô độc: người đó sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Khi các ngươi gặt lúa trong xứ mình, chớ có gặt đến cuối đầu đồng, và chớ mót lại những bông còn sót;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'các ngươi chớ cắn mót nho mình, đừng nhặt những trái rớt rồi, hãy để cho mấy người nghèo và kẻ khách: Ta là Giê-hô-va Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Các ngươi chớ ăn trộm ăn cắp, chớ nói dối, và chớ lừa đảo nhau.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Các ngươi chớ chỉ danh ta mà thề dối, vì ngươi làm ô danh của Ðức Chúa Trời mình: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Chớ ức hiếp kẻ lân cận mình, chớ cướp giựt của họ. Tiền công của kẻ làm mướn ngươi, chớ nên để lại trong nhà mình cho đến ngày mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Chớ nên rủa sả người điếc, chớ để trước mặt người mù vật chi làm cho người vấp té; nhưng hãy kính sợ Ðức Chúa Trời ngươi: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Các ngươi chớ phạm sự bất nghĩa trong việc xét đoán, chớ thiên vị người nghèo, chớ nể kẻ quyền thế; hãy cứ theo công bình mà xét đoán kẻ lân cận ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Chớ buông lời phao vu trong dân sự mình, chớ lập mưu kế nghịch sự sống của kẻ lân cận mình: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Chớ có lòng ghen ghét anh em mình; hãy sửa dạy kẻ lân cận mình, đừng vì cớ họ mà phải mắc tội.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Chớ toan báo thù, chớ giữ sự báo thù cùng con cháu dân sự mình; nhưng hãy yêu thương kẻ lân cận ngươi như mình: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Các ngươi hãy giữ những mạng lịnh ta. Chớ để loài vật khác giống phủ lẫn nhau; chớ gieo ruộng ngươi hai thứ giống, và chớ mặc mình bằng áo dệt nhiều thứ chỉ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Nếu một người nam nằm và cấu hiệp cùng một đứa tớ gái đã hứa gả cho một người, nhưng chưa chuộc ra, hoặc chưa được phóng mọi; thì hai người đều sẽ bị hình phạt, mà không phải đến chết, vì đứa tớ gái chưa được phóng mọi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Người nam vì lỗi mình sẽ dẫn một con chiên đực đến trước mặt Ðức Giê-hô-va tại cửa hội mạc, mà làm của lễ chuộc sự mắc lỗi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Thầy tế lễ sẽ dùng con chiên đực làm của lễ chuộc sự mắc lỗi đặng làm lễ chuộc tội cho người đã phạm, trước mặt Ðức Giê-hô-va; vậy, tội người đã phạm sẽ được tha.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Khi các ngươi sẽ vào xứ Ca-na-an, và đã trồng các thứ cây trái rồi, hãy coi các trái chiếng nó không sạch, như chưa chịu phép cắt bì; trong ba năm các ngươi hãy coi nó không sạch, chớ nên ăn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'nhưng qua năm thứ tư, các trái nó sẽ nên thánh làm của lễ khen ngợi Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Qua năm thứ năm, các ngươi phải ăn trái, hầu cho cây thêm hoa quả: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Các ngươi chớ ăn vật chi có huyết, chớ dùng bói khoa, chớ làm thuật số.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Chớ cắt mé tóc mình cho tròn, và chớ nên phá khóe râu mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Chớ vì kẻ chết mà cắt thịt mình, chớ xăm vẽ trên mình: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Chớ nhục con gái ngươi khiến nó làm kỵ nữ, để trong xứ không có điều dâm loạn và đầy dẫy những ác dục.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Các ngươi phải giữ những sa-bát ta, và tôn kính nơi thánh ta: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Các ngươi chớ cầu đồng cốt hay là thầy bói; chớ hỏi chúng nó, e vì chúng nó mà các ngươi phải bị ô uế: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Trước mặt người tóc bạc, ngươi hãy đứng dậy, kính người già cả, và kính sợ Ðức Chúa Trời ngươi. Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Khi kẻ khách nào kiều ngụ trong xứ các ngươi, thì chớ hà hiếp người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Kẻ khách kiều ngụ giữa các ngươi sẽ kể như kẻ đã sanh đẻ giữa các ngươi; hãy thương yêu người như mình, vì các ngươi đã làm khách kiều ngụ trong xứ Ê-díp-tô: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Các ngươi chớ phạm sự bất nghĩa trong việc xét đoán, hoặc sự đo, sự cân, hay là sự lường.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Các ngươi phải có cân thiệt, trái cân bằng đá đúng, một ê-pha thiệt, và một hin thiệt: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi, Ðấng đã dẫn các ngươi ra khỏi xứ Ê-díp-tô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Vậy, các ngươi hãy gìn giữ làm theo các luật pháp và các mạng lịnh ta: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Ngươi hãy nói cùng dân Y-sơ-ra-ên rằng: Phàm ai trong dân Y-sơ-ra-ên hay là kẻ khách kiều ngụ giữa vòng họ, dùng một trong các con mình dâng cho thần Mo-lóc, thì chắc sẽ bị xử tử: dân bổn xứ phải ném đá người ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Còn ta sẽ nổi giận cùng người đó, truất nó khỏi dân sự mình, vì nó đã nộp con cái mình cho thần Mo-lóc, làm cho nơi thánh ta ô uế, và làm ô danh thánh ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Nếu dân bổn xứ nhắm mắt khi người đó dâng một trong các con cái nó cho thần Mo-lóc mà chẳng giết nó đi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'thì ta đây sẽ nổi giận cùng người đó và nhà nó, rồi truất nó cùng những kẻ nào theo nó mà thông dâm cùng thần Mo-lóc, ra khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Nếu ai xây về đồng cốt và thầy bói mà thông dâm cùng chúng nó, thì ta sẽ nổi giận cùng người đó, truất nó ra khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Các ngươi hãy làm sạch mình, và hãy nên thánh, vì ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Các ngươi hãy giữ làm theo những luật pháp ta: Ta là Ðức Giê-hô-va, Ðấng làm cho các ngươi nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Khi một người nào chửi cha mắng mẹ mình, thì phải bị xử tử: nó đã chửi rủa cha mẹ; huyết nó sẽ đổ lại trên mình nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Nếu người nào phạm tội tà dâm cùng vợ của người khác, hay là phạm tội tà dâm cùng vợ người lân cận mình, người nam cùng người nữ đó đều phải bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Nếu người nào nằm cùng vợ cha mình, ấy là gây nhục cho cha mình, thì hai người đều hẳn phải bị xử tử; huyết họ sẽ đổ lại trên mình họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Nếu người nào nằm cùng dâu mình, hai người đều hẳn phải bị phạt xử tử; vì họ phạm một sự gớm ghiếc; huyết họ sẽ đổ lại trên mình họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Nếu một người nam nằm cùng một người nam khác, như nằm cùng người nữ, thì hai người đó đều hẳn phải bị xử tử, vì họ đã làm một sự gớm ghiếc; huyết họ sẽ đổ lại trên mình họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Nếu một người nam lấy cả và mẹ con làm vợ; ấy là một sự tà ác; hãy thiêu cả ba đi, hầu cho sự tà ác đó không còn trong vòng các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Nếu một người nam cấu hiệp cùng thú vật, thì hẳn phải bị xử tử, và các ngươi hãy giết thú đó đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Nếu một người nữ lại gần một con thú đặng cấu hiệp cùng nó, ngươi hãy giết người nữ và con thú đó đi; huyết nó sẽ đổ lại trên mình nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Nếu một người nam lấy chị em gái mình, hoặc một cha khác mẹ, hoặc một mẹ khác cha, và họ cấu hiệp nhau; ấy là sự điếm nhục; họ sẽ bị truất khỏi trước mặt dân sự mình; người đã gây nhục cho chị em mình; người sẽ mang tội ác mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Nếu một người nam nằm cùng một người nữ trong lúc có kinh nguyệt, và người nam lộ ra nguyên huyết của người nữ, và chánh người nữ cũng lộ ra nguyên huyết mình, thì cả hai đều sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Chớ cấu hiệp cùng chị em của mẹ hay là chị em của cha ngươi, vì là gây nhục cho thân tộc mình; hai người đều sẽ mang tội ác mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Nếu người nam nằm cùng bác gái hay thím mình, tức là gây nhục cho chú bác mình; hai người đều sẽ mang sự hình phạt của tội mình. Họ sẽ chết tuyệt tự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Nếu một người nam lấy vợ của anh em mình, ấy là sự ô uế; người đó đã gây nhục cho anh em mình. Hai người đó sẽ tuyệt tự.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Các ngươi hãy gìn giữ làm theo những luật pháp và mạng lịnh ta, hầu cho xứ mà ta dẫn các ngươi đến ở không mửa các ngươi ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Chớ nên noi theo thói tục của dân mà ta sẽ đuổi ra khỏi trước mặt các ngươi, vì họ đã làm những điều đó, và ta lấy làm gớm ghiếc lắm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Ta đã phán cùng các ngươi rằng: Ấy là các ngươi sẽ được xứ của dân đó; ta cho các ngươi xứ ấy đặng làm sản nghiệp; ấy là một xứ đượm sữa và mật: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi, đã phân rẽ các ngươi cùng các dân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Vậy, hãy phân biệt thú tinh sạch với thú ô uế, chim ô uế với chim tinh sạch; chớ gây cho mình ra gớm ghiếc vì loài vật, vì chim chóc, vì các loài côn trùng trên mặt đất, mà ta đã dạy các ngươi phân biệt như loài ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Ðối cùng ta các ngươi hãy nên thánh, vì ta, Ðức Giê-hô-va, là thánh; ta đã phân rẽ các ngươi với các dân, để các ngươi thuộc về ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Khi nào một người nam hay nữ làm đồng cốt, hay là bói khoa, thì hẳn sẽ bị xử tử; người ta sẽ ném đá chúng nó: huyết chúng nó sẽ đổ lại trên mình chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng: Hãy nói cùng những thầy tế lễ, là các con trai A-rôn, mà rằng: Thầy tế lễ chớ vì một người chết trong dân sự là làm cho mình ra ô uế;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'trừ ra vì bà con thân thích mình, vì mẹ, cha, con trai, con gái, anh em mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'và vì chị em ruột mình còn đồng trinh, chưa chồng, thì người được vì chị em đó làm cho mình ra ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Người là đầu trưởng trong dân sự mình, chớ làm mình ra tục mà bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Các thầy tế lễ chớ nên làm sói trên đầu; chớ cạo mép râu mình, đừng cắt thịt mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Họ sẽ biệt riêng ra thánh cho Ðức Chúa Trời mình, và chớ làm ô danh Ngài, vì họ dâng cho Ðức Giê-hô-va các của lễ dùng lửa thiêu; tức là thực vật của Ðức Chúa Trời mình: họ phải nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Thầy tế lễ chớ nên cưới một người kỵ nữ hay là kẻ dâm ô; cũng chẳng nên cưới người bị chồng để, vì thầy tế lễ đã biệt riêng ra thánh cho Ðức Chúa Trời mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Vậy, ngươi hãy kể thầy tế lễ như thánh, vì người dâng thực vật của Ðức Chúa Trời người; người sẽ là thánh cho ngươi, vì ta, Ðức Giê-hô-va, là thánh, Ðấng làm cho các ngươi nên thánh vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Nếu con gái thầy tế lễ đi dâm ô, tự làm nên kỵ nữ, ấy là làm ô danh cho cha nó, nó phải bị thiêu lửa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Thầy tế lễ được quyền trọng hơn các anh em mình, đã được rưới dầu xức trên đầu mình, được biệt riêng ra thánh, để mặc mình bằng bộ áo thánh, chẳng nên để đầu trần và xé áo mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Ngươi chớ đi đến cùng một kẻ chết, chớ vì cha hay mẹ mà làm mình ra ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Người chẳng nên đi ra khỏi nơi thánh, đừng làm cho nơi thánh của Ðức Chúa Trời mình ra ô uế, vì cái mão dầu xức của Ðức Chúa Trời vẫn ở trên đầu người: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Người phải cưới gái đồng trinh làm vợ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Người chẳng nên cưới đàn bà góa, bị để, dâm ô hay là kỵ nữ, nhưng phải cưới một người đồng trinh trong vòng dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Người chẳng nên làm ô danh dòng họ mình giữa dân sự người, vì ta là Ðức Giê-hô-va làm cho người nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Ðức Giê-hô-va còn phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Hãy nói cùng A-rôn mà rằng: Phàm ai trong dòng họ ngươi, trải các đời, có một tật bịnh trong thân thể, chớ đến gần mà dâng thực vật cho Ðức Chúa Trời mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Phàm ai có một tật không được đến gần, như đây: người mù, què, sệp mũi hay là tứ chi không đều;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'người gãy chân hay gãy tay,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'người có bướu hay là lỏng khỏng, có vảy cá mắt hay là có ghẻ chốc, có lát hay là có hòn nang dập.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Phàm con cháu thầy tế lễ A-rôn, có tật trong mình, không được đến gần dâng của lễ dùng lửa dâng lên cho Ðức Giê-hô-va. Nếu có một tật trong mình, không được đến gần dâng thực vật cho Ðức Chúa Trời mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Người được ăn thực vật của Ðức Chúa Trời mình, là các vật chí thánh và các vật biệt riêng ra thánh;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'nhưng không được đi đến gần bàn thờ, vì có tật nơi mình. Ngươi chớ làm các nơi thánh ta ra ô uế, vì ta, Ðức Giê-hô-va, làm các nơi đó nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Môi-se nói như vậy cho A-rôn và các con trai người, cùng cho cả dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Hãy truyền cho A-rôn và các con trai người rằng phải kiêng cữ những của lễ thánh của dân Y-sơ-ra-ên, dâng biệt riêng ra thánh cho ta, hầu cho chúng chớ làm ô danh thánh ta: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Hãy nói với họ rằng: Phàm ai trong dòng giống các ngươi và trong vòng con cháu các ngươi đã bị ô uế, đến gần các vật thánh mà dân Y-sơ-ra-ên biệt riêng cho Ðức Giê-hô-va, thì ai đó sẽ bị truất khỏi trước mặt ta: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Phàm ai là con cháu của A-rôn bị bịnh phung hay là bạch trược, thì chẳng được ăn vật biệt riêng ra thánh cho đến chừng nào được tinh sạch. Ai đụng đến một người đã bị ô uế bởi xác chết, ai có di tinh,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'hay là ai đụng đến hoặc loài côn trùng, hoặc một người bị sự ô uế nào làm cho mình ô uế, thì cũng phải một thể ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Ai đụng đến các vật đó sẽ bị ô uế đến chiều tối, không được ăn vật biệt riêng ra thánh, nhưng phải tắm mình trong nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Sau khi mặt trời lặn, người sẽ được sạch lại, rồi mới được phép ăn các vật thánh, vì là đồ ăn của người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Người chẳng nên ăn một con thú nào chết tự nhiên hay là bị xé, hầu khỏi bị ô uế: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Vậy, họ phải giữ điều ta phán dặn, kẻo mang tội lỗi và chết chăng, vì đã làm các vật thánh nay ra ô uế: Ta là Ðức Giê-hô-va làm cho họ nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Chẳng một kẻ khách ngoại bang nào được ăn vật thánh; kẻ nào ở tại nhà thầy tế lễ hay là người làm mướn, cũng chẳng được ăn vật thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Nhưng kẻ nào thầy tế lễ lấy bạc mua về, và kẻ sanh đẻ tại nhà người, thì được phép ăn đồ ăn của người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Nếu con gái của thầy tế lễ kết thân cùng kẻ khách ngoại bang, thì sẽ không được ăn vật thánh dâng giơ lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Còn nếu con gái của thầy tế lễ đã góa hay là bị để, không có con, trở về nhà cha ở như buổi còn thơ, thì nàng sẽ được ăn đồ ăn của cha mình, nhưng chẳng kẻ khách ngoại bang nào nên ăn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Nếu ai lầm ăn một vật thánh, thì phải đền lại cho thầy tế lễ giá của vật thánh đó, và phụ thêm một phần năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Thầy tế lễ chớ làm ô uế của lễ mà dân Y-sơ-ra-ên dâng giơ lên cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Ai ăn vật thánh đã dâng như vậy sẽ mang tội mình đã phạm, vì ta là Ðức Giê-hô-va làm cho các vật đó nên thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Hãy truyền cho A-rôn và các con trai người, cùng cho cả dân Y-sơ-ra-ên, mà rằng: Hễ người nhà Y-sơ-ra-ên hay là kẻ khách kiều ngụ giữa họ, mà dâng của lễ thiêu cho Ðức Giê-hô-va, hoặc của lễ khấn nguyện, hay là của lễ lạc ý, hầu cho được nhậm,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'phải dâng một con đực không tì vít chi bắt trong bầy bò, hoặc chiên con hay là dê cái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Các ngươi chớ dâng một con vật nào có tì vít, vì nó sẽ không được nhậm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Khi một người nào dâng cho Ðức Giê-hô-va một của lễ thù ân bằng bò hay chiên, hoặc dâng trả lễ khấn nguyện hay là lạc ý, hầu cho con sinh được nhậm, phải không có một tì vít chi trên mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Các ngươi chớ dâng cho Ðức Giê-hô-va một con thú nào hoặc mù mắt, què cẳng, bị xé, ghẻ chốc, hay là lát; các ngươi chớ bắt nó làm của lễ dùng lửa dâng lên cho Ðức Giê-hô-va trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Các ngươi được bắt một con bò hay chiên con có giò dài, hoặc ngắn quá mà làm của lễ lạc ý; nhưng về của lễ khấn nguyện, con thú như vầy quả sẽ chẳng được nhậm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Các ngươi chớ dâng cho Ðức Giê-hô-va tại xứ mình một con thú nào hòn nang bị dập nát, rứt hay là thiến đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Chớ nhận nơi tay kẻ khách ngoại bang một con sinh nào bị như vậy đặng dâng làm thực vật cho Ðức Chúa Trời mình, vì nó đã bị hư và có tì vít trên mình, không được nhậm vì các ngươi đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Hễ con bò con, con chiên con hay con dê con, phải ở quẩn theo mẹ trong bảy ngày sau khi lọt lòng; nhưng qua ngày thứ tám về sau sẽ được nhậm làm của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Bất kỳ bò cái hay chiên cái, các ngươi chớ giết nó và con nó trong một ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Khi các ngươi dâng của lễ thù ân cho Ðức Giê-hô-va, thì phải dâng thế nào cho của lễ vì các ngươi được nhậm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Của lễ đó phải ăn nội ngày, không nên để chi lại cho đến sớm mai: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Vậy, hãy giữ làm theo các điều răn ta: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Ðừng làm ô danh thánh ta, thì ta sẽ được tôn thánh giữa dân Y-sơ-ra-ên: Ta là Ðức Giê-hô-va làm cho các ngươi nên thánh,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'tức Ðấng đã đem các ngươi ra khỏi xứ Ê-díp-tô, để làm Ðức Chúa Trời các ngươi: Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Nầy là những ngày lễ của Ðức Giê-hô-va các ngươi hãy rao truyền ra là các hội thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Người ta làm việc trong sáu ngày, nhưng qua ngày thứ bảy là ngày sa-bát, một ngày nghỉ, tức một sự nhóm hiệp thánh; đừng làm một công việc gì; ấy là lễ sa-bát của Ðức Giê-hô-va trong những nơi các ngươi ở.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Nầy là những lễ của Ðức Giê-hô-va, tức những sự nhóm hiệp thánh, các ngươi phải rao truyền ra khi đến kỳ nhất định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Ðến ngày mười bốn tháng giêng, vào buổi chiều tối, ấy là lễ Vượt-qua của Ðức Giê-hô-va;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'qua ngày rằm tháng nầy, ấy là lễ bánh không men để kính trọng Ðức Giê-hô-va; các ngươi sẽ ăn bánh không pha men trong bảy ngày.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Ngày đầu, các ngươi sẽ có một sự nhóm hiệp thánh, chẳng nên làm một công việc xác thịt.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Trong bảy ngày các ngươi phải dâng cho Ðức Giê-hô-va những của lễ dùng lửa dâng lên; đến ngày thứ bảy, sẽ có một sự nhóm hiệp thánh nữa, các ngươi đừng làm một công việc xác thịt nào hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Khi nào các ngươi đã vào xứ mà ta sẽ ban cho, và đã gặt mùa màng rồi, thì hãy đem đến cho thầy tế lễ một bó lúa đầu mùa của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Qua ngày sau lễ sa-bát, thầy tế lễ sẽ dâng bó lúa đưa qua đưa lại trước mặt Ðức Giê-hô-va, hầu cho bó lúa đó được nhậm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Chánh ngày dâng bó lúa đưa qua đưa lại đó, các ngươi cũng phải dâng cho Ðức Giê-hô-va một chiên con giáp năm, không tì vít chi, đặng làm của lễ thiêu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'và dâng thêm một của lễ chay bằng hai phần mười bột lọc chế dầu, làm của lễ dùng lửa dâng lên, có mùi thơm cho Ðức Giê-hô-va, với một phần tư hin rượu, làm lễ quán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Các ngươi chớ ăn hoặc bánh, hoặc hột lúa rang, hoặc lúa đang ở trong gié cho đến chánh ngày nầy, tức là ngày các ngươi đem dâng của lễ cho Ðức Chúa Trời mình. Mặc dầu ở nơi nào, ấy là một lệ định đời đời cho con cháu các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Kể từ ngày sau lễ sa-bát, là ngày đem bó lúa dâng đưa qua đưa lại, các ngươi sẽ tính bảy tuần lễ trọn:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'các ngươi tính năm mươi ngày cho đến ngày sau của lễ sa-bát thứ bảy, thì phải dâng một của lễ chay mới cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Các ngươi hãy từ nhà mình đem đến hai ổ bánh đặng làm của lễ dâng đưa qua đưa lại; bánh đó làm bằng hai phần mười bột lọc hấp có pha men: ấy là của đầu mùa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Các ngươi cũng phải dâng luôn với bánh, bảy chiên con giáp năm chẳng tì vít chi, một con bò tơ, và hai con chiên đực với của lễ chay và lễ quán cặp theo, đặng làm của lễ thiêu tế Ðức Giê-hô-va: ấy là một của lễ dùng lửa xông, có mùi thơm cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Các ngươi cũng phải dâng một con dê đực đặng làm của lễ chuộc tội, và hai chiên con giáp năm, đặng làm của lễ thù ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Thầy tế lễ sẽ lấy các của lễ đó với hai ổ bánh bằng lúa đầu mùa, và hai chiên con, dâng đưa qua đưa lại trước mặt Ðức Giê-hô-va; các vật đó sẽ biệt riêng ra thánh cho Ðức Giê-hô-va, và thuộc về thầy tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Các ngươi hãy rao truyền sự nhóm hiệp trong chánh một ngày đó; phải có một sự nhóm hiệp thánh, chớ nên làm một công việc xác thịt nào. Ấy là một lệ định đời đời cho dòng dõi các ngươi, mặc dầu ở nơi nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Khi các ngươi gặt lúa trong xứ mình, chớ gặt tận đầu đồng, và chớ mót lúa sót lại; hãy để phần đó cho người nghèo và cho kẻ khách ngoại bang: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Ngày mồng một tháng bảy, sẽ có cho các ngươi một ngày nghỉ, một lễ kỷ niệm lấy tiếng kèn thổi mà rao truyền, tức là một sự nhóm hiệp thánh vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Chớ làm một công việc xác thịt nào; phải dâng các của lễ dùng lửa dâng cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Ðức Giê-hô-va cũng phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Ngày mồng mười tháng bảy nầy là ngày lễ chuộc tội; các ngươi sẽ có sự nhóm hiệp thánh; hãy ép tâm hồn mình và dâng cho Ðức Giê-hô-va các của lễ dùng lửa dâng lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Ngày đó chẳng nên làm công việc nào, vì là ngày chuộc tội, trong ngày đó phải làm lễ chuộc tội cho các ngươi trước mặt Giê-hô-va, Ðức Chúa Trời mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Trong ngày đó, hễ ai không ép tâm hồn mình, sẽ bị truất khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Và hễ ai làm một công việc gì, thì ta sẽ diệt họ khỏi dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Các ngươi chẳng nên làm công việc chi hết, ấy là một lệ định đời đời cho dòng dõi các ngươi, mặc dầu ở nơi nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ấy sẽ là một lễ sa-bát, một ngày nghỉ cho các ngươi; các ngươi phải ép tâm hồn mình. Ngày mồng chín tháng đó, các ngươi phải giữ lễ sa-bát mình, từ chiều nay đến chiều mai.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Ngày rằm tháng bảy nầy là lễ lều tạm, trải qua bảy ngày đặng tôn kính Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Ngày thứ nhất sẽ có sự nhóm hiệp thánh, các ngươi chẳng nên làm một công việc xác thịt nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Trong bảy ngày phải dâng các của lễ dùng lửa dâng cho Ðức Giê-hô-va; qua ngày thứ tám, các ngươi có một sự nhóm hiệp thánh nữa, cũng dâng của lễ dùng lửa dâng cho Ðức Giê-hô-va. Ấy sẽ là một hội trọng thể; chớ nên làm một công việc xác thịt nào hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Ðó là những lễ trọng thể của Ðức Giê-hô-va, mà các ngươi phải rao truyền là sự nhóm hiệp thánh, đặng dâng cho Ðức Giê-hô-va những của lễ dùng lửa dâng lên, của lễ thiêu, của lễ chay, của lễ thù ân, lễ quán, vật nào đã định theo ngày nấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Ngoài ra, các ngươi phải cứ giữ lễ sa-bát của Ðức Giê-hô-va, cứ dâng cho Ngài các lễ vật mình, các của lễ khấn nguyện và lạc ý.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Nhưng đến ngày rằm tháng bảy, khi các ngươi đã thâu-hoạch thổ sản mình rồi, hãy giữ một lễ cho Ðức Giê-hô-va trong bảy ngày. Bữa thứ nhất sẽ là ngày nghỉ, và bữa thứ tám cũng sẽ là ngày nghỉ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Bữa thứ nhất, các ngươi phải lấy trái cây tốt, tàu chà là, nhành cây rậm, và cây dương liễu, rồi vui mừng trong bảy ngày trước mặt Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Mỗi năm, vào tháng bảy, các ngươi phải giữ lễ nầy cho Ðức Giê-hô-va như vậy trong bảy ngày. Ấy là một lệ định đời đời cho dòng dõi các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Hết thảy ai sanh trong dòng Y-sơ-ra-ên sẽ ở nơi trại trong bảy ngày,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'hầu cho dòng dõi các ngươi biết rằng khi ta đem dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô, ta cho họ ở trong những trại: Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Ấy vậy, Môi-se truyền cho dân Y-sơ-ra-ên biết các lễ của Ðức Giê-hô-va là lễ nào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Hãy truyền cho dân Y-sơ-ra-ên đem dầu ô-li-ve ép, trong sạch, đặng thắp đèn, để giữ cho đèn cháy luôn luôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'A-rôn sẽ làm đèn đó trong hội mạc, ngoài bức màn che hòm bảng chứng, hầu cho đèn cháy luôn luôn, từ chiều tối đến sáng mai, trước mặt Ðức Giê-hô-va; ấy là một lệ định đời đời cho dòng dõi các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'A-rôn sẽ để các đèn trên chân đèn bằng vàng, cho đèn cháy luôn luôn trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Ngươi cũng phải lấy bột lọc, hấp mười hai ổ bánh; mỗi ổ cân nặng hai phần mười ê-pha;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'đoạn sắp ra hai hàng sáu ổ trên cái bàn bằng vàng ròng trước mặt Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'cùng rắc nhũ hương thánh trên mỗi hàng, để làm kỷ niệm trên bánh, như một của lễ dùng lửa dâng trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Mỗi ngày sa-bát, người ta sẽ sắp bánh nầy trước mặt Ðức Giê-hô-va luôn luôn, do nơi dân Y-sơ-ra-ên cung cấp; ấy là một giao ước đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Các bánh đó sẽ thuộc về A-rôn và các con trai người; họ phải ăn tại một nơi thánh, vì là vật chí thánh cho họ, bởi các của lễ dùng lửa dâng cho Ðức Giê-hô-va. Ấy là một lệ định đời đời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Có một đứa con trai, mẹ là người Y-sơ-ra-ên, và cha là người Ê-díp-tô, đi ra giữa vòng dân Y-sơ-ra-ên, đánh lộn tại nơi trại quân với một người Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Ðứa trai đó nói phạm đến và rủa sả danh Ðức Giê-hô-va; người ta dẫn nó đến Môi-se, bèn giam nó vào ngục cho đến chừng Ðức Giê-hô-va phán định phải xử làm sao.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Mẹ nó tên là Sê-lô-mít, con gái của Ðiệp-ri, thuộc về chi phái Ðan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Vả, Ðức Giê-hô-va bèn phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Hãy đem kẻ đã rủa sả ra ngoài trại quân, hết thảy ai đã có nghe nó phải đặt tay mình trên đầu nó, và cả hội chúng phải ném đá nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Ðoạn hãy nói cùng dân Y-sơ-ra-ên rằng: Người nào rủa sả Ðức Chúa Trời mình sẽ mang sự hình phạt của tội mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Ai nói phạm đến danh Ðức Giê-hô-va hẳn sẽ bị xử tử; cả hội chúng sẽ ném đá nó: mặc dầu nó là kẻ khách ngoại bang hay là sanh trong xứ, hễ khi nào nói phạm đến danh Ðức Giê-hô-va, thì sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Kẻ nào đánh chết một người nào, mặc dầu kẻ đó là ai, sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Kẻ nào đánh chết một súc vật, phải thường lại, nghĩa là mạng đền mạng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Khi một người nào làm thương tích cho kẻ lân cận mình, thì người ta phải làm thương tích cho người đó lại như chính người đã làm:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'gãy đền gãy, mắt đền mắt, răng đền răng. Người ta sẽ làm cho người ấy đồng một thương vít như chính người đã làm cho người khác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kẻ nào làm chết một súc vật, thì sẽ thường lại; còn kẻ nào giết chết một người, thì phải bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Bất luận kẻ khách ngoại bang hay là người trong xứ, các ngươi cũng phải dùng một luật lệ: vì ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Vậy, Môi-se nói lại cùng dân Y-sơ-ra-ên, biểu đem kẻ đã rủa sả ra khỏi trại quân rồi ném đá nó. Thế thì, dân Y-sơ-ra-ên làm y như lời Ðức Giê-hô-va đã truyền dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Ðức Giê-hô-va cũng phán cùng Môi-se tại trên núi Si-na -i rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Khi các ngươi đã vào xứ ta sẽ ban cho rồi, thì đất phải nghỉ, giữ một lễ sa-bát cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Trong sáu năm, ngươi sẽ gieo ruộng và hớt nho mình, cùng thâu hoạch thổ sản.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Nhưng năm thứ bảy sẽ là năm sa-bát, để cho đất nghỉ, tức là một năm sa-bát cho Ðức Giê-hô-va; ngươi chẳng nên gieo ruộng mình hay là hớt nho mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'chẳng nên gặt lại những chi đã tự mọc lên sau khi mùa màng, và đừng hái nho của vườn nho không hớt sửa: ấy sẽ là một năm cho đất nghỉ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Phàm vật gì mà đất sanh sản trong năm sa-bát, sẽ dùng làm đồ ăn cho ngươi, cho tôi trai tớ gái ngươi, cho kẻ làm thuê của ngươi, và cho kẻ ngoại bang kiều ngụ với ngươi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'cùng luôn cho lục súc và thú vật ở trong xứ ngươi nữa; hết thảy thổ sản dùng làm đồ ăn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Ngươi cũng hãy tính bảy tuần năm tức bảy lần bảy năm; thì giờ của bảy tuần năm nầy sẽ là bốn mươi chín năm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'rồi đến ngày mồng mười tháng bảy, tức là ngày chuộc tội, các ngươi phải thổi kèn vang trong khắp xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Các ngươi phải làm cho năm thứ năm mươi nên thánh, và rao truyền sự tự do cho hết thảy dân trong xứ. Ấy sẽ là năm hân hỉ cho các ngươi; ai nấy đều được nhận lại cơ nghiệp mình, và ai nấy đều trở về gia quyến mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Năm thứ năm mươi nầy là một năm hân hỉ cho các ngươi, không nên gieo, không nên gặt vật chi đất tự sanh sản, và cũng chẳng nên hái nho không có hớt sửa,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'vì là một năm hân hỉ, sẽ làm thánh cho các ngươi; phải ăn những thổ sản.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Trong năm hân hỉ nầy, các sản nghiệp đều sẽ trở về nguyên chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Nếu các ngươi bán hay là mua vật chi với kẻ lân cận mình, thì chớ lận anh em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Người sẽ cứ lấy số năm từ sau năm hân hỉ mà mua với kẻ lân cận mình; còn người, cứ lấy theo số năm có hoa lợi mà bán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Tùy theo số năm sau năm hân hỉ, ngươi sẽ bù thêm giá; tùy theo số năm ít, ngươi sẽ giảm bớt giá; vì theo số mùa gặt mà người bán cho ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Chớ ai trong vòng các ngươi làm lận kẻ lân cận mình; nhưng hãy kính sợ Ðức Chúa Trời, vì ta là Giê-hô-va Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Các ngươi khá làm theo mạng lịnh ta, gìn giữ luật pháp ta và noi theo, như vậy sẽ được ăn ở bình yên trong xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Ðất sẽ sanh sản hoa lợi cho các ngươi, các ngươi sẽ ăn no và được ở bình yên trong xứ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Vì các ngươi nói rằng: Nếu chúng tôi chẳng gieo, chẳng gặt mùa màng, thì trong năm thứ bảy sẽ lấy chi mà ăn?');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Năm thứ sáu, ta sẽ giáng phước cho các ngươi, và năm ấy sẽ trúng mùa bù ba năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Năm thứ tám, các ngươi sẽ gieo và ăn hoa lợi của mùa màng cũ cho đến mùa màng mới của năm thứ chín.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Ðất không được đoạn mãi; vì đất thuộc về ta, các ngươi ở cùng ta như kẻ khách ngoại bang và kẻ kiều ngụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Trong khắp xứ mà các ngươi sẽ được làm sản nghiệp, hãy cho phép chuộc đất lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Nếu anh em ngươi trở nên nghèo, và bán một phần sản nghiệp mình, thì người bà con gần có quyền chuộc lại, phải đến chuộc phần đất anh em người đã bán.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Nếu người nào không có ai được quyền chuộc lại, nhưng tự lo cho có chi chuộc lại được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'thì phải tính từ năm đã bán bồi số trội cho chủ mua, rồi người sẽ được nhận sản nghiệp mình lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Nếu nguyên chủ không tìm đủ giá đặng trả cho, đất bán sẽ thuộc về người chủ mua cho đến năm hân hỉ; đoạn đất sẽ ra khỏi tay chủ mua và về nguyên chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Nếu người nào bán một cái nhà ở trong thành có vách bọc, thì có được phép chuộc lại cho đến giáp một năm sau khi bán; phép chuộc lại của người chỉ trong một năm trọn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Còn nếu không chuộc lại trước khi giáp hạn một năm trọn, thì nhà ở trong thành có vách bọc đó sẽ về chủ mua và dòng dõi người mãi mãi; đến năm hân hỉ nhà đó không ra khỏi tay họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Nhưng các nhà ở nơi hương thôn không có vách bọc lấy, thì kể như ruộng đất; chủ bán có phép chuộc lại; đến năm hân hỉ nhà sẽ về nguyên chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Còn về các thành của người Lê-vi, và về các nhà của họ ở trong thành đó, thì người Lê-vi luôn luôn có quyền chuộc lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Ai mua của người Lê-vi một cái nhà tại trong thành người Lê-vi, đến năm hân hỉ nhà đó sẽ về nguyên chủ; vì các nhà cửa tại trong những thành người Lê-vi là sản nghiệp của họ giữa dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Những ruộng đất thuộc về thành người Lê-vi không phép bán, vì là nghiệp đời đời của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Nếu anh em ở gần ngươi trở nên nghèo khổ, tài sản người lần lần tiêu mòn, thì hãy cứu giúp người, mặc dầu là kẻ khách kiều ngụ, hầu cho người cứ ở cùng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Chớ ăn lời, cũng đừng lấy lợi người; nhưng hãy kính sợ Ðức Chúa Trời mình, thì anh em ngươi sẽ ở cùng ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Chớ cho người vay bạc ăn lời và đừng cho mượn lương thực đặng lấy lời.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ta là Giê-hô-va, Ðức Chúa Trời các ngươi, Ðấng đã đem các ngươi ra khỏi xứ Ê-díp-tô, đặng ban cho các ngươi xứ Ca-na-an, và làm Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Nếu anh em ở gần ngươi trở nên nghèo khổ, đem bán mình cho ngươi, chớ nên bắt người làm việc như tôi mọi;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'người ở nhà ngươi như kẻ làm thuê, người ở đậu, sẽ giúp việc ngươi cho đến năm hân hỉ:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'đoạn người và con cái người thôi ở nhà người, trở về nhà và nhận lấy sản nghiệp của tổ phụ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Vì ấy là những tôi tớ ta mà ta đã đem ra khỏi xứ Ê-díp-tô; không nên bán họ như người ta bán tôi mọi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Ngươi chớ lấn lướt mà khắc bạc họ, nhưng phải kính sợ Ðức Chúa Trời ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Còn tôi trai tớ gái thuộc về ngươi, thì sẽ do các dân chung quanh mình mà ra; ấy do nơi những dân đó mà các ngươi mua tôi trai tớ gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Các ngươi cũng có phép mua tôi mọi trong bọn con cái của kẻ khách kiều ngụ nơi mình và của họ hàng chúng nó sanh ra trong xứ các ngươi; vậy, họ sẽ làm sản nghiệp của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Các ngươi để họ lại làm cơ nghiệp cho con cháu mình; hằng giữ họ như kẻ tôi mọi. Nhưng về phần anh em các ngươi, là dân Y-sơ-ra-ên, thì không ai nên lấn lướt mà khắc bạc anh em mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Khi một khách ngoại bang hay là một người kiều ngụ nơi ngươi trở nên giàu, còn anh em ngươi ở cùng họ lại nên nghèo, đem bán mình cho kẻ khách ngoại bang kiều ngụ nơi ngươi, hay là cho một người nào trong nhà kẻ khách ngoại bang ấy,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'sau khi đã đem bán mình rồi, thì sẽ có phép chuộc lại: một anh em người được chuộc người lại,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'hoặc bác chú, hoặc con của bác chú; hoặc một người thân thích cũng được chuộc người lại; hay là nếu người có thế, thì chánh người phải chuộc mình lấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Người sẽ tính cùng chủ mua từ năm nào mình đã bán mình cho đến năm hân hỉ; và giá bán sẽ tính theo số năm nhiều hay ít: tức là tính như ngày công của người làm thuê vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Nếu còn nhiều năm thì hãy cứ số năm nầy, cân phân theo giá đã bán mình mà chuộc lại;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'nếu đến năm hân hỉ còn ít năm, thì hãy tính với chủ mua cứ theo số năm nầy mà thối hồi số mua mình lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Họ đối cùng chủ như một người làm thuê năm, chứ không nên lấn lướt mà khắc bạc người trước mặt ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Nếu người không được chuộc lại bởi các thế ấy, đến năm hân hỉ người và các con trai người sẽ được ra tự do.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Vì dân Y-sơ-ra-ên là tôi tớ ta, tức các tôi tớ ta đã đem ra khỏi xứ Ê-díp-tô. Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Các ngươi chớ làm những hình tượng; hoặc hình chạm, hoặc hình đúc; chớ dựng trong xứ mình một hòn đá nào có dạng-hình, đặng sấp mình trước mặt hình đó, vì ta là Giê-hô-va, Ðức Chúa Trời của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Hãy giữ lễ sa-bát ta, và tôn kính nơi thánh ta. Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Nếu các ngươi tuân theo luật pháp ta, gìn giữ các điều răn ta và làm theo,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'thì ta sẽ giáng mưa thuận-thì, đất sẽ sanh hoa lợi, và cây ngoài đồng sẽ kết bông trái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Mùa đập lúa sẽ lần đến mùa hái nho, mùa hái nho sẽ lần đến mùa gieo mạ; các ngươi sẽ ăn no, ở bình yên trong xứ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Ta sẽ giáng sự bình tịnh trong nước, các ngươi ngủ không sợ ai dọa; ta sẽ diệt những loài thú dữ khỏi xứ, gươm giáo chẳng đưa qua xứ các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Các ngươi đuổi theo quân nghịch, họ sẽ bị gươm sa ngã trước mặt các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Năm người trong các ngươi sẽ đuổi theo một trăm; một trăm trong các ngươi sẽ đuổi theo một muôn, và quân nghịch sẽ bị gươm sa ngã trước mặt các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Ta sẽ đoái lại cùng các ngươi, làm cho sanh sản và thêm nhiều, cùng kết lập giao ước với các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Các ngươi sẽ ăn hoa lợi cũ mình, và đem cái cũ ra đặng chừa chỗ cho cái mới.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ta sẽ lập chỗ ở ta giữa các ngươi, tâm hồn ta không hề ghê gớm các ngươi đâu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Ta sẽ đi giữa các ngươi, và các ngươi sẽ làm dân ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ta là Giê-hô-va, Ðức Chúa Trời của các ngươi, Ðấng đã đem các ngươi ra khỏi xứ Ê-díp-tô, hầu cho khỏi làm tôi mọi. Ta đã bẻ gãy cái ách của các ngươi, làm cho các ngươi đi ngước đầu lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Song nếu các ngươi không nghe ta, không làm theo các điều răn nầy,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'nếu khinh bỉ mạng lịnh ta, và tâm hồn các ngươi nghịch cùng luật pháp ta, đến nỗi không làm theo những điều răn ta, mà bội sự giao ước ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'thì nầy là những điều ta sẽ giáng cho các ngươi: Ta sẽ giáng cho các ngươi sự kinh khủng, bịnh tổn và rét làm hư mòn con mắt và nhọc mệt tâm hồn. Các ngươi gieo mạ luống công, quân thù nghịch sẽ ăn hết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Ta sẽ nổi giận cùng các ngươi; các ngươi sẽ bị quân thù nghịch đánh đập; kẻ nào ghét các ngươi sẽ lấn lướt các ngươi, và các ngươi sẽ chạy trốn không ai đuổi theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Nếu đến đỗi vậy mà các ngươi không khứng nghe ta, ta sẽ vì cớ tội phạm, thêm gấp bảy lần đặng sửa phạt các ngươi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'và ta sẽ dẹp sự kiêu ngạo về năng lực các ngươi. Ta sẽ khiến trời các ngươi cứng như sắt và đất trơ như đồng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'năng lực mình hao mòn vô ích, đất không sanh sản huê lợi, cây cối không kết bông trái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Nếu các ngươi phản đối cùng ta, và không muốn nghe ta, thì ta sẽ tùy theo tội phạm giáng tai vạ trên các ngươi gấp bảy lần nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Ta sẽ sai những thú đồng đến tha con cái các ngươi đi, ăn hại súc vật, diệt số người ra ít; và đường nẻo các ngươi sẽ vắng tanh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Dẫu đến những việc ấy mà các ngươi cứ không phục sự sửa phạt ta, cứ phản đối cùng ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'thì ta đây cũng sẽ nghịch lại cùng các ngươi, và vì cớ tội lỗi, sẽ giáng tai vạ cho các ngươi gấp bảy lần nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Ta sẽ khiến gươm giáo đến trên các ngươi đặng báo thù sự giao ước ta; khi các ngươi hội hiệp trong những thành mình, ta sẽ giáng dịch hạch đến giữa các ngươi, và nộp các ngươi vào tay thù nghịch.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Khi ta dẫn sự đói kém đến, mười người nữ sẽ nướng bánh của các ngươi trong một lò, cân bánh trao lại cho các ngươi; các ngươi sẽ ăn mà không no.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Dầu đến nỗi vậy, mà các ngươi cứ không khứng nghe ta, còn phản đối cùng ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'thì ta cũng sẽ nghịch lại cùng các ngươi cách giận dữ, và vì cớ tội lỗi các ngươi, sẽ sửa phạt gấp bảy lần nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Các ngươi sẽ ăn thịt con trai con gái mình;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'ta sẽ hủy diệt những nơi cao các ngươi, phá đổ những hình mặt trời, và để thây các ngươi chồng trên thây của hình tượng mình, tâm hồn ta sẽ ghê gớm các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Ta sẽ làm cho thành các ngươi ra vắng vẻ, các nơi thánh quạnh hiu, và ta chẳng còn hưởng mùi thơm về của lễ các ngươi nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ta sẽ làm xứ ra đồi bại, đến nỗi kẻ thù nghịch ở tại đó cũng lấy làm lạ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Ta sẽ tản lạc các ngươi trong các dân và rút gươm ra đuổi theo sau các ngươi: xứ các ngươi sẽ hoang vu, thành sẽ vắng vẻ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Trọn trong lúc đất bỏ hoang vu, và các ngươi ở trong đất của kẻ thù nghịch, khi đó đất sẽ được an nghỉ hưởng những năm sa-bát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Trọn lúc đất bỏ hoang vu sẽ được an nghỉ; vì lúc các ngươi còn ở đất đó, nó không được an nghỉ trong những năm sa-bát của các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Còn ai trong các ngươi sống sót lại, ta sẽ làm cho họ nhát gan trong xứ của thù nghịch mình; tiếng lá khua sẽ làm cho họ chạy trốn, khác nào chạy trốn trước lưỡi gươm, té ngã mà không ai đuổi theo.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Người nầy vấp ngã trên người kia như trước ngọn gươm, vốn chẳng ai rượt đuổi theo họ; các ngươi không thể chịu nổi trước mặt quân thù nghịch mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Các ngươi sẽ bị chết mất giữa các dân, đất kẻ thù nghịch sẽ nuốt các ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Ai trong các ngươi còn sống, sẽ vì cớ gian ác mình và gian ác của tổ phụ mà hao mòn trong xứ kẻ thù nghịch mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Khi ấy, họ sẽ nhận gian ác mình, và gian ác của tổ phụ mình, những tội lỗi họ đã phạm, và sự chống trả họ đã cự cùng ta,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'đến đỗi ta cũng chống trả lại, dẫn họ vào xứ kẻ thù nghịch. Bấy giờ nếu lòng không chịu cắt bì của họ sẽ tự hạ mình xuống, và sẽ phục điều sửa phạt về gian ác mình,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'thì ta sẽ nhớ lại sự giao ước ta đã lập cùng Gia-cốp, cùng Y-sác, cùng Áp-ra-ham, và ta sẽ nhớ lại xứ nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Vì xứ bị họ bỏ hoang sẽ được nghỉ bấy nhiêu năm sa-bát tùy theo họ bỏ hoang vu bao nhiêu: họ sẽ chịu hình phạt của gian ác mình, bởi vì đã khinh bỉ mạng lịnh ta, và tâm hồn họ đã lấy làm ghê gớm các luật pháp ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Dẫu vậy, đương khi họ bị ở trong xứ kẻ thù nghịch mình, ta cũng chẳng bỏ họ đâu, chẳng ghê gớm họ đến phải hao mòn hết, và chẳng bội sự giao ước ta lập cùng họ đâu, vì ta là Giê-hô-va, Ðức Chúa Trời của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ta vì họ sẽ nhớ lại sự giao ước đã lập cùng tổ phụ họ mà ta đã đem ra khỏi xứ Ê-díp-tô trước mặt các dân, đặng làm Ðức Chúa Trời của họ. Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ðó là các điều lệ, mạng lịnh, và luật pháp mà Ðức Giê-hô-va nhờ Môi-se,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Hãy truyền cho dân Y-sơ-ra-ên rằng: Khi nào có ai dùng loài người mà khấn nguyện, thì ngươi hãy định giá cho; giá đó thuộc về Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Nếu ngươi định giá về một người nam từ hai mươi đến sáu mươi tuổi, thì hãy định cho năm chục siếc-lơ bạc, tùy theo siếc-lơ nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Nếu là một người nữ, hãy định giá ba chục siếc-lơ bạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Nếu là một đứa con trẻ từ năm đến hai mươi tuổi, thì hãy định giá hai chục siếc-lơ cho một đứa trai, và mười siếc-lơ cho một đứa gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ví bằng một đứa trẻ từ một tháng đến năm tuổi, thì hãy định giá năm siếc-lơ bạc cho một đứa trai, và ba siếc-lơ bạc cho một đứa gái.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Nếu một người già cả từ sáu mươi tuổi trở lên, ngươi hãy định giá mười lăm siếc-lơ bạc cho một người nam, và mười siếc-lơ bạc cho một người nữ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Bằng người khấn nguyện rất nghèo khổ, không nộp được giá tiền ngươi định, thì hãy đem đến trước mặt thầy tế lễ cho người nhất định cho. Thầy tế lễ sẽ tùy theo phương thế người khấn nguyện mà nhất định giá vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Nếu khấn nguyện về thú vật dùng làm của lễ dâng cho Ðức Giê-hô-va, thì hễ con thú nào dâng cho Ðức Giê-hô-va sẽ là vật thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Người ta không nên đổi hay là thế một con tốt cho một con xấu, hay là một con xấu cho một con tốt. Nếu thế một con nào cho một con khác, thì con nầy và con thế đều sẽ nên vật thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Nếu là thú vật ô uế không phép dùng làm của lễ dâng cho Ðức Giê-hô-va, thì phải đem con thú đó đến trước mặt thầy tế lễ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'rồi thầy tế lễ sẽ tùy theo con thú xấu hay tốt mà định giá. Họ sẽ theo giá định của thầy tế lễ mà trả.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Còn nếu muốn chuộc lại, thì phải phụ thêm một phần năm giá của ngươi định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Nếu ai biệt nhà mình ra thành cho Ðức Giê-hô-va, thì thầy tế lễ sẽ tùy theo nhà tốt hay xấu mà định giá; họ phải nhận lấy giá của thầy tế lễ đã định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Còn nếu kẻ đã biệt nhà mình ra thánh muốn chuộc nó lại, thì phải phụ thêm một phần năm giá ngươi đã định, rồi nhà sẽ thuộc về người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Nếu ai biệt một phần ruộng tổ nghiệp mình ra thánh cho Ðức Giê-hô-va, thì ngươi hãy định giá tùy theo số họ gieo, nghĩa là cứ năm chục siếc-lơ bạc mỗi một ô-me mạch nha giống.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Nếu biệt ruộng mình ra thánh từ năm hân hỉ, họ sẽ nhận giá ngươi định;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'còn nếu họ biệt ruộng mình ra thánh sau năm hân hỉ, thì thầy tế lễ cứ theo số năm còn lại đến năm hân hỉ mà định giá ruộng, và trừ lại giá ngươi định.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Nếu ngươi đã biệt ruộng mình ra thánh muốn chuộc nó lại, thì phải phụ thêm một phần năm giá ngươi định, rồi ruộng sẽ thuộc về người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Còn ví ngươi không chuộc lại, và người ta bán ruộng cho người khác, thì không được chuộc lại nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Khi đến năm hân hỉ, ruộng ra khỏi tay chủ mua, thì sẽ trở nên thánh, biệt riêng ra cho Ðức Giê-hô-va như một sở ruộng cấm: nó sẽ làm sản nghiệp cho thầy tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Nếu ai biệt ra thánh cho Ðức Giê-hô-va một sở ruộng mình mua, chớ chẳng phải của tổ nghiệp,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'thì thầy tế lễ sẽ tùy theo giá ngươi định mà đánh giá đến năm hân hỉ, rồi chánh trong ngày đó, người nầy phải nộp số tiền nhất định, vì là một vật biệt riêng ra thánh cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Năm hân hỉ, ruộng đó sẽ trở về chủ bán, tức là trở về nguyên chủ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Vả, phàm các giá định đều cứ theo siếc-lơ nơi thánh: một siếc-lơ giá hai chục ghê-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Song không ai được biệt ra thánh con đầu lòng của súc vật mình, hoặc bò, hoặc chiên, vì các con đầu lòng theo phép đã thuộc về Ðức Giê-hô-va rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Còn nếu là một con thú không sạch, họ phải tùy theo giá ngươi định, phụ thêm một phần năm mà chuộc nó lại; nếu con thú chẳng chuộc lại, thì phải đem bán tùy theo giá định của ngươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Phàm vật cấm, tức là hết thảy vật chi mà một người hằng dâng cho Ðức Giê-hô-va do những của mình có, hoặc người, hoặc loài vật, hoặc ruộng tổ nghiệp, thì chẳng được phép bán, cũng không được phép chuộc lại; hễ vật gì cấm, thì biệt ra chí thánh cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Hễ ai đã bị phú cho Ðức Giê-hô-va, thì không được phép chuộc lại, họ hẳn phải bị giết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Phàm thuế một phần mười thổ sản, bất kỳ vật gieo hay là hoa quả của cây, đều thuộc về Ðức Giê-hô-va; ấy là một vật thánh, biệt riêng ra cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Nếu ai muốn chuộc lại vật chi về một phần mười của mình, thì phải phụ thêm một phần năm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Còn về một phần mười của bầy bò hay là chiên, tức là mọi vật chi đi ngang dưới gậy, con thứ mười sẽ là thánh, biệt riêng ra thánh cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Họ không nên phân biệt con tốt hay là con xấu, và cũng không nên đổi. Nếu đổi, thì con thú bị đổi, và con đổi, cả hai đều biệt riêng ra thánh: không phép chuộc nó lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Ðó là các mạng lịnh mà Ðức Giê-hô-va truyền cho Môi-se về dân Y-sơ-ra-ên tại trên núi Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Ngày mồng một tháng hai, năm thứ hai, sau khi dân Y-sơ-ra-ên ra khỏi xứ Ê-díp-tô, Ðức Giê-hô-va phán cùng Môi-se ở trong hội mạc, tại đồng vắng Si-na -i, mà rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Hãy dựng sổ cả hội dân Y-sơ-ra-ên, theo họ hàng và tông tộc của họ, cứ đếm từng tên của hết thảy nam đinh,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'từ hai mươi tuổi sắp lên, tức là mọi người trong Y-sơ-ra-ên đi ra trận được; ngươi và A-rôn sẽ kê sổ chúng nó tùy theo đội ngũ của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Trong mỗi chi phái phải có một người giúp đỡ các ngươi, tức là người làm tộc trưởng của chi phái mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Ðây là tên những người sẽ giúp đỡ các ngươi: Về chi phái Ru-bên, Ê-lít-su, con trai của Sê-đêu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'về chi phái Si-mê-ôn, Sê-lu-mi-ên, con trai của Xu-ri-ha-đai;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'về chi phái Giu-đa, Na-ha-sôn, con trai của A-mi-na-đáp;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'về chi phái Y-sa-ca, Na-tha-na-ên, con trai của Xu-a;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'về chi phái Sa-bu-lôn, Ê-li-áp, con trai của Hê-lôn;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'về con cháu Giô-sép, nghĩa là về chi phái Ép-ra-im, Ê-li-sa-ma, con trai của A-mi-hút; về chi phái Ma-na-se, Ga-ma-li-ên, con trai của Phê-đát-su;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'về chi phái Bên-gia-min, A-bi-đan, con trai của Ghi-đeo-ni;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'về chi phái Ðan, A-hi-ê-xe, con trai của A-mi-sa-đai;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'về chi phái A-se, Pha-ghi-ên, con trai của Oùc-ran;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'về chi phái Gát, Ê-li-a-sáp, con trai của Ðê -u-ên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'về chi phái Nép-ta-li, A-hi-ra, con trai của Ê-nan.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ðó là những người được gọi từ trong hội chúng, vốn là quan trưởng của các chi phái tổ phụ mình, và là quan tướng quân đội Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Vậy, Môi-se và A-rôn nhận lấy các người ấy mà đã được xướng tên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'đến ngày mồng một tháng hai, truyền nhóm cả hội chúng, cứ kể tên từng người từ hai mươi tuổi sắp lên mà nhập sổ theo họ hàng và tông tộc của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Vậy, Môi-se kê sổ chúng nó tại đồng vắng Si-na -i, y như Ðức Giê-hô-va đã phán dặn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Con cháu Ru-bên, là trưởng nam của Y-sơ-ra-ên, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên của hết thảy nam đinh từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Ru-bên đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'số là bốn mươi sáu ngàn năm trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Con cháu Si-mê-ôn, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên của hết thảy nam đinh từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Si-mê-ôn đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'số là năm mươi chín ngàn ba trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Con cháu Gát, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Gát đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'số là bốn mươi lăm ngàn sáu trăm năm mươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Con cháu Giu-đa, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Giu-đa đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'số là bảy mươi bốn ngàn sáu trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Con cháu của Y-sa-ca, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Y-sa-ca đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'số là năm mươi bốn ngàn bốn trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Con cháu của Sa-bu-lôn, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Sa-bu-lôn đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'số là năm mươi bảy ngàn bốn trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Về hậu tự Giô-sép, là con cháu Ép-ra-im, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Ép-ra-im đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'số là bốn mươi ngàn năm trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Con cháu Ma-na-se, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Ma-na-se đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'số là ba mươi hai ngàn hai trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Con cháu Bên-gia-min, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Bên-gia-min đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'số là ba mươi lăm ngàn bốn trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Con cháu Ðan, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Ðan đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'số là sáu mươi hai ngàn bảy trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Con cháu A-se, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái A-se đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'số là bốn mươi mốt ngàn năm trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Con cháu Nép-ta-li, dòng dõi họ tùy theo họ hàng và tông tộc mình, cứ kể từng tên, từ hai mươi tuổi sắp lên, tức là mọi người trong chi phái Nép-ta-li đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'số là năm mươi ba ngàn bốn trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ðó là những người mà Môi-se, A-rôn, và mười hai quan trưởng Y-sơ-ra-ên kê sổ; mỗi quan trưởng kê sổ cho tông tộc mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Thế thì, hết thảy những người trong dân Y-sơ-ra-ên đã được nhập sổ tùy theo tông tộc mình, từ hai mươi tuổi sắp lên, tức là mọi người trong Y-sơ-ra-ên đi ra trận được,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'số là sáu trăm ba ngàn năm trăm năm mươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Nhưng người Lê-vi, theo chi phái tổ phụ mình, không kê sổ chung với những chi phái khác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Vì Ðức Giê-hô-va có phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Ngươi chớ kê sổ chi phái Lê-vi, và cũng đừng dựng bộ họ chung với dân Y-sơ-ra-ên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'nhưng hãy cắt phần người Lê-vi coi sóc đền tạm chứng cớ, hết thảy đồ đạc và các món thuộc về đền tạm. Ấy là người Lê-vi sẽ chuyên-vận đền tạm và hết thảy đồ đạc nó, cùng sẽ làm công việc về đền tạm và đóng trại ở chung quanh đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Khi nào đền tạm dời chỗ, thì người Lê-vi sẽ tháo dỡ nó; khi nào đền tạm dừng lại, thì họ sẽ dựng nó lên; còn người ngoại đến gần sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Dân Y-sơ-ra-ên mỗi người phải đóng ở trong trại quân mình, và mỗi trại quân, từng đội ngũ, phải đóng gần bên ngọn cờ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Nhưng người Lê-vi sẽ đóng trại chung quanh đền tạm chứng cớ, để đừng có sự giận dữ cùng hội-dân Y-sơ-ra-ên; người Lê-vi sẽ coi sóc đền tạm chứng cớ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Dân Y-sơ-ra-ên làm y như mọi điều Ðức Giê-hô-va đã phán dặn Môi-se vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Ðức Giê-hô-va phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Dân Y-sơ-ra-ên mỗi người phải đóng trại gần bên ngọn cờ mình, ở dưới bảng hiệu của tông tộc mình, đối ngang nhau vây chung quanh hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Trại quân Giu-đa sẽ đóng tại hướng đông, về phía mặt trời mọc, với ngọn cờ và những đội ngũ của mình. Quan-trưởng của người Giu-đa là Na-ha-sôn, con trai của A-mi-na-đáp;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'và quân đội người, cứ theo kê sổ, cọng bảy mươi bốn ngàn sáu trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Chi phái Y-sa-ca phải đóng trại bên Giu-đa; quan trưởng của người Y-sa-ca là Na-tha-na-ên, con trai Xu-a;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'và quân đội người, cứ theo kê sổ, cọng năm mươi bốn ngàn bốn trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Kế đến chi phái Sa-bu-lôn; quan trưởng của người Sa-bu-lôn là Ê-li-áp, con trai của Hê-lôn,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'và quân đội người, cứ theo kê sổ, cộng năm mươi bảy ngàn bốn trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Vậy, các người đã kê sổ theo trại quân Giu-đa, từng đội ngũ, cộng một trăm tám mươi sáu ngàn bốn trăm người. Họ phải đi tiên phong.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Ngọn cờ của trại quân Ru-bên và những đội ngũ mình, phải đóng về hướng nam. Quan trưởng của người Ru-bên là Ê-li-su, con trai của Sê-đêu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'và quân đội người, cứ theo kê sổ, cộng bốn mươi sáu ngàn năm trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Chi phái Si-mê-ôn phải đóng trại bên Ru-bên; quan trưởng của người Si-mê-ôn là Sê-lu-mi-ên, con trai của Xu-ri-ha-đai;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'và quân đội người, cứ theo kê sổ, cộng năm mươi chín ngàn ba trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Kế đến chi phái Gát; các quan trưởng của người Gát là Ê-li-a-sáp, con trai của Rê -u-ên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'và quân đội người, cứ theo kê sổ, cộng bốn mươi lăm ngàn sáu trăm năm mươi người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Vậy, các người đã kê sổ theo trại quân Ru-bên, từng đội ngũ, cộng một trăm năm mươi mốt ngàn bốn trăm năm mươi người. Họ phải đi thứ nhì.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Sau ấy, hội mạc sẽ đi với trại quân Lê-vi, ở giữa các trại quân khác; trại quân Lê-vi sẽ đi theo thứ tự như đã đóng, mỗi người theo hàng ngũ và theo ngọn cờ mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Ngọn cờ của trại quân Ép-ra-im và những quân đội người phải đóng về hướng tây; quan trưởng của người Ép-ra-im là Ê-li-sa-ma, con trai A-mi-hút;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'và quân đội người, cứ theo kê sổ, cộng bốn mươi ngàn năm trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Chi phái Ma-na-se phải đóng trại bên Ép-ra-im; quan trưởng của người Ma-na-se là Ga-ma-li-ên, con trai của Phê-đát-su;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'và quân đội người, cứ theo kê sổ, cộng ba mươi hai ngàn hai trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Kế đến chi phái Bên-gia-min; quan trưởng của người Bên-gia-min là A-bi-đan, con trai của Ghi-đeo-ni;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'và quân đội người, cứ theo kê sổ, cộng ba mươi lăm ngàn bốn trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Vậy, các người đã kê sổ theo trại quân Ép-ra-im, từng đội ngũ, cộng một trăm tám ngàn một trăm người. Họ phải đi thứ ba.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Ngọn cờ của trại quân Ðan và những quân đội họ phải đóng về hướng bắc. Quan trưởng của người Ðan là A-hi-ê-xe, con trai của A-mi-sa-đai;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'và quân đội người, cứ theo kê sổ, cộng sáu mươi hai ngàn bảy trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Chi phái A-se phải đóng trại bên Ðan; quan trưởng của người A-se là Pha-ghi-ên, con trai của Oùc-ran;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'và quân đội người, cứ theo kê sổ, cộng bốn mươi mốt ngàn năm trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Kế đến chi phái Nép-ta-li; quan trưởng của người Nép-ta-li là A-hi-ra, con trai của Ê-nan;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'và quân đội người, cứ theo kê sổ, cộng năm mươi ba ngàn bốn trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Vậy, các người đã kê sổ theo trại quân Ðan, cộng một trăm năm mươi bảy ngàn sáu trăm người. Họ theo ngọn cờ mình phải đi hậu binh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ðó là những người trong dân Y-sơ-ra-ên mà người ta tu bộ tùy theo tông tộc mình. Trong các trại quân hết thảy người đã kê sổ từng đội ngũ là sáu trăm ba ngàn năm trăm năm mươi người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Nhưng người Lê-vi không nhập sổ chung với dân Y-sơ-ra-ên, tùy theo mạng của Ðức Giê-hô-va đã truyền cho Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Dân Y-sơ-ra-ên y theo mọi điều Ðức Giê-hô-va đã phán dặn Môi-se, bèn đóng trại tùy theo ngọn cờ mình, và mỗi người ra đi tùy theo họ hàng và tông tộc mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Nầy là dòng dõi của A-rôn và Môi-se, về ngày Ðức Giê-hô-va phán cùng Môi-se tại trên núi Si-na -i.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Nầy là tên các con trai A-rôn: Trưởng nam là Na-đáp, A-bi-hu, Ê-lê-a-sa, và Y-tha-ma.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ðó là tên các con trai A-rôn, tức những thầy tế lễ đã chịu phép xức dầu, và được lập lên để làm chức tế lễ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Vả, Na-đáp và A-bi-hu đã thác trước mặt Ðức Giê-hô-va khi hai người dâng một thứ lửa lạ trước mặt Ðức Giê-hô-va tại trong đồng vắng Si-na -i. Hai người nầy không có con. Còn Ê-lê-a-sa và Y-tha-ma làm chức tế lễ trước mặt A-rôn, là cha mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Hãy khiến chi phái Lê-vi lại gần, đặt trước thầy tế lễ A-rôn, để người Lê-vi phục sự người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Người Lê-vi sẽ giữ chức phận của người và chức phận của cả hội chúng về trước hội mạc mà làm những công việc của đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Cũng phải coi sóc hết thảy đồ đạc của hội mạc và mọi vật chi dân Y-sơ-ra-ên giao cho đặng dùng làm công việc của đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Vậy, ngươi phải giao người Lê-vi cho A-rôn và cho các con trai người; vì đã lấy họ từ trong vòng dân Y-sơ-ra-ên mà ban trọn cho A-rôn rồi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Vậy, ngươi sẽ lập A-rôn và các con trai người, để làm chức tế lễ; người ngoại đến gần sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Nầy, từ giữa dân Y-sơ-ra-ên ta chọn lấy người Lê-vi thế cho hết thảy con đầu lòng của dân Y-sơ-ra-ên; vậy, người Lê-vi sẽ thuộc về ta.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Vì hết thảy con đầu lòng đều thuộc về ta; ngày xưa khi ta hành hại các con đầu lòng trong xứ Ê-díp-tô, ta đã biệt riêng ra thánh cho ta hết thảy con đầu lòng trong Y-sơ-ra-ên, bất luận loài người hay thú vật; chúng nó đều sẽ thuộc về ta. Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Ðức Giê-hô-va lại phán cùng Môi-se tại trong đồng vắng Si-na -i mà rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Hãy kê sổ con cháu Lê-vi, tùy theo tông tộc và họ hàng chúng nó, kê hết thảy nam đinh từ một tháng sắp lên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Môi-se bèn kê sổ người Lê-vi theo mạng của Ðức Giê-hô-va, y như Ngài đã phán dặn người vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ðây là các con trai của Lê-vi kể từng tên: Ghẹt-sôn, Kê-hát, và Mê-ra-ri.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Ðây là tên của các con trai Ghẹt-sôn, tùy theo họ hàng mình: Líp-ni và Si-mê -y.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Ðây là các con trai của Kê-hát tùy theo họ hàng mình: Am-ram, Dít-sa, Hếp-rôn và U-xi-ên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'và các con trai của Mê-ra-ri, tùy theo họ hàng mình, là: Mách-li và Mu-si. Ðó là những họ hàng của người Lê-vi, tùy theo tông tộc của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Họ hàng Líp-ni và họ hàng Si-mê -y thuộc về Ghẹt-sôn. Ðó là hai họ hàng của Ghẹt-sôn vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Những người trong họ Ghẹt-sôn được tu bộ, kể mọi nam đinh từ một tháng sắp lên, số là bảy ngàn năm trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Các họ hàng của Ghẹt-sôn đóng trại về phía tây, sau đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Quan trưởng của tông tộc Ghẹt-sôn là Ê-li-a-sáp, con trai của La-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Chức phận của con cháu Ghẹt-sôn trong hội mạc là coi sóc mọi vật chi can đến đền tạm và Trại, tức là tấm bong của Trại và bức màn của cửa hội mạc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'các bố vi của hành lang, và bức màn của cửa hành lang bao phủ chung quanh đền tạm và bàn thờ, cùng dây chạc về các việc của đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Họ hàng Am-ram, họ hàng Dít-sa, họ hàng Hếp-rôn và họ hàng U-xi-ên thuộc về Kê-hát. Ðó là những họ hàng của Kê-hát.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Cứ kể mọi nam đinh từ một tháng sắp lên, số là tám ngàn sáu trăm người có chức phận săn sóc nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Các họ hàng của con cháu Kê-hát đóng trại bên hông đền tạm về phía nam.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Quan trưởng của tông tộc Kê-hát là Ê-li-sa-phan, con trai của U-xi-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Người Kê-hát coi sóc hòm bảng chứng, cái bàn, chân đèn, các bàn thờ, và những đồ đạc của nơi thánh để dùng về việc thờ phượng, luôn với bức màn và các vật chi can đến.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Tổng trưởng của người Lê-vi là Ê-lê-a-sa, con trai của thầy tế lễ A-rôn, được đặt lên quản trị những người coi sóc nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Họ hàng Mách-li và họ hàng Mu-si thuộc về Mê-ra-ri. Ðó là hai họ hàng của Mê-ra-ri vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Những người trong bọn Mê-ra-ri được tu bộ, kể mọi nam đinh từ một tháng sắp lên, số là sáu ngàn hai trăm người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Quan trưởng của tông tộc Mê-ra-ri là Xu-ri-ên, con trai của A-bi-hai. Con cháu Mê-ra-ri đóng trại bên hông đền tạm về phía bắc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'có phần coi sóc các tấm ván của đền tạm, cây xà ngang, trụ, lỗ trụ, những đồ đạc, và mọi việc thuộc về đó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'những trụ ở chung quanh hành lang và lỗ trụ, những nọc và dây chạc của trụ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Những người đóng trại trước đền tạm về phía đông, tức trước hội mạc về phía mặt trời mọc, là Môi-se, A-rôn và các con trai người, có chức phận săn sóc nơi thánh thế cho dân Y-sơ-ra-ên. Người ngoại đến gần sẽ bị xử tử.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Hết thảy người Lê-vi mà Môi-se và A-rôn vâng mạng Ðức Giê-hô-va tu bộ, tùy theo họ hàng của họ, kể mọi nam đinh từ một tháng sắp lên, số là hai mươi hai ngàn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Ðoạn, Ðức Giê-hô-va phán cùng Môi-se rằng: Hãy kê sổ hết thảy con trưởng nam của dân Y-sơ-ra-ên, từ một tháng sắp lên, và hãy dựng sổ tên chúng nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Ta là Ðức Giê-hô-va. Ngươi phải chọn lấy cho ta người Lê-vi thế cho các con trưởng nam trong dân Y-sơ-ra-ên; cũng phải bắt súc vật của người Lê-vi thế cho mọi con súc vật đầu lòng của dân Y-sơ-ra-ên.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Vậy, Môi-se kê sổ các con trưởng nam của dân Y-sơ-ra-ên, y như Ðức Giê-hô-va đã phán dặn người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Hết thảy những con trưởng nam kể từng tên, từ tuổi một tháng sắp lên, theo sự kê sổ họ, là hai mươi hai ngàn hai trăm bảy mươi ba người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Hãy chọn lấy những người Lê-vi thế cho hết thảy con trưởng nam của dân Y-sơ-ra-ên, và súc vật của người Lê-vi thế cho súc vật của dân Y-sơ-ra-ên; vậy, các người Lê-vi sẽ thuộc về ta. Ta là Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Còn về sự chuộc lại con trưởng nam của dân Y-sơ-ra-ên, kê sổ hơn số người Lê-vi hai trăm bảy mươi ba,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'thì ngươi phải thâu mỗi người năm siếc-lơ, tùy theo siếc-lơ nơi thánh; một siếc-lơ là hai chục ghê-ra.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Ngươi phải giao bạc cho A-rôn và các con trai người; ấy là bạc chuộc lại những con trưởng nam trổi hơn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Vậy, Môi-se thâu bạc chuộc lại những con trưởng nam trổi hơn số người Lê-vi đã chuộc lại.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Bạc mà người thâu về những con trưởng nam của dân Y-sơ-ra-ên, cộng được một ngàn ba trăm sáu mươi lăm siếc-lơ, theo siếc-lơ của nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Môi-se vâng mạng Ðức Giê-hô-va, giao bạc chuộc lại cho A-rôn và các con trai người, y như Ðức Giê-hô-va đã phán dặn Môi-se.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Ðức Giê-hô-va phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Trong người Lê-vi hãy dựng sổ các con cháu Kê-hát, tùy theo họ hàng và tông tộc của chúng nó,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'từ ba mươi tuổi sắp lên cho đến năm mươi, tức là hết thảy người nào có thể giúp công vào hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Nầy sẽ là phần việc của con cháu Kê-hát tại trong hội mạc. Họ sẽ coi sóc nơi chí thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Khi nào dời trại quân đi, A-rôn và các con trai người sẽ đến gỡ bức màn mà bao lấy hòm bảng chứng;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'đoạn đắp lên một tấm phủ bằng da cá nược, trải trên một tấm nỉ toàn bằng màu điều xanh và xỏ đòn khiêng vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Cũng trải một tấm nỉ màu điều xanh trên cái bàn về bánh trần thiết; ở trên bàn thì sắp dĩa, chén, tộ và chậu về những lễ quán; bánh hằng trần thiết cũng sẽ có ở trên nữa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Rồi trải trên các vật đó một tấm nỉ màu đỏ sặm, đắp một tấm phủ bằng da cá nược và xỏ đòn khiêng vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Cũng phải lấy một tấm nỉ màu điều xanh mà đậy chân đèn thắp, các thếp đèn, kéo hớt tim, đồ đựng tro, và các bình dầu mà người ta dùng về chân đèn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Rồi để chân đèn và hết thảy đồ phụ tùng trong một tấm phủ bằng da cá nược, để lên trên cái sề.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Họ phải trải trên bàn thờ bằng vàng một tấm nỉ màu điều xanh và đắp một tấm phủ bằng da cá nược, rồi xỏ đòn khiêng vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Lại, cũng phải lấy hết thảy đồ đạc dùng về công việc nơi thánh, để trong một tấm nỉ màu điều xanh, rồi đắp một tấm phủ bằng da cá nược và để lên trên cái sề.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Phải hốt tro của bàn thờ, trải ở trên một tấm nỉ màu đỏ điều,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'để lên trên hết thảy đồ đạc dùng về công việc của bàn thờ, tức là những lư hương, nĩa, vá, chén, cùng những đồ phụ tùng của bàn thờ. Rồi đắp trên bàn thờ một tấm phủ bằng da cá nược và xỏ đòn khiêng vào.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Sau khi A-rôn và các con trai người đã đậy-điệm nơi thánh và các đồ đạc thánh xong, khi dời trại quân đi, thì các con cháu Kê-hát phải đến đặng khiêng các đồ đạc đó; họ chẳng nên đụng vào những vật thánh, e phải chết chăng. Trong hội mạc, ấy là đồ mà các con cháu Kê-hát phải khiêng đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Ê-lê-a-sa, con trai thầy tế lễ A-rôn, sẽ coi về dầu thắp đèn, hương-liệu, của lễ chay hằng hiến, dầu xức, cả đền tạm, và hết thảy vật chi ở trong nơi thánh với đồ phụ tùng của nơi thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Ðức Giê-hô-va lại phán cùng Môi-se và A-rôn rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Hãy làm thể nào cho tông tộc Kê-hát chớ bị truất khỏi chi phái Lê-vi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'và hãy làm điều nầy cho chúng nó, để khi đến gần nơi chí thánh, chúng nó được sống, chẳng phải chết: A-rôn và các con trai người phải đến cắt công việc cho mỗi người, và đồ chi họ phải khiêng đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Dẫu một lát, chúng nó chớ nên vào đặng xem những vật thánh, e phải chết chăng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Cũng hãy dựng sổ các con cháu Ghẹt-sôn, tùy theo tông tộc và họ hàng họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Từ ba mươi tuổi sắp lên cho đến năm mươi, ngươi khá kê sổ hết thảy những người nào có thể làm công việc trong hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Nầy là chức việc của các họ hàng Ghẹt-sôn, hoặc phải làm hoặc phải khiêng đồ:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'họ sẽ mang những tấm màn của đền tạm và hội mạc, tấm bong của hội mạc, tấm lá-phủ bằng da cá nược ở trên, và bức màn của cửa hội mạc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'các bố vi của hành lang ở chung quanh đền tạm và bàn thờ, bức màn của cửa hành lang, những dây chạc, và hết thảy đồ dùng về các vật đó, cùng làm các công việc về những món ấy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Hết thảy công việc của con cháu Ghẹt-sôn, món chi họ phải khiêng đi, và việc chi họ phải làm điều sẽ theo lịnh A-rôn và các con trai người chỉ biểu; người phải giao cho họ coi sóc mọi món chi phải khiêng đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Trong hội mạc, ấy là công việc của các họ hàng con cháu Ghẹt-sôn. Họ sẽ giữ chức phận mình dưới quyền cai trị của Y-tha-ma, con trai thầy tế lễ A-rôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Ngươi phải kê sổ con cháu Mê-ra-ri, tùy theo họ hàng và tông tộc của họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'từ ba mươi tuổi sắp lên cho đến năm mươi, tức là hết thảy người nào có thể giúp công vào hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Về các công việc của con cháu Mê-ra-ri trong hội mạc, nầy là vật họ phải coi sóc và khiêng đi: những tấm ván của đền tạm, các xà ngang, trụ, lỗ trụ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'các trụ chung quanh hành lang và lỗ trụ, nọc, dây chạc, cùng hết thảy đồ đạc và các vật chi dùng về việc đó; các ngươi sẽ kê sổ từng tên những vật chi họ phải coi sóc và khiêng đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Ðó là hết thảy việc của các họ hàng Mê-ra-ri, về những công việc trong hội mạc mà họ phải làm ở dưới quyền cai trị của Y-tha-ma, con trai thầy tế lễ A-rôn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Vậy, Môi-se, A-rôn và những hội trưởng kê sổ con cháu Kê-hát, tùy theo họ hàng và tông tộc của họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'từ ba mươi tuổi sắp lên cho đến năm mươi, tức là hết thảy người nào có thể giúp công trong hội mạc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'và những người mà người ta kê sổ, tùy theo họ hàng mình, cộng được hai ngàn bảy trăm năm mươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ðó là những người của các họ hàng Kê-hát đã bị kê sổ, tức là hết thảy người hầu việc trong hội mạc mà Môi-se và A-rôn kê sổ, y theo mạng của Ðức Giê-hô-va đã cậy Môi-se truyền dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Còn con cháu của Ghẹt-sôn đã bị kê sổ, tùy theo họ hàng và tông tộc của họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'từ ba mươi tuổi sắp lên cho đến năm mươi, tức là hết thảy người có thể giúp công trong hội mạc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'cộng được hai ngàn sáu trăm ba mươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ðó là những người về các họ hàng con cháu Ghẹt-sôn đã bị kê sổ, tức là mọi người hầu việc trong hội mạc mà Môi-se và A-rôn tu bộ y theo mạng của Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Còn những người về họ hàng con cháu Mê-ra-ri đã bị kê sổ, tùy theo họ hàng và tông tộc của họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'từ ba mươi tuổi sắp lên cho đến năm mươi, tức là mọi người có thể giúp công trong hội mạc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'cộng được ba ngàn hai trăm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ðó là những người về các họ hàng con cháu Mê-ra-ri đã bị kê sổ. Môi-se và A-rôn lấy bộ dân, y theo mạng của Ðức Giê-hô-va đã cậy Môi-se truyền dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Hết thảy những kẻ trong người Lê-vi mà Môi-se, A-rôn, và các quan trưởng Y-sơ-ra-ên tu bộ, tùy theo họ hàng và tông tộc của họ,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'từ ba mươi tuổi sắp lên cho đến năm mươi, tức là mọi người đến đặng hầu việc và khiêng đồ trong hội mạc,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'cộng được tám ngàn năm trăm tám mươi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Người ta tu bộ người Lê-vi tùy theo mạng của Ðức Giê-hô-va đã cậy Môi-se truyền dạy, cắt phần cho mỗi người việc mình phải làm, và vật chi mình phải khiêng đi; người ta tu bộ dân tùy theo lời Ðức Giê-hô-va đã phán dặn Môi-se vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Ðoạn, Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Hãy biểu dân Y-sơ-ra-ên đuổi ra ngoài trại quân hết thảy người phung, người có bịnh bạch trược, và người vì cớ đụng đến một xác chết nào đã bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Bất luận nam hay nữ, các ngươi phải đuổi họ ra ngoài trại quân, hầu cho họ không làm cho trại quân bị ô uế, là nơi ta ngự ở trong.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Dân Y-sơ-ra-ên bèn làm như vậy, đuổi họ ra khỏi trại quân, y như Ðức Giê-hô-va đã truyền lịnh cho Môi-se vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Hãy nói cùng dân Y-sơ-ra-ên như vầy: Khi một người nam hay nữ phạm một trong những tội người ta thường phạm, cho đến can phạm cùng Ðức Giê-hô-va, và vì cớ đó phải mắc tội,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'thì người ấy phải xưng tội mình đã phạm ra, và trả tang vật lại đủ, và thêm một phần năm giá vật mà giao cho người mình đã mắc tội cùng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Nếu người nầy không còn, và không bà con nào để lãnh tang vật đó lại, thì vật ấy sẽ về Ðức Giê-hô-va, tức là về thầy tế lễ, ngoại trừ con chiên đực về lễ chuộc tội mà thầy tế lễ sẽ dùng đặng chuộc tội cho người mắc tội đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Phàm lễ vật chi biệt riêng ra thánh mà dân Y-sơ-ra-ên dâng cho thầy tế lễ, đều sẽ thuộc về người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Những vật biệt riêng ra thánh mà mỗi người dâng sẽ thuộc về người; vật chi mỗi người ban cho thầy tế lễ, chắc sẽ thuộc về người vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Hãy nói cho dân Y-sơ-ra-ên rằng: Nếu một người đàn bà lỗi đạo và phạm tội bất chánh cùng chồng,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'nếu có một người nam gian dâm cùng nàng mà việc nhẹm khuất mắt chồng; nếu nàng bị ô uế kín nhiệm, không có chứng cớ đối cùng nàng, và nàng không bị bắt tại trận;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'nếu tánh ghen phát nơi người chồng ghen vợ mình, hoặc đã thật bị ô uế, hoặc không có bị ô uế,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'thì người nầy phải dẫn vợ mình đến trước mặt thầy tế lễ, và vì nàng đem theo một phần mười ê-pha bột mạch nha dùng làm của tế lễ. Người chớ nên chế dầu vào, và cũng chẳng nên bỏ nhũ hương lên trên, vì là một của lễ chay về sự ghen tương, một của lễ chay kỷ niệm đặng nhắc tội gian ác.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Thầy tế lễ sẽ biểu người nữ đến gần, đứng trước mặt Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Kế đó thầy tế lễ lấy nước thánh đổ vào chậu đất, hốt bụi ở trên đất của đền tạm mà bỏ trong nước.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Ðoạn, thầy tế lễ phải biểu người nữ đứng trước mặt Ðức Giê-hô-va, lột trần đầu nàng, để của lễ kỷ niệm trên lòng bàn tay nàng, nghĩa là của lễ chay về sự ghen tương; và thầy tế lễ phải có nước đắng giáng rủa sả trong tay mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Thầy tế lễ phải bắt người nữ thề, và nói cùng nàng rằng: Nếu chẳng một người nam nào nằm cùng ngươi, và nếu đương dưới quyền chồng ngươi không có lỗi đạo và không bị ô uế, thì chẳng phải mắc một điều hại nào của nước đắng giáng rủa sả nầy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Còn nếu đương dưới quyền chồng, mà ngươi lỗi đạo; nếu ngươi bị ô uế, và nếu một người nào khác hơn chồng đã nằm cùng ngươi');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'bấy giờ thầy tế lễ phải bắt người nữ lấy một lời thề trù ẻo mà thề, và nói cùng nàng rằng: Cầu Ðức Giê-hô-va khiến cho ngươi trở nên một mầm rủa sả và trù ẻo giữa vòng dân sự ngươi, làm cho ngươi ốm lòi hông và phình bụng lên;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'nước đắng giáng rủa sả nầy khá chun vào ruột gan làm cho bụng ngươi phình lên và ốm lòi hông. Người nữ sẽ nói rằng: A-men, a-men!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Kế đó, thầy tế lễ phải viết các lời trù ẻo nầy trong một cuốn sách, rồi lấy nước đắng bôi đi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Thầy tế lễ sẽ biểu người nữ uống nước đắng giáng rủa sả, nước đắng giáng rủa sả sẽ vào trong mình nàng đặng làm cay đắng cho nàng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Ðoạn, thầy tế lễ sẽ lấy khỏi tay người nữ của lễ chay về sự ghen tương, đưa qua đưa lại trước mặt Ðức Giê-hô-va và dâng lên trên bàn thờ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Rồi lấy một nắm của lễ chay kỷ niệm và xông trên bàn thờ; kế biểu người nữ uống nước đắng.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Vả, khi nào thầy tế lễ biểu người uống nước đắng rồi, nếu quả người có bị ô uế phạm tội bất chánh cùng chồng mình, thì nước đắng giáng rủa sả sẽ vào mình làm cay đắng cho nàng, bụng nàng sẽ phình lên, hông nàng ốm lòi, và người nữ nầy sẽ làm một mầm rủa sả giữa vòng dân sự mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Còn nếu người nữ không bị ô uế, vẫn thanh sạch, thì nàng sẽ chẳng bị một điều hại nào, và sẽ sanh con.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Ðó là luật lệ về sự ghen tương khi một người đàn bà, ở dưới quyền chồng mình, lỗi đạo và bị ô uế;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'hoặc khi nào tánh ghen phát sanh nơi người chồng mà ghen vợ mình: người phải đem vợ đến trước mặt Ðức Giê-hô-va, và thầy tế lễ sẽ làm cho nàng hết thảy điều chi luật lệ nầy truyền dạy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Người chồng sẽ vô tội, còn người đàn bà đó sẽ mang lấy tội mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Ðức Giê-hô-va lại phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Hãy nói cho dân Y-sơ-ra-ên rằng: Bất luận người nam hay nữ, khi hứa nguyện Na-xi-rê đặng biệt mình riêng ra cho Ðức Giê-hô-va,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'thì phải kiêng cữ rượu và vật uống say; chẳng nên uống hoặc giấm rượu, hoặc giấm của vật uống say; lại cũng chẳng nên uống một thứ nước nào bằng trái nho, hay là ăn nho tươi, hoặc nho khô.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Trọn trong lúc người biệt mình riêng ra, chớ ăn món chi của nho sanh sản hết, từ hột đến da.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Trọn trong lúc hứa nguyện Na-xi-rê mình, chớ nên dùng dao cạo đầu; người sẽ nên thánh, và phải để tóc mọc cho đến chừng nào kỳ biệt mình riêng ra cho Ðức Giê-hô-va đã được mãn.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Trọn trong lúc người biệt mình riêng ra cho Ðức Giê-hô-va chớ đến gần người chết.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Người chớ vì cha hoặc vì mẹ, vì anh hoặc vì chị đã chết, mà làm cho mình bị ô uế, vì dấu chỉ sự biệt riêng ra cho Ðức Chúa Trời vẫn ở trên đầu người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Trọn trong lúc hứa nguyện Na-xi-rê, người được biệt ra thánh cho Ðức Giê-hô-va.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Nếu ai chết thình lình gần bên người, làm cho ô uế đầu mình đã biệt riêng ra thánh, thì phải cạo đầu mình trong ngày được sạch, tức là ngày thứ bảy;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'qua ngày thứ tám, người phải đem hai chim cu hay là hai bò câu con đến cho thầy tế lễ tại cửa hội mạc.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Thầy tế lễ sẽ dâng con nầy làm của lễ chuộc tội, con kia làm của lễ thiêu, và chuộc tội cho người đã phạm, vì cớ xác chết. Vậy, trong ngày đó người sẽ biệt đầu mình riêng ra thánh.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Thế thì, người phải biệt riêng ra cho Ðức Giê-hô-va những ngày về nguyện Na-xi-rê mình lại, và dâng một con chiên đực giáp năm làm của lễ chuộc sự mắc lỗi, và những ngày trước không kể nữa, vì sự Na-xi-rê mình đã bị ô uế.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Nầy là luật lệ về người Na-xi-rê: Khi nào những ngày Na-xi-rê mình đã mãn, người ta phải đem người đến tại cửa hội mạc;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'người phải dâng của lễ mình cho Ðức Giê-hô-va, tức là một con chiên con giáp năm không tì vít, làm của lễ thiêu, một con chiên cái giáp năm không tì vít, làm của lễ chuộc tội, và một con chiên đực không tì vít, làm của lễ thù ân;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'một giỏ bánh không men bằng bột lọc, bánh nhỏ tưới dầu, bánh tráng không men thoa dầu, luôn với của lễ chay và lễ quán cặp theo các lễ kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Thầy tế lễ sẽ đem những của lễ nầy đến trước mặt Ðức Giê-hô-va, và dâng của lễ chuộc tội cùng của lễ thiêu của người;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'rồi ngoại trừ giỏ bánh không men, dâng luôn con chiên đực làm của lễ thù ân, cùng dâng của lễ chay và lễ quán của người.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Tại cửa hội mạc, người Na-xi-rê phải cạo đầu mình đã biệt riêng ra, lấy tóc bỏ vào lửa dưới của lễ thù ân.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Sau khi người Na-xi-rê cạo đầu rồi, thầy tế lễ sẽ lấy cái vai chín của chiên đực, một cái bánh nhỏ không men trong giỏ, một bánh tráng không men và để trong lòng hai bàn tay người,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'rồi đưa qua đưa lại trước mặt Ðức Giê-hô-va: ấy là một vật thánh về thầy tế lễ với cái o đưa qua đưa lại và cái giò dâng giơ lên. Kế đó, người Na-xi-rê được phép uống rượu.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Ðó là luật lệ về người Na-xi-rê đã hứa nguyện, và đây là của lễ người phải dâng cho Ðức Giê-hô-va về nguyện Na-xi-rê mình, ngoại trừ của lễ nào người có thể dâng thêm. Người phải theo luật lệ về sự Na-xi-rê mình mà làm theo lời hứa nguyện của mình vậy.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Ðức Giê-hô-va phán cùng Môi-se rằng:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Hãy nói cùng A-rôn và các con trai người mà rằng: Các ngươi phải chúc phước cho dân Y-sơ-ra-ên như vầy:');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Cầu xin Ðức Giê-hô-va ban phước cho ngươi và phù hộ ngươi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Cầu xin Ðức Giê-hô-va chiếu sáng mặt Ngài trên ngươi, và làm ơn cho ngươi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Cầu xin Ðức Giê-hô-va đoái xem ngươi và ban bình an cho ngươi!');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Họ phải đặt danh ta trên dân Y-sơ-ra-ên như vầy, thì ta đây sẽ ban phước cho dân đó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Khi Môi-se đã dựng xong đền tạm, và đã xức dầu cùng biệt riêng ra thánh hết thảy đồ đạc của đền tạm, xức dầu và biệt riêng ra thánh bàn thờ và hết thảy đồ đạc của bàn thờ rồi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'thì các trưởng tộc của Y-sơ-ra-ên, tức là các quan trưởng về những chi phái mà đã cai trị cuộc tu bộ dân, đều đem dâng lễ vật của mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Vậy, các quan trưởng dẫn lễ vật mình đến trước mặt Ðức Giê-hô-va: Sáu xe cộ, hình như cái kiệu, và mười hai con bò đực, nghĩa là mỗi hai quan trưởng đồng dâng một xe cộ, và mỗi một người dâng một con bò đực; họ dâng lễ vật đó trước đền tạm.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Ðức Giê-hô-va bèn phán cùng Môi-se rằng: Hãy thâu nhận các lễ vật của những người nầy, để dùng vào công việc hội mạc; và hãy giao cho người Lê-vi,');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'tức là cho mọi người tùy theo chức phận mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Vậy, Môi-se bèn nhận lấy các xe cộ và những bò đực, giao cho người Lê-vi.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Người giao cho con cháu Ghẹt-sôn hai xe cộ và bốn con bò đực, tùy theo chức phận của họ.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Người giao cho con cháu Mê-ra-ri bốn xe cộ và tám con bò đực, tùy theo chức phận của họ, có Y-tha-ma, con trai thầy tế lễ A-rôn, làm quản lý.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Nhưng người không có giao chi cho con cháu Kê-hát, vì họ mắc phần công việc về những vật thánh, và gánh vác những vật đó trên vai mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Trong ngày bàn thờ được xức dầu, các quan trưởng dâng lễ vật mình trước bàn thờ về cuộc khánh thành nó.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Ðức Giê-hô-va phán cùng Môi-se rằng: Các quan trưởng phải đem lễ vật mình về cuộc khánh thành bàn thờ, người nầy thì ngày nay, người kia thì ngày kia.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Người dâng lễ vật mình ngày đầu, là Na-ha-sôn, con trai của A-mi-na-đáp, thuộc về chi phái Giu-đa.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Lễ-vật người là một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy chục siếc-lơ, theo siếc-lơ của nơi thánh; cả hai cái đều đầy bột lọc nhồi dầu, dùng về của lễ chay;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'một cái chén vàng nặng mười siếc-lơ, đầy thuốc thơm;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'một con bò đực tơ, một con chiên đực, một con chiên con giáp năm, dùng về của lễ thiêu;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'một con dê đực dùng về của lễ chuộc tội;');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'và về của lễ thù ân, hai con bò đực, năm con chiên đực, năm con dê đực, và năm con chiên con giáp năm. Ðó là lễ vật của Na-ha-sôn, con trai A-mi-na-đáp.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Ngày thứ hai, Na-tha-na-ên, con trai của Xu-a, quan trưởng Y-sa-ca, dâng lễ vật mình.');
INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Người dâng một cái đĩa bạc nặng một trăm ba mươi siếc-lơ, một cái chậu bạc nặng bảy chục siếc-lơ, theo siếc-lơ của nơi thánh, cả hai cái đều đầy bột lọc nhồi dầu, dùng về của lễ chay;');
