INSERT INTO `Viet_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Ngày thứ ba, đến quan trưởng của con cháu Sa-bu-lôn, là Ê-li-áp, con trai của Hê-lôn.');
